import { beforeEach, describe, expect, it, vi } from "vitest";
import { NextResponse } from "next/server";
import {
  consumeRateLimit,
  getRequestIp,
  tooManyRequestsResponse,
} from "@/lib/ip-rate-limit";
import { parseIntroRequestId } from "@/lib/admin-api-auth";
import { canonicalGitHubRepoUrl } from "@/lib/provix-token";

vi.mock("@/lib/api-auth", () => ({
  requireApiUser: vi.fn(),
}));

vi.mock("@/lib/provix-token-server", () => ({
  findMatchingProvixFile: vi.fn(),
  persistVerifiedRepo: vi.fn(),
}));

vi.mock("@/utils/supabase/server", () => ({
  createClient: vi.fn(),
}));

vi.mock("next/headers", () => ({
  cookies: vi.fn(),
}));

describe("Next.js API route handler helpers", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.resetModules();
  });

  it("extracts client IPs and enforces route rate limits", () => {
    const forwarded = new Request("https://getprovix.com/api/audit", {
      headers: { "x-forwarded-for": "203.0.113.10, 10.0.0.1" },
    });
    expect(getRequestIp(forwarded)).toBe("203.0.113.10");

    const realIp = new Request("https://getprovix.com/api/audit", {
      headers: { "x-real-ip": "198.51.100.7" },
    });
    expect(getRequestIp(realIp)).toBe("198.51.100.7");
    expect(getRequestIp(new Request("https://getprovix.com/api/audit"))).toBe(
      "unknown"
    );

    const key = `api-route-test:${Date.now()}`;
    expect(consumeRateLimit(key, 2, 60_000).ok).toBe(true);
    expect(consumeRateLimit(key, 2, 60_000).ok).toBe(true);
    const blocked = consumeRateLimit(key, 2, 60_000);
    expect(blocked.ok).toBe(false);
    expect(blocked.retryAfterSec).toBeGreaterThan(0);

    const response = tooManyRequestsResponse(12);
    expect(response.status).toBe(429);
    expect(response.headers.get("Retry-After")).toBe("12");
  });

  it("parses intro request ids and normalizes GitHub repo URLs for handlers", () => {
    expect(parseIntroRequestId({ requestId: " req-1 " })).toBe("req-1");
    expect(parseIntroRequestId({ id: "id-2" })).toBe("id-2");
    expect(parseIntroRequestId({ introId: "intro-3" })).toBe("intro-3");
    expect(parseIntroRequestId({})).toBe("");
    expect(canonicalGitHubRepoUrl("Acme", "Widgets")).toBe(
      "https://github.com/acme/widgets"
    );
  });

  it("returns 401 and 400 from verify-repo before persistence", async () => {
    const { requireApiUser } = await import("@/lib/api-auth");
    const { POST } = await import("@/app/api/verify-repo/route");

    vi.mocked(requireApiUser).mockResolvedValue(
      NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    );
    const unauthorized = await POST(
      new Request("https://getprovix.com/api/verify-repo", {
        method: "POST",
        body: JSON.stringify({}),
      })
    );
    expect(unauthorized.status).toBe(401);

    vi.mocked(requireApiUser).mockResolvedValue({
      user: { id: "user-1" },
      supabase: {} as never,
    } as never);

    const missingRepo = await POST(
      new Request("https://getprovix.com/api/verify-repo", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: "abc" }),
      })
    );
    expect(missingRepo.status).toBe(400);
    await expect(missingRepo.json()).resolves.toMatchObject({
      error: "repo_url is required.",
    });

    const missingToken = await POST(
      new Request("https://getprovix.com/api/verify-repo", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          repo_url: "https://github.com/acme/widgets",
        }),
      })
    );
    expect(missingToken.status).toBe(400);
    await expect(missingToken.json()).resolves.toMatchObject({
      error: "token is required.",
    });

    const badUrl = await POST(
      new Request("https://getprovix.com/api/verify-repo", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          repo_url: "https://github.com/acme",
          token: "abc",
        }),
      })
    );
    expect(badUrl.status).toBe(400);
  });

  it("signs out through the auth API route and clears supabase cookies", async () => {
    const { createClient } = await import("@/utils/supabase/server");
    const { cookies } = await import("next/headers");
    const signOut = vi.fn().mockResolvedValue({});
    const deleteCookie = vi.fn();

    vi.mocked(createClient).mockResolvedValue({
      auth: { signOut },
    } as never);
    vi.mocked(cookies).mockResolvedValue({
      getAll: () => [
        { name: "sb-access-token", value: "a" },
        { name: "other", value: "b" },
        { name: "my-supabase-session", value: "c" },
      ],
      delete: deleteCookie,
    } as never);

    const { POST } = await import("@/app/api/auth/signout/route");
    const response = await POST();
    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toEqual({ success: true });
    expect(signOut).toHaveBeenCalledOnce();
    expect(deleteCookie).toHaveBeenCalledWith("sb-access-token");
    expect(deleteCookie).toHaveBeenCalledWith("my-supabase-session");
    expect(deleteCookie).not.toHaveBeenCalledWith("other");
  });
});

import { describe, expect, it } from "vitest";
import { clampScore0to100 } from "@/lib/score-scale";
import {
  getGitHubUrlValidationMessage,
  hasUsableGitHubAuditTarget,
  isValidGitHubUrl,
  normalizeGitHubAuditTarget,
  parseGitHubRepoPath,
  parseGitHubUrl,
} from "@/lib/validate-github-url";

describe("GitHub API input validation", () => {
  it("accepts owner/repo audit targets and rejects bare handles", () => {
    expect(parseGitHubRepoPath("https://github.com/acme/widgets")).toEqual({
      owner: "acme",
      repo: "widgets",
    });
    expect(parseGitHubRepoPath("acme/widgets")).toEqual({
      owner: "acme",
      repo: "widgets",
    });
    expect(parseGitHubRepoPath("acme")).toBeNull();
    expect(hasUsableGitHubAuditTarget("https://github.com/acme/widgets")).toBe(
      true
    );
    expect(hasUsableGitHubAuditTarget("github.com/acme")).toBe(false);
  });

  it("normalizes URLs and surfaces validation messages", () => {
    expect(normalizeGitHubAuditTarget("github.com/acme/widgets/")).toBe(
      "https://github.com/acme/widgets"
    );
    expect(isValidGitHubUrl("https://github.com/acme/widgets")).toBe(true);
    expect(isValidGitHubUrl("not-a-url")).toBe(false);
    expect(getGitHubUrlValidationMessage("acme")).not.toBeNull();
    expect(
      getGitHubUrlValidationMessage("https://github.com/acme/widgets")
    ).toBeNull();
  });

  it("parses profile-only URLs separately from repo URLs", () => {
    expect(parseGitHubUrl("https://github.com/acme")).toEqual({
      owner: "acme",
      repo: null,
    });
    expect(parseGitHubUrl("https://github.com/acme/widgets")).toEqual({
      owner: "acme",
      repo: "widgets",
    });
    expect(clampScore0to100(150)).toBe(100);
    expect(clampScore0to100(-5)).toBe(0);
    expect(clampScore0to100("42")).toBe(42);
  });
});

import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
  INACCESSIBLE_PUBLIC_REPO_MESSAGE,
  isInaccessiblePublicAudit,
  isInvalidRepoFormatResponse,
  isPrivateOrNotFoundAuditResponse,
  isUnverifiedOwnershipResponse,
  unverifiedOwnershipOwner,
  unverifiedOwnershipUsername,
} from "@/lib/inaccessible-public-audit";
import {
  REPO_NOT_FOUND_OR_PRIVATE,
  UNVERIFIED_OWNERSHIP,
} from "@/lib/github-ownership";
import {
  getGitHubUrlValidationMessage,
  hasUsableGitHubAuditTarget,
  INVALID_REPO_FORMAT,
  isValidGitHubUrl,
  parseGitHubRepoPath,
} from "@/lib/validate-github-url";
import {
  consumeRateLimit,
  getRequestIp,
  tooManyRequestsResponse,
} from "@/lib/ip-rate-limit";
import {
  describeDeepScreeningFailure,
  isAbortOrTimeoutError,
  isNetworkDropError,
} from "@/lib/talent-pool-candidate";
import { parseIntroRequestId } from "@/lib/admin-api-auth";
import {
  formatZodErrorDetails,
  parseJsonWithSchema,
} from "@/lib/parse-request-json";

describe("API error handling and input validation", () => {
  it("validates GitHub audit URL inputs before handlers run", () => {
    expect(parseGitHubRepoPath("https://github.com/acme/widgets")).toEqual({
      owner: "acme",
      repo: "widgets",
    });
    expect(parseGitHubRepoPath("acme")).toBeNull();
    expect(hasUsableGitHubAuditTarget("https://github.com/acme/widgets")).toBe(
      true
    );
    expect(hasUsableGitHubAuditTarget("github.com/acme")).toBe(false);
    expect(isValidGitHubUrl("https://github.com/acme/widgets")).toBe(true);
    expect(getGitHubUrlValidationMessage("acme")).not.toBeNull();
    expect(
      getGitHubUrlValidationMessage("https://github.com/acme/widgets")
    ).toBeNull();
    expect(INVALID_REPO_FORMAT).toBeTruthy();
  });

  it("classifies inaccessible, ownership, and format API error payloads", () => {
    expect(
      isUnverifiedOwnershipResponse({
        error: UNVERIFIED_OWNERSHIP,
        owner: "acme",
        username: "walter",
      })
    ).toBe(true);
    expect(
      unverifiedOwnershipOwner({
        error: UNVERIFIED_OWNERSHIP,
        owner: " acme ",
      })
    ).toBe("acme");
    expect(
      unverifiedOwnershipUsername({
        error: UNVERIFIED_OWNERSHIP,
        github_username: "walter",
      })
    ).toBe("walter");

    expect(isInvalidRepoFormatResponse({ error: INVALID_REPO_FORMAT })).toBe(
      true
    );
    expect(
      isPrivateOrNotFoundAuditResponse({
        error: REPO_NOT_FOUND_OR_PRIVATE,
        isPrivateOrNotFound: true,
        repoUrl: "https://github.com/acme/widgets",
      })
    ).toBe(true);
    expect(
      isPrivateOrNotFoundAuditResponse({ error: UNVERIFIED_OWNERSHIP })
    ).toBe(false);

    expect(
      isInaccessiblePublicAudit({
        status: 404,
        result: { error: REPO_NOT_FOUND_OR_PRIVATE },
      })
    ).toBe(true);
    expect(
      isInaccessiblePublicAudit({
        status: 403,
        result: { error: UNVERIFIED_OWNERSHIP },
      })
    ).toBe(false);
    expect(INACCESSIBLE_PUBLIC_REPO_MESSAGE).toMatch(/public GitHub/i);
  });

  it("maps transport failures and returns structured API rate-limit errors", () => {
    expect(isAbortOrTimeoutError({ name: "AbortError" })).toBe(true);
    expect(isAbortOrTimeoutError({ message: "Request timed out" })).toBe(true);
    expect(isNetworkDropError(new TypeError("Failed to fetch"))).toBe(true);
    expect(describeDeepScreeningFailure({ name: "TimeoutError" }, 504)).toMatch(
      /timed out/i
    );
    expect(describeDeepScreeningFailure(null, 503)).toMatch(/dropped/i);

    expect(parseIntroRequestId({ requestId: " intro-9 " })).toBe("intro-9");
    expect(parseIntroRequestId({ id: "legacy-id" })).toBe("legacy-id");

    const request = new Request("https://getprovix.com/api/screen", {
      headers: { "x-forwarded-for": "203.0.113.50, 10.0.0.8" },
    });
    expect(getRequestIp(request)).toBe("203.0.113.50");

    const key = `api-test:${Date.now()}`;
    expect(consumeRateLimit(key, 1, 60_000).ok).toBe(true);
    const blocked = consumeRateLimit(key, 1, 60_000);
    expect(blocked.ok).toBe(false);

    const response = tooManyRequestsResponse(blocked.retryAfterSec);
    expect(response.status).toBe(429);
    expect(response.headers.get("Retry-After")).toBe(
      String(blocked.retryAfterSec)
    );
  });

  it("rejects invalid JSON bodies with Zod schema details", async () => {
    const schema = z.object({
      repo_url: z.string().min(1),
      token: z.string().min(1),
    });

    const invalidJson = await parseJsonWithSchema(
      new Request("https://getprovix.com/api/verify-repo", {
        method: "POST",
        body: "{not-json",
        headers: { "Content-Type": "application/json" },
      }),
      schema
    );
    expect(invalidJson.ok).toBe(false);
    if (!invalidJson.ok) {
      expect(invalidJson.response.status).toBe(400);
      await expect(invalidJson.response.json()).resolves.toMatchObject({
        error: "Invalid JSON body.",
      });
    }

    const invalidShape = await parseJsonWithSchema(
      new Request("https://getprovix.com/api/verify-repo", {
        method: "POST",
        body: JSON.stringify({ repo_url: "" }),
        headers: { "Content-Type": "application/json" },
      }),
      schema
    );
    expect(invalidShape.ok).toBe(false);
    if (!invalidShape.ok) {
      expect(invalidShape.response.status).toBe(400);
      const payload = await invalidShape.response.json();
      expect(payload.error).toBe("Invalid request payload.");
      expect(Array.isArray(payload.details)).toBe(true);
      expect(payload.details.length).toBeGreaterThan(0);
    }

    const valid = await parseJsonWithSchema(
      new Request("https://getprovix.com/api/verify-repo", {
        method: "POST",
        body: JSON.stringify({
          repo_url: "https://github.com/acme/widgets",
          token: "abc",
        }),
        headers: { "Content-Type": "application/json" },
      }),
      schema
    );
    expect(valid.ok).toBe(true);
    if (valid.ok) {
      expect(valid.data.token).toBe("abc");
    }

    const details = formatZodErrorDetails(
      schema.safeParse({ repo_url: 1 }).error!
    );
    expect(details.some((item) => item.includes("repo_url"))).toBe(true);
  });
});

import { describe, expect, it } from "vitest";
import {
  applyUpstreamDerivativePenalty,
  computeProductionAuditMetrics,
  PRODUCTION_METRIC_WEIGHTS,
  scoreArchitecture,
  scoreDevops,
  scoreResilience,
  scoreTesting,
  UPSTREAM_DERIVATIVE_PENALTY,
  weightedProductionScore,
} from "@/lib/production-audit-metrics";
import { classifyRepoFilesystem } from "@/lib/repo-filesystem";
import { clampScore0to100, scoreBarWidthPercent } from "@/lib/score-scale";

describe("auditor scoring and weighting math", () => {
  it("uses dual-mode production weights (fulltime baseline export)", () => {
    const weightSum =
      PRODUCTION_METRIC_WEIGHTS.architecture +
      PRODUCTION_METRIC_WEIGHTS.testing +
      PRODUCTION_METRIC_WEIGHTS.devops +
      PRODUCTION_METRIC_WEIGHTS.resilience;

    expect(weightSum).toBeCloseTo(1);
    expect(PRODUCTION_METRIC_WEIGHTS).toEqual({
      architecture: 0.3,
      testing: 0.3,
      devops: 0.15,
      resilience: 0.25,
    });

    expect(
      weightedProductionScore(
        {
          architecture: 80,
          testing: 60,
          devops: 40,
          resilience: 20,
        },
        "fulltime"
      )
    ).toBe(Math.round(80 * 0.3 + 60 * 0.3 + 40 * 0.15 + 20 * 0.25));
  });

  it("clamps headline scores and applies the upstream fork penalty", () => {
    expect(clampScore0to100(142)).toBe(100);
    expect(clampScore0to100(-3)).toBe(0);
    expect(clampScore0to100("67")).toBe(67);
    expect(scoreBarWidthPercent(110)).toBe("100%");

    expect(applyUpstreamDerivativePenalty(88, false)).toBe(88);
    expect(applyUpstreamDerivativePenalty(88, true)).toBe(
      88 - UPSTREAM_DERIVATIVE_PENALTY
    );
    expect(applyUpstreamDerivativePenalty(10, true)).toBe(0);
    expect(UPSTREAM_DERIVATIVE_PENALTY).toBe(30);
  });

  it("computes pillar scores from an inspected repository file tree", () => {
    const filesystem = classifyRepoFilesystem(
      [
        "package.json",
        "tsconfig.json",
        "next.config.ts",
        "eslint.config.mjs",
        "src/app/layout.tsx",
        "src/app/page.tsx",
        "src/app/error.tsx",
        "src/lib/auth.ts",
        "src/lib/auth.test.ts",
        "src/lib/client.test.ts",
        ".github/workflows/ci.yml",
      ],
      { inspected: true }
    );

    const architecture = scoreArchitecture(filesystem);
    const testing = scoreTesting(filesystem);
    const devops = scoreDevops(filesystem);
    const resilience = scoreResilience(filesystem, filesystem.repo_kind);
    const metrics = computeProductionAuditMetrics(filesystem);

    expect(filesystem.repo_kind).toBe("web_app");
    expect(architecture).toBeGreaterThan(0);
    expect(architecture).toBeLessThanOrEqual(82);
    expect(testing).toBeGreaterThan(0);
    expect(devops).toBeGreaterThan(0);
    expect(resilience).toBeGreaterThan(0);
    expect(metrics.productionScore).toBe(
      weightedProductionScore(
        {
          architecture: metrics.architecture,
          testing: metrics.testing,
          devops: metrics.devops,
          resilience: metrics.resilience,
        },
        "contract"
      )
    );
    expect(metrics.weights.architecture).toBe(0.45);
  });
});

import { describe, expect, it } from "vitest";
import { AUTH_SESSION_TIMEOUT_MS } from "@/lib/auth-session-timeout";
import {
  EMPLOYER_DASHBOARD_PATH,
  ROLE_ONBOARDING_PATH,
  isCandidateShellPath,
  isEmployerAllowedDashboardRequest,
  isEmployerAuthIntent,
  isEmployerDashboardRequest,
  normalizeAccountKind,
  profileDefaultsForAccountRole,
  resolveAccountRole,
  resolvePostAuthDestination,
  signupMetadataForKind,
  signupRoleFromSearch,
} from "@/lib/account-role";
import {
  canAccessTalentPool,
  isEmployeeRole,
  isEmployerRole,
  isProtectedAppPath,
  isPublicRoute,
  isVerifiedEmployerFlag,
  shouldSkipMiddlewareAuth,
} from "@/lib/dashboard-account";
import {
  getPostLoginPath,
  isAdminUser,
  isAllowedAdminUser,
} from "@/lib/admin-access";
import { buildOAuthCallbackUrl } from "@/lib/auth-callback-url";

describe("authentication and session validation", () => {
  it("keeps a short browser session timeout for mobile auth reads", () => {
    expect(AUTH_SESSION_TIMEOUT_MS).toBe(1500);
  });

  it("normalizes roles and post-auth destinations by account kind", () => {
    expect(normalizeAccountKind("business")).toBe("employer");
    expect(normalizeAccountKind("employee")).toBe("candidate");
    expect(normalizeAccountKind("unknown")).toBeNull();

    expect(
      resolveAccountRole("employer", {
        user_metadata: { role: "candidate" },
      } as never)
    ).toBe("employer");
    expect(
      resolveAccountRole(null, {
        user_metadata: { role: "business" },
      } as never)
    ).toBe("employer");

    expect(
      resolvePostAuthDestination({ role: null, requestedNext: "/dashboard" })
    ).toBe(ROLE_ONBOARDING_PATH);
    expect(
      resolvePostAuthDestination({
        role: "employer",
        requestedNext: "/dashboard/profile",
      })
    ).toBe(EMPLOYER_DASHBOARD_PATH);
    expect(
      resolvePostAuthDestination({
        role: "candidate",
        requestedNext: "/dashboard?tab=talent",
      })
    ).toBe(EMPLOYER_DASHBOARD_PATH);
    expect(
      resolvePostAuthDestination({
        role: "candidate",
        setupComplete: false,
      })
    ).toBe("/onboarding");
    expect(
      resolvePostAuthDestination({
        role: "candidate",
        requestedNext: "/dashboard/auditor",
        isAdmin: true,
      })
    ).toBe("/admin");

    expect(profileDefaultsForAccountRole("employer")).toEqual({
      role: "employer",
      is_visible_in_pool: false,
    });
    expect(signupMetadataForKind("business", {
      first_name: "Ada",
      last_name: "Lovelace",
    }).role).toBe("employer");
    expect(signupRoleFromSearch("?role=founder")).toBe("employer");
    expect(isEmployerAuthIntent("?next=/employer/verify")).toBe(true);
  });

  it("gates middleware, employer shells, and talent-pool verification", () => {
    expect(shouldSkipMiddlewareAuth("/login")).toBe(true);
    expect(shouldSkipMiddlewareAuth("/dashboard")).toBe(false);
    expect(isPublicRoute("/audit")).toBe(true);
    expect(isPublicRoute("/verify-email")).toBe(true);
    expect(isProtectedAppPath("/settings")).toBe(true);

    expect(isEmployerRole("employer")).toBe(true);
    expect(isEmployeeRole("employee")).toBe(true);
    expect(isEmployeeRole("candidate")).toBe(false);
    expect(isVerifiedEmployerFlag(true)).toBe(true);
    expect(canAccessTalentPool("employer", true)).toBe(true);
    expect(canAccessTalentPool("employer", false)).toBe(true);
    expect(canAccessTalentPool("candidate", true)).toBe(true);

    expect(isEmployerDashboardRequest("/dashboard", "?tab=talent")).toBe(true);
    expect(isEmployerDashboardRequest("/dashboard/jobs")).toBe(true);
    expect(isEmployerAllowedDashboardRequest("/dashboard/jobs")).toBe(true);
    expect(isEmployerDashboardRequest("/dashboard/profile")).toBe(false);
    expect(isEmployerAllowedDashboardRequest("/dashboard", "?tab=auditor")).toBe(
      true
    );
    expect(isCandidateShellPath("/dashboard/profile")).toBe(true);
    expect(isCandidateShellPath("/dashboard", "?tab=talent")).toBe(false);
  });

  it("classifies admins and builds safe OAuth callback URLs", () => {
    const admin = {
      email: "eliasdiangelo91@gmail.com",
      user_metadata: {},
    } as never;
    const metadataAdmin = {
      email: "someone@example.com",
      user_metadata: { role: "admin" },
    } as never;
    const regular = {
      email: "dev@example.com",
      user_metadata: { role: "candidate" },
    } as never;

    expect(isAdminUser(admin)).toBe(true);
    expect(isAllowedAdminUser(metadataAdmin)).toBe(true);
    expect(isAdminUser(regular)).toBe(false);
    expect(getPostLoginPath(admin)).toBe("/admin");
    expect(getPostLoginPath(regular)).toBe("/dashboard");

    const originalWindow = globalThis.window;
    const originalDocument = globalThis.document;
    Object.defineProperty(globalThis, "window", {
      configurable: true,
      value: {
        location: {
          origin: "https://getprovix.com",
          pathname: "/login",
          search: "?next=/opportunities",
        },
      },
    });
    Object.defineProperty(globalThis, "document", {
      configurable: true,
      value: { cookie: "" },
    });
    expect(buildOAuthCallbackUrl()).toBe(
      "https://getprovix.com/auth/callback"
    );

    Object.defineProperty(globalThis, "window", {
      configurable: true,
      value: {
        location: {
          origin: "https://getprovix.com",
          pathname: "/pricing",
          search: "",
        },
      },
    });
    expect(buildOAuthCallbackUrl()).toBe(
      "https://getprovix.com/auth/callback"
    );

    Object.defineProperty(globalThis, "window", {
      configurable: true,
      value: {
        location: {
          origin: "https://getprovix.com",
          pathname: "/audit",
          search: "",
        },
      },
    });
    expect(buildOAuthCallbackUrl()).toBe(
      "https://getprovix.com/auth/callback"
    );

    if (originalWindow) {
      Object.defineProperty(globalThis, "window", {
        configurable: true,
        value: originalWindow,
      });
    } else {
      // @ts-expect-error cleanup test window shim
      delete globalThis.window;
    }
    if (originalDocument) {
      Object.defineProperty(globalThis, "document", {
        configurable: true,
        value: originalDocument,
      });
    }
  });
});

import { describe, expect, it } from "vitest";
import {
  EMPLOYER_DASHBOARD_PATH,
  ROLE_ONBOARDING_PATH,
  isEmployerAuthIntent,
  normalizeAccountKind,
  resolveAccountRole,
  resolvePostAuthDestination,
  signupRoleFromSearch,
} from "@/lib/account-role";
import {
  canAccessTalentPool,
  isEmployeeRole,
  isEmployerRole,
  isProtectedAppPath,
  isVerifiedEmployerFlag,
  shouldSkipMiddlewareAuth,
} from "@/lib/dashboard-account";
import {
  getPostLoginPath,
  isAdminUser,
  isAllowedAdminUser,
} from "@/lib/admin-access";
import { AUTH_SESSION_TIMEOUT_MS } from "@/lib/auth-session-timeout";
import { buildOAuthCallbackUrl } from "@/lib/auth-callback-url";
import {
  getCorporateWorkEmailValidationMessage,
