describe("database query helpers", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("resolves daily scan usage and resets across UTC days", () => {
    const sameDay = resolveDailyScanUsage(4, "2026-10-02", "2026-10-02");
    expect(sameDay).toEqual({
      daily_scans: 4,
      last_scan_date: "2026-10-02",
      limit_reached: false,
      remaining: DAILY_SCAN_LIMIT - 4,
    });

    const nextDay = resolveDailyScanUsage(10, "2026-10-01", "2026-10-02");
    expect(nextDay.daily_scans).toBe(0);
    expect(nextDay.limit_reached).toBe(false);
    expect(nextDay.remaining).toBe(DAILY_SCAN_LIMIT);

    const capped = resolveDailyScanUsage(10, "2026-10-02", "2026-10-02");
    expect(capped.limit_reached).toBe(true);
    expect(capped.remaining).toBe(0);
  });

  it("loads and increments daily scan counters through profiles queries", async () => {
    const today = new Date().toISOString().slice(0, 10);
    const loaded = createProfilesClient({
      selectData: { daily_scans: 2, last_scan_date: today },
    });
    const usage = await loadDailyScanUsage(
      loaded.client as never,
      "11111111-1111-4111-8111-111111111111"
    );
    expect(usage.error).toBeNull();
    expect(usage.usage.daily_scans).toBe(2);
    expect(loaded.calls.some((call) => call.op === "select")).toBe(true);

    const failing = createProfilesClient({
      selectError: { message: "relation missing" },
    });
    const failed = await loadDailyScanUsage(
      failing.client as never,
      "11111111-1111-4111-8111-111111111111"
    );
    expect(failed.error).toBe("relation missing");
    expect(failed.usage.daily_scans).toBe(0);

    const writer = createProfilesClient({});
    const next = await incrementDailyScanUsage(
      writer.client as never,
      "11111111-1111-4111-8111-111111111111",
      resolveDailyScanUsage(2, today, today)
    );
    expect(next.daily_scans).toBe(3);
    expect(writer.calls.some((call) => call.op === "update")).toBe(true);
  });

  it("parses shared audit payloads and validates UUID ids", async () => {
    const validId = "aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee";
    expect(isSharedAuditId(validId)).toBe(true);
    expect(isSharedAuditId("not-a-uuid")).toBe(false);

    const metrics = emptyProductionAuditMetrics();
    metrics.evidence.inspected = true;
    const parsed = parseSharedAuditPayload(validId, {
      repoName: "acme/widgets",
      repoUrl: "https://github.com/acme/widgets",
      result: {
        score: 72,
        strengths: ["typed source"],
        redFlags: [1, "missing CI"],
        recommendations: ["add workflow"],
        checks: [],
        scoreCap: emptyScoreCapAudit(72),
        metrics,
        filesystem: null,
        commitDates: ["2026-09-01"],
        executiveBrief: {
          employerSummary: "Scoped product bet.",
          developerSummary: "Add CI first.",
          recommendedRoleBand: "Needs Hardening",
        },
      },
    });

    expect(parsed?.repoName).toBe("acme/widgets");
    expect(parsed?.result.score).toBe(72);
    expect(parsed?.result.redFlags).toEqual(["missing CI"]);
    expect(parsed?.result.executiveBrief?.recommendedRoleBand).toBe(
      "Needs Hardening"
    );
    expect(parseSharedAuditPayload(validId, { result: { score: "bad" } })).toBeNull();

    const { createClient } = await import("@/utils/supabase/server");
    vi.mocked(createClient).mockResolvedValue({
      from: () => ({
        select: () => ({
          eq: () => ({
            maybeSingle: async () => ({
              data: {
                id: validId,
                payload: {
                  repoName: "acme/widgets",
                  result: {
                    score: 72,
                    metrics,
                    strengths: [],
                    redFlags: [],
                    recommendations: [],
                    checks: [],
                  },
                },
              },
              error: null,
            }),
          }),
        }),
      }),
    } as never);

    const shared = await getSharedAudit(validId);
    expect(shared?.id).toBe(validId);
    expect(await getSharedAudit("bad-id")).toBeNull();
  });

  it("normalizes profile ids and job feed query results", async () => {
    const id = "22222222-2222-4222-8222-222222222222";
    expect(isProfileUuid(id)).toBe(true);
    expect(isProfileUuid("nope")).toBe(false);
    expect(uniqueCandidateIds([id, id, null, "bad"])).toEqual([id]);
    expect(
      profileRowLookupKeys({
        id,
        user_id: "33333333-3333-4333-8333-333333333333",
      })
    ).toContain(id);

    expect(parseJobListInput(["React", "react", "TypeScript"])).toEqual([
      "React",
      "TypeScript",
    ]);
    expect(
      jobDisplayTags({
        tech_stack: ["Next.js"],
        required_skills: ["TypeScript"],
        tags: ["ignored"],
      })
    ).toEqual(["Next.js", "TypeScript"]);
    expect(
      toJobMatchJobPayload({
        id: "job-1",
        title: "Engineer",
        company: "Acme",
        location: null,
        salary_range: null,
        tags: ["node"],
        tech_stack: ["Node.js"],
        required_skills: [],
        employer_id: id,
        status: "active",
      }).requiredSkills
    ).toEqual(["node"]);

    const jobs = createJobsClient([
      {
        data: [
          {
            id: "job-1",
            title: "Engineer",
            company: "Acme",
            location: null,
            salary_range: null,
            tags: ["node"],
            employer_id: id,
            status: "active",
          },
        ],
        error: null,
      },
    ]);
    const feed = await fetchPublicJobFeed(jobs as never);
    expect(feed.error).toBeNull();
    expect(feed.data).toHaveLength(1);

    const kind = await loadProfileAccountKind(
      createProfilesClient({ selectData: { role: "employer" } }).client,
      id
    );
    expect(kind).toBe("employer");

    const role = await loadStoredAccountRole(
      createProfilesClient({ selectData: { role: "candidate" } }).client,
      { id, user_metadata: {} } as never
    );
    expect(role).toBe("candidate");
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  CORPORATE_WORK_EMAIL_MESSAGE,
  extractEmailDomain,
  getCorporateWorkEmailValidationMessage,
  isCorporateWorkEmail,
  isFreeWebmailDomain,
} from "@/lib/corporate-email";
import {
  buildEmployerVerificationConfirmUrl,
  generateEmployerVerificationToken,
  hashEmployerVerificationToken,
} from "@/lib/employer-email-verification";
import {
  buildPasswordResetRedirectUrl,
  getStandardEmailValidationMessage,
  isStandardEmail,
  normalizeEmail,
} from "@/lib/validate-email";
import {
  buildEmployerVerificationEmailHtml,
  sendEmployerVerificationEmail,
} from "@/lib/send-employer-verification-email";
import { buildCandidateIntroRequestEmailHtml } from "@/lib/send-intro-email";

const sendMock = vi.fn();

vi.mock("resend", () => ({
  Resend: class {
    emails = { send: sendMock };
  },
}));

describe("email dispatcher helpers and payload validation", () => {
  const originalResendKey = process.env.RESEND_API_KEY;

  beforeEach(() => {
    sendMock.mockReset();
    delete process.env.RESEND_API_KEY;
  });

  afterEach(() => {
    if (originalResendKey === undefined) {
      delete process.env.RESEND_API_KEY;
    } else {
      process.env.RESEND_API_KEY = originalResendKey;
    }
  });

  it("validates standard and corporate work email payloads", () => {
    expect(normalizeEmail("  founder@acme.com ")).toBe("founder@acme.com");
    expect(isStandardEmail("founder@acme.com")).toBe(true);
    expect(isStandardEmail("not-an-email")).toBe(false);
    expect(getStandardEmailValidationMessage("")).toBe(
      "Enter your email address."
    );
    expect(getStandardEmailValidationMessage("bad")).toBe(
      "Enter a valid email address."
    );
    expect(getStandardEmailValidationMessage("ok@acme.io")).toBeNull();

    expect(extractEmailDomain("Founder@Acme.IO")).toBe("acme.io");
    expect(isFreeWebmailDomain("gmail.com")).toBe(true);
    expect(isCorporateWorkEmail("hire@gmail.com")).toBe(false);
    expect(isCorporateWorkEmail("hire@acme.io")).toBe(true);
    expect(getCorporateWorkEmailValidationMessage("hire@gmail.com")).toBe(
      CORPORATE_WORK_EMAIL_MESSAGE
    );
    expect(getCorporateWorkEmailValidationMessage("hire@acme.io")).toBeNull();
  });

  it("builds verification tokens, confirm URLs, and escaped HTML payloads", () => {
    const { token, tokenHash } = generateEmployerVerificationToken();
    expect(token.length).toBeGreaterThan(20);
    expect(tokenHash).toBe(hashEmployerVerificationToken(token));
    expect(tokenHash).not.toBe(token);

    const confirmUrl = buildEmployerVerificationConfirmUrl(
      "https://getprovix.com",
      token
    );
    expect(confirmUrl.startsWith(
      "https://getprovix.com/verify-email?token="
    )).toBe(true);
    expect(new URL(confirmUrl).searchParams.get("token")).toBe(token);

    // www origins are normalized to apex so email links stay spam-filter friendly.
    expect(
      buildEmployerVerificationConfirmUrl("https://www.getprovix.com", token)
    ).toBe(confirmUrl);

    const html = buildEmployerVerificationEmailHtml({
      confirmUrl: 'https://example.com/confirm?x="1"',
      workEmail: 'hire@acme.io<script>',
    });
    expect(html).toContain("Provix Employer Verification");
    expect(html).toContain("hire@acme.io&lt;script&gt;");
    expect(html).toContain('href="https://example.com/confirm?x=&quot;1&quot;"');
    expect(html).not.toContain("<script>");

    const introHtml = buildCandidateIntroRequestEmailHtml({
      candidateName: "Ada <Lovelace>",
      companyName: "Acme & Co",
      companyEmail: "talent@acme.io",
      targetRole: "Full-Stack Engineer",
      compensationRange: "$120k–$140k",
      acceptUrl: "https://getprovix.com/accept",
      declineUrl: "https://getprovix.com/decline",
      dashboardUrl: "https://getprovix.com/dashboard",
    });
    expect(introHtml).toContain("Ada &lt;Lovelace&gt;");
    expect(introHtml).toContain("Acme &amp; Co");
    expect(introHtml).toContain("Accept Intro");
    expect(buildPasswordResetRedirectUrl("https://www.getprovix.com")).toBe(
      "https://www.getprovix.com/auth/callback?next=%2Fupdate-password"
    );
  });

  it("dispatches employer verification email through Resend when configured", async () => {
    await expect(
      sendEmployerVerificationEmail({
        to: "hire@acme.io",
        confirmUrl: "https://getprovix.com/confirm",
      })
    ).resolves.toEqual({
      error:
        "Email delivery is not configured. Set RESEND_API_KEY and try again.",
    });
    expect(sendMock).not.toHaveBeenCalled();

    process.env.RESEND_API_KEY = "re_test_key";
    sendMock.mockResolvedValue({ error: null });

    await expect(
      sendEmployerVerificationEmail({
        to: "hire@acme.io",
        confirmUrl: "https://getprovix.com/confirm",
      })
    ).resolves.toEqual({ error: null });

    expect(sendMock).toHaveBeenCalledWith(
      expect.objectContaining({
        from: "Provix <notifications@getprovix.com>",
        to: "hire@acme.io",
        subject: "Confirm your Provix employer email",
        html: expect.stringContaining("hire@acme.io"),
      })
    );

    sendMock.mockResolvedValue({ error: { message: "rate limited" } });
    await expect(
      sendEmployerVerificationEmail({
        to: "hire@acme.io",
        confirmUrl: "https://getprovix.com/confirm",
      })
    ).resolves.toEqual({
      error: "Could not send the confirmation email. Try again shortly.",
    });
  });
});

import { describe, expect, it } from "vitest";
import {
  countUnhandledAsyncCalls,
  preferSourceSamplePaths,
} from "@/lib/audit-content-signals";
import {
  classifyRepoFilesystem,
  isExecutableCodeFile,
  isNoisePath,
  isSourceFile,
  isTestPath,
} from "@/lib/repo-filesystem";

describe("filesystem and content heuristics", () => {
  it("ignores vendor and demo noise while classifying source and tests", () => {
    expect(isNoisePath("node_modules/lodash/index.js")).toBe(true);
    expect(isNoisePath("examples/demo/app.ts")).toBe(true);
    expect(isSourceFile("src/lib/auth.ts")).toBe(true);
    expect(isExecutableCodeFile("src/components/ui/button.tsx")).toBe(true);
    expect(isTestPath("src/lib/auth.test.ts")).toBe(true);
    expect(isSourceFile("src/lib/auth.test.ts")).toBe(false);
  });

  it("classifies a web app file tree into scoring buckets", () => {
    const evidence = classifyRepoFilesystem(
      [
        "package.json",
        "tsconfig.json",
        "next.config.ts",
        "src/app/layout.tsx",
        "src/app/page.tsx",
        "src/app/error.tsx",
        "src/app/api/audit/route.ts",
        "src/lib/auth.ts",
        "src/lib/auth.test.ts",
        ".github/workflows/ci.yml",
        "node_modules/react/index.js",
        "docs/readme-extra.md",
      ],
      { inspected: true }
    );

    expect(evidence.inspected).toBe(true);
    expect(evidence.repo_kind).toBe("web_app");
    expect(evidence.test_paths.length).toBeGreaterThan(0);
    expect(evidence.ci_workflow_paths.length).toBeGreaterThan(0);
    expect(evidence.error_handling_paths.length).toBeGreaterThan(0);
    expect(evidence.sample_paths.some((path) => path.includes("node_modules"))).toBe(
      false
    );
  });

  it("prefers API routes for content sampling and counts unhandled async", () => {
    const sampled = preferSourceSamplePaths(
      [
        "src/components/ui/button.tsx",
        "src/app/api/audit/route.ts",
        "src/lib/client.ts",
        "src/utils/format.ts",
      ],
      2
    );
    expect(sampled[0]).toContain("api/audit/route");

    expect(
      countUnhandledAsyncCalls(`
        export async function load() {
          return await fetch("/api");
        }
      `)
    ).toBeGreaterThan(0);

    expect(
      countUnhandledAsyncCalls(`
        export async function load() {
          try {
            return await fetch("/api");
          } catch {
            return null;
          }
        }
      `)
    ).toBe(0);
  });
});

import { describe, expect, it } from "vitest";
import {
  applyUpstreamDerivativePenalty,
  computeProductionAuditMetrics,
  PRODUCTION_METRIC_WEIGHTS,
  scoreArchitecture,
  scoreResilience,
  scoreTesting,
  UPSTREAM_DERIVATIVE_PENALTY,
  weightedProductionScore,
} from "@/lib/production-audit-metrics";
import { classifyRepoFilesystem } from "@/lib/repo-filesystem";

describe("core production scoring", () => {
  it("weights fulltime pillars at 30/25/15/30", () => {
    expect(PRODUCTION_METRIC_WEIGHTS).toEqual({
      architecture: 0.3,
      testing: 0.3,
      devops: 0.15,
      resilience: 0.25,
    });
    expect(
      weightedProductionScore(
        {
          architecture: 100,
          testing: 80,
          devops: 60,
          resilience: 40,
        },
        "fulltime"
      )
    ).toBe(Math.round(100 * 0.3 + 80 * 0.3 + 60 * 0.15 + 40 * 0.25));
  });

  it("caps scaffold architecture and floors upstream forks", () => {
    const filesystem = classifyRepoFilesystem(
      [
        "package.json",
        "tsconfig.json",
        "next.config.ts",
        "src/app/layout.tsx",
        "src/app/page.tsx",
        "eslint.config.mjs",
      ],
      { inspected: true }
    );

    expect(scoreArchitecture(filesystem)).toBeLessThanOrEqual(82);
    expect(applyUpstreamDerivativePenalty(70, true)).toBe(
      70 - UPSTREAM_DERIVATIVE_PENALTY
    );
    expect(applyUpstreamDerivativePenalty(20, true)).toBe(0);
    expect(applyUpstreamDerivativePenalty(70, false)).toBe(70);
  });

  it("scores testing and resilience from inspected evidence", () => {
    const filesystem = classifyRepoFilesystem(
      [
        "package.json",
        "tsconfig.json",
        "src/index.ts",
        "src/client.ts",
        "src/index.test.ts",
        "src/app/error.tsx",
        ".github/workflows/ci.yml",
      ],
      { inspected: true }
    );
    const metrics = computeProductionAuditMetrics(filesystem);

    expect(scoreTesting(filesystem)).toBeGreaterThan(0);
    expect(scoreResilience(filesystem, filesystem.repo_kind)).toBeGreaterThan(
      0
    );
    expect(metrics.productionScore).toBe(
      weightedProductionScore(
        {
          architecture: metrics.architecture,
          testing: metrics.testing,
          devops: metrics.devops,
          resilience: metrics.resilience,
        },
        "contract"
      )
    );
  });
});

