  const handleVisibilityToggle = async () => {
    if (isTogglingVisibility) return;

    const nextVisible = !isVisibleInPool;
    // Match the green "✓ Linked / Ownership verified" status exactly — including
    // repo-namespace ownership when verification_status is not yet "verified".
    const toggleGitHubUsername = (dbProfile?.github_username ?? "")
      .replace(/^@/, "")
      .trim();
    const toggleAudit = parseProductionAuditFromProfileRow(dbProfile);
    const githubLinked = isTalentPoolGitHubLinked({
      githubVerified: dbProfile?.github_verified === true,
      githubUsername: toggleGitHubUsername,
    });
    const toggleOwnershipVerified = isTalentPoolOwnershipVerified({
      verificationStatus: dbProfile?.verification_status,
      isAuditVerified:
        dbProfile?.is_audit_verified === true ||
        toggleAudit?.isAuditVerified === true,
      auditedRepoUrl: resolveTalentPoolAuditedRepoUrl({
        auditedRepoUrl: toggleAudit?.breakdown.audited_repo_url,
        auditBreakdown: dbProfile?.audit_breakdown,
        portfolioUrl: dbProfile?.portfolio_url ?? portfolioUrl,
      }),
      auditBreakdown: dbProfile?.audit_breakdown,
      portfolioUrl: dbProfile?.portfolio_url ?? portfolioUrl,
      githubUsername: toggleGitHubUsername,
    });
    const toggleScores = [
      dbProfile?.production_score,
      dbProfile?.audit_score,
      toggleAudit?.productionScore,
    ];
    const canEnable = canEnableTalentPoolVisibility({
      githubVerified: githubLinked,
      ownershipVerified: toggleOwnershipVerified,
      scores: toggleScores,
    });
    if (nextVisible && !canEnable) {
      showToast(
        talentPoolVisibilityFailureMessage({
          githubVerified: githubLinked,
          ownershipVerified: toggleOwnershipVerified,
          scores: toggleScores,
        })
      );
      setIsVisibleInPool(false);
      return;
    }

    // Persist gates against auth.uid(); prefer the session user id over profile.id.
    const profileId = user?.id ?? dbProfile?.id;
    if (!profileId) {
      showToast("You must be logged in to update visibility.");
      return;
    }

    const previousVisible = isVisibleInPool;
    const previousPubliclyVisible = dbProfile?.is_publicly_visible === true;
    setIsVisibleInPool(nextVisible);
    setIsTogglingVisibility(true);

    try {
      const supabase = createClient();
      const { error, userMessage } = await persistCandidatePoolVisibility(
        supabase,
        profileId,
        nextVisible
      );

      if (error) {
        setIsVisibleInPool(previousVisible);
        showToast(
          userMessage ?? "Could not update Provix Talent Network visibility. Please try again."
        );
        return;
      }

      // Keep scorecard public visibility aligned with the single employer toggle.
      try {
        const scorecardResponse = await fetchWithAuth(
          "/api/profile/production-audit",
          {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ is_publicly_visible: nextVisible }),
          }
        );
        if (!scorecardResponse.ok) {
          console.warn(
            "Scorecard visibility sync failed:",
            scorecardResponse.status
          );
        }
      } catch (scorecardError) {
        console.warn("Scorecard visibility sync threw:", scorecardError);
      }

      setDbProfile((prev) =>
        prev
          ? {
              ...prev,
              is_visible_in_pool: nextVisible,
              visible_to_employers: nextVisible,
              is_publicly_visible: nextVisible,
            }
          : prev
      );
      setSavedCandidateProfile((prev) =>
        prev ? { ...prev, visibleInPool: nextVisible } : prev
      );
      void publishTalentPoolVisibility(supabase, {
        profileId,
        visible: nextVisible,
      });
      showToast(
        nextVisible
          ? "You are now visible to employers."
          : "You are hidden from the Provix Talent Network."
      );
    } catch (error) {
      setDbProfile((prev) =>
        prev
          ? { ...prev, is_publicly_visible: previousPubliclyVisible }
          : prev
      );
      console.error("Talent pool visibility update failed:", error);
      setIsVisibleInPool(previousVisible);
      showToast("Could not update Provix Talent Network visibility. Please try again.");
