    try {
      const supabase = createClient();
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();

      if (sessionError || !session?.user?.id) {
        console.error(
          "Profile update failed: missing session",
          serializePersistError(sessionError)
        );
        showToast("You must be logged in to save your profile.");
        return;
      }

      const academicPrimary = primaryEducationFields(nextEducation);
      const academicMajor = academicPrimary.fieldOfStudy;
      const academicInstitution = academicPrimary.institution;
      const academicGradYear = academicPrimary.graduationYear;
      const normalizedPortfolioUrl = normalizeGitHubUrl(portfolioUrl);
      const effectiveVisibleInPool =
        isVisibleInPool && isValidGitHubUrl(normalizedPortfolioUrl);
      if (isVisibleInPool && !effectiveVisibleInPool) {
        setIsVisibleInPool(false);
      }
      const gatedOpenToFulltime = canToggleFullTime && openToFulltime;
      const gatedOpenToContract = canToggleContract && openToContract;
      const normalizedAvailability = normalizeAvailabilityStatus(
        gatedOpenToFulltime || gatedOpenToContract
          ? "Available Now"
          : "Not Available"
      );
      const normalizedContractRate = gatedOpenToContract
        ? normalizeContractHourlyRate(contractHourlyRate)
        : null;
      const normalizedContractHours = gatedOpenToContract
        ? normalizeContractHoursPerWeek(contractHoursPerWeek)
        : "";
      const contractDetailsError = getContractDetailsValidationError(
        gatedOpenToContract,
        normalizedContractHours,
        normalizedContractRate
      );
      if (contractDetailsError) {
        showToast(contractDetailsError);
        return;
      }
      const payload = buildCandidateProfileUpdatePayload(
        {
          fullName: profileData.name,
          jobTitle: title,
          bio,
          university: academicInstitution,
          major: academicMajor,
          degree: academicPrimary.credentialType,
          skills,
          education: nextEducation,
          isSelfTaught,
          portfolioUrl: normalizedPortfolioUrl,
          youtubeUrl: dbProfile?.youtube_url ?? "",
          experienceLevel,
          availabilityStatus: normalizedAvailability,
          workPreference,
          candidateTimezone,
          openToFulltime: gatedOpenToFulltime,
          openToContract: gatedOpenToContract,
          contractHoursPerWeek: normalizedContractHours,
          contractHourlyRate: normalizedContractRate,
          isVisibleInPool: effectiveVisibleInPool,
          gradYear: academicGradYear,
          gpa: formatGpa(profileData.gpa),
          keyAccomplishments: profileData.projects,
        },
        session.user.id,
        { existingProfileSlug: dbProfile?.profile_slug }
      );

      const { data, error, userMessage } = await persistCandidateProfile(
        supabase,
        session.user.id,
        payload
      );

      if (error) {
        console.error("Profile update failed:", {
          ...serializePersistError(error),
          userMessage,
          contractHourlyRateInput: contractHourlyRate,
          normalizedContractRate,
          payloadContractHourlyRate: payload.contract_hourly_rate,
          payloadContractHoursPerWeek: payload.contract_hours_per_week,
          payloadOpenToContract: payload.open_to_contract,
          payloadOpenToFulltime: payload.open_to_fulltime,
          marketplaceBaseReady,
          canToggleContract,
          canToggleFullTime,
          githubUsername: marketplaceGitHubUsername,
          githubVerified: marketplaceGithubVerified,
          ownershipVerified: marketplaceOwnershipVerified,
