                        </td>
                        <td className="px-5 py-4 align-top text-textMuted">
                          {request.compensation_band || "—"}
                        </td>
                        <td className="px-5 py-4 align-top">
                          <span
                            className={`inline-flex rounded-full border px-2.5 py-1 text-[11px] font-bold uppercase tracking-wide ${getIntroStatusBadgeClass(request.status)}`}
                          >
                            {getIntroStatusLabel(request.status)}
                          </span>
                        </td>
                        <td className="px-5 py-4 align-top min-w-[240px]">
                          <div className="space-y-3">
                            <select
                              value={selectedStatus}
                              onChange={(event) =>
                                handleStatusDraftChange(
                                  request.id,
                                  event.target.value as IntroPipelineStatus
                                )
                              }
                              disabled={isUpdating}
                              className="w-full bg-background border border-border rounded-xl px-3 py-2 text-xs text-textMain focus:outline-none focus:border-brand"
                            >
                              {INTRO_PIPELINE_STATUSES.map((status) => (
                                <option key={status.value} value={status.value}>
                                  {status.label}
                                </option>
                              ))}
                            </select>

                            {selectedStatus === "hired" && (
                              <div>
                                <label className="block text-[10px] font-bold uppercase tracking-wider text-textMuted mb-1.5">
                                  Agreed First-Year Compensation
                                </label>
                                <input
                                  type="number"
                                  min="0"
                                  step="1000"
                                  value={compensationDraft}
                                  onChange={(event) =>
                                    handleCompensationDraftChange(
                                      request.id,
                                      event.target.value
                                    )
                                  }
                                  placeholder="e.g. 85000"
                                  disabled={isUpdating}
                                  className="w-full bg-background border border-border rounded-xl px-3 py-2 text-xs text-textMain placeholder:text-textMuted focus:outline-none focus:border-brand"
                                />
                              </div>
                            )}

                            <button
                              type="button"
                              disabled={isUpdating}
                              onClick={() => void updateIntroRequest(request)}
                              className="inline-flex items-center gap-1.5 rounded-lg border border-brand/30 bg-brandGlow px-3 py-1.5 text-[11px] font-bold text-brand hover:bg-brandHover/20 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                            >
                              {isUpdating ? (
                                <>
                                  <Loader2
                                    className="w-3.5 h-3.5 animate-spin"
                                    aria-hidden
                                  />
                                  Saving...
                                </>
                              ) : (
                                "Save Pipeline Update"
                              )}
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

import { NextResponse } from "next/server";
import { z } from "zod";
import {
  parseIntroRequestId,
  requireAdminApiAccess,
} from "@/lib/admin-api-auth";
import { parseJsonWithSchema } from "@/lib/parse-request-json";
import { sendIntroEmail } from "@/lib/send-intro-email";

const adminActionBodySchema = z.object({
  id: z.string().optional(),
  requestId: z.string().optional(),
  introId: z.string().optional(),
});

export async function POST(request: Request) {
  try {
    const access = await requireAdminApiAccess();
    if (access instanceof NextResponse) {
      return access;
    }

    const parsedBody = await parseJsonWithSchema(request, adminActionBodySchema);
    if (!parsedBody.ok) {
      return parsedBody.response;
    }

    const requestId = parseIntroRequestId(parsedBody.data);

    if (!requestId) {
      return NextResponse.json(
        { error: "Intro request id is required" },
        { status: 400 }
      );
    }

    const { data: updatedRequest, error: updateError } = await access.dataClient
      .from("intro_requests")
      .update({ status: "approved_intro_sent" })
      .eq("id", requestId)
      .select()
      .single();

    if (updateError) {
      console.error("Admin approve update error:", updateError);
      return NextResponse.json(
        { error: "Could not update intro request status" },
        { status: 500 }
      );
    }

    if (!updatedRequest) {
      return NextResponse.json(
        { error: "Intro request not found" },
        { status: 404 }
      );
    }

    await sendIntroEmail(updatedRequest, access.dataClient);

    return NextResponse.json(
      { success: true, data: updatedRequest },
      { status: 200 }
    );
  } catch (error) {
    console.error("Admin approve error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { fetchProfilesForCandidateIds } from "@/lib/resolve-candidate-profile";
import { requireAdminApiAccess } from "@/lib/admin-api-auth";

const JOB_COLUMNS = "id, title, company, employer_id, created_at";
const APPLICATION_COLUMNS = "id, job_id, candidate_id, created_at";
const CANDIDATE_DOSSIER_COLUMNS =
  "id, full_name, codename_alias, contact_email, email, phone, linkedin_url, portfolio_url, bio, major, headline, job_title";

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
    value
  );
}

export async function GET() {
  try {
    const access = await requireAdminApiAccess();
    if (access instanceof NextResponse) {
      return access;
    }

    const { data: jobs, error: jobsError } = await access.dataClient
      .from("jobs")
      .select(JOB_COLUMNS)
      .order("created_at", { ascending: false });

    if (jobsError) {
      console.error("Admin jobs fetch error:", jobsError);
      return NextResponse.json(
        { error: "Could not load job postings" },
        { status: 500 }
      );
    }

    const { data: applications, error: applicationsError } =
      await access.dataClient
        .from("job_applications")
        .select(APPLICATION_COLUMNS)
        .order("created_at", { ascending: false });

    if (applicationsError) {
      console.error("Admin job applications fetch error:", applicationsError);
      return NextResponse.json(
        { error: "Could not load job interest submissions" },
        { status: 500 }
      );
    }

    const candidateIds = [
      ...new Set(
        (applications ?? [])
          .map((row) => row.candidate_id)
          .filter((value): value is string => Boolean(value && isUuid(value)))
      ),
    ];

    let dossierById = new Map<string, Record<string, unknown>>();

    if (candidateIds.length > 0) {
      dossierById = await fetchProfilesForCandidateIds(
        access.dataClient,
        candidateIds,
        CANDIDATE_DOSSIER_COLUMNS
      );
    }

    const applicationsByJobId = new Map<
      string,
      Array<{
        id: string;
        candidate_id: string;
        created_at: string;
        candidate_dossier: Record<string, unknown> | null;
      }>
    >();

    for (const application of applications ?? []) {
      const bucket = applicationsByJobId.get(application.job_id) ?? [];
      bucket.push({
        id: application.id,
        candidate_id: application.candidate_id,
        created_at: application.created_at,
        candidate_dossier: dossierById.get(application.candidate_id) ?? null,
      });
      applicationsByJobId.set(application.job_id, bucket);
    }

    const data = (jobs ?? []).map((job) => {
      const applicants = applicationsByJobId.get(job.id) ?? [];
      return {
        job_id: job.id,
        title: job.title,
        company: job.company,
        employer_id: job.employer_id,
        created_at: job.created_at,
        interest_count: applicants.length,
        applicants,
      };
    });

    return NextResponse.json({ data });
  } catch (error) {
    console.error("Admin job applications error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import {
  parseIntroRequestId,
  requireAdminApiAccess,
} from "@/lib/admin-api-auth";
import { parseJsonWithSchema } from "@/lib/parse-request-json";

const adminActionBodySchema = z.object({
  id: z.string().optional(),
  requestId: z.string().optional(),
  introId: z.string().optional(),
});

export async function POST(request: Request) {
  try {
    const access = await requireAdminApiAccess();
    if (access instanceof NextResponse) {
      return access;
    }

    const parsedBody = await parseJsonWithSchema(request, adminActionBodySchema);
    if (!parsedBody.ok) {
      return parsedBody.response;
    }

    const requestId = parseIntroRequestId(parsedBody.data);

    if (!requestId) {
