function attachModeEvaluation(
  result: AuditResult,
  mode: AuditMode,
  metrics: ProductionAuditMetrics,
  summaryFallback?: string
): AuditResult {
  const evaluation = buildModeAwareEvaluation(mode, {
    architecture: metrics.architecture,
    testing: metrics.testing,
    devops: metrics.devops,
    resilience: metrics.resilience,
  });
  // Prefer the metrics headline (Code Health / productionScore) over a raw
  // pillar re-blend.
  const headlineScore = clampScore0to100(metrics.productionScore);
  const tier = assignAuditTier(mode, headlineScore);
  const summary =
    result.summary?.trim() ||
    result.executiveBrief?.employerSummary?.trim() ||
    summaryFallback?.trim() ||
    `${auditModeLabel(mode)} · ${tier} · ${headlineScore}/100.`;
  const improvements =
    result.improvements?.length >= 3
      ? result.improvements.slice(0, 3)
      : result.recommendations.slice(0, 3);

  return {
    ...result,
    score: headlineScore,
    overallScore: headlineScore,
    auditMode: mode,
    tier,
    breakdown: evaluation.breakdown,
    summary,
    improvements,
    metrics: {
      ...metrics,
      productionScore: headlineScore,
      codeHealthScore: headlineScore,
    },
  };
}

const MODEL_CANDIDATES = [
  "gemini-3.6-flash",
  "gemini-3.5-flash-lite",
] as const;

function isGeminiUnavailableError(error: unknown): boolean {
  if (!error || typeof error !== "object") {
    return false;
  }
  const record = error as { status?: unknown; message?: unknown };
  if (record.status === 503) {
    return true;
  }
  const message =
    typeof record.message === "string"
      ? record.message
      : error instanceof Error
        ? error.message
        : "";
  return /"code"\s*:\s*503|"status"\s*:\s*"UNAVAILABLE"|high demand/i.test(
    message
  );
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function clampScore(value: unknown): number {
  return clampScore0to100(value, 0);
}

function normalizeStringArray(value: unknown, maxItems = 6): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is string => typeof item === "string")
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, maxItems);
}

function isMissingResumeFlag(text: string): boolean {
  const value = text.trim();
  if (!value) {
    return false;
  }

  return (
    /no resume|missing resume|without (a )?resume|lack of (a )?resume/i.test(
      value
    ) ||
    /(resume|cv|experience summary).{0,24}(not (provided|uploaded|included|submitted|attached)|is missing|was missing)/i.test(
      value
    ) ||
    /resume or experience summary/i.test(value)
  );
}

/** Rewrite LLM copy that still claims History −25 (or similar oversized cadence dings). */
function sanitizeHistoryPenaltyCopy(text: string): string {
  return text
    .replace(
      /History\s*[:−-]?\s*−?\s*\d+\b/gi,
      "activity: informational only"
    )
    .replace(
      /(?:history|commit(?:\s+history)?|cadence|inactiv(?:e|ity)|stale)\b[^.]{0,80}?(?:−|-|minus\s+)\s*\d+\s*(?:pts?|points?)?/gi,
      (match) =>
        match.replace(
          /(?:−|-|minus\s+)\s*\d+\s*(?:pts?|points?)?/i,
          " (informational, no score impact)"
        )
    );
}

function optionalFilesystem(value: unknown): RepoFilesystemEvidence | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }

  return parseRepoFilesystemEvidence(value);
}

function attachAuditEvidence(
  result: AuditResult,
  filesystem: RepoFilesystemEvidence | null,
  commitDates: string[],
  commitStats?: CommitHistoryStat[]
): AuditResult {
  return {
    ...result,
    filesystem,
    commitDates: normalizeCommitDates(commitDates),
    commitStats: Array.isArray(commitStats) ? commitStats : [],
  };
}

function isJavaScriptFamily(language: string | null | undefined): boolean {
  const value = (language ?? "").trim().toLowerCase();
  return (
    value === "typescript" ||
    value === "javascript" ||
    value === "tsx" ||
    value === "jsx"
  );
}

function repoHasReadme(
  githubArtifacts: GitHubArtifactAudit | null,
  filesystem: RepoFilesystemEvidence | null
): boolean {
  if (githubArtifacts?.artifacts.some((artifact) => artifact.readme_excerpt?.trim())) {
    return true;
  }
  const paths = [
    ...(filesystem?.sample_paths ?? []),
    ...(filesystem?.architecture_paths ?? []),
  ];
  return paths.some((path) => /(^|\/)readme(\.[^/]+)?$/i.test(path));
}

function primaryRepoLanguage(
  githubArtifacts: GitHubArtifactAudit | null
): string | null {
  return githubArtifacts?.artifacts.find((artifact) => artifact.language)?.language ?? null;
}

const REAL_TEST_FILE_COPY =
  /add a real test file|tests\/test_app\.py|\*_test\.go|_test\.go/i;
const README_COPY = /add a concise readme|readme per repo|with readme/i;
const EXPAND_TESTS_COPY = /integration coverage|end-to-end|e2e test/i;
const PROMPT_LEAK_COPY =
  /name the exact workflow file or route handler that would lift the lowest pillar/i;

function refineActionableFixes(
  recommendations: string[],
  input: {
    productionScore: number;
    architecture: number;
    testingScore: number;
    devopsScore: number;
    resilience: number;
    testFileCount: number;
    language: string | null;
    hasReadme: boolean;
    needsSchemaValidation: boolean;
    needsBuildGate: boolean;
  }
): string[] {
  if (
    isProductionReadyAudit({
      productionScore: input.productionScore,
      architecture: input.architecture,
      testing: input.testingScore,
      devops: input.devopsScore,
      resilience: input.resilience,
    })
  ) {
    return [PRODUCTION_READY_VERIFIED];
  }

  const javascript = isJavaScriptFamily(input.language);
  const language = (input.language ?? "").trim().toLowerCase();
  const testing = input.testingScore;
  const suppressNewTestFile =
    testing >= 70 || input.testFileCount >= 10;
  const jsToolchainCopy =
    /\b(next\s+build|npx\s+tsc|\btsc\b|\bnpm\b|\byarn\b|\bpnpm\b|\beslint\b|\bvitest\b|\bjest\b|\bzod\b|\bas Type\b)\b/i;
  const goToolchainCopy =
    /\b(go\s+build|go\s+test|golangci-lint|_test\.go)\b/i;
  const pythonToolchainCopy =
    /\b(pytest|ruff|mypy|tests\/test_|\.py\b)\b/i;
  const rustToolchainCopy =
    /\b(cargo\s+(check|clippy|test)|\.rs\b)\b/i;

  const cleaned = recommendations
    .map((item) => {
      if (!javascript) {
        return item;
      }
      return item
        .replace(/,?\s*tests\/test_app\.py/gi, "")
        .replace(/,?\s*or \*_test\.go/gi, "")
        .replace(/\*_test\.go/gi, "")
        .replace(/_test\.go/gi, "")
        .replace(/\.go\b/gi, "")
        .replace(/\.py\b/gi, "")
        .replace(/\s{2,}/g, " ")
        .replace(/\s+,/g, ",")
        .trim();
    })
    .filter((item) => {
      if (!item) {
        return false;
      }
      if (javascript && /\.(go|py)\b/i.test(item)) {
        return false;
      }
      if (
        language &&
        !javascript &&
        jsToolchainCopy.test(item) &&
        !/\b(typescript|javascript|tsx|jsx)\b/i.test(item)
      ) {
        return false;
      }
      if (language === "go" && (pythonToolchainCopy.test(item) || rustToolchainCopy.test(item))) {
        return false;
      }
      if (
        (language === "python" || language === "jupyter notebook") &&
        (goToolchainCopy.test(item) || rustToolchainCopy.test(item))
      ) {
        return false;
      }
      if (language === "rust" && (goToolchainCopy.test(item) || pythonToolchainCopy.test(item))) {
        return false;
      }
      if (input.hasReadme && README_COPY.test(item)) {
        return false;
      }
      if (suppressNewTestFile && REAL_TEST_FILE_COPY.test(item)) {
        return false;
      }
      if (testing >= 70 && EXPAND_TESTS_COPY.test(item)) {
        return false;
      }
      if (testing < 70 && REAL_TEST_FILE_COPY.test(item)) {
        return false;
      }
      if (PROMPT_LEAK_COPY.test(item)) {
        return false;
      }
      if (input.devopsScore >= 75 && /production build step/i.test(item)) {
        return false;
      }
      return true;
    });

  if (javascript && input.needsSchemaValidation) {
    cleaned.unshift(
      "Add Zod schema parsing on API route handlers that currently cast JSON with `as Type`."
    );
  }
  if (input.needsBuildGate && input.devopsScore < 75) {
    if (javascript) {
      cleaned.unshift(
        "Add a production build step (`next build` or `tsc`) to the CI workflow."
      );
    } else if (language === "go") {
      cleaned.unshift(
        "Add a CI step that runs `go build ./...` (and ideally `go test ./...`) on pull requests."
      );
    } else if (language === "python" || language === "jupyter notebook") {
      cleaned.unshift(
        "Add a CI step that runs `pytest` (and ideally `ruff check` or `mypy`) on pull requests."
      );
    } else if (language === "rust") {
      cleaned.unshift(
        "Add a CI step that runs `cargo check` and `cargo test` on pull requests."
      );
    } else {
      cleaned.unshift(
        "Add a CI workflow that runs this repository's native lint, test, and build commands on pull requests."
      );
    }
  }
  if (
    testing < 70 &&
    input.testFileCount < 10 &&
    !cleaned.some((item) => EXPAND_TESTS_COPY.test(item))
  ) {
    const [expand] = targetedAuditSuggestions({
      language: input.language,
      testingScore: testing,
      testFileCount: input.testFileCount,
      devopsScore: input.devopsScore,
      needsSchemaValidation: false,
      needsBuildGate: false,
    });
    if (expand) {
      cleaned.unshift(expand);
    }
  }

  const languageCiFiller =
    language === "go"
      ? "Add a GitHub Actions workflow that runs `golangci-lint run`, `go test ./...`, and `go build ./...`."
      : language === "python" || language === "jupyter notebook"
        ? "Add a GitHub Actions workflow that runs `ruff check`, `pytest`, and a packaging/typecheck step."
        : language === "rust"
          ? "Add a GitHub Actions workflow that runs `cargo clippy`, `cargo test`, and `cargo check`."
          : javascript
            ? "Add a GitHub Actions workflow that runs lint, tests, and a production build."
            : "Add a GitHub Actions workflow that runs this repo's native lint, test, and build commands.";

  const languageResilienceFiller =
    language === "go"
      ? "Return structured errors from handlers and wrap failing I/O with idiomatic Go error handling instead of ignoring returned errors."
      : language === "python" || language === "jupyter notebook"
        ? "Catch and log exceptions at service boundaries; avoid bare `except:` that swallows failures."
        : language === "rust"
          ? "Propagate `Result`/`Option` at API boundaries instead of `.unwrap()` on fallible paths."
          : javascript
            ? "Wrap unvalidated route handlers in Zod parsing instead of `as Type` casts."
            : "Add explicit error handling at the request/service boundary for this language's idioms.";

  const fillers = [
    input.hasReadme
      ? "Document the module boundaries already covered by the existing README."
      : "Add a concise README covering architecture, your contributions, and setup steps.",
    languageCiFiller,
    languageResilienceFiller,
  ].filter((item) => !(input.hasReadme && README_COPY.test(item)));

  for (const filler of fillers) {
    if (cleaned.length >= 3) {
      break;
    }
    if (!cleaned.includes(filler)) {
      cleaned.push(filler);
    }
  }

  return cleaned.slice(0, 3);
}

function primaryArtifactFromAudit(
  githubArtifacts: GitHubArtifactAudit | null
) {
  const artifacts = githubArtifacts?.artifacts ?? [];
  const filesystem = strongestFilesystemEvidence(artifacts);
  return (
    artifacts.find((artifact) => artifact.filesystem === filesystem) ??
    artifacts[0]
  );
}

function commitDatesFromArtifacts(
  githubArtifacts: GitHubArtifactAudit | null
): string[] {
  return normalizeCommitDates(primaryArtifactFromAudit(githubArtifacts)?.commit_dates);
}

function commitHistoryFromArtifacts(
  githubArtifacts: GitHubArtifactAudit | null
): {
  commitDates: string[] | null;
  commitStats: NonNullable<
    GitHubArtifactAudit["artifacts"][number]["commit_stats"]
  > | null;
} | null {
  const primary = primaryArtifactFromAudit(githubArtifacts);
  if (!primary) {
    return null;
  }
  // Failed GitHub commit list → null history → zero hygiene penalty.
  if (primary.commit_history_fetched === false) {
    return null;
  }
  return {
    commitDates: normalizeCommitDates(primary.commit_dates),
    commitStats: Array.isArray(primary.commit_stats)
      ? primary.commit_stats
      : [],
  };
}

function normalizeAuditResult(raw: unknown): AuditResult {
  const record =
    raw && typeof raw === "object" ? (raw as Record<string, unknown>) : {};

  const recommendations = normalizeStringArray(record.recommendations, 3).map(
    sanitizeHistoryPenaltyCopy
  );
  const redFlagsRaw = normalizeStringArray(record.redFlags, 5).map(
    sanitizeHistoryPenaltyCopy
  );
  const redFlags = redFlagsRaw.filter((flag) => !isMissingResumeFlag(flag));
  const strippedResumeFlags = redFlagsRaw.length - redFlags.length;
  const score =
    strippedResumeFlags > 0
      ? clampScore(
          clampScore(record.score) + Math.min(12, strippedResumeFlags * 6)
        )
      : clampScore(record.score);

  const resolvedRecommendations =
    recommendations.length >= 3
      ? recommendations.slice(0, 3)
      : [
          ...recommendations,
          "Add a public GitHub repo with README, architecture notes, and recent commits.",
          "Add file-system proof of tests, CI workflows, and error handling.",
          "Align project stack keywords with the target role in your headline and bio.",
        ].slice(0, 3);
  const improvements = normalizeStringArray(
    record.improvements ?? resolvedRecommendations,
    3
  ).map(sanitizeHistoryPenaltyCopy);
  const auditMode = normalizeAuditMode(record.auditMode);
  const breakdown =
    record.breakdown &&
    typeof record.breakdown === "object" &&
    !Array.isArray(record.breakdown)
      ? {
          architecture: clampScore(
            (record.breakdown as Record<string, unknown>).architecture
          ),
          security: clampScore(
            (record.breakdown as Record<string, unknown>).security
          ),
          tooling: clampScore(
            (record.breakdown as Record<string, unknown>).tooling
          ),
          testing: clampScore(
            (record.breakdown as Record<string, unknown>).testing
          ),
        }
      : emptyBreakdown();
  const overallScore = clampScore(record.overallScore ?? score);
  const summary =
    typeof record.summary === "string"
      ? sanitizeHistoryPenaltyCopy(record.summary)
      : "";

  return {
    score: overallScore,
    overallScore,
    auditMode,
    tier:
      typeof record.tier === "string" && record.tier.trim()
        ? record.tier.trim()
        : "Needs Refinement",
    breakdown,
    summary,
    strengths: normalizeStringArray(record.strengths, 5).map(
      sanitizeHistoryPenaltyCopy
    ),
    improvements:
      improvements.length >= 3
        ? improvements.slice(0, 3)
        : resolvedRecommendations,
    redFlags,
    recommendations: resolvedRecommendations,
    checks: normalizeAuditChecks(record.checks).map((check) => ({
      ...check,
      summary: sanitizeHistoryPenaltyCopy(check.summary),
    })),
    scoreCap:
      parseScoreCapAudit(record.scoreCap) ?? emptyScoreCapAudit(overallScore),
    metrics: emptyProductionAuditMetrics(),
    filesystem: optionalFilesystem(record.filesystem),
    commitDates: normalizeCommitDates(record.commitDates ?? record.commit_dates),
    commitStats: Array.isArray(record.commitStats)
      ? record.commitStats.flatMap((entry) => {
          if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
            return [];
          }
          const row = entry as Record<string, unknown>;
          if (typeof row.date !== "string" || !row.date.trim()) {
            return [];
          }
          return [
            {
              date: row.date.trim(),
              additions:
                typeof row.additions === "number" ? row.additions : undefined,
              deletions:
                typeof row.deletions === "number" ? row.deletions : undefined,
              filesChanged:
                typeof row.filesChanged === "number"
                  ? row.filesChanged
                  : undefined,
              message:
                typeof row.message === "string" ? row.message : undefined,
            },
          ];
        })
      : [],
    commitHistoryFetched:
      typeof record.commitHistoryFetched === "boolean"
        ? record.commitHistoryFetched
        : record.commit_history_fetched === true
          ? true
          : record.commit_history_fetched === false
            ? false
            : undefined,
    auditedAt:
      typeof record.auditedAt === "string" && record.auditedAt.trim()
        ? record.auditedAt.trim()
        : typeof record.audited_at === "string" && record.audited_at.trim()
          ? record.audited_at.trim()
          : undefined,
    executiveBrief: parseExecutiveBrief(record.executiveBrief),
  };
}

function isValidRequestBody(body: AuditRequestBody): boolean {
  return (
    hasUsableGitHubAuditTarget(body.githubUrl) ||
    hasUsableExternalProjects(body.externalProjects)
  );
}

function hasPublicGitHubLink(githubUrl: string | undefined, workIsPrivate: boolean): boolean {
  if (workIsPrivate) {
    return false;
  }

  return hasUsableGitHubAuditTarget(githubUrl);
}

function formString(form: FormData, key: string): string | undefined {
  const value = form.get(key);
  return typeof value === "string" ? value : undefined;
}

function parseJsonValue(value: string | undefined): unknown {
  if (!value?.trim()) {
    return null;
  }

  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function normalizeAuditRequestBody(
  body: z.infer<typeof auditRequestBodySchema>
): AuditRequestBody {
  const githubUrl = body.githubUrl?.trim() || body.repoUrl?.trim() || undefined;
  return {
    targetRole: body.targetRole,
    githubUrl,
    repoUrl: body.repoUrl,
    resumeSummary: body.resumeSummary,
    compensationLevel: body.compensationLevel,
    auditMode: normalizeAuditMode(body.auditMode),
    workIsPrivate: parseWorkIsPrivate(body.workIsPrivate),
    playground: body.playground === true,
    isPublicTeaser: body.isPublicTeaser === true,
    adminAudit: body.adminAudit === true,
    candidateName: body.candidateName?.trim() || undefined,
    candidateHandle: body.candidateHandle?.trim() || undefined,
    externalProjects: normalizeExternalProjects(body.externalProjects),
  };
}

async function readAuditRequest(request: Request): Promise<
  | { ok: true; body: AuditRequestBody; resumeFile: File | null }
  | { ok: false; response: NextResponse }
> {
  const contentType = request.headers.get("content-type") ?? "";

  if (contentType.includes("multipart/form-data")) {
    try {
      const form = await request.formData();
      const resumeValue = form.get("resumeFile") ?? form.get("file");
      return {
        ok: true,
        body: {
          targetRole: formString(form, "targetRole"),
          githubUrl:
            formString(form, "githubUrl") || formString(form, "repoUrl"),
          repoUrl: formString(form, "repoUrl"),
          resumeSummary: formString(form, "resumeSummary"),
          compensationLevel: formString(form, "compensationLevel"),
          auditMode: normalizeAuditMode(formString(form, "auditMode")),
          workIsPrivate: parseWorkIsPrivate(formString(form, "workIsPrivate")),
          playground: formString(form, "playground") === "true",
          isPublicTeaser: formString(form, "isPublicTeaser") === "true",
          adminAudit: formString(form, "adminAudit") === "true",
          candidateName: formString(form, "candidateName"),
          candidateHandle: formString(form, "candidateHandle"),
          externalProjects: normalizeExternalProjects(
            parseJsonValue(formString(form, "externalProjects"))
          ),
        },
        resumeFile:
          resumeValue instanceof File && resumeValue.size > 0
            ? resumeValue
            : null,
      };
    } catch {
      return {
        ok: false,
        response: NextResponse.json(
          { error: "Invalid request body." },
          { status: 400 }
        ),
      };
    }
  }

  const parsed = await parseJsonWithSchema(request, auditRequestBodySchema);
  if (!parsed.ok) {
    return { ok: false, response: parsed.response };
  }

  return {
    ok: true,
    body: normalizeAuditRequestBody(parsed.data),
    resumeFile: null,
  };
}

function buildFallbackAudit(
  body: AuditRequestBody,
  githubArtifacts: GitHubArtifactAudit | null,
  externalProjects: ExternalProjectRecord[],
  usedExternalFallback: boolean
): AuditResult {
  const hasGithub = githubArtifactAuditSucceeded(githubArtifacts);
  const hasExternal = hasUsableExternalProjects(externalProjects);
  const hasResume = !!body.resumeSummary?.trim();
  const role = body.targetRole?.trim() || "your target role";
  const level = body.compensationLevel?.trim() || "Mid";

  let score = 0;
  const strengths: string[] = [];
  const redFlags: string[] = [];
  const recommendations: string[] = [];

  if (hasGithub && !usedExternalFallback) {
    score += 75;
    const artifact = githubArtifacts?.artifacts[0];
    strengths.push(
      artifact
        ? `GitHub artifacts sampled from ${artifact.owner}/${artifact.repo} (${artifact.language ?? "unknown language"}, ${artifact.commit_count_sampled} recent commits).`
        : `GitHub URL supplied — reviewers can trace repository activity for ${role}.`
    );
  } else if (hasExternal) {
    score += 75;
    const primary = externalProjects.find(
      (project) => project.project_title.trim() && project.description.trim()
    ) ?? externalProjects[0];
    strengths.push(
      primary
        ? `External project "${primary.project_title}" was reviewed from its technical breakdown${primary.project_url ? ` and live/docs URL (${primary.project_url})` : ""}.`
        : "Submitted external project artifacts are available for proof-of-work review."
    );
  } else {
    redFlags.push(
      "Missing GitHub profile or repository URL limits artifact verification."
    );
  }

  if (hasGithub || hasExternal) {
    score += 10;
    strengths.push(
      hasResume
        ? hasExternal && usedExternalFallback
          ? "Resume claims can be cross-referenced against submitted project write-ups and live/docs links."
          : "Resume and GitHub artifacts can be cross-referenced for claim verification."
        : hasExternal && usedExternalFallback
          ? "Project write-ups and live/docs links are available for proof-of-work review."
          : "Repository file-tree and commit artifacts are the basis of this score."
    );
  }

  if (hasResume) {
    strengths.push(
      "Resume text was parsed and can be checked against repository claims."
    );
  }

  if (body.targetRole?.trim()) {
    score += 15;
    strengths.push(`Target role "${role}" gives reviewers a clear evaluation lens.`);
  }

  recommendations.push(
    usedExternalFallback
      ? `Tie each project write-up to ${level}-level ${role} work: APIs, data model, ownership, and production constraints.`
      : `Pin 1-2 production repos that map directly to ${level}-level ${role} expectations.`,
    hasResume
      ? "Rewrite top resume bullets with metrics, stack tags, and links to live demos or PRs."
      : "Expand integration or end-to-end coverage for the modules this repository already ships.",
    usedExternalFallback
      ? "Add architecture notes, error handling, and test strategy to each technical breakdown so reviewers can score production standards."
      : "Add the CI, test, or schema check that is holding the lowest pillar down."
  );

  if (strengths.length === 0) {
    strengths.push("Profile inputs give a baseline starting point for a credibility audit.");
  }

  const artifact = githubArtifacts?.artifacts[0];
  const filesystem = strongestFilesystemEvidence(githubArtifacts?.artifacts ?? []);
  const primaryProject = externalProjects[0];
  const checks = CANONICAL_AUDIT_CHECKS.map((canonical) => {
    if (canonical.id === "artifact_analysis") {
      return {
        ...canonical,
        summary:
          usedExternalFallback && primaryProject
            ? `Reviewed external project "${primaryProject.project_title}"${primaryProject.project_url ? ` at ${primaryProject.project_url}` : ""}. ${primaryProject.description ? "The technical breakdown is a write-up, not a file tree, so tests, CI, and error handling were not verified as code artifacts." : "The write-up was thin, so production claims still need more concrete evidence."}`
            : artifact
            ? `Sampled ${artifact.owner}/${artifact.repo} (${artifact.language ?? "unknown language"}, ${artifact.commit_count_sampled} recent commits, ${filesystem?.file_count ?? 0} inspected files). README and commit history ${artifact.readme_excerpt ? "are present" : "are limited"}; file-tree proof of tests/CI/error handling is ${filesystem?.inspected ? "what the score is based on" : "missing"}.`
            : hasGithub
              ? `A GitHub URL was supplied for ${role}, but repository artifacts were too thin to verify README quality, commit history, or a file tree.`
              : "No GitHub artifacts were available to verify README quality, commit history, or language signals.",
      };
    }

    if (canonical.id === "architecture_review") {
      return {
        ...canonical,
        summary:
          usedExternalFallback && primaryProject?.description
            ? `Architecture was scored from the technical breakdown for "${primaryProject.project_title}". Module ownership and system boundaries still need file-system proof for ${level}-level ${role} work.`
            : filesystem?.sample_paths.length
            ? `File tree from ${artifact?.owner}/${artifact?.repo} includes ${filesystem.sample_paths.slice(0, 4).join(", ")}. Folder-level architecture still needs a clearer ownership and module map for ${level}-level ${role} work.`
            : artifact?.readme_excerpt
            ? `README excerpt from ${artifact.owner}/${artifact.repo} was reviewed as a claim sheet only. No file-tree architecture proof was available for ${level}-level ${role} work.`
            : "Architecture signals were limited. No documented module structure or system-design notes were available from the provided artifacts.",
      };
    }

    return {
      ...canonical,
      summary:
        usedExternalFallback && primaryProject?.description
          ? `API and data-handling claims were taken from the submitted technical breakdown for "${primaryProject.project_title}". Error handling, persistence, and tests still need file-system proof and cannot be credited from prose.`
          : filesystem?.inspected
          ? `File-tree inspection found tests=${filesystem.test_paths.length > 0}, CI=${filesystem.ci_workflow_paths.length > 0}, error handling=${filesystem.error_handling_paths.length > 0}. Missing core files are not waived by README language.`
          : "API and data-resiliency evidence was not confirmed. Error handling, tests, and CI could not be verified from a repository file tree.",
    };
  });

  return normalizeAuditResult({
    score,
    strengths,
    redFlags,
    recommendations,
    checks,
  });
}

async function generateGeminiAudit(
  body: AuditRequestBody,
  githubArtifacts: GitHubArtifactAudit | null,
  externalProjects: ExternalProjectRecord[],
  usedExternalFallback: boolean
): Promise<AuditResult> {
  const apiKey = process.env.GEMINI_API_KEY;

  if (!apiKey) {
    throw new Error("GEMINI_API_KEY is not configured.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const githubUrl = body.githubUrl?.trim() ?? "";
  const githubUnavailableReason = usedExternalFallback
    ? body.workIsPrivate
      ? "private_or_enterprise"
      : githubUrl
        ? "ghost_or_unreadable_repository"
        : "not_provided"
    : null;

  const filesystemEvidence = usedExternalFallback
    ? null
    : strongestFilesystemEvidence(githubArtifacts?.artifacts ?? []);
  const scorePolicy = buildFilesystemScorePolicy(filesystemEvidence);
  const isUpstreamDerivative = Boolean(
    !usedExternalFallback &&
      githubArtifacts?.artifacts.some((artifact) => artifact.is_upstream_derivative)
  );
  const auditMode = normalizeAuditMode(body.auditMode);
  const promptHistory = commitHistoryFromArtifacts(
    usedExternalFallback ? null : githubArtifacts
  );
  let promptMetrics = computeProductionAuditMetrics(
    filesystemEvidence,
    auditMode,
    promptHistory
  );
  let modeEvaluation = buildModeAwareEvaluation(auditMode, {
    architecture: promptMetrics.architecture,
    testing: promptMetrics.testing,
    devops: promptMetrics.devops,
    resilience: promptMetrics.resilience,
  });
  if (promptMetrics.evidence.inspected && isUpstreamDerivative) {
    const penalizedScore = applyUpstreamDerivativePenalty(
      modeEvaluation.overallScore,
      true
    );
    modeEvaluation = {
      ...modeEvaluation,
      overallScore: penalizedScore,
      tier: assignAuditTier(auditMode, penalizedScore),
    };
    promptMetrics = {
      ...promptMetrics,
      productionScore: penalizedScore,
      codeHealthScore: penalizedScore,
      upstreamDerivativePenalty: UPSTREAM_DERIVATIVE_PENALTY,
    };
  } else {
    promptMetrics = {
      ...promptMetrics,
      productionScore: modeEvaluation.overallScore,
      codeHealthScore: modeEvaluation.overallScore,
    };
  }
  const deterministicMetrics = deterministicMetricsPayload({
    productionScore: promptMetrics.productionScore,
    overallScore: modeEvaluation.overallScore,
    auditMode,
    tier: modeEvaluation.tier,
    breakdown: modeEvaluation.breakdown,
    isUpstreamDerivative,
    architectureScore: promptMetrics.architecture,
    testScore: promptMetrics.testing,
    devopsScore: promptMetrics.devops,
    resilienceScore: promptMetrics.resilience,
  });
  const primaryLanguage =
    primaryRepoLanguage(githubArtifacts)?.trim() || "unknown";

  const userPrompt = JSON.stringify({
    evaluationMode: auditMode,
    evaluationModeLabel: auditModeLabel(auditMode),
    deterministicMetrics,
    primaryLanguage,
    languageConstraint: {
      primaryLanguage,
      rule:
        "Every recommendation, actionable fix, and tool suggestion MUST match primaryLanguage and the detected toolchain. Do not suggest JS/TS tools unless the repo is JavaScript/TypeScript.",
      examples: {
        Go: ["go build ./...", "golangci-lint run", "go test -v ./..."],
        Python: ["pytest", "ruff", "mypy"],
        Rust: ["cargo check", "cargo clippy", "cargo test"],
        TypeScript: ["next build", "tsc", "vitest", "eslint"],
      },
    },
    targetRole: body.targetRole?.trim() ?? "",
    githubUrl,
    resumeText: (body.resumeSummary ?? "").slice(0, RESUME_TEXT_LIMIT),
    compensationLevel: body.compensationLevel?.trim() ?? "Mid",
    workIsPrivate: Boolean(body.workIsPrivate),
    usedExternalFallback,
    auditMode: usedExternalFallback
      ? githubArtifactAuditSucceeded(githubArtifacts)
        ? "hybrid"
        : "external_projects"
      : "github",
    githubUnavailableReason,
    scorePolicy,
    codeFirst: true,
    resumeOptional: true,
    githubProfile: usedExternalFallback ? null : githubArtifacts?.profile ?? null,
    githubArtifacts: usedExternalFallback
      ? []
      : (githubArtifacts?.artifacts ?? []).map((artifact) => ({
          repo_url: artifact.repo_url,
          owner: artifact.owner,
          repo: artifact.repo,
          stars: artifact.stars,
          forks: artifact.forks,
          is_fork: artifact.is_fork,
          parent_full_name: artifact.parent_full_name,
          template_repository: artifact.template_repository,
          is_upstream_derivative: artifact.is_upstream_derivative,
          created_at: artifact.created_at,
          language: artifact.language,
          commit_count_sampled: artifact.commit_count_sampled,
          commit_dates: artifact.commit_dates,
          commit_stats: artifact.commit_stats,
          readme_excerpt: artifact.readme_excerpt,
          filesystem: compactFilesystemForPrompt(artifact.filesystem),
        })),
    githubFetchWarnings: usedExternalFallback
      ? []
      : githubArtifacts?.fetch_warnings ?? [],
    externalProjects: externalProjects.map((project) => ({
      project_title: project.project_title,
      project_url: project.project_url,
      description: project.description.slice(0, 4000),
    })),
  });

  let lastError: unknown;

  for (const model of MODEL_CANDIDATES) {
    for (let attempt = 0; attempt < 3; attempt += 1) {
      try {
        const response = await ai.models.generateContent({
          model,
          contents: userPrompt,
          config: {
            systemInstruction: buildSystemPrompt(auditMode),
            responseMimeType: "application/json",
            responseSchema: AUDIT_RESPONSE_SCHEMA,
            temperature: 0,
          },
        });

        const text = response.text?.trim();

        if (!text) {
          throw new Error(`Gemini (${model}) returned an empty response.`);
        }

        return normalizeAuditResult(JSON.parse(text));
      } catch (error) {
        lastError = error;
        console.error(
          `Gemini audit failed for model ${model}${
            attempt > 0 ? " (retry)" : ""
          }:`,
          error
        );
        // 503 / high-demand: backoff before retry so spikes can clear.
        if (attempt < 2 && isGeminiUnavailableError(error)) {
          await sleep(1500 * (attempt + 1));
          continue;
        }
        break;
      }
    }
  }

  throw lastError instanceof Error
    ? lastError
    : new Error("All Gemini models failed.");
}

async function resolveAuditAccess(): Promise<
  | { ok: false; response: NextResponse }
  | {
      ok: true;
      supabase: Awaited<ReturnType<typeof createClient>>;
      user: User | null;
      usage: DailyScanUsage;
    }
> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    return {
      ok: true,
      supabase,
      user: null,
      usage: resolveDailyScanUsage(0, null),
    };
  }

  const { usage, error } = await loadDailyScanUsage(supabase, user.id);

  if (error) {
    console.error("[audit] failed to load daily scan usage:", error);
    return {
      ok: false,
      response: NextResponse.json(
        { error: "Could not verify daily scan limit." },
        { status: 500 }
      ),
    };
  }

  return { ok: true, supabase, user, usage };
}

async function loadStoredExternalProjects(
  supabase: Awaited<ReturnType<typeof createClient>>,
  userId: string
): Promise<ExternalProjectRecord[]> {
  const { data, error } = await supabase
    .from("external_projects")
    .select("id, project_title, project_url, description, created_at")
    .eq("user_id", userId)
    .order("created_at", { ascending: false });

  if (error) {
    console.error("[audit] failed to load external_projects:", error);
    return [];
  }

  return normalizeExternalProjects(data);
}

async function persistOwnIntegrityAudit(
  supabase: Awaited<ReturnType<typeof createClient>>,
  userId: string,
  score: number,
  artifacts: GitHubArtifactAudit | null,
  externalProjects: ExternalProjectRecord[],
  usedExternalFallback: boolean,
  scoreCap?: ScoreCapAudit | null,
  metrics?: ProductionAuditMetrics | null
): Promise<void> {
  const primary = artifacts?.artifacts.find((artifact) =>
    githubAuditHasFetchedArtifacts(artifact)
  );
  const hasExternal = hasUsableExternalProjects(externalProjects);

  if (!primary && !(usedExternalFallback && hasExternal)) {
    return;
  }

  const { data: existingRows, error: loadError } = await supabase
    .from("profiles")
    .select("id, audit_data")
    .or(`id.eq.${userId},user_id.eq.${userId}`)
    .limit(1);

  if (loadError) {
    console.error("[audit] failed to load profile for integrity persist:", loadError);
    return;
  }

  const existing = Array.isArray(existingRows) ? existingRows[0] : existingRows;

  const existingAudit =
    existing?.audit_data &&
    typeof existing.audit_data === "object" &&
    !Array.isArray(existing.audit_data)
      ? (existing.audit_data as Record<string, unknown>)
      : null;

  if (Array.isArray(existingAudit?.interview_questions)) {
    return;
  }

  const source = usedExternalFallback
    ? primary
      ? "hybrid_artifact_audit"
      : "external_projects_audit"
    : "github_integrity_audit";

  const integrityScore = Math.max(1, clampScore0to100(score));
  const { error: updateError } = await supabase
    .from("profiles")
    .update({
      integrity_score: integrityScore,
      audit_data: {
        integrity_score: clampScore0to100(score),
        scoreCap: scoreCap ?? emptyScoreCapAudit(score),
        metrics: metrics ?? emptyProductionAuditMetrics(),
        github_audit: usedExternalFallback ? primary ?? null : primary,
        external_projects: hasExternal
          ? externalProjects.map((project) => ({
              project_title: project.project_title,
              project_url: project.project_url,
              description: project.description,
            }))
          : [],
        source,
      },
    })
    .eq("id", existing?.id ?? userId);

  if (updateError) {
    console.error("[audit] failed to persist integrity audit:", updateError);
  }
}

export async function GET() {
  const access = await resolveAuditAccess();

  if (!access.ok) {
    return access.response;
  }

  return NextResponse.json(access.usage);
}

export async function POST(request: Request) {
  const parsed = await readAuditRequest(request);
  if (!parsed.ok) {
    return parsed.response;
  }

  const payload: AuditRequestBody = { ...parsed.body };
  const access = await resolveAuditAccess();

  if (!access.ok) {
    return access.response;
  }

  const isAdminOperator = isAdminUser(access.user);
  const isAdminAudit = payload.adminAudit === true && isAdminOperator;
  const wantsUnrestrictedTeaser =
    payload.isPublicTeaser === true || payload.playground === true;

  if (payload.adminAudit === true && !isAdminOperator) {
    return NextResponse.json(
      { error: "Admin audits require an authenticated platform admin." },
      { status: 403 }
    );
  }

  // Unrestricted ad-hoc scans are admin-only (moved off the public landing page).
  if (wantsUnrestrictedTeaser && !isAdminOperator) {
    return NextResponse.json(
      {
        error:
          "Unrestricted repository audits are limited to platform admins. Builders verify their own repos from the dashboard.",
      },
      { status: 403 }
    );
  }

  if (!access.user) {
    const guestLimit = consumeRateLimit(
      `audit-guest:${getRequestIp(request)}`,
      8,
      60 * 60 * 1000
    );
    if (!guestLimit.ok) {
      return tooManyRequestsResponse(guestLimit.retryAfterSec);
    }
  }

  // Admin unlimited audits never consume or block on the daily scan allowance.
  if (access.user && access.usage.limit_reached && !isAdminAudit) {
    return NextResponse.json(
      { error: DAILY_LIMIT_API_MESSAGE, ...access.usage },
      { status: 429 }
    );
  }

  const bumpUsage = async (): Promise<DailyScanUsage> => {
    if (!access.user || isAdminAudit) {
      return access.usage;
    }
    return incrementDailyScanUsage(
      access.supabase,
      access.user.id,
      access.usage
    );
  };

  let storedProjects: ExternalProjectRecord[] = [];
  if (access.user) {
    storedProjects = await loadStoredExternalProjects(
      access.supabase,
      access.user.id
    );
  }

  payload.externalProjects = mergeExternalProjects(
    storedProjects,
    payload.externalProjects
  );

  const githubField = payload.githubUrl?.trim() ?? "";
  const parsedRepoPath = parseGitHubRepoPath(githubField);
  const githubMissing =
    !githubField ||
    isGitHubPlaceholderInput(githubField) ||
    !parsedRepoPath;

  if (
    githubField &&
    !isGitHubPlaceholderInput(githubField) &&
    !parsedRepoPath
  ) {
    return NextResponse.json(
      {
        error: INVALID_REPO_FORMAT,
        message: INVALID_REPO_FORMAT_MESSAGE,
      },
      { status: 400 }
    );
  }

  if (githubMissing && !hasUsableExternalProjects(payload.externalProjects)) {
    return NextResponse.json(
      { error: AUDIT_MISSING_GITHUB_OR_ARTIFACT_MESSAGE },
      { status: 400 }
    );
  }

  if (parsed.resumeFile) {
    try {
      payload.resumeSummary = await extractResumeTextFromFile(parsed.resumeFile);
    } catch (error) {
      return NextResponse.json(
        {
          error:
            error instanceof Error
              ? error.message
              : "Could not parse the uploaded resume.",
        },
        { status: 422 }
      );
    }
  }

  if (access.user && (!payload.resumeSummary?.trim() || !payload.githubUrl?.trim())) {
    const { data } = await access.supabase
      .from("profiles")
      .select("resume_text, portfolio_url")
      .eq("id", access.user.id)
      .maybeSingle();

    if (!payload.resumeSummary?.trim() && data?.resume_text?.trim()) {
      payload.resumeSummary = data.resume_text;
    }

    if (
      data &&
      !payload.workIsPrivate &&
      !hasUsableGitHubAuditTarget(payload.githubUrl) &&
      hasUsableGitHubAuditTarget(data.portfolio_url)
    ) {
      payload.githubUrl = data.portfolio_url;
    }
  }

  if (!isValidRequestBody(payload)) {
    return NextResponse.json(
      { error: AUDIT_MISSING_GITHUB_OR_ARTIFACT_MESSAGE },
      { status: 400 }
    );
  }

  const workIsPrivate = Boolean(payload.workIsPrivate);
  const publicGithub = hasPublicGitHubLink(payload.githubUrl, workIsPrivate);
  const githubFetchUrl = publicGithub
    ? normalizeGitHubAuditTarget(payload.githubUrl)
    : "";

  if (githubFetchUrl) {
    const parsedFetch = parseGitHubRepoPath(githubFetchUrl);
    if (!parsedFetch?.owner?.trim() || !parsedFetch?.repo?.trim()) {
      return NextResponse.json(
        {
          error: INVALID_REPO_FORMAT,
          message: INVALID_REPO_FORMAT_MESSAGE,
        },
        { status: 400 }
      );
    }

    const probe = await probeGitHubRepository(githubFetchUrl);
    if (probe?.status === "not_found") {
      return NextResponse.json(
        {
          error: REPO_NOT_FOUND_OR_PRIVATE,
          message: REPO_NOT_FOUND_OR_PRIVATE_MESSAGE,
          isPrivateOrNotFound: true,
          repoUrl: githubFetchUrl,
          inaccessibleRepo: true,
          ...(await bumpUsage()),
        },
        { status: 404 }
      );
    }

    if (
      probe?.status === "found" &&
      access.user &&
      payload.isPublicTeaser !== true &&
      !isAdminAudit
    ) {
      const { data: roleRow } = await access.supabase
        .from("profiles")
        .select("role")
        .or(`id.eq.${access.user.id},user_id.eq.${access.user.id}`)
        .limit(1)
        .maybeSingle();
      const employerViewer = isEmployerRole(
        typeof roleRow?.role === "string" ? roleRow.role : null
      );

      if (!employerViewer) {
        const ownership = await verifyGitHubRepoOwnership({
          user: access.user,
          repoUrl: githubFetchUrl,
        });
        const tokenVerified = await hasPersistedProvixTokenVerification(
          access.supabase,
          access.user.id,
          githubFetchUrl
        );
        if (!ownership.verified && !tokenVerified) {
          return NextResponse.json(
            {
              error: UNVERIFIED_OWNERSHIP,
              owner: probe.owner,
              username: ownership.username,
              message: UNVERIFIED_OWNERSHIP_MESSAGE,
              ...(await bumpUsage()),
            },
            { status: 403 }
          );
        }
      }
    }
  }

  let githubArtifacts: GitHubArtifactAudit | null = null;
  if (githubFetchUrl) {
    try {
      githubArtifacts = await fetchGitHubProfileArtifacts(githubFetchUrl);
    } catch (error) {
      if (error instanceof GithubContentReadError) {
        return NextResponse.json(
          { error: error.message },
          { status: 503 }
        );
      }
      console.error("[audit] GitHub artifact fetch failed:", error);
    }
  }

  const inaccessibleRepo =
    !workIsPrivate &&
    Boolean(githubFetchUrl) &&
    (githubArtifacts === null || githubAuditLooksInaccessible(githubArtifacts));

  if (inaccessibleRepo) {
    return NextResponse.json(
      {
        isPrivateOrNotFound: true,
        repoUrl: githubFetchUrl,
        inaccessibleRepo: true,
        error: INACCESSIBLE_PUBLIC_REPO_MESSAGE,
        ...(await bumpUsage()),
      },
      { status: 404 }
    );
  }

  const usedExternalFallback = shouldUseExternalProjectFallback({
    workIsPrivate,
    githubUrl: publicGithub ? payload.githubUrl?.trim() ?? "" : "",
    githubAuditSucceeded: githubArtifactAuditSucceeded(githubArtifacts),
    hasExternalProjects: hasUsableExternalProjects(payload.externalProjects),
  });

  let result: AuditResult;

  try {
    result = await generateGeminiAudit(
      payload,
      githubArtifacts,
      payload.externalProjects ?? [],
      usedExternalFallback
    );
  } catch (error) {
    console.error("Gemini audit API failed, using fallback:", error);
    result = buildFallbackAudit(
      payload,
      githubArtifacts,
      payload.externalProjects ?? [],
      usedExternalFallback
    );
  }

  const auditMode = normalizeAuditMode(payload.auditMode);
  const filesystem = strongestFilesystemEvidence(
    githubArtifacts?.artifacts ?? []
  );
  const commitDates = commitDatesFromArtifacts(githubArtifacts);
  const commitHistory = commitHistoryFromArtifacts(githubArtifacts);
  let metrics = computeProductionAuditMetrics(
    usedExternalFallback ? null : filesystem,
    auditMode,
    commitHistory
  );
  result = attachAuditEvidence(
    applyFilesystemScoreCap(result, filesystem),
    filesystem,
    commitDates,
    commitHistory?.commitStats ?? undefined
  );
  result = attachModeEvaluation(result, auditMode, metrics);
  metrics = result.metrics;

  // Headline grade is the mode-weighted file-tree index only.
  // Gemini text stays on strengths, red flags, and recommendations.
  if (metrics.evidence.inspected) {
    result = applyFilesystemScoreCap(
      {
        ...result,
        score: metrics.productionScore,
        overallScore: metrics.productionScore,
      },
      filesystem
    );
    result = attachModeEvaluation(result, auditMode, metrics);
    metrics = result.metrics;
  }

  const isUpstreamDerivative = Boolean(
    githubArtifacts?.artifacts.some((artifact) => artifact.is_upstream_derivative)
  );
  if (metrics.evidence.inspected && isUpstreamDerivative) {
    const penalized = applyUpstreamDerivativePenalty(result.overallScore, true);
    metrics = {
      ...metrics,
      productionScore: penalized,
      codeHealthScore: penalized,
      upstreamDerivativePenalty: UPSTREAM_DERIVATIVE_PENALTY,
    };
    result = {
      ...result,
      score: penalized,
      overallScore: penalized,
      tier: assignAuditTier(auditMode, penalized),
      metrics,
      redFlags: result.redFlags.includes(UPSTREAM_DERIVATIVE_WARNING)
        ? result.redFlags
        : [...result.redFlags, UPSTREAM_DERIVATIVE_WARNING],
    };
  }

  const commitHistoryFetched = commitHistory != null;
  result = {
    ...result,
    commitHistoryFetched,
    auditedAt: new Date().toISOString(),
    executiveBrief: finalizeExecutiveBrief({
      draft: result.executiveBrief,
      productionScore: metrics.productionScore,
      architectureScore: metrics.architecture,
      testScore: metrics.testing,
      devopsScore: metrics.devops,
      resilienceScore: metrics.resilience,
      isUpstreamDerivative: metrics.upstreamDerivativePenalty > 0,
      auditMode,
    }),
  };
  if (!result.summary.trim() && result.executiveBrief?.employerSummary) {
    result = {
      ...result,
      summary: result.executiveBrief.employerSummary,
    };
  }

  const refinedRecommendations = refineActionableFixes(result.recommendations, {
    productionScore: metrics.productionScore,
    architecture: metrics.architecture,
    testingScore: metrics.testing,
    devopsScore: metrics.devops,
    resilience: metrics.resilience,
    testFileCount: filesystem?.unit_test_file_count ?? 0,
    language: primaryRepoLanguage(githubArtifacts),
    hasReadme: repoHasReadme(githubArtifacts, filesystem),
    needsSchemaValidation:
      filesystem?.route_contracts_sampled === true &&
      filesystem.route_schema_validation !== true,
    needsBuildGate:
      (filesystem?.ci_workflow_paths.length ?? 0) > 0 &&
      filesystem?.ci_has_build !== true,
  });
  result = {
    ...result,
    recommendations: refinedRecommendations,
    improvements: refinedRecommendations,
  };

  const usage = await bumpUsage();

  const auditedRepoUrl = workIsPrivate
    ? PRIVATE_AUDITED_REPO_LABEL
    : payload.githubUrl?.trim() ||
      githubArtifacts?.source_url ||
      githubArtifacts?.artifacts[0]?.repo_url ||
      PRIVATE_AUDITED_REPO_LABEL;
  const parsedRepo = parseGitHubUrl(auditedRepoUrl);
  const isPublicGitHubClaim = Boolean(
    !workIsPrivate &&
      parsedRepo?.owner &&
      parsedRepo.repo &&
      auditedRepoUrl !== PRIVATE_AUDITED_REPO_LABEL
  );

  let verificationStatus: DossierVerificationStatus = "unverified";
  let lowContributionWarning = false;
  if (
    access.user &&
    isPublicGitHubClaim &&
    payload.isPublicTeaser !== true &&
    !isAdminAudit
  ) {
    try {
      const ownership = await verifyGitHubRepoOwnership({
        user: access.user,
        repoUrl: auditedRepoUrl,
      });
      verificationStatus = ownership.verified ? "verified" : "unverified";
      lowContributionWarning = ownership.lowContributionWarning === true;
      if (
        lowContributionWarning &&
        !result.redFlags.includes(LOW_CONTRIBUTION_WARNING)
      ) {
        result = {
          ...result,
          redFlags: [...result.redFlags, LOW_CONTRIBUTION_WARNING],
        };
      }
    } catch (error) {
      console.error("[audit] ownership verification threw:", error);
      verificationStatus = "unverified";
    }
  }

  if (
    access.user &&
    !isAdminAudit &&
    payload.playground !== true &&
    payload.isPublicTeaser !== true &&
    (githubArtifactAuditSucceeded(githubArtifacts) ||
      (usedExternalFallback &&
        hasUsableExternalProjects(payload.externalProjects)))
  ) {
    if (verificationStatus === "verified" || workIsPrivate) {
      const primaryArtifact = githubArtifacts?.artifacts.find((artifact) =>
        githubAuditHasFetchedArtifacts(artifact)
      );
      if (primaryArtifact && result.executiveBrief) {
        primaryArtifact.executiveBrief = result.executiveBrief;
      }
      try {
        await persistOwnIntegrityAudit(
          access.supabase,
          access.user.id,
          result.score,
          githubArtifacts,
          payload.externalProjects ?? [],
          usedExternalFallback,
          result.scoreCap,
          result.metrics
        );
      } catch (error) {
        console.error("[audit] persist integrity audit threw:", error);
      }
    }

    try {
      const claim = buildProductionAuditClaim({
        score: result.score,
        githubUrl: auditedRepoUrl,
        filesystem,
        scoreCap: result.scoreCap,
        isPubliclyVisible: false,
        deliveryHygieneScore: result.metrics.deliveryHygieneScore,
        commitHistoryFetched: result.commitHistoryFetched,
        auditedAt: result.auditedAt,
      });
      await persistProfileProductionAudit(
        access.supabase,
        access.user.id,
        claim,
        {
          isPubliclyVisible: false,
          verificationStatus,
        }
      );
    } catch (error) {
      console.error("[audit] persist production audit threw:", error);
    }
  }

  const benchmark: CodebaseBenchmark = getCalibratedBenchmark(
    result.metrics.productionScore
  );
  const benchmarkClient = createServiceRoleClient();

  let profileSlug: string | null = null;
  let profileUrl: string | null = null;

  if (isAdminAudit && access.user) {
    verificationStatus = "verified";
    const dataClient = benchmarkClient ?? access.supabase;
    const canPublish = canPublishProductionScore(
      result.score,
      result.metrics.deliveryHygieneScore,
      result.commitHistoryFetched
    );
    const claim = buildProductionAuditClaim({
      score: result.score,
      githubUrl: auditedRepoUrl,
      filesystem,
      scoreCap: result.scoreCap,
      isPubliclyVisible: canPublish,
      deliveryHygieneScore: result.metrics.deliveryHygieneScore,
      commitHistoryFetched: result.commitHistoryFetched,
      auditedAt: result.auditedAt,
    });

    try {
      const target = await resolveAdminAuditTargetProfile(dataClient, {
        candidateHandle: payload.candidateHandle,
        githubOwner: parsedRepo?.owner ?? null,
      });

      if (target) {
        const persisted = await persistProfileProductionAudit(
          dataClient,
          target.id,
          claim,
          {
            isPubliclyVisible: canPublish,
            enrollInTalentPool: canPublish,
            verificationStatus: "verified",
          }
        );
        await applyAdminAuditCandidateLabel(
          dataClient,
          target.id,
          payload.candidateName
        );
        profileSlug = persisted.profileSlug ?? target.profileSlug;
      }
    } catch (error) {
      console.error("[audit] admin target profile persist threw:", error);
    }

    if (profileSlug) {
      profileUrl = buildPublicProfileUrl(profileSlug);
    }
  }

  let shareId: string | null = null;
  if (
    access.user &&
    (isAdminAudit ||
      (payload.playground !== true && payload.isPublicTeaser !== true))
  ) {
    const repoName =
      parsedRepo?.owner && parsedRepo.repo
        ? `${parsedRepo.owner}/${parsedRepo.repo}`
        : null;
    const shareClient = isAdminAudit
      ? (benchmarkClient ?? access.supabase)
      : access.supabase;
    const { data: shared, error: shareError } = await shareClient
      .from("shared_audits")
      .insert({
        user_id: access.user.id,
        payload: {
          result: { ...result, benchmark },
          repoName,
          repoUrl: auditedRepoUrl,
          candidateName: payload.candidateName ?? null,
          candidateHandle: payload.candidateHandle ?? null,
          profileSlug,
          adminAudit: isAdminAudit,
        },
      })
      .select("id")
      .maybeSingle();

    if (shareError) {
      console.error("[audit] shared audit insert failed:", shareError);
    } else if (shared && typeof shared.id === "string") {
      shareId = shared.id;
    }
  }

  const reportUrl = shareId ? `/audit/${shareId}` : null;
  const pdfUrl = shareId ? `/audit/${shareId}?print=1` : null;

  return NextResponse.json({
    ...result,
    benchmark,
    shareId,
    reportUrl,
    pdfUrl,
    profileUrl,
    profileSlug,
    ...usage,
    verification_status: verificationStatus,
    ownership_verified: verificationStatus === "verified",
    lowContributionWarning,
    adminAudit: isAdminAudit,
  });
}

import { cookies } from "next/headers";
import { NextResponse } from "next/server";
import { createClient } from "@/utils/supabase/server";

function isSupabaseAuthCookie(name: string): boolean {
  return name.startsWith("sb-") || name.includes("supabase");
}

export async function POST() {
  try {
    const supabase = await createClient();
    await supabase.auth.signOut();

    const cookieStore = await cookies();
    for (const cookie of cookieStore.getAll()) {
      if (isSupabaseAuthCookie(cookie.name)) {
        cookieStore.delete(cookie.name);
      }
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("API auth sign out error:", error);
    return NextResponse.json({ error: "Failed to sign out" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { getCorporateWorkEmailValidationMessage } from "@/lib/corporate-email";
import { parseJsonWithSchema } from "@/lib/parse-request-json";
import { createClient } from "@/utils/supabase/server";

const betaAccessBodySchema = z.object({
  company_name: z.string().optional(),
  work_email: z.string().optional(),
});

type SupabaseErrorLike = {
  code?: string;
  message?: string;
};

function isSchemaError(error: SupabaseErrorLike | null | undefined): boolean {
  if (!error) {
    return false;
  }

  return (
    error.code === "42P01" ||
    error.code === "42703" ||
    error.code === "PGRST204" ||
    error.code === "PGRST205" ||
    (error.message?.includes("does not exist") ?? false) ||
    (error.message?.includes("Could not find the table") ?? false) ||
    (error.message?.includes("Could not find the") ?? false)
  );
}

async function saveBetaLead(
  supabase: Awaited<ReturnType<typeof createClient>>,
  userId: string,
  companyName: string,
  workEmail: string
): Promise<{ saved: boolean; table?: string; warning?: string }> {
  try {
    const { error: betaLeadError } = await supabase.from("beta_leads").insert({
      user_id: userId,
      company_name: companyName,
      work_email: workEmail,
    });

    if (!betaLeadError) {
      return { saved: true, table: "beta_leads" };
    }

    if (isSchemaError(betaLeadError)) {
      console.warn(
        "[beta-access] beta_leads table unavailable, trying leads fallback:",
        betaLeadError
      );
    } else {
      console.error("[beta-access] beta_leads insert failed:", betaLeadError);
      return {
        saved: false,
        warning: betaLeadError.message ?? "Could not save beta lead.",
      };
    }
  } catch (error) {
    console.error("[beta-access] beta_leads insert threw:", error);
  }

  try {
    const { error: leadsError } = await supabase.from("leads").insert({
      user_id: userId,
      company_name: companyName,
      email: workEmail,
    });

    if (!leadsError) {
      return { saved: true, table: "leads" };
    }

    if (isSchemaError(leadsError)) {
      console.warn(
        "[beta-access] leads table unavailable; continuing without lead persistence:",
        leadsError
      );
      return {
        saved: false,
        warning: "Lead tables are not configured yet; beta access will still unlock.",
      };
    }

    console.error("[beta-access] leads insert failed:", leadsError);
    return {
      saved: false,
      warning: leadsError.message ?? "Could not save lead.",
    };
  } catch (error) {
    console.error("[beta-access] leads insert threw:", error);
    return {
      saved: false,
      warning: "Lead capture failed; beta access will still unlock.",
    };
  }
}

async function unlockEmployerProfile(
  supabase: Awaited<ReturnType<typeof createClient>>,
  userId: string,
  companyName: string,
  workEmail: string
): Promise<{ updated: boolean; warning?: string }> {
  try {
    const { data: profile, error: profileError } = await supabase
      .from("profiles")
      .update({
        is_pro: true,
        tier: "pro",
        company_name: companyName,
        contact_email: workEmail,
        email: workEmail,
      })
      .eq("id", userId)
      .select("id, is_pro, tier, company_name")
      .maybeSingle();

    if (!profileError && profile) {
      return { updated: true };
    }

    if (profileError && isSchemaError(profileError)) {
      console.warn(
        "[beta-access] Pro columns unavailable, falling back to company_name only:",
        profileError
      );

      const { error: fallbackError } = await supabase
        .from("profiles")
        .update({ company_name: companyName })
        .eq("id", userId);

      if (!fallbackError) {
        return {
          updated: false,
          warning:
            "Profile tier columns are missing; unlock will persist for this session.",
        };
      }

      console.error("[beta-access] company_name fallback failed:", fallbackError);
    } else if (profileError) {
      console.error("[beta-access] profile unlock failed:", profileError);
    }
  } catch (error) {
    console.error("[beta-access] profile unlock threw:", error);
  }

  return {
    updated: false,
    warning: "Could not update profile in Supabase; unlock will persist for this session.",
  };
}

export async function POST(request: Request) {
  const parsedBody = await parseJsonWithSchema(request, betaAccessBodySchema);
  if (!parsedBody.ok) {
    return parsedBody.response;
  }

  const body = parsedBody.data;
  const companyName = body.company_name?.trim() ?? "";
  const workEmail = body.work_email?.trim() ?? "";

  if (!companyName || !workEmail) {
    return NextResponse.json(
      { error: "Company name and work email are required." },
      { status: 400 }
    );
  }

  const emailError = getCorporateWorkEmailValidationMessage(workEmail);
  if (emailError) {
    return NextResponse.json({ error: emailError }, { status: 400 });
  }

  const supabase = await createClient();
  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();

  if (userError || !user) {
    return NextResponse.json({ error: "Unauthorized." }, { status: 401 });
  }

  const warnings: string[] = [];

  const leadResult = await saveBetaLead(
    supabase,
    user.id,
    companyName,
    workEmail
  );
  if (leadResult.warning) {
    warnings.push(leadResult.warning);
  }

  const profileResult = await unlockEmployerProfile(
    supabase,
    user.id,
    companyName,
    workEmail
  );
  if (profileResult.warning) {
    warnings.push(profileResult.warning);
  }

  return NextResponse.json({
    success: true,
    unlocked: true,
    lead_saved: leadResult.saved,
    lead_table: leadResult.table ?? null,
    profile_updated: profileResult.updated,
    company_name: companyName,
    work_email: workEmail,
    warnings: warnings.length > 0 ? warnings : undefined,
  });
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { parseJsonWithSchema } from "@/lib/parse-request-json";
import { getStripe } from "@/lib/stripe";
import { createClient } from "@/utils/supabase/server";

const checkoutBodySchema = z.object({
  candidateId: z.string().optional(),
  jobId: z.string().optional(),
  applicationId: z.string().optional(),
});

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    value
  );
}

export async function POST(request: Request) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const parsedBody = await parseJsonWithSchema(request, checkoutBodySchema);
    if (!parsedBody.ok) {
      return parsedBody.response;
    }

    const body = parsedBody.data;
    const candidateId = body.candidateId?.trim() ?? "";
    const jobId = body.jobId?.trim() ?? "";
    const applicationId = body.applicationId?.trim() ?? "";

    if (!candidateId || !jobId || !applicationId) {
      return NextResponse.json(
        { error: "candidateId, jobId, and applicationId are required." },
        { status: 400 }
      );
    }

    if (!isUuid(candidateId) || !isUuid(jobId) || !isUuid(applicationId)) {
      return NextResponse.json({ error: "Invalid request payload." }, { status: 400 });
    }

    const { data: job, error: jobError } = await supabase
      .from("jobs")
      .select("id, title, employer_id")
      .eq("id", jobId)
      .eq("employer_id", user.id)
      .maybeSingle();

    if (jobError) {
      console.error("[checkout] job lookup failed:", jobError);
      return NextResponse.json(
        { error: "Could not verify job ownership." },
        { status: 500 }
      );
    }

    if (!job) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const { data: application, error: applicationError } = await supabase
      .from("job_applications")
      .select("id, job_id, candidate_id, unlocked")
      .eq("id", applicationId)
      .eq("job_id", jobId)
      .eq("candidate_id", candidateId)
      .maybeSingle();

    if (applicationError) {
      console.error("[checkout] application lookup failed:", applicationError);
      return NextResponse.json(
        { error: "Could not verify application." },
        { status: 500 }
      );
    }

    if (!application) {
      return NextResponse.json({ error: "Application not found." }, { status: 404 });
    }

    if (application.unlocked) {
      return NextResponse.json(
        { error: "This candidate contact is already unlocked." },
        { status: 400 }
      );
    }

    const appUrl = process.env.NEXT_PUBLIC_APP_URL?.replace(/\/$/, "") ?? "http://localhost:3000";
    const successUrl = `${appUrl}/dashboard?payment_success=true&application_id=${encodeURIComponent(applicationId)}`;

    const session = await getStripe().checkout.sessions.create({
      mode: "payment",
      line_items: [
        {
          quantity: 1,
          price_data: {
            currency: "usd",
            unit_amount: 4900,
            product_data: {
              name: "Candidate Introduction Unlock",
              description: `Unlock contact details for ${job.title ?? "this role"}.`,
            },
          },
        },
      ],
      metadata: {
        candidateId,
        jobId,
        applicationId,
        employerId: user.id,
      },
      success_url: successUrl,
      cancel_url: `${appUrl}/dashboard?payment_canceled=true`,
    });

    if (!session.url) {
      return NextResponse.json(
        { error: "Could not create checkout session." },
        { status: 500 }
      );
    }

    return NextResponse.json({ url: session.url });
  } catch (error) {
    console.error("[checkout] unexpected error:", error);
    return NextResponse.json(
      { error: "Could not start checkout. Please try again." },
      { status: 500 }
    );
  }
}

