async function generateGeminiCollegeFit(
  credentials: ParsedCredentials
): Promise<CollegeFitResult> {
  const apiKey = process.env.GEMINI_API_KEY;

  if (!apiKey) {
    throw new Error("GEMINI_API_KEY is not configured.");
  }

  const ai = new GoogleGenAI({ apiKey });
  const systemInstruction = buildSystemPrompt(credentials.tier);
  const userPrompt = buildUserPrompt(credentials);

  let lastError: unknown;

  for (const model of MODEL_CANDIDATES) {
    try {
      const response = await ai.models.generateContent({
        model,
        contents: userPrompt,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: COLLEGE_FIT_RESPONSE_SCHEMA,
          temperature: 0,
        },
      });

      const text = response.text?.trim();

      if (!text) {
        throw new Error(`Gemini (${model}) returned an empty response.`);
      }

      return normalizeCollegeFitResult(JSON.parse(text));
    } catch (error) {
      lastError = error;
      console.error(`[college-fit] Gemini College Fit Error (${model}):`, error);
    }
  }

  throw lastError instanceof Error
    ? lastError
    : new Error("All Gemini models failed.");
}

export async function POST(request: Request) {
  const denied = await requireAiApiAccess();
  if (denied) {
    return denied;
  }

  const parsedBody = await parseJsonWithSchema(request, collegeFitBodySchema);
  if (!parsedBody.ok) {
    return parsedBody.response;
  }

  const { gpa, major, testScores, locationPreference, budgetPreference } =
    parsedBody.data;
  const credentials = buildParsedCredentials(
    gpa,
    major,
    testScores,
    locationPreference,
    budgetPreference
  );

  try {
    const result = await generateGeminiCollegeFit(credentials);
    return NextResponse.json(result);
  } catch (error) {
    console.error("[college-fit] Gemini College Fit Error — using fallback:", error);
    return NextResponse.json(buildFallbackReport(credentials));
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import type { SupabaseClient } from "@supabase/supabase-js";
import { resolveAccountRole } from "@/lib/account-role";
import { createServiceRoleClient } from "@/lib/admin-access";
import { requireApiUser } from "@/lib/api-auth";
import { isEmployerRole } from "@/lib/dashboard-account";
import {
  APPLICANT_PROFILE_COLUMNS,
  mapEmployerApplicant,
  type ApplicantProfileRow,
  type EmployerApplicantsPayload,
} from "@/lib/job-applicants";
import { parseJobListInput } from "@/lib/jobs";
import type { MatchResult } from "@/lib/match-heuristic";
import { parseJsonWithSchema } from "@/lib/parse-request-json";
import {
  employerIdentityIds,
  fetchProfileForCandidateId,
  fetchProfilesForCandidateIds,
} from "@/lib/resolve-candidate-profile";
import { isSupabaseSchemaError, schemaErrorMentionsColumn } from "@/lib/supabase-schema-errors";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const MAX_APPLICATIONS = 80;

type ApplicationRow = {
  id: string;
  job_id: string;
  candidate_id: string;
  created_at: string;
  unlocked?: boolean | null;
  review_status?: string | null;
};

type JobRow = {
  id: string;
  title: string | null;
  status: string | null;
  tags?: string[] | null;
  tech_stack?: string[] | null;
  required_skills?: string[] | null;
};

function matchKey(jobId: string, candidateId: string): string {
  return `${jobId}:${candidateId}`;
}

async function fetchEmployerJobs(
  client: SupabaseClient,
  employerIds: string[]
): Promise<{ jobs: JobRow[]; error: { message: string } | null }> {
  const first = await client
    .from("jobs")
    .select("id, title, status, tags, tech_stack, required_skills, created_at")
    .in("employer_id", employerIds)
    .order("created_at", { ascending: false });

  if (
    first.error &&
    isSupabaseSchemaError(first.error) &&
    (schemaErrorMentionsColumn(first.error, "tech_stack") ||
      schemaErrorMentionsColumn(first.error, "required_skills"))
  ) {
    const fallback = await client
      .from("jobs")
      .select("id, title, status, tags, created_at")
      .in("employer_id", employerIds)
      .order("created_at", { ascending: false });
    return {
      jobs: (fallback.data ?? []) as JobRow[],
      error: fallback.error,
    };
  }

  return {
    jobs: (first.data ?? []) as JobRow[],
    error: first.error,
  };
}

async function fetchJobApplications(
  client: SupabaseClient,
  jobIds: string[]
): Promise<{ rows: ApplicationRow[]; error: { message: string } | null }> {
  const first = await client
    .from("job_applications")
    .select("id, job_id, candidate_id, created_at, unlocked, review_status")
    .in("job_id", jobIds)
    .order("created_at", { ascending: false })
    .limit(MAX_APPLICATIONS);

  if (
    first.error &&
    isSupabaseSchemaError(first.error) &&
    (schemaErrorMentionsColumn(first.error, "unlocked") ||
      schemaErrorMentionsColumn(first.error, "review_status"))
  ) {
    const fallback = await client
      .from("job_applications")
      .select("id, job_id, candidate_id, created_at")
      .in("job_id", jobIds)
      .order("created_at", { ascending: false })
      .limit(MAX_APPLICATIONS);
    return {
      rows: (fallback.data ?? []) as ApplicationRow[],
      error: fallback.error,
    };
  }

  return {
    rows: (first.data ?? []) as ApplicationRow[],
    error: first.error,
  };
}

export async function GET(request: Request) {
  const access = await requireApiUser(request);
  if (access instanceof NextResponse) {
    return access;
  }

  const reader = createServiceRoleClient() ?? access.supabase;
  const viewerRow = await fetchProfileForCandidateId(
    reader,
    access.user.id,
    "id, user_id, role"
  );
  const viewerRole = resolveAccountRole(
    typeof viewerRow?.role === "string" ? viewerRow.role : null,
    access.user
  );

  if (!isEmployerRole(viewerRole)) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const employerIds = employerIdentityIds(access.user.id, viewerRow);
  const { jobs, error: jobsError } = await fetchEmployerJobs(reader, employerIds);

  if (jobsError) {
    console.error("[employer applicants] jobs lookup failed:", jobsError.message);
    return NextResponse.json(
      { error: "Could not load interested candidates." },
      { status: 500 }
    );
  }

  const jobSummaries = jobs.map((job) => ({
    id: job.id,
    title: job.title?.trim() || "Open Role",
    status: job.status === "paused" ? "Paused" : "Active",
  }));

  if (jobs.length === 0) {
    return NextResponse.json(
      { applicants: [], jobs: jobSummaries } satisfies EmployerApplicantsPayload,
      { headers: { "Cache-Control": "no-store" } }
    );
  }

  const jobIds = jobs.map((job) => job.id);
  const jobsById = new Map(jobs.map((job) => [job.id, job]));

  const { rows, error: applicationsError } = await fetchJobApplications(
    reader,
    jobIds
  );

  if (applicationsError) {
    console.error(
      "[employer applicants] applications lookup failed:",
      applicationsError.message
    );
    return NextResponse.json(
      { error: "Could not load interested candidates." },
      { status: 500 }
    );
  }

  const candidateIds = [
    ...new Set(rows.map((row) => row.candidate_id).filter(Boolean)),
  ];

  let profilesByRef = await fetchProfilesForCandidateIds(
    reader,
    candidateIds,
    APPLICANT_PROFILE_COLUMNS.join(", ")
  );

  if (profilesByRef.size === 0 && candidateIds.length > 0) {
    const fallbackColumns = APPLICANT_PROFILE_COLUMNS.filter(
      (column) =>
        column !== "key_accomplishments" && column !== "audit_data"
    );
    profilesByRef = await fetchProfilesForCandidateIds(
      reader,
      candidateIds,
      fallbackColumns.join(", ")
    );
  }

  const matchByKey = new Map<string, MatchResult | number>();
  if (candidateIds.length > 0) {
    const { data: matchRows, error: matchError } = await reader
      .from("talent_match_scores")
      .select(
        "candidate_id, job_id, match_percentage, reasoning, matching_skills, missing_skills"
      )
      .in("employer_id", employerIds)
      .in("job_id", jobIds)
      .in("candidate_id", candidateIds);

    if (matchError) {
      console.error(
        "[employer applicants] match scores lookup failed:",
        matchError.message
      );
    } else {
      for (const row of matchRows ?? []) {
        if (!row.candidate_id || !row.job_id) {
          continue;
        }
        matchByKey.set(matchKey(row.job_id, row.candidate_id), {
          match_percentage: row.match_percentage,
          reasoning: typeof row.reasoning === "string" ? row.reasoning : "",
          matching_skills: Array.isArray(row.matching_skills)
            ? row.matching_skills.filter(
                (skill): skill is string => typeof skill === "string"
              )
            : [],
          missing_skills: Array.isArray(row.missing_skills)
            ? row.missing_skills.filter(
                (skill): skill is string => typeof skill === "string"
              )
            : [],
        });
      }
    }
  }

  const introIds = new Set<string>();
  const profileIds = [
    ...new Set(
      candidateIds
        .map((id) => {
          const profile = profilesByRef.get(id) as ApplicantProfileRow | undefined;
          return (
            (typeof profile?.id === "string" && profile.id) ||
            (typeof profile?.user_id === "string" && profile.user_id) ||
            id
          );
        })
        .filter(Boolean)
    ),
  ];

  if (profileIds.length > 0) {
    const { data: introRows, error: introError } = await reader
      .from("intro_requests")
      .select("candidate_id")
      .in("user_id", employerIds)
      .in("candidate_id", profileIds);

    if (introError) {
      console.warn(
        "[employer applicants] intro requests lookup failed:",
        introError.message
      );
    } else {
      for (const row of introRows ?? []) {
        if (typeof row.candidate_id === "string" && row.candidate_id.trim()) {
          introIds.add(row.candidate_id.trim());
        }
      }
    }
  }

  const applicants = rows.flatMap((row) => {
    const job = jobsById.get(row.job_id);
    if (!job) {
      return [];
    }

    const profile = (profilesByRef.get(row.candidate_id) ??
      null) as ApplicantProfileRow | null;
    const profileId =
      (typeof profile?.id === "string" && profile.id) || row.candidate_id;

    return [
      mapEmployerApplicant({
        applicationId: row.id,
        candidateId: row.candidate_id,
        createdAt: row.created_at,
        unlocked: row.unlocked,
        profile,
        job: {
          id: job.id,
          title: job.title?.trim() || "Open Role",
          status: job.status,
          techStack: parseJobListInput(job.tech_stack),
          requiredSkills: parseJobListInput(
            job.required_skills && job.required_skills.length > 0
              ? job.required_skills
              : job.tags
          ),
          tags: parseJobListInput(job.tags),
        },
        cachedMatch: matchByKey.get(matchKey(row.job_id, row.candidate_id)),
        introRequested:
          introIds.has(profileId) || introIds.has(row.candidate_id),
        reviewStatus: row.review_status,
      }),
    ];
  });

  return NextResponse.json(
    { applicants, jobs: jobSummaries } satisfies EmployerApplicantsPayload,
    { headers: { "Cache-Control": "no-store" } }
  );
}

const APPLICATION_UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const rejectApplicantBodySchema = z.object({
  applicationId: z.string().optional(),
  status: z.string().optional(),
});

export async function PATCH(request: Request) {
  const access = await requireApiUser(request);
  if (access instanceof NextResponse) {
    return access;
  }

  const reader = createServiceRoleClient() ?? access.supabase;
  const viewerRow = await fetchProfileForCandidateId(
    reader,
    access.user.id,
    "id, user_id, role"
  );
  const viewerRole = resolveAccountRole(
    typeof viewerRow?.role === "string" ? viewerRow.role : null,
    access.user
  );

  if (!isEmployerRole(viewerRole)) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const parsedBody = await parseJsonWithSchema(
    request,
    rejectApplicantBodySchema
  );
  if (!parsedBody.ok) {
    return parsedBody.response;
  }

  const applicationId = parsedBody.data.applicationId?.trim() ?? "";
  const status = parsedBody.data.status?.trim().toLowerCase() ?? "";

  if (!APPLICATION_UUID_PATTERN.test(applicationId) || status !== "rejected") {
    return NextResponse.json({ error: "Invalid status update." }, { status: 400 });
  }

  const employerIds = employerIdentityIds(access.user.id, viewerRow);

  const { data: application, error: applicationError } = await reader
    .from("job_applications")
    .select("id, job_id")
    .eq("id", applicationId)
    .maybeSingle();

  if (applicationError) {
    console.error(
      "[employer applicants] reject lookup failed:",
      applicationError.message
    );
    return NextResponse.json(
      { error: "Could not update candidate status." },
      { status: 500 }
    );
  }

  if (!application?.job_id) {
    return NextResponse.json({ error: "Application not found." }, { status: 404 });
  }

  const { data: job, error: jobError } = await reader
    .from("jobs")
    .select("id, employer_id")
    .eq("id", application.job_id)
    .maybeSingle();

  if (jobError) {
    console.error("[employer applicants] reject job lookup failed:", jobError.message);
    return NextResponse.json(
      { error: "Could not update candidate status." },
      { status: 500 }
    );
  }

  if (!job || !employerIds.includes(job.employer_id)) {
    return NextResponse.json({ error: "Application not found." }, { status: 404 });
  }

  const { error: updateError } = await reader
    .from("job_applications")
    .update({ review_status: "rejected" })
    .eq("id", applicationId);

  if (updateError) {
    console.error(
      "[employer applicants] reject update failed:",
      updateError.message
    );
    return NextResponse.json(
      { error: "Could not update candidate status." },
      { status: 500 }
    );
  }

  return NextResponse.json(
    { ok: true, applicationId, status: "rejected" },
    { headers: { "Cache-Control": "no-store" } }
  );
}

import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import { createServiceRoleClient } from "@/lib/admin-access";
import { hashEmployerVerificationToken } from "@/lib/employer-email-verification";
import {
  employerIsVerifiedInDatabase,
  persistEmployerVerifiedFlag,
} from "@/lib/persist-employer-verified";
import { normalizeSiteUrl } from "@/lib/site";

export const runtime = "nodejs";

const cookieOptions = {
  path: "/",
  sameSite: "lax" as const,
};

function resolveRedirectOrigin(request: NextRequest): string {
  const envUrl = process.env.NEXT_PUBLIC_APP_URL?.replace(/\/$/, "");
  const forwardedHost = request.headers.get("x-forwarded-host");
  const isLocalEnv = process.env.NODE_ENV === "development";

  if (!isLocalEnv && forwardedHost) {
    return normalizeSiteUrl(`https://${forwardedHost}`);
  }

  if (envUrl) {
    return normalizeSiteUrl(envUrl);
  }

  return normalizeSiteUrl(new URL(request.url).origin);
}

function copyResponseCookies(from: NextResponse, to: NextResponse) {
  from.cookies.getAll().forEach((cookie) => {
    to.cookies.set(cookie);
  });
}

function wantsJsonResponse(request: NextRequest): boolean {
  const accept = request.headers.get("accept") ?? "";
  return accept.includes("application/json");
}

function verificationJson(
  input: { verified: boolean; signedIn: boolean; error?: string },
  cookieSource: NextResponse
) {
  const body = input.verified
    ? { verified: true as const, signedIn: input.signedIn }
    : {
        verified: false as const,
        signedIn: input.signedIn,
        error: input.error ?? "invalid",
      };
  const response = NextResponse.json(body, {
    status: input.verified ? 200 : 400,
  });
  copyResponseCookies(cookieSource, response);
  return response;
}

function verificationRedirect(
  origin: string,
  input: { verified: boolean; signedIn: boolean; error?: string },
  cookieSource: NextResponse
) {
  const path = input.signedIn ? "/dashboard" : "/login";
  const url = new URL(path, origin);

  if (!input.signedIn) {
    url.searchParams.set("next", "/dashboard");
  }

  if (input.verified) {
    url.searchParams.set("employer_verified", "1");
  } else {
    url.searchParams.set("employer_verified", "0");
    if (input.error) {
      url.searchParams.set("verify_error", input.error);
    }
  }

  const redirectResponse = NextResponse.redirect(url, 303);
  copyResponseCookies(cookieSource, redirectResponse);
  return redirectResponse;
}

export async function GET(request: NextRequest) {
  const origin = resolveRedirectOrigin(request);
  const token = request.nextUrl.searchParams.get("token")?.trim() ?? "";
  const preferJson = wantsJsonResponse(request);

  const cookieResponse = NextResponse.next({ request });
  let signedIn = false;

  try {
    const supabase = createServerClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
      {
        cookieOptions,
        cookies: {
          getAll() {
            return request.cookies.getAll();
          },
          setAll(cookiesToSet) {
            cookiesToSet.forEach(({ name, value, options }) => {
              request.cookies.set(name, value);
              cookieResponse.cookies.set(name, value, {
                ...cookieOptions,
                ...options,
              });
            });
          },
        },
      }
    );

    const {
      data: { user },
    } = await supabase.auth.getUser();
    signedIn = Boolean(user);
  } catch (error) {
    console.warn("[employer-verify] session refresh during confirm failed:", error);
  }

  const respond = (input: {
    verified: boolean;
    signedIn: boolean;
    error?: string;
  }) =>
    preferJson
      ? verificationJson(input, cookieResponse)
      : verificationRedirect(origin, input, cookieResponse);

  const fail = (error: string) =>
    respond({ verified: false, signedIn, error });
  const succeed = () => respond({ verified: true, signedIn });

  if (!token) {
    return fail("missing_token");
  }

  const admin = createServiceRoleClient();
  if (!admin) {
    return fail("unavailable");
  }

  const tokenHash = hashEmployerVerificationToken(token);
  const nowIso = new Date().toISOString();

  try {
    const { data: pending, error: lookupError } = await admin
      .from("employer_email_verifications")
      .select("id, user_id, email, expires_at, consumed_at")
      .eq("token_hash", tokenHash)
      .maybeSingle();

    if (lookupError) {
      console.error("[employer-verify] token lookup failed:", lookupError);
      return fail("invalid");
    }

    if (!pending?.user_id) {
      return fail("invalid");
    }

    const userId = String(pending.user_id);
    const workEmail = String(pending.email ?? "").trim().toLowerCase();
    const alreadyConsumed = Boolean(pending.consumed_at);
    const expired =
      typeof pending.expires_at === "string" &&
      new Date(pending.expires_at).getTime() <= Date.now();

    if (alreadyConsumed || expired) {
      if (await employerIsVerifiedInDatabase(admin, userId)) {
        return succeed();
      }
      return fail("invalid");
    }

    const persisted = await persistEmployerVerifiedFlag(admin, userId, workEmail);
    if (!persisted.ok) {
      console.error(
        "[employer-verify] failed to set is_verified=true for user",
        userId
      );
      return fail("update_failed");
    }

    const stillVerified = await employerIsVerifiedInDatabase(admin, userId);
    if (!stillVerified) {
      console.error(
        "[employer-verify] is_verified was not true after persist for",
        userId
      );
      return fail("update_failed");
    }

    const { error: consumeError } = await admin
      .from("employer_email_verifications")
      .update({ consumed_at: nowIso })
      .eq("id", pending.id)
      .is("consumed_at", null);

    if (consumeError) {
      console.warn("[employer-verify] token consume failed:", consumeError);
    }

    await admin
      .from("employer_email_verifications")
      .update({ consumed_at: nowIso })
      .eq("user_id", userId)
      .is("consumed_at", null);

    if (!(await employerIsVerifiedInDatabase(admin, userId))) {
      console.error("[employer-verify] is_verified did not remain true for", userId);
      return fail("update_failed");
    }

    return succeed();
  } catch (error) {
    console.error("[employer-verify] confirm threw:", error);
    return fail("update_failed");
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { createServiceRoleClient } from "@/lib/admin-access";
import { requireApiUser } from "@/lib/api-auth";
import { resolveAccountRole } from "@/lib/account-role";
import { getCorporateWorkEmailValidationMessage } from "@/lib/corporate-email";
import { isEmployerRole } from "@/lib/dashboard-account";
import {
  buildEmployerVerificationConfirmUrl,
  EMPLOYER_VERIFICATION_TTL_MS,
  generateEmployerVerificationToken,
} from "@/lib/employer-email-verification";
import { sendEmployerVerificationEmail } from "@/lib/send-employer-verification-email";
import { consumeRateLimit, tooManyRequestsResponse } from "@/lib/ip-rate-limit";
import { parseJsonWithSchema } from "@/lib/parse-request-json";
import { fetchProfileForCandidateId } from "@/lib/resolve-candidate-profile";
import { SITE_URL } from "@/lib/site";
import { normalizeEmail } from "@/lib/validate-email";

export const runtime = "nodejs";

const verifyEmailBodySchema = z.object({
  email: z.string().optional(),
});

export async function POST(request: Request) {
  const access = await requireApiUser(request);
  if (access instanceof NextResponse) {
    return access;
  }

  const limited = consumeRateLimit(
    `employer-verify:${access.user.id}`,
    3,
    15 * 60 * 1000
  );
  if (!limited.ok) {
    return tooManyRequestsResponse(limited.retryAfterSec);
  }

  const viewerRow = await fetchProfileForCandidateId(
    access.supabase,
    access.user.id,
    "id, role, is_verified, contact_email, email"
  );
  const viewerRole = resolveAccountRole(
    typeof viewerRow?.role === "string" ? viewerRow.role : null,
    access.user
  );

  if (!isEmployerRole(viewerRole)) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const parsedBody = await parseJsonWithSchema(request, verifyEmailBodySchema);
  if (!parsedBody.ok) {
    return parsedBody.response;
  }

  const workEmail = normalizeEmail(parsedBody.data.email ?? "").toLowerCase();
  const emailError = getCorporateWorkEmailValidationMessage(workEmail);
  if (emailError) {
    return NextResponse.json({ error: emailError }, { status: 400 });
  }

  const admin = createServiceRoleClient();
  if (!admin) {
    return NextResponse.json(
      { error: "Verification is temporarily unavailable." },
      { status: 503 }
    );
  }

  const { token, tokenHash } = generateEmployerVerificationToken();
  const now = new Date();
  const expiresAt = new Date(now.getTime() + EMPLOYER_VERIFICATION_TTL_MS).toISOString();

  const { error: invalidateError } = await admin
    .from("employer_email_verifications")
    .update({ consumed_at: now.toISOString() })
    .eq("user_id", access.user.id)
    .is("consumed_at", null);

  if (invalidateError) {
    console.error("[employer-verify] token invalidate failed:", invalidateError);
    return NextResponse.json(
      { error: "Could not start verification. Apply the latest database migration and try again." },
      { status: 500 }
    );
  }

  const { error: insertError } = await admin.from("employer_email_verifications").insert({
    user_id: access.user.id,
    email: workEmail,
    token_hash: tokenHash,
    expires_at: expiresAt,
  });

  if (insertError) {
    console.error("[employer-verify] token insert failed:", insertError);
    return NextResponse.json(
      { error: "Could not create a verification link. Try again shortly." },
      { status: 500 }
    );
  }

  const profileId =
    typeof viewerRow?.id === "string" ? viewerRow.id : access.user.id;
  const currentVerifiedEmail = (
    (typeof viewerRow?.contact_email === "string" && viewerRow.contact_email) ||
    (typeof viewerRow?.email === "string" && viewerRow.email) ||
    ""
  )
    .trim()
    .toLowerCase();
  const emailChanged = currentVerifiedEmail !== workEmail;

  const profilePatch: Record<string, string | boolean | null> = {
    contact_email: workEmail,
    email: workEmail,
  };
  if (emailChanged && viewerRow?.is_verified === true) {
    profilePatch.is_verified = false;
  }

  const { error: profileError } = await admin
    .from("profiles")
    .update(profilePatch)
    .eq("id", profileId);

  if (profileError) {
    console.warn("[employer-verify] profile email update failed:", profileError);
  }

  const confirmUrl = buildEmployerVerificationConfirmUrl(SITE_URL, token);
  const { error: sendError } = await sendEmployerVerificationEmail({
    to: workEmail,
    confirmUrl,
  });

  if (sendError) {
    return NextResponse.json({ error: sendError }, { status: 502 });
  }

  return NextResponse.json({
    success: true,
    email: workEmail,
    expires_at: expiresAt,
  });
}

import { GoogleGenAI, Type } from "@google/genai";
import { NextResponse } from "next/server";
import { z } from "zod";
import { requireAiApiAccess } from "@/lib/api-auth";
import { parseJsonWithSchema } from "@/lib/parse-request-json";

const essayReviewBodySchema = z.object({
  prompt: z.string().trim().min(1),
  draft: z.string().trim().min(1),
  targetSchool: z.string().optional(),
});

export type LineFeedback = {
  originalText: string;
  suggestion: string;
  reason: string;
};

export type EssayReviewResult = {
  overallScore: number;
  verdict: string;
  strengths: string[];
  improvements: string[];
  lineFeedback: LineFeedback[];
};

const SYSTEM_PROMPT = `You are an expert college admissions essay coach for Provix. Review the student's essay draft against the provided college prompt.

Return strict JSON only in this exact structure:
{
  "overallScore": number (integer 1-10),
  "verdict": "1-2 sentence overall assessment written in second person (You/Your)",
  "strengths": ["strength1", "strength2"],
  "improvements": ["improvement1", "improvement2"],
  "lineFeedback": [
    {
      "originalText": "exact quote or paraphrased phrase from the draft",
      "suggestion": "specific rewrite or edit",
      "reason": "brief explanation of why"
    }
  ]
}

Rules:
- overallScore must be an integer from 1 to 10 inclusive.
- verdict speaks directly to the student using "You" / "Your".
- strengths: 2-4 specific positives about voice, structure, authenticity, or fit.
- improvements: 2-4 actionable areas to strengthen the essay.
- lineFeedback: 2-5 targeted suggestions referencing actual phrases from the draft.
- Consider the target school when provided, but focus primarily on essay quality and prompt alignment.
- Do not include markdown, code fences, or extra keys.`;

const ESSAY_RESPONSE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    overallScore: {
      type: Type.INTEGER,
      description: "Overall essay score from 1 to 10.",
    },
    verdict: {
      type: Type.STRING,
      description: "Brief overall assessment in second person.",
    },
    strengths: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
    },
    improvements: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
    },
    lineFeedback: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          originalText: { type: Type.STRING },
          suggestion: { type: Type.STRING },
          reason: { type: Type.STRING },
        },
        required: ["originalText", "suggestion", "reason"],
      },
    },
  },
  required: [
    "overallScore",
    "verdict",
    "strengths",
    "improvements",
    "lineFeedback",
  ],
};

const MODEL_CANDIDATES = [
  "gemini-2.5-flash",
  "gemini-3.6-flash",
  "gemini-2.0-flash",
] as const;

function clampScore(value: unknown): number {
  const numeric =
    typeof value === "number"
      ? value
      : typeof value === "string"
        ? Number.parseInt(value, 10)
        : Number.NaN;

  if (!Number.isFinite(numeric)) {
    return 6;
  }

  return Math.min(10, Math.max(1, Math.round(numeric)));
}

function normalizeStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is string => typeof item === "string")
    .map((item) => item.trim())
    .filter(Boolean);
}

function normalizeLineFeedback(value: unknown): LineFeedback[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is Record<string, unknown> => !!item && typeof item === "object")
    .map((item) => ({
      originalText:
        typeof item.originalText === "string" ? item.originalText.trim() : "",
      suggestion:
        typeof item.suggestion === "string" ? item.suggestion.trim() : "",
      reason: typeof item.reason === "string" ? item.reason.trim() : "",
    }))
    .filter((item) => item.originalText || item.suggestion || item.reason);
}

function normalizeEssayReview(raw: unknown): EssayReviewResult {
  const record =
    raw && typeof raw === "object" ? (raw as Record<string, unknown>) : {};

  const verdict =
    typeof record.verdict === "string" && record.verdict.trim()
      ? record.verdict.trim()
      : "Your essay shows promise but needs more refinement to fully answer the prompt.";

  return {
    overallScore: clampScore(record.overallScore),
    verdict,
    strengths: normalizeStringArray(record.strengths),
    improvements: normalizeStringArray(record.improvements),
    lineFeedback: normalizeLineFeedback(record.lineFeedback),
  };
}

function buildFallbackReview(
  prompt: string,
  draft: string,
  targetSchool?: string
): EssayReviewResult {
  const wordCount = draft.trim().split(/\s+/).filter(Boolean).length;
  const hasStrongLength = wordCount >= 250 && wordCount <= 650;
  const schoolNote = targetSchool
    ? ` for ${targetSchool}`
    : "";

  const overallScore = clampScore(
    hasStrongLength ? 7 : wordCount < 150 ? 5 : 6
  );

  const strengths = hasStrongLength
    ? [
        "Your draft has enough depth to develop a compelling narrative.",
        "You provide material that can be shaped into a clearer personal story.",
      ]
    : ["You have a starting point to build from with focused revision."];

  const improvements = [
    wordCount < 250
      ? "Expand key moments with specific details and reflection."
      : "Tighten sentences and ensure every paragraph advances your main theme.",
    prompt
      ? "Make sure each section directly addresses the college prompt."
      : "Add a clearer through-line that connects your experiences.",
  ];

  const firstSentence =
    draft.trim().split(/[.!?]/)[0]?.trim().slice(0, 120) ||
    draft.trim().slice(0, 120);

  return {
    overallScore,
    verdict: `Your essay${schoolNote} has a workable foundation, but you should strengthen prompt alignment and add more vivid, specific details.`,
    strengths,
    improvements,
    lineFeedback: firstSentence
      ? [
          {
            originalText: firstSentence,
            suggestion:
              "Open with a specific scene or moment that immediately reveals your perspective.",
            reason:
              "Admissions readers connect faster when the essay starts in media res with concrete detail.",
          },
        ]
      : [],
  };
}

async function generateGeminiEssayReview(
  prompt: string,
  draft: string,
  targetSchool?: string
): Promise<EssayReviewResult> {
  const apiKey = process.env.GEMINI_API_KEY;

  if (!apiKey) {
    throw new Error("GEMINI_API_KEY is not configured.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const userPrompt = `Review this college admissions essay.

College Prompt:
${prompt}

${targetSchool ? `Target School: ${targetSchool}` : "Target School: Not specified"}

Essay Draft:
${draft}`;

  let lastError: unknown;

  for (const model of MODEL_CANDIDATES) {
    try {
      const response = await ai.models.generateContent({
        model,
        contents: userPrompt,
        config: {
          systemInstruction: SYSTEM_PROMPT,
          responseMimeType: "application/json",
          responseSchema: ESSAY_RESPONSE_SCHEMA,
          temperature: 0.3,
        },
      });

      const text = response.text?.trim();

      if (!text) {
        throw new Error(`Gemini (${model}) returned an empty response.`);
      }

      return normalizeEssayReview(JSON.parse(text));
    } catch (error) {
      lastError = error;
      console.error(`Gemini essay review failed for model ${model}:`, error);
    }
  }

  throw lastError instanceof Error
    ? lastError
    : new Error("All Gemini models failed.");
}

export async function POST(request: Request) {
  const denied = await requireAiApiAccess();
  if (denied) {
    return denied;
  }

  const parsedBody = await parseJsonWithSchema(request, essayReviewBodySchema);
  if (!parsedBody.ok) {
    return parsedBody.response;
  }

  const { prompt, draft, targetSchool } = parsedBody.data;

  try {
    const result = await generateGeminiEssayReview(prompt, draft, targetSchool);
    return NextResponse.json(result);
  } catch (error) {
    console.error("Gemini Essay Review Error:", error);
    return NextResponse.json(
      buildFallbackReview(prompt, draft, targetSchool)
    );
  }
}

import { GoogleGenAI, Type } from "@google/genai";
import { NextResponse } from "next/server";
import { z } from "zod";
import { requireAiApiAccess } from "@/lib/api-auth";
import { parseJsonWithSchema } from "@/lib/parse-request-json";

export type InterviewSimulatorRequestBody = {
  targetJobTitle?: string;
  coreTechStack?: string;
  interviewRound?: string;
  companyType?: string;
};

const interviewSimulatorBodySchema = z
  .object({
    targetJobTitle: z.string().optional(),
    coreTechStack: z.string().optional(),
    interviewRound: z.string().optional(),
    companyType: z.string().optional(),
  })
  .refine(
    (data) => !!data.targetJobTitle?.trim() || !!data.coreTechStack?.trim(),
    {
      message:
        "Provide at least a target job title or core tech stack to simulate.",
    }
  );

export type InterviewQuestion = {
  question: string;
  idealAnswer: string;
  talkingPoints: string[];
};

export type InterviewSimulatorResult = {
  questions: InterviewQuestion[];
  technicalTrap: string;
  closingQuestion: string;
};

const SYSTEM_PROMPT = `You are Provix's Interview Simulator — a rigorous hiring manager coach for technical and architecture interviews.

Given a target job title, core tech stack, interview round, and company type, generate a realistic interview simulation cheat sheet.

Return strict JSON only:
{
  "questions": [
    {
      "question": "Interview question tailored to role, stack, and round",
      "idealAnswer": "Strong sample answer structure the candidate should aim for",
      "talkingPoints": ["key point 1", "key point 2", "key point 3"]
    }
  ],
  "technicalTrap": "The top technical trap or pitfall to avoid in this round",
  "closingQuestion": "One smart question the candidate should ask the interviewer at the end"
}

Rules:
- questions: exactly 4 objects, ordered from foundational to deeper.
- Tailor difficulty and focus to the interview round:
  * Initial Technical Screen — coding fundamentals, stack fluency, debugging, API/data basics.
  * System Design & Architecture — scalability, tradeoffs, data modeling, reliability, component boundaries.
  * Behavioral & Culture Fit — ownership, ambiguity, collaboration, startup/enterprise context.
- Adapt tone and expectations to company type (Early-Stage Startup, High-Growth Scaleup, Enterprise).
- idealAnswer: concise but substantive — show structure, not fluff.
- talkingPoints: 2-4 bullets per question highlighting what graders listen for.
- technicalTrap: one specific, actionable pitfall (not generic "don't be nervous").
- closingQuestion: thoughtful, role-specific, shows seniority and curiosity.
- No markdown, no extra keys.`;

const INTERVIEW_RESPONSE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    questions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          question: { type: Type.STRING },
          idealAnswer: { type: Type.STRING },
          talkingPoints: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
          },
        },
        required: ["question", "idealAnswer", "talkingPoints"],
      },
    },
    technicalTrap: { type: Type.STRING },
    closingQuestion: { type: Type.STRING },
  },
  required: ["questions", "technicalTrap", "closingQuestion"],
};

const MODEL_CANDIDATES = [
  "gemini-1.5-flash",
  "gemini-2.0-flash",
  "gemini-2.5-flash",
  "gemini-3.6-flash",
] as const;

function normalizeStringArray(value: unknown, maxItems = 4): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is string => typeof item === "string")
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, maxItems);
}

function normalizeQuestion(item: unknown): InterviewQuestion | null {
  if (!item || typeof item !== "object") {
    return null;
  }

  const record = item as Record<string, unknown>;
  const question =
    typeof record.question === "string" ? record.question.trim() : "";
  const idealAnswer =
    typeof record.idealAnswer === "string" ? record.idealAnswer.trim() : "";

  if (!question) {
    return null;
  }

  return {
    question,
    idealAnswer:
      idealAnswer ||
      "Open with context, explain your approach, tradeoffs, and a concrete example from past work.",
    talkingPoints: normalizeStringArray(record.talkingPoints, 4),
  };
}

function normalizeInterviewResult(raw: unknown): InterviewSimulatorResult {
  const record =
    raw && typeof raw === "object" ? (raw as Record<string, unknown>) : {};

  const questions = Array.isArray(record.questions)
    ? record.questions
        .map(normalizeQuestion)
        .filter((item): item is InterviewQuestion => item !== null)
        .slice(0, 4)
    : [];

  const technicalTrap =
    typeof record.technicalTrap === "string" && record.technicalTrap.trim()
      ? record.technicalTrap.trim()
      : "Avoid hand-waving on tradeoffs — interviewers penalize vague answers without constraints or metrics.";

  const closingQuestion =
    typeof record.closingQuestion === "string" && record.closingQuestion.trim()
      ? record.closingQuestion.trim()
      : "What does success look like in the first 90 days for this role on your team?";

  return {
    questions,
    technicalTrap,
    closingQuestion,
  };
}

function buildFallbackInterview(
  body: InterviewSimulatorRequestBody
): InterviewSimulatorResult {
  const title = body.targetJobTitle?.trim() || "Software Engineer";
  const stack = body.coreTechStack?.trim() || "TypeScript, APIs, databases";
  const round = body.interviewRound?.trim() || "Initial Technical Screen";
  const company = body.companyType?.trim() || "Early-Stage Startup";

  const isSystemDesign = round.includes("System Design");
  const isBehavioral = round.includes("Behavioral");

  let questions: InterviewQuestion[];

  if (isSystemDesign) {
    questions = [
      {
        question: `Design a service for ${title} responsibilities using ${stack}. How would you handle read-heavy traffic?`,
        idealAnswer:
          "Clarify requirements, estimate scale, propose layered architecture (CDN/cache, app tier, DB), discuss read replicas or caching strategy, and note tradeoffs.",
        talkingPoints: [
          "Ask clarifying questions before designing",
          "Quantify scale assumptions",
          "Separate hot path from admin/analytics reads",
        ],
      },
      {
        question: "Where would you draw service boundaries, and what belongs in a shared library vs a microservice?",
        idealAnswer:
          "Bound by change frequency and team ownership; shared libs for pure utilities, services for deployable business capabilities with clear APIs.",
        talkingPoints: [
          "Domain-driven boundaries",
          "Avoid premature microservices",
          "Contract/versioning between services",
        ],
      },
      {
        question: "How do you ensure reliability when a downstream dependency fails?",
        idealAnswer:
          "Timeouts, retries with jitter, circuit breakers, graceful degradation, idempotency, and observability on error budgets.",
        talkingPoints: [
          "Fail fast with bounded retries",
          "User-visible fallback paths",
          "Metrics and alerting on SLOs",
        ],
      },
      {
        question: `How would schema or API evolution work as ${company} scales product scope?`,
        idealAnswer:
          "Backward-compatible API versioning, expand-contract migrations, feature flags, and staged rollouts with rollback plans.",
        talkingPoints: [
          "Zero-downtime migrations",
          "Versioned public contracts",
          "Coordination across teams",
        ],
      },
    ];
  } else if (isBehavioral) {
    questions = [
      {
        question: `Tell me about a time you shipped under ambiguity as a ${title}.`,
        idealAnswer:
          "Situation with unclear requirements, actions you took to reduce ambiguity, stakeholder alignment, outcome with metric, and lesson learned.",
        talkingPoints: [
          "STAR structure",
          "Specific decision you owned",
          "Measurable result",
        ],
      },
      {
        question: `How do you collaborate with non-engineers at a ${company}?`,
        idealAnswer:
          "Translate technical tradeoffs into business impact, set expectations early, document decisions, and iterate with feedback loops.",
        talkingPoints: [
          "Clear communication cadence",
          "Written decision records",
          "Empathy for business constraints",
        ],
      },
      {
        question: "Describe a mistake you made in production and how you handled it.",
        idealAnswer:
          "Own the incident, communicate timeline, mitigate user impact, root-cause analysis, and preventive follow-ups.",
        talkingPoints: [
          "Accountability without blame",
          "Postmortem culture",
          "Systemic fixes",
        ],
      },
      {
        question: "Why this role and company type now?",
        idealAnswer:
          "Connect your proof-of-work to their stage, explain what you want to learn, and show you've researched their product and constraints.",
        talkingPoints: [
          "Authentic motivation",
          "Stage-fit (speed vs process)",
          "Growth alignment",
        ],
      },
    ];
  } else {
    questions = [
      {
        question: `Walk me through how you'd build a feature end-to-end with ${stack}.`,
        idealAnswer:
          "Requirements → API contract → data model → implementation → tests → deployment → monitoring, calling out stack-specific choices.",
        talkingPoints: [
          "Structured delivery process",
          "Testing strategy",
          "Operational readiness",
        ],
      },
      {
        question: "How would you debug a slow API endpoint in production?",
        idealAnswer:
          "Check metrics/traces, reproduce locally, profile DB queries, inspect N+1 or missing indexes, validate caching, roll out fix with verification.",
        talkingPoints: [
          "Observability first",
          "Hypothesis-driven debugging",
          "Safe rollout",
        ],
      },
      {
        question: `Explain a tradeoff you made when choosing tools from ${stack}.`,
        idealAnswer:
          "State options, constraints, decision criteria, chosen approach, and what you'd revisit at higher scale.",
        talkingPoints: [
          "Explicit tradeoffs",
          "Context-dependent choices",
          "Future scalability",
        ],
      },
      {
        question: "How do you write tests for a critical user flow?",
        idealAnswer:
          "Unit tests for logic, integration tests for API/DB boundaries, one happy-path e2e, and edge cases for auth/validation failures.",
        talkingPoints: [
          "Test pyramid balance",
          "Deterministic fixtures",
          "CI gating",
        ],
      },
    ];
  }

  return normalizeInterviewResult({
    questions,
    technicalTrap: isSystemDesign
      ? "Jumping to microservices before defining load, consistency, and team boundaries — interviewers want pragmatic scaling, not buzzwords."
      : isBehavioral
        ? "Giving polished but unverifiable stories without metrics, scope, or your specific contribution."
        : `Name-dropping ${stack} without explaining how you'd use each tool under ${company} constraints.`,
    closingQuestion: isSystemDesign
      ? "What are the top two scalability bottlenecks your team is actively designing around this quarter?"
      : isBehavioral
        ? "How does your engineering team define ownership and success in the first 90 days?"
        : "What would you expect me to ship in my first 30 days that would clearly add value?",
  });
}

async function generateGeminiInterview(
  body: InterviewSimulatorRequestBody
): Promise<InterviewSimulatorResult> {
  const apiKey = process.env.GEMINI_API_KEY;

  if (!apiKey) {
    throw new Error("GEMINI_API_KEY is not configured.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const userPrompt = JSON.stringify({
    targetJobTitle: body.targetJobTitle?.trim() ?? "",
    coreTechStack: body.coreTechStack?.trim() ?? "",
    interviewRound: body.interviewRound?.trim() ?? "Initial Technical Screen",
    companyType: body.companyType?.trim() ?? "Early-Stage Startup",
  });

  let lastError: unknown;

  for (const model of MODEL_CANDIDATES) {
    try {
      const response = await ai.models.generateContent({
        model,
        contents: userPrompt,
        config: {
          systemInstruction: SYSTEM_PROMPT,
          responseMimeType: "application/json",
          responseSchema: INTERVIEW_RESPONSE_SCHEMA,
          temperature: 0.35,
        },
      });

      const text = response.text?.trim();

      if (!text) {
        throw new Error(`Gemini (${model}) returned an empty response.`);
      }

      const normalized = normalizeInterviewResult(JSON.parse(text));

      if (normalized.questions.length < 4) {
        throw new Error(`Gemini (${model}) returned fewer than 4 questions.`);
      }

      return normalized;
    } catch (error) {
      lastError = error;
      console.error(`Gemini interview-simulator failed for model ${model}:`, error);
    }
  }

  throw lastError instanceof Error
    ? lastError
    : new Error("All Gemini models failed.");
}

export async function POST(request: Request) {
  const denied = await requireAiApiAccess();
  if (denied) {
    return denied;
  }

  const parsedBody = await parseJsonWithSchema(
    request,
    interviewSimulatorBodySchema
  );
  if (!parsedBody.ok) {
    return parsedBody.response;
  }

  const payload = parsedBody.data;

  try {
    const result = await generateGeminiInterview(payload);
    return NextResponse.json(result);
  } catch (error) {
    console.error("Gemini interview-simulator API failed, using fallback:", error);
    return NextResponse.json(buildFallbackInterview(payload));
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { createServiceRoleClient } from "@/lib/admin-access";
import { parseJsonWithSchema } from "@/lib/parse-request-json";
import {
  fetchCandidateIntroRequestById,
  updateCandidateIntroDismissed,
} from "@/lib/respond-candidate-intro";
import { createClient } from "@/utils/supabase/server";

const dismissBodySchema = z.object({
  dismissed: z.boolean(),
});

export async function POST(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await context.params;
    const introId = id?.trim() ?? "";
    const parsedBody = await parseJsonWithSchema(request, dismissBodySchema);
    if (!parsedBody.ok) {
      return parsedBody.response;
    }

    const dismissed = parsedBody.data.dismissed;

    if (!introId) {
      return NextResponse.json(
        { error: "Intro id and dismissed are required." },
        { status: 400 }
      );
    }

    const authClient = await createClient();
    const {
      data: { user },
    } = await authClient.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const introRequest = await fetchCandidateIntroRequestById(authClient, introId, {
      candidateId: user.id,
    });

    if (!introRequest) {
      return NextResponse.json(
        { error: "Intro request not found." },
        { status: 404 }
      );
    }

    const dataClient = createServiceRoleClient() ?? authClient;
    const updated = await updateCandidateIntroDismissed(
      dataClient,
      introRequest,
      dismissed
    );

    if (!updated) {
      return NextResponse.json(
        { error: "Could not update intro request." },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      dismissed,
      status: updated.status,
      candidate_dismissed_at: updated.candidate_dismissed_at ?? null,
      message: dismissed
        ? "Intro request moved to dismissed."
        : "Intro request restored to your inbox.",
      data: updated,
    });
  } catch (error) {
    console.error("Intro dismiss POST error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

