      a { display: inline-block; margin-top: 20px; background: #4f46e5; color: #fff; text-decoration: none; font-weight: 700; padding: 12px 18px; border-radius: 12px; }
    </style>
  </head>
  <body>
    <div class="wrap">
      <h1>${input.title}</h1>
      <p>${input.message}</p>
      <a href="${input.dashboardUrl}">Open Intro Requests</a>
    </div>
  </body>
</html>`;
}

function buildSuccessResponse(input: {
  status: CandidateIntroStatus;
  message: string;
  data?: unknown;
  wantsHtml: boolean;
  title: string;
  dashboardUrl: string;
}) {
  if (input.wantsHtml) {
    return new NextResponse(
      buildRespondHtml({
        title: input.title,
        message: input.message,
        dashboardUrl: input.dashboardUrl,
      }),
      { status: 200, headers: { "Content-Type": "text/html; charset=utf-8" } }
    );
  }

  return NextResponse.json(
    {
      success: true,
      status: input.status,
      message: input.message,
      data: input.data,
    },
    { status: 200 }
  );
}

async function handleIntroResponse(
  id: string,
  action: IntroRespondAction,
  options?: {
    token?: string | null;
    wantsHtml?: boolean;
  }
) {
  const wantsHtml = options?.wantsHtml ?? false;
  const dashboardUrl = `${getPublicProfileBaseUrl()}/dashboard?tab=intro_requests`;
  const token = options?.token?.trim() || null;

  let introRequest = null;
  let dataClient = createServiceRoleClient();
  let emailClient = dataClient;

  if (token) {
    if (!dataClient) {
      return NextResponse.json(
        { error: "Server misconfigured for email intro responses." },
        { status: 500 }
      );
    }

    introRequest = await fetchCandidateIntroRequestById(dataClient, id, {
      responseToken: token,
    });
  } else {
    const authClient = await createClient();
    const {
      data: { user },
    } = await authClient.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    dataClient = dataClient ?? authClient;
    emailClient = createServiceRoleClient() ?? authClient;

    introRequest = await fetchCandidateIntroRequestById(authClient, id, {
      candidateId: user.id,
    });
  }

  if (!dataClient) {
    return NextResponse.json({ error: "Server misconfigured" }, { status: 500 });
  }

  if (!introRequest) {
    return NextResponse.json(
      { error: "Intro request not found." },
      { status: 404 }
    );
  }

  const currentStatus = toCandidateIntroStatus(introRequest.status);

  if (!isPendingCandidateIntroStatus(introRequest.status)) {
    const message =
      currentStatus === "accepted"
        ? "This intro request was already accepted."
        : currentStatus === "dismissed"
          ? "This intro request was dismissed."
          : "This intro request was already declined.";

    return buildSuccessResponse({
      status: currentStatus,
      message,
      wantsHtml,
      title: "Intro request already handled",
      dashboardUrl,
    });
  }

  const updated = await updateCandidateIntroRequestStatus(
    dataClient,
    id,
    action
  );

  if (!updated) {
    return NextResponse.json(
      { error: "Could not update intro request." },
      { status: 500 }
    );
  }

  if (updated.status === "accepted") {
    await sendIntroEmail(updated.row, emailClient ?? dataClient);
  }

  const title = updated.status === "accepted" ? "Intro accepted" : "Intro declined";
  const message =
    updated.status === "accepted"
      ? "You're connected. Check your inbox for the mutual introduction email with employer contact details."
      : "The employer has been notified that you declined this introduction request.";

  return buildSuccessResponse({
    status: updated.status,
    message,
    data: updated.row,
    wantsHtml,
    title,
    dashboardUrl,
  });
}

export async function GET(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  const { id } = await context.params;
  const { searchParams } = new URL(request.url);
  const action = parseAction(searchParams.get("action"));
  const token = searchParams.get("token");

  if (!id?.trim() || !action) {
    return NextResponse.json(
      { error: "Intro id and action are required." },
      { status: 400 }
    );
  }

  if (!token?.trim()) {
    return NextResponse.json(
      { error: "Response token is required for email links." },
      { status: 400 }
    );
  }

  try {
    return await handleIntroResponse(id.trim(), action, {
      token,
      wantsHtml: true,
    });
  } catch (error) {
    console.error("Intro respond GET error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

export async function POST(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await context.params;
    const parsedBody = await parseJsonWithSchema(request, respondBodySchema);
    if (!parsedBody.ok) {
      return parsedBody.response;
    }

    const body = parsedBody.data;
    const action = parseAction(body.action ?? null);

    if (!id?.trim() || !action) {
      return NextResponse.json(
        { error: "Intro id and action are required." },
        { status: 400 }
      );
    }

    return await handleIntroResponse(id.trim(), action, {
      token: body.token,
      wantsHtml: false,
    });
  } catch (error) {
    console.error("Intro respond POST error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { randomUUID } from "crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { createServiceRoleClient } from "@/lib/admin-access";
import { requireVerifiedEmployer } from "@/lib/api-auth";
import { isCorporateWorkEmail } from "@/lib/corporate-email";
import {
  buildIntroRequestInsertPayload,
  CANDIDATE_INTRO_REQUEST_COLUMNS,
} from "@/lib/candidate-intro-requests";
import {
  CONTRACT_INTRO_COMMITMENT_OPTIONS,
  CONTRACT_INTRO_DURATION_OPTIONS,
  formatContractIntroCompensationRange,
} from "@/lib/intro-hire-type";
import { parseJsonWithSchema } from "@/lib/parse-request-json";
import { sendCandidateIntroRequestEmail } from "@/lib/send-intro-email";

const introRequestBodySchema = z.object({
  candidateId: z.string().trim().min(1),
  candidateName: z.string().trim().min(1),
  companyName: z.string().trim().min(1),
  companyEmail: z
    .string()
    .trim()
    .min(1)
    .refine((email) => isCorporateWorkEmail(email), {
      message: "A valid corporate work email is required.",
    }),
  targetRole: z.string().trim().min(1),
  compensationRange: z.string().trim().min(1),
  hireType: z.enum(["fulltime", "contract"]).optional().default("fulltime"),
  contractHourlyRate: z.number().positive().optional(),
  estimatedCommitment: z
    .enum(CONTRACT_INTRO_COMMITMENT_OPTIONS)
    .optional(),
  estimatedDuration: z.enum(CONTRACT_INTRO_DURATION_OPTIONS).optional(),
  termsAccepted: z.literal(true),
});

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
    value
  );
}

export async function POST(request: Request) {
  try {
    const access = await requireVerifiedEmployer(request);
    if (access instanceof NextResponse) {
      return access;
    }

    const { user, supabase: authClient } = access;

    const parsedBody = await parseJsonWithSchema(request, introRequestBodySchema);
    if (!parsedBody.ok) {
      return parsedBody.response;
    }

    const body = parsedBody.data;
    const candidateId = body.candidateId;
    if (!isUuid(candidateId)) {
      return NextResponse.json(
        { error: "A valid candidate profile id is required." },
        { status: 400 }
      );
    }

    const serviceClient = createServiceRoleClient() ?? authClient;
    const tosAcceptedAt = new Date().toISOString();
    const responseToken = randomUUID();

    // Contract details are folded into compensation_range/band text so existing
    // full-time intro_requests rows and columns stay compatible.
    let compensationRange = body.compensationRange;
    if (body.hireType === "contract") {
      if (
        typeof body.contractHourlyRate === "number" &&
        body.estimatedCommitment &&
        body.estimatedDuration
      ) {
        compensationRange = formatContractIntroCompensationRange({
          hourlyRate: body.contractHourlyRate,
          commitment: body.estimatedCommitment,
          duration: body.estimatedDuration,
        });
      } else if (!/^Contract\s+\$/i.test(compensationRange)) {
        return NextResponse.json(
          {
            error:
              "Contract introductions require hourly rate, commitment, and duration.",
          },
          { status: 400 }
        );
      }
    }

    const insertPayload = buildIntroRequestInsertPayload({
      userId: user.id,
      candidateId,
      candidateName: body.candidateName,
      companyName: body.companyName,
      companyEmail: body.companyEmail,
      targetRole: body.targetRole,
      compensationRange,
      tosAcceptedAt,
      responseToken,
    });

    const { data: introRequest, error: insertError } = await authClient
      .from("intro_requests")
      .insert(insertPayload)
      .select(CANDIDATE_INTRO_REQUEST_COLUMNS)
      .single();

    if (insertError || !introRequest) {
      console.error("Intro request insert error:", insertError);
      return NextResponse.json(
        { error: "Could not submit intro request." },
        { status: 500 }
      );
    }

    const { data: candidateProfile } = await serviceClient
      .from("profiles")
      .select("contact_email, email")
      .eq("id", candidateId)
      .maybeSingle();

    const candidateEmail =
      candidateProfile?.contact_email?.trim() ||
      candidateProfile?.email?.trim() ||
      "";

    if (candidateEmail) {
      await sendCandidateIntroRequestEmail(
        introRequest,
        candidateEmail,
        serviceClient
      );
    } else {
      console.warn(
        "Intro request saved but candidate email unavailable for notification."
      );
    }

    return NextResponse.json(
      {
        success: true,
        data: {
          id: introRequest.id,
          status: introRequest.status,
        },
      },
      { status: 201 }
    );
  } catch (error) {
    console.error("Intro request API error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { createServiceRoleClient } from "@/lib/admin-access";
import { requireVerifiedEmployer } from "@/lib/api-auth";
import {
  employerIdentityIds,
  fetchProfileForCandidateId,
  fetchProfilesForCandidateIds,
} from "@/lib/resolve-candidate-profile";
import { isSupabaseSchemaError, schemaErrorMentionsColumn } from "@/lib/supabase-schema-errors";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export async function GET(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  const access = await requireVerifiedEmployer(request);
  if (access instanceof NextResponse) {
    return access;
  }

  const { id: jobId } = await context.params;
  if (!UUID_PATTERN.test(jobId)) {
    return NextResponse.json({ error: "Invalid job id." }, { status: 400 });
  }

  const reader = createServiceRoleClient() ?? access.supabase;
  const viewerRow = await fetchProfileForCandidateId(
    reader,
    access.user.id,
    "id, user_id, role"
  );
  const employerIds = employerIdentityIds(access.user.id, viewerRow);

  const { data: job, error: jobError } = await reader
    .from("jobs")
    .select("id, employer_id")
    .eq("id", jobId)
    .maybeSingle();

  if (jobError) {
    console.error("[job applicants] job lookup failed:", jobError.message);
    return NextResponse.json(
      { error: "Could not load job applicants." },
      { status: 500 }
    );
  }

  if (!job || !employerIds.includes(job.employer_id)) {
    return NextResponse.json({ error: "Job not found." }, { status: 404 });
  }

  let applications: Array<{
    id: string;
    candidate_id: string;
    created_at: string;
    unlocked?: boolean | null;
  }> | null = null;
  let applicationsError: { message: string } | null = null;

  {
    const first = await reader
      .from("job_applications")
      .select("id, candidate_id, created_at, unlocked")
      .eq("job_id", jobId)
      .order("created_at", { ascending: false });

    applications = first.data ?? null;
    applicationsError = first.error;

    if (
      applicationsError &&
      isSupabaseSchemaError(applicationsError) &&
      schemaErrorMentionsColumn(applicationsError, "unlocked")
    ) {
      const fallback = await reader
        .from("job_applications")
        .select("id, candidate_id, created_at")
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });
      applications = fallback.data ?? [];
      applicationsError = fallback.error;
    }
  }

  if (applicationsError) {
    console.error(
      "[job applicants] applications lookup failed:",
      applicationsError.message
    );
    return NextResponse.json(
      { error: "Could not load job applicants." },
      { status: 500 }
    );
  }

  const rows = applications ?? [];
  const candidateIds = rows
    .map((row) => row.candidate_id)
    .filter((value): value is string => typeof value === "string");

  const profilesByRef = await fetchProfilesForCandidateIds(reader, candidateIds);

  const profiles: Record<string, Record<string, unknown>> = {};
  for (const candidateId of candidateIds) {
    const row = profilesByRef.get(candidateId);
    if (row) {
      profiles[candidateId] = row;
    }
  }

  const matches: Record<string, number> = {};
  if (candidateIds.length > 0) {
    const { data: matchRows, error: matchError } = await reader
      .from("talent_match_scores")
      .select("candidate_id, match_percentage")
      .in("employer_id", employerIds)
      .eq("job_id", jobId)
      .in("candidate_id", candidateIds);

    if (matchError) {
      console.error(
        "[job applicants] match scores lookup failed:",
        matchError.message
      );
    } else {
      for (const matchRow of matchRows ?? []) {
        if (
          matchRow.candidate_id &&
          typeof matchRow.match_percentage === "number"
        ) {
          matches[matchRow.candidate_id] = matchRow.match_percentage;
        }
      }
    }
  }

  return NextResponse.json(
    {
      applications: rows,
      profiles,
      matches,
    },
    { headers: { "Cache-Control": "no-store" } }
  );
}

import { NextResponse } from "next/server";
import { createServiceRoleClient } from "@/lib/admin-access";
import { requireApiUser } from "@/lib/api-auth";
import { createEmployerNotification } from "@/lib/employer-notifications";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    value
  );
}

export async function POST(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const access = await requireApiUser(request);
    if (access instanceof NextResponse) {
      return access;
    }

    const { id: jobId } = await context.params;
    if (!isUuid(jobId)) {
      return NextResponse.json({ error: "Invalid job id." }, { status: 400 });
    }

    const { user, supabase } = access;
    const writer = createServiceRoleClient() ?? supabase;

    const { data: job, error: jobError } = await supabase
      .from("jobs")
      .select("id, title, employer_id, status")
      .eq("id", jobId)
      .maybeSingle();

    if (jobError) {
      console.error("[job interest] job lookup failed:", jobError.message);
      return NextResponse.json(
        { error: "Could not submit interest." },
        { status: 500 }
      );
    }

    if (!job || job.status !== "active") {
      return NextResponse.json({ error: "Job not found." }, { status: 404 });
    }

    if (job.employer_id === user.id) {
      return NextResponse.json(
        { error: "You cannot express interest in your own listing." },
        { status: 400 }
      );
    }

    const { error: insertError } = await writer.from("job_applications").insert({
      job_id: job.id,
      candidate_id: user.id,
    });

    if (insertError) {
      if (insertError.code === "23505") {
        return NextResponse.json({ ok: true, alreadyApplied: true });
      }

      console.error("[job interest] insert failed:", insertError.message);
      return NextResponse.json(
        { error: "Could not submit interest." },
        { status: 500 }
      );
    }

    if (job.employer_id) {
      const { data: existingNote } = await writer
        .from("notifications")
        .select("id")
        .eq("user_id", job.employer_id)
        .eq("job_id", job.id)
        .gte("created_at", new Date(Date.now() - 10_000).toISOString())
        .limit(1);

      if (!existingNote?.length) {
        await createEmployerNotification(writer, {
          userId: job.employer_id,
          jobId: job.id,
          title: "New Candidate Interest",
          message: `A candidate expressed interest in your role: ${
            job.title?.trim() || "Open Role"
          }`,
        });
      }
    }

    return NextResponse.json({ ok: true, alreadyApplied: false });
  } catch (error) {
    console.error("[job interest] unexpected error:", error);
    return NextResponse.json(
      { error: "Could not submit interest." },
      { status: 500 }
    );
  }
}

import { revalidatePath } from "next/cache";
import { NextResponse } from "next/server";
import { z } from "zod";
import { deleteOwnedJob } from "@/lib/jobs";
import { parseJsonWithSchema } from "@/lib/parse-request-json";
import { createClient } from "@/utils/supabase/server";

type JobStatus = "active" | "paused";

const patchJobBodySchema = z.object({
  status: z.unknown().optional(),
});

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    value
  );
}

function normalizeJobStatus(value: unknown): JobStatus | null {
  if (value === "active") {
    return "active";
  }

  // Treat deactivation synonyms as paused (schema value for inactive listings).
  if (value === "paused" || value === "inactive") {
    return "paused";
  }

  return null;
}

export async function PATCH(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { id: jobId } = await context.params;

    if (!isUuid(jobId)) {
      return NextResponse.json({ error: "Invalid job id." }, { status: 400 });
    }

    const parsedBody = await parseJsonWithSchema(request, patchJobBodySchema);
    if (!parsedBody.ok) {
      return parsedBody.response;
    }

    const status = normalizeJobStatus(parsedBody.data.status);

    if (!status) {
      return NextResponse.json(
        { error: "status must be active, paused, or inactive." },
        { status: 400 }
      );
    }

    const supabase = await createClient();
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { data: job, error: updateError } = await supabase
      .from("jobs")
      .update({ status })
      .eq("id", jobId)
      .eq("employer_id", user.id)
      .select("*")
      .maybeSingle();

    if (updateError) {
      console.error("[jobs] status update failed:", updateError);
      return NextResponse.json(
        { error: "Could not update job status." },
        { status: 500 }
      );
    }

    if (!job) {
      return NextResponse.json({ error: "Job not found." }, { status: 404 });
    }

    revalidatePath("/dashboard");
    revalidatePath("/opportunities");

    return NextResponse.json({ job });
  } catch (error) {
    console.error("[jobs] PATCH failed:", error);
    return NextResponse.json(
      { error: "Unexpected error updating job." },
      { status: 500 }
    );
  }
}

export async function DELETE(
  _request: Request,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { id: jobId } = await context.params;

    if (!isUuid(jobId)) {
      return NextResponse.json({ error: "Invalid job id." }, { status: 400 });
    }

    const supabase = await createClient();
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { deletedId, error: deleteError } = await deleteOwnedJob(
      supabase,
      jobId,
      user.id
    );

    if (deleteError) {
      console.error("[jobs] delete failed:", deleteError);
      return NextResponse.json(
        { error: "Could not delete listing." },
        { status: 500 }
      );
    }

    if (!deletedId) {
      return NextResponse.json({ error: "Job not found." }, { status: 404 });
    }

    revalidatePath("/dashboard");
    revalidatePath("/opportunities");

    return NextResponse.json({ success: true, id: deletedId });
  } catch (error) {
    console.error("[jobs] DELETE failed:", error);
    return NextResponse.json(
      { error: "Unexpected error deleting job." },
      { status: 500 }
    );
  }
}

