function parseVisibilityFlag(value: unknown): boolean | undefined {
  if (typeof value === "boolean") {
    return value;
  }
  return undefined;
}

async function getProductionAudit(request: Request) {
  const access = await requireApiUser(request);
  if (access instanceof NextResponse) {
    return access;
  }

  const { data: profile } = await access.supabase
    .from("profiles")
    .select(
      "production_score, audit_breakdown, is_audit_verified, is_publicly_visible, verification_status, role"
    )
    .or(`id.eq.${access.user.id},user_id.eq.${access.user.id}`)
    .limit(1)
    .maybeSingle();

  const history = await listProductionAuditHistory(
    access.supabase,
    access.user.id
  );
  const current = parseProductionAuditFromProfileRow(profile);

  return NextResponse.json({
    current: current
      ? {
          production_score: current.productionScore,
          audit_breakdown: current.breakdown,
          is_audit_verified: current.isAuditVerified,
          is_publicly_visible: current.isPubliclyVisible,
          verification_status: current.verificationStatus,
        }
      : null,
    history: history.map((entry) => ({
      id: entry.id,
      production_score: entry.productionScore,
      audited_repo_url: entry.auditedRepoUrl,
      audited_at: entry.auditedAt,
      ci_cd_score: entry.ciCdScore,
      test_density: entry.testDensity,
      error_handling: entry.errorHandling,
      created_at: entry.createdAt,
    })),
  });
}

async function postProductionAudit(request: Request) {
  const access = await requireApiUser(request);
  if (access instanceof NextResponse) {
    return access;
  }

  const parsedBody = await parseJsonWithSchema(
    request,
    postProductionAuditBodySchema
  );
  if (!parsedBody.ok) {
    return parsedBody.response;
  }

  const record = parsedBody.data;
  const breakdown = parseProductionAuditBreakdown(record.audit_breakdown);
  if (!breakdown) {
    return NextResponse.json(
      { error: "A production audit payload is required." },
      { status: 400 }
    );
  }

  const productionScore = clampScore0to100(record.production_score);
  const repoUrl = breakdown.audited_repo_url.trim();
  const parsedRepo = parseGitHubUrl(repoUrl);
  const isPublicGitHubClaim = Boolean(
    parsedRepo?.owner &&
      parsedRepo.repo &&
      repoUrl !== PRIVATE_AUDITED_REPO_LABEL
  );

  if (isPublicGitHubClaim) {
    const ownership = await verifyGitHubRepoOwnership({
      user: access.user,
      repoUrl,
    });
    if (!ownership.verified) {
      const rejectedClaim: ProductionAuditClaim = {
        production_score: productionScore,
        audit_breakdown: breakdown,
        is_audit_verified: true,
        is_publicly_visible: false,
      };
      await persistProfileProductionAudit(
        access.supabase,
        access.user.id,
        rejectedClaim,
        {
          isPubliclyVisible: false,
          enrollInTalentPool: false,
          verificationStatus: "unverified",
        }
      );
      return NextResponse.json(
        {
          error: REPO_OWNERSHIP_ERROR,
          verified: false,
          verification_status: "unverified",
        },
        { status: 403 }
      );
    }
  }

  const hygiene =
    typeof record.delivery_hygiene_score === "number"
      ? record.delivery_hygiene_score
      : breakdown.delivery_hygiene_score;
  const historyFetched =
    typeof record.commit_history_fetched === "boolean"
      ? record.commit_history_fetched
      : breakdown.commit_history_fetched;
  const qualifiesForTalentPool =
    isPublicGitHubClaim &&
    canPublishProductionScore(productionScore, hygiene, historyFetched);
  const requestedVisible = parseVisibilityFlag(record.is_publicly_visible);
  const isPubliclyVisible = resolvePublicScorecardVisibility(
    productionScore,
    qualifiesForTalentPool ? true : requestedVisible ?? false,
    hygiene,
    historyFetched
  );
  const claim: ProductionAuditClaim = {
    production_score: productionScore,
    audit_breakdown: {
      ...breakdown,
      delivery_hygiene_score: hygiene,
      commit_history_fetched: historyFetched,
    },
    is_audit_verified: true,
    is_publicly_visible: isPubliclyVisible,
    delivery_hygiene_score: hygiene,
    commit_history_fetched: historyFetched,
  };

  const { error, profileSlug } = await persistProfileProductionAudit(
    access.supabase,
    access.user.id,
    claim,
    {
      isPubliclyVisible,
      enrollInTalentPool: qualifiesForTalentPool,
      verificationStatus: isPublicGitHubClaim ? "verified" : undefined,
    }
  );

  if (error) {
    return NextResponse.json({ error }, { status: 500 });
  }

  const history = await listProductionAuditHistory(
    access.supabase,
    access.user.id
  );

  return NextResponse.json({
    production_score: claim.production_score,
    audit_score: claim.production_score,
    audit_breakdown: claim.audit_breakdown,
    is_audit_verified: true,
    is_publicly_visible: claim.is_publicly_visible,
    is_in_talent_pool: qualifiesForTalentPool,
    verification_status: isPublicGitHubClaim ? "verified" : "unverified",
    enrolled_in_talent_pool: qualifiesForTalentPool,
    profile_slug: profileSlug ?? null,
    threshold: PUBLIC_SCORECARD_THRESHOLD,
    history: history.map((entry) => ({
      id: entry.id,
      production_score: entry.productionScore,
      audited_repo_url: entry.auditedRepoUrl,
      audited_at: entry.auditedAt,
      ci_cd_score: entry.ciCdScore,
      test_density: entry.testDensity,
      error_handling: entry.errorHandling,
      created_at: entry.createdAt,
    })),
  });
}

async function patchProductionAudit(request: Request) {
  const access = await requireApiUser(request);
  if (access instanceof NextResponse) {
    return access;
  }

  const parsedBody = await parseJsonWithSchema(
    request,
    patchProductionAuditBodySchema
  );
  if (!parsedBody.ok) {
    return parsedBody.response;
  }

  const isPubliclyVisible = parsedBody.data.is_publicly_visible;

  let result = await persistScorecardVisibility(
    access.supabase,
    access.user.id,
    isPubliclyVisible
  );

  if (result.error) {
    const admin = createServiceRoleClient();
    if (admin) {
      const adminResult = await persistScorecardVisibility(
        admin,
        access.user.id,
        isPubliclyVisible
      );
      if (!adminResult.error) {
        result = adminResult;
      }
    }
  }

  const { error, record: nextRecord } = result;

  if (error) {
    const status = nextRecord ? 400 : 500;
    return NextResponse.json({ error }, { status });
  }

  return NextResponse.json({
    production_score: nextRecord?.productionScore ?? null,
    audit_breakdown: nextRecord?.breakdown ?? null,
    is_audit_verified: Boolean(nextRecord?.isAuditVerified),
    is_publicly_visible: Boolean(nextRecord?.isPubliclyVisible),
    verification_status: nextRecord?.verificationStatus ?? "unverified",
  });
}

import { NextResponse } from "next/server";
import { requireApiUser } from "@/lib/api-auth";
import {
  extractResumeTextFromFile,
  getResumeFileError,
} from "@/lib/parse-resume";
import { isSupabaseSchemaError } from "@/lib/supabase-schema-errors";

export const runtime = "nodejs";

type ResumeMeta = {
  filename: string | null;
  uploadedAt: string | null;
  hasResume: boolean;
  excerptLength: number;
};

function isMissingResumeColumn(error: { message?: string; code?: string } | null) {
  if (!error) {
    return false;
  }

  return (
    isSupabaseSchemaError(error) ||
    error.code === "42703" ||
    error.code === "PGRST204" ||
    (error.message?.toLowerCase().includes("resume_text") ?? false) ||
    (error.message?.toLowerCase().includes("resume_filename") ?? false)
  );
}

function missingColumnResponse() {
  return NextResponse.json(
    {
      error:
        "Resume storage is not enabled yet. Apply Supabase migration 0044_add_resume_text.sql.",
    },
    { status: 500 }
  );
}

export async function GET() {
  const access = await requireApiUser();
  if (access instanceof NextResponse) {
    return access;
  }

  const { data, error } = await access.supabase
    .from("profiles")
    .select("resume_filename, resume_uploaded_at, resume_text")
    .eq("id", access.user.id)
    .maybeSingle();

  if (error && isMissingResumeColumn(error)) {
    return NextResponse.json({
      filename: null,
      uploadedAt: null,
      hasResume: false,
      excerptLength: 0,
    } satisfies ResumeMeta);
  }

  if (error) {
    console.error("[profile/resume] GET failed:", error);
    return NextResponse.json(
      { error: "Could not load saved resume." },
      { status: 500 }
    );
  }

  const filename = data?.resume_filename?.trim() || null;
  const text = data?.resume_text?.trim() || "";

  return NextResponse.json({
    filename,
    uploadedAt: data?.resume_uploaded_at ?? null,
    hasResume: Boolean(text || filename),
    excerptLength: text.length,
  } satisfies ResumeMeta);
}

export async function POST(request: Request) {
  const access = await requireApiUser();
  if (access instanceof NextResponse) {
    return access;
  }

  let formData: FormData;

  try {
    formData = await request.formData();
  } catch {
    return NextResponse.json({ error: "Invalid form data." }, { status: 400 });
  }

  const file = formData.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json(
      { error: "Choose a PDF or text resume to upload." },
      { status: 400 }
    );
  }

  const fileError = getResumeFileError(file);
  if (fileError) {
    return NextResponse.json({ error: fileError }, { status: 400 });
  }

  let resumeText: string;

  try {
    resumeText = await extractResumeTextFromFile(file);
  } catch (error) {
    console.error("[profile/resume] parse failed:", error);
    return NextResponse.json(
      {
        error:
          error instanceof Error
            ? error.message
            : "Could not parse that resume. Try a PDF or .txt file.",
      },
      { status: 422 }
    );
  }

  const uploadedAt = new Date().toISOString();
  const payload = {
    resume_text: resumeText,
    resume_filename: file.name.slice(0, 240),
    resume_uploaded_at: uploadedAt,
  };

  const { error } = await access.supabase
    .from("profiles")
    .update(payload)
    .eq("id", access.user.id);

  if (error && isMissingResumeColumn(error)) {
    return missingColumnResponse();
  }

  if (error) {
    console.error("[profile/resume] save failed:", error);
    return NextResponse.json(
      { error: "Could not save the parsed resume to your profile." },
      { status: 500 }
    );
  }

  return NextResponse.json({
    filename: payload.resume_filename,
    uploadedAt,
    hasResume: true,
    excerptLength: resumeText.length,
  } satisfies ResumeMeta);
}

export async function DELETE() {
  const access = await requireApiUser();
  if (access instanceof NextResponse) {
    return access;
  }

  const { error } = await access.supabase
    .from("profiles")
    .update({
      resume_text: null,
      resume_filename: null,
      resume_uploaded_at: null,
    })
    .eq("id", access.user.id);

  if (error && isMissingResumeColumn(error)) {
    return missingColumnResponse();
  }

  if (error) {
    console.error("[profile/resume] delete failed:", error);
    return NextResponse.json(
      { error: "Could not remove the saved resume." },
      { status: 500 }
    );
  }

  return NextResponse.json({
    filename: null,
    uploadedAt: null,
    hasResume: false,
    excerptLength: 0,
  } satisfies ResumeMeta);
}

