import { useRouter } from "next/navigation";

// This route's full talent-pool/profile-studio UI (previously ~1,800 lines,
// gated behind a mock localStorage "auth" overlay) has moved to
// src/app/dashboard/page.tsx, now gated by real Supabase auth instead.
// This stub just forwards old links/bookmarks so nothing 404s.
export default function DraftRedirectPage() {
  const router = useRouter();

  useEffect(() => {
    router.replace("/dashboard");
  }, [router]);

  return (
    <div className="min-h-screen bg-background flex items-center justify-center">
      <p className="text-sm text-textMuted">Redirecting...</p>
    </div>
  );
}

import { redirect } from "next/navigation";
import { EMPLOYER_DASHBOARD_PATH } from "@/lib/account-role";
import { createClient } from "@/utils/supabase/server";

export default async function EmployerPage() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect("/");
  }

  // Talent directory is browsable by any authenticated account (employer,
  // candidate, or admin) so live pool cards can be verified locally.
  redirect(EMPLOYER_DASHBOARD_PATH);
}

"use client";

import { useEffect } from "react";
import Link from "next/link";
import Button from "@/components/ui/Button";

export default function Error({
  error,
  retry,
}: {
  error: Error & { digest?: string };
  retry: () => void;
}) {
  useEffect(() => {
    console.error("App error boundary:", error);
  }, [error]);

  return (
    <div className="min-h-screen bg-background text-textMain flex items-center justify-center px-6">
      <div className="card-edge w-full max-w-md rounded-md border border-border bg-panel p-8 text-center">
        <h1 className="text-2xl font-extrabold tracking-tight text-textMain">Something went wrong</h1>
        <p className="mt-3 text-sm text-textMuted leading-relaxed">
          The page hit an unexpected error. You can try again or go back home.
        </p>
        {error.digest ? (
          <p className="mt-2 font-mono text-[11px] text-textMuted">
            {error.digest}
          </p>
        ) : null}
        <div className="mt-6 flex flex-col sm:flex-row items-center justify-center gap-3">
          <Button type="button" onClick={() => retry()}>
            Try again
          </Button>
          <Link
            href="/"
            className="text-sm text-brand hover:text-brand font-medium transition-colors duration-200"
          >
            Back to Home
          </Link>
        </div>
      </div>
    </div>
  );
}

