function appendAuthQuery(
  path: string,
  search: string
): string {
  const params = new URLSearchParams(search);
  const verified = params.get("employer_verified");
  const verifyError = params.get("verify_error");
  const url = new URL(path, "https://getprovix.com");

  if (verified && !url.searchParams.has("employer_verified")) {
    url.searchParams.set("employer_verified", verified);
  }
  if (verifyError && !url.searchParams.has("verify_error")) {
    url.searchParams.set("verify_error", verifyError);
  }

  return `${url.pathname}${url.search}`;
}

async function destinationAfterAuth(
  user: User,
  search: string,
  signupKind?: SignUpType
): Promise<string> {
  const profileKind = await loadProfileAccountKind(supabase, user.id);
  const role =
    signupKind === "business"
      ? "employer"
      : profileKind;
  const params = new URLSearchParams(search);

  let setupComplete: boolean | null = null;
  if (role === "candidate") {
    const { data: profile } = await supabase
      .from("profiles")
      .select(
        "full_name, name, first_name, last_name, job_title, headline, bio, skills, experience_level, portfolio_url"
      )
      .eq("id", user.id)
      .maybeSingle();
    setupComplete = hasCompletedCandidateSetup(profile);
  }

  const destination = resolvePostAuthDestination({
    role,
    requestedNext: params.get("next"),
    isAdmin: getPostLoginPath(user) === "/admin",
    setupComplete,
  });

  return appendAuthQuery(destination, search);
}

export default function LoginPage() {
  const router = useRouter();
  const [mode, setMode] = useState<AuthMode>("sign-in");
  const [email, setEmail] = useState("");
  const [resetEmail, setResetEmail] = useState("");
  const [resetEmailError, setResetEmailError] = useState<string | null>(null);
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [checkingSession, setCheckingSession] = useState(true);
  const [showResetPassword, setShowResetPassword] = useState(false);
  const [isClaimAudit, setIsClaimAudit] = useState(false);
  const [signupKind, setSignupKind] = useState<SignUpType>("candidate");

  useEffect(() => {
    const search = window.location.search;
    const params = new URLSearchParams(search);
    const roleFromQuery = signupRoleFromSearch(search);
    const modeParam = params.get("mode")?.trim().toLowerCase();

    if (roleFromQuery === "employer") {
      setSignupKind("business");
      setMode("sign-up");
    } else if (roleFromQuery === "developer") {
      setSignupKind("candidate");
      setMode("sign-up");
    } else if (modeParam === "sign-up" || modeParam === "signup") {
      setMode("sign-up");
    }

    if (params.get("intent")?.trim() === CLAIM_AUDIT_INTENT) {
      setMode("sign-up");
      setIsClaimAudit(true);
    }

    const authError = params.get("error")?.trim();
    if (!authError) {
      return;
    }

    setError(
      authError === "auth_failed" || authError === "oauth_failed"
        ? "Sign-in failed. Please try again."
        : authError
    );
    params.delete("error");
    const remaining = params.toString();
    window.history.replaceState(
      {},
      "",
      `${window.location.pathname}${remaining ? `?${remaining}` : ""}`
    );
  }, []);

  useEffect(() => {
    let cancelled = false;

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event) => {
      if (event === "PASSWORD_RECOVERY") {
        router.push("/update-password");
      }
    });

    const prepareLogin = async () => {
      try {
        const { data, error } = await supabase.auth.getUser();
        // If this page rendered, middleware did not confirm a cookie session.
        // Clear leftover client tokens so they cannot bounce us to `/dashboard` then `/`.
        if (error || data.user) {
          await supabase.auth.signOut({ scope: "local" });
        }
      } catch (err) {
        console.error("Login session check failed:", err);
        try {
          await supabase.auth.signOut({ scope: "local" });
        } catch {
          // Ignore cleanup failures and still show the form.
        }
      } finally {
        if (!cancelled) {
          setCheckingSession(false);
        }
      }
    };

    void prepareLogin();

    return () => {
      cancelled = true;
      subscription.unsubscribe();
    };
  }, [router]);

  const switchMode = (nextMode: AuthMode) => {
    setMode(nextMode);
    setShowResetPassword(false);
    setError(null);
    setMessage(null);
  };

  const handleResetPasswordSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);
    setMessage(null);
    setResetEmailError(null);

    const trimmedEmail = normalizeEmail(resetEmail);
    setResetEmail(trimmedEmail);

    const validationMessage = getStandardEmailValidationMessage(trimmedEmail);
    if (validationMessage) {
      setResetEmailError(validationMessage);
      return;
    }

    setLoading(true);

    const { error: resetError } = await supabase.auth.resetPasswordForEmail(
      trimmedEmail,
      {
        redirectTo: buildPasswordResetRedirectUrl(window.location.origin),
      }
    );

    setLoading(false);

    if (resetError) {
      setError(resetError.message);
      return;
    }

    setMessage("Check your email for a password reset link.");
  };

  const redirectAfterAuth = async (
    user: User | null | undefined,
    signupKind?: SignUpType
  ) => {
    await supabase.auth.getSession();
    let claimQuery = "";
    if (user && signupKind !== "business" && !isEmployerSignup(user)) {
      const claimed = await claimPendingProductionAuditResult();
      if (claimed.enrolledInTalentPool) {
        claimQuery = "dossier=published";
      } else if (claimed.error) {
        claimQuery = `claim_error=${encodeURIComponent(claimed.error)}`;
      }
    }
    const destination = user
      ? await destinationAfterAuth(user, window.location.search, signupKind)
      : getPostLoginPath(user);
    const nextDestination = claimQuery
      ? `${destination}${destination.includes("?") ? "&" : "?"}${claimQuery}`
      : destination;
    router.refresh();
    router.push(nextDestination);
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);
    setMessage(null);

    if (mode === "sign-up" && (!firstName.trim() || !lastName.trim())) {
      setError("Enter your first and last name.");
      return;
    }

    const trimmedEmail = normalizeEmail(email);
    setEmail(trimmedEmail);
    const emailError = getStandardEmailValidationMessage(trimmedEmail);
    if (emailError) {
      setError(emailError);
      return;
    }

    if (password.length < 6) {
      setError("Password must be at least 6 characters.");
      return;
    }

    setLoading(true);

    if (mode === "sign-in") {
      const { data, error: signInError } = await supabase.auth.signInWithPassword({
        email: trimmedEmail,
        password,
      });

      if (signInError) {
        setError(signInError.message);
        setLoading(false);
        return;
      }

      try {
        await redirectAfterAuth(data.session?.user ?? null);
      } catch (redirectError) {
        console.error("Post-login redirect failed:", redirectError);
        setError("Signed in, but we could not redirect you. Please refresh and try again.");
        setLoading(false);
      }
      return;
    }

    const { data, error: signUpError } = await supabase.auth.signUp({
      email: trimmedEmail,
      password,
      options: {
        data: signupMetadataForKind(signupKind, {
          first_name: firstName.trim(),
          last_name: lastName.trim(),
        }),
      },
    });

    if (signUpError) {
      setError(signUpError.message);
      setLoading(false);
      return;
    }

    if (!data.session) {
      setLoading(false);
      setMessage("Check your email to confirm your account.");
      setMode("sign-in");
      return;
    }

    const signedUpUser = data.session.user;
    try {
      if (signupKind === "business") {
        await persistEmployerAccount(
          supabase,
          signedUpUser.id,
          signedUpUser.email ?? trimmedEmail
        );
      } else {
        await persistAccountRole(
          supabase,
          signedUpUser.id,
          "candidate",
          signedUpUser.email ?? trimmedEmail
        );
      }
      await redirectAfterAuth(signedUpUser, signupKind);
    } catch (redirectError) {
      console.error("Post-signup redirect failed:", redirectError);
      setError("Account created, but we could not redirect you. Please refresh and try again.");
      setLoading(false);
    }
  };

  if (checkingSession) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <p className="text-sm text-textMuted">Loading...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex items-center justify-center">
      <div className="w-full max-w-md px-6">
        <BackToHomeLink className="mb-4" />
        <div className="rounded-md border border-border bg-panel p-8">
          <div className="flex justify-center mb-6">
            <Link href="/" className="hover:opacity-90 transition-opacity">
              <ProvixLogo />
            </Link>
          </div>
          <h1 className="text-2xl font-extrabold text-textMain tracking-tight text-center">
            {showResetPassword
              ? "Reset Password"
              : isClaimAudit
                ? "Claim your verified scorecard"
                : "Welcome to Provix"}
          </h1>
          <p className="text-sm text-textMuted text-center mb-8 mt-3">
            {showResetPassword
              ? "Enter your email to receive a password reset link"
              : isClaimAudit
                ? "Sign in or create an account to attach this production score to your anonymous developer profile. GitHub is the fastest way."
                : mode === "sign-in"
                  ? "Sign in to access your account"
                  : signupKind === "business"
                    ? "Create a founder account to post roles and hire verified talent"
                    : "Create a developer account to connect GitHub and run audits"}
          </p>

          {error && (
            <div className="mb-4 bg-red-500/10 border border-red-500/20 text-red-400 text-sm rounded-lg px-4 py-2.5">
              {error}
            </div>
          )}
