              {result.tier ? (
                <span className="inline-flex items-center rounded-md border border-cyan-500/25 bg-cyan-500/10 px-2.5 py-1 text-[11px] font-semibold text-cyan-300">
                  {result.tier}
                </span>
              ) : null}
            </div>
            <p className="text-xs leading-relaxed text-zinc-500">
              Score {result.overallScore ?? result.score}/100
              {repoLabel ? ` · ${repoLabel}` : ""} ·{" "}
              {auditModeLabel(result.auditMode ?? auditMode)}
              {result.tier ? ` · ${result.tier}` : ""}. PDF opens the shared
              report with print dialog (browser Save as PDF).
            </p>
          </div>

          <AuditResultsPanel
            result={result}
            repoName={repoLabel ?? undefined}
            repoUrl={githubUrl.trim() || undefined}
            shareId={result.shareId ?? null}
            readOnly
          />
        </div>
      ) : null}
    </div>
  );
}

function LinkRow({
  label,
  href,
  emptyHint,
  icon = "link",
}: {
  label: string;
  href?: string | null;
  emptyHint: string;
  icon?: "link" | "pdf";
}) {
  if (!href) {
    return (
      <div className="rounded-lg border border-white/[0.08] bg-[#070709] px-3 py-2.5">
        <p className="text-xs font-semibold text-zinc-400">{label}</p>
        <p className="mt-0.5 text-sm text-zinc-500">{emptyHint}</p>
      </div>
    );
  }

  return (
    <a
      href={href}
      target="_blank"
      rel="noreferrer"
      className="flex items-center justify-between gap-3 rounded-lg border border-emerald-500/25 bg-emerald-500/10 px-3 py-2.5 text-sm text-emerald-200 transition-colors hover:bg-emerald-500/15"
    >
      <span className="min-w-0">
        <span className="block text-xs font-semibold uppercase tracking-wide text-emerald-300/80">
          {label}
        </span>
        <span className="mt-0.5 block truncate font-mono text-xs text-emerald-100">
          {href}
        </span>
      </span>
      {icon === "pdf" ? (
        <FileDown className="h-4 w-4 shrink-0" aria-hidden />
      ) : (
        <ExternalLink className="h-4 w-4 shrink-0" aria-hidden />
      )}
    </a>
  );
}

