                      <p className="text-sm text-zinc-200 leading-relaxed">
                        {prompt.question}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] uppercase font-bold tracking-wider text-zinc-500 mb-1">
                        What to Listen For
