"use client";

import ProductionScoreVerifiedBadge from "@/components/ProductionScoreVerifiedBadge";
import type { ExecutiveBrief, RecommendedRoleBand } from "@/lib/executive-brief";
import type { PillarSubLog } from "@/lib/forensic-dossier";
import {
  type ProductionAuditMetrics,
  emptyProductionAuditMetrics,
  resolveCodeHealthScore,
  weightedProductionScore,
} from "@/lib/production-audit-metrics";
import { formatCodebaseBenchmark, type CodebaseBenchmark } from "@/lib/codebase-benchmark";
import { clampScore0to100 } from "@/lib/score-scale";

const SECTION_LABEL =
  "text-[11px] font-semibold uppercase tracking-wider text-zinc-500";

const METRIC_ROWS: Array<{
  key: "architecture" | "testing" | "devops" | "resilience";
  label: string;
  shortLabel: string;
  microLabel: string;
  countKey:
    | "architecturePathCount"
    | "githubWorkflowCount"
    | "ciWorkflowCount"
    | "testFileCount"
    | "errorBoundaryCount"
    | "handlerCount";
}> = [
  {
    key: "architecture",
    label: "Architecture",
    shortLabel: "Arch",
    microLabel: "structure gaps",
    countKey: "architecturePathCount",
  },
  {
    key: "testing",
    label: "Testing",
    shortLabel: "Tests",
    microLabel: "missing suites",
    countKey: "testFileCount",
  },
  {
    key: "devops",
    label: "DevOps",
    shortLabel: "CI",
    microLabel: "missing workflows",
    countKey: "githubWorkflowCount",
  },
  {
    key: "resilience",
    label: "Resilience",
    shortLabel: "Resilience",
    microLabel: "unhandled errors",
    countKey: "handlerCount",
  },
];

function getMetricTone(score: number): string {
  if (score >= 80) {
    return "text-emerald-400";
  }
  if (score >= 60) {
    return "text-violet-400";
  }
  if (score > 0) {
    return "text-orange-300";
  }
  return "text-red-400";
}

function metricCount(
  metrics: ProductionAuditMetrics,
  countKey: (typeof METRIC_ROWS)[number]["countKey"]
): number {
  if (countKey === "githubWorkflowCount") {
    return (
      metrics.evidence.githubWorkflowCount || metrics.evidence.ciWorkflowCount
    );
  }
  return metrics.evidence[countKey];
}

/** Inverse signal for micro-copy: presence score high → 0 failing/flaky/unhandled. */
function metricIssueCount(score: number, foundCount: number): number {
  if (!foundCount) {
    return score > 0 ? 0 : 1;
  }
  return score >= 60 ? 0 : Math.max(1, Math.min(foundCount, 3));
}

type ProductionScorecardProps = {
  metrics?: ProductionAuditMetrics | null;
  className?: string;
  /** Dense single-row layout for profile settings / tight result panels. */
  compact?: boolean;
  /** Live rank against completed production audits. Hidden math stays off the compact card. */
  benchmark?: CodebaseBenchmark | null;
  executiveBrief?: ExecutiveBrief | null;
  /** Employer dossiers lead with the founder brief. Candidate audits lead with the peer review. */
  audience?: "candidate" | "employer";
  /** Terminal-style forensic receipts under each pillar (non-compact dossier). */
  pillarSubLogs?: PillarSubLog[] | null;
  /** Shown under Founder Hiring Verdict when History blocks Provix Verified. */
  historyVerifiedNote?: string | null;
};

/** Split a 2–3 sentence brief into tight executive bullets. */
function briefBullets(summary: string): string[] {
  const cleaned = summary.replace(/\s+/g, " ").trim();
  if (!cleaned) {
    return [];
  }

  const chunks = cleaned
    .split(/\n+|(?:^|\s)[•]\s+|(?:^|\s)[-*]\s+/)
    .flatMap((chunk) =>
      chunk
        .split(/(?<=[.!?])\s+(?=[A-Z0-9])/)
        .map((sentence) => sentence.trim())
        .filter(Boolean)
    );

  return chunks.length > 0 ? chunks : [cleaned];
}

function BriefBulletList({ summary }: { summary: string }) {
  const bullets = briefBullets(summary);

  return (
    <ul className="mt-2 space-y-1 text-[12px] leading-snug text-zinc-200 print:mt-1 print:space-y-0.5 print:text-[10px] print:leading-tight">
      {bullets.map((item, index) => (
        <li
          key={`${index}-${item.slice(0, 32)}`}
          className="dossier-bullet flex items-start gap-1.5"
        >
          <span aria-hidden className="leading-snug">
            •
          </span>
          <span>{item}</span>
        </li>
      ))}
    </ul>
  );
}

function roleBandClass(band: RecommendedRoleBand): string {
  if (
    band === "Elite Sprint Contractor" ||
    band === "Production-Grade / Core Lead"
  ) {
    return "border-emerald-500/30 bg-emerald-500/10 text-emerald-300";
  }
  if (
    band === "Verified Sprint Builder" ||
    band === "Mid/Senior Production-Ready"
  ) {
    return "border-cyan-500/30 bg-cyan-500/10 text-cyan-200";
  }
  if (band === "Supervised Feature Builder") {
    return "border-violet-500/30 bg-violet-500/10 text-violet-200";
  }
  if (band === "Needs Refinement") {
    return "border-orange-500/30 bg-orange-500/10 text-orange-200";
  }
  return "border-rose-500/30 bg-rose-500/10 text-rose-200";
}

function EngineeringBriefCards({
  brief,
  audience,
  historyVerifiedNote = null,
}: {
  brief: ExecutiveBrief;
  audience: "candidate" | "employer";
  historyVerifiedNote?: string | null;
}) {
  const staffReview = (
    <section className="rounded-lg border border-zinc-800/80 bg-zinc-950/70 px-3 py-3 print:px-2 print:py-1.5">
      <div className="flex flex-wrap items-center gap-2">
        <p className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">
          Technical Peer Review
        </p>
        <span className="text-xs px-2 py-0.5 rounded bg-blue-500/10 text-blue-400 border border-blue-500/20">
          FOR CANDIDATES
        </span>
      </div>
      <p className="mt-1 text-xs leading-snug text-zinc-500">
        Actionable engineering feedback to improve code health.
      </p>
      <BriefBulletList summary={brief.developerSummary} />
    </section>
  );
  const executiveBrief = (
    <section
      className={`rounded-lg border px-3 py-3 print:px-2 print:py-1.5 ${
        audience === "employer"
          ? "border-violet-500/30 bg-violet-500/10"
          : "border-zinc-800/80 bg-zinc-950/70"
      }`}
    >
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <p className="text-[11px] font-semibold uppercase tracking-wider text-zinc-400">
            Founder Hiring Verdict
          </p>
          <span className="text-xs px-2 py-0.5 rounded bg-amber-500/10 text-amber-400 border border-amber-500/20">
            FOR HIRING TEAMS
          </span>
        </div>
        <span
          className={`inline-flex items-center rounded-md border px-2 py-0.5 text-[11px] font-semibold ${roleBandClass(
            brief.recommendedRoleBand
          )}`}
        >
          {brief.recommendedRoleBand}
        </span>
      </div>
      <p className="mt-1 text-xs leading-snug text-zinc-500">
        Production risk evaluation for founders and recruiters.
      </p>
      {historyVerifiedNote ? (
        <p className="mt-2 rounded-md border border-amber-500/25 bg-amber-500/10 px-2.5 py-1.5 text-[12px] leading-snug text-amber-100">
          {historyVerifiedNote}
        </p>
      ) : null}
      <BriefBulletList summary={brief.employerSummary} />
    </section>
  );

  return (
    <div className="mt-4 space-y-3">
      {audience === "employer" ? (
        <>
          {executiveBrief}
          {staffReview}
        </>
      ) : (
        <>
          {staffReview}
          {executiveBrief}
        </>
      )}
    </div>
  );
}

export default function ProductionScorecard({
  metrics,
  className = "",
  compact = true,
  benchmark = null,
  executiveBrief = null,
  audience = "candidate",
  pillarSubLogs = null,
  historyVerifiedNote = null,
}: ProductionScorecardProps) {
  const resolved = metrics ?? emptyProductionAuditMetrics();
  const codeHealthScore = resolveCodeHealthScore(resolved);
  const productionScore = codeHealthScore;
  const inspected = resolved.evidence.inspected;
  const upstreamPenalty = Math.max(0, resolved.upstreamDerivativePenalty ?? 0);
  const subLogByPillar = new Map(
    (pillarSubLogs ?? []).map((log) => [log.pillar, log] as const)
  );
  const weightedTotal = weightedProductionScore({
    architecture: resolved.architecture,
    testing: resolved.testing,
    devops: resolved.devops,
    resilience: resolved.resilience,
  });

  if (compact) {
    return (
      <div
        className={`dossier-card rounded-xl border border-zinc-800/80 bg-zinc-900/60 p-5 backdrop-blur-sm ${className}`.trim()}
      >
        <div className="min-w-0">
          <p className="mb-1 block text-xs uppercase tracking-wider text-muted-foreground text-zinc-500">
            Codebase Score
          </p>
          <div className="flex items-center justify-between gap-3">
            <p
              className={`min-w-0 font-mono text-sm font-medium tabular-nums ${getMetricTone(
                productionScore
              )}`}
            >
              Code Health: {codeHealthScore}/100
            </p>
            <ProductionScoreVerifiedBadge score={codeHealthScore} />
          </div>
          <p className="mt-1 text-sm leading-relaxed text-zinc-400">
            {inspected
              ? `Pillar index · ${resolved.evidence.fileCount} paths`
              : "Run a GitHub audit to compute architecture, tests, CI, and resilience."}
          </p>
          {upstreamPenalty > 0 ? (
            <p className="mt-1 font-mono text-[11px] tabular-nums text-zinc-500">
              Weighted total {weightedTotal}/100 − {upstreamPenalty} upstream fork
              or template = {productionScore}/100
            </p>
          ) : null}
          {executiveBrief ? (
            <EngineeringBriefCards
              brief={executiveBrief}
              audience={audience}
              historyVerifiedNote={historyVerifiedNote}
            />
          ) : null}
        </div>

        <div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4">
          {METRIC_ROWS.map((row) => {
            const score = clampScore0to100(resolved[row.key]);
            const found = metricCount(resolved, row.countKey);
            const issues = inspected ? metricIssueCount(score, found) : 0;

            return (
              <div
                key={row.key}
                className="rounded-lg border border-zinc-800/80 bg-zinc-950/60 px-2.5 py-2.5 text-center"
              >
                <p
                  className={`font-mono text-sm font-bold tabular-nums ${getMetricTone(
                    score
                  )}`}
                >
                  {score}
                </p>
                <p className="mt-0.5 text-xs font-medium uppercase tracking-wide text-zinc-400">
                  {row.shortLabel}
                </p>
                {inspected ? (
                  <p className="mt-1 text-[11px] leading-snug text-zinc-500">
                    {issues} {row.microLabel}
                  </p>
                ) : null}
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div
      className={`dossier-card space-y-4 rounded-xl border border-zinc-800/80 bg-zinc-900/60 p-5 backdrop-blur-sm print:space-y-2 print:p-3 sm:p-6 ${className}`.trim()}
    >
      <div className="flex items-start justify-between gap-3">
        <div>
          <div className={`${SECTION_LABEL} mb-1`}>Code Health · Pillars</div>
          <p className="text-sm font-semibold text-zinc-100">
            {formatCodebaseBenchmark(benchmark)}
          </p>
          {!inspected ? (
            <p className="mt-1 text-sm leading-relaxed text-zinc-400">
              Repository file tree was not inspected, so production metrics stay
              at 0.
            </p>
          ) : null}
        </div>
        <ProductionScoreVerifiedBadge score={codeHealthScore} />
      </div>

      {executiveBrief ? (
        <EngineeringBriefCards
          brief={executiveBrief}
          audience={audience}
          historyVerifiedNote={historyVerifiedNote}
        />
      ) : null}

      <ul className="grid grid-cols-1 gap-3 sm:grid-cols-2 print:grid-cols-2 print:gap-2 lg:grid-cols-4">
        {METRIC_ROWS.map((row) => {
          const score = clampScore0to100(resolved[row.key]);
          const found = metricCount(resolved, row.countKey);
          const issues = inspected ? metricIssueCount(score, found) : 0;
          const subLog = subLogByPillar.get(row.key);

          return (
            <li
              key={row.key}
              className="dossier-card flex min-h-[8.5rem] flex-col rounded-lg border border-zinc-800/80 bg-zinc-950/60 px-4 py-4 print:min-h-0 print:px-3 print:py-3"
            >
              <div className="flex items-center justify-between gap-2">
                <p className="text-sm font-semibold tracking-tight text-zinc-100">
                  {row.label}
                </p>
                <span
                  className={`font-mono text-lg font-bold tabular-nums ${getMetricTone(
                    score
                  )}`}
                >
                  {score}
                </span>
              </div>
              <p className="mt-3 text-[13px] leading-snug text-zinc-400">
                {subLog?.summary ??
                  (inspected
                    ? `${issues} ${row.microLabel}`
                    : "Not inspected")}
              </p>
            </li>
          );
        })}
      </ul>
      {upstreamPenalty > 0 ? (
        <p className="font-mono text-[11px] tabular-nums text-zinc-500">
          Upstream fork or generated template −{upstreamPenalty} · Code Health{" "}
          {productionScore}/100 (weighted {weightedTotal}/100)
        </p>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, type FormEvent } from "react";
import { useRouter } from "next/navigation";
import {
  AlertTriangle,
  Check,
  Loader2,
  ShieldCheck,
} from "lucide-react";
import type { AuditResult } from "@/app/api/audit/route";
import { normalizeAuditChecks } from "@/lib/audit-checks";
import { DAILY_LIMIT_UI_MESSAGE, type DailyScanUsage } from "@/lib/daily-scan-limit";
import { readJsonResponse } from "@/lib/read-json-response";
import {
  buildProductionAuditClaim,
  CLAIM_AUDIT_INTENT,
  cachePendingProductionAudit,
  clearPendingProductionAudit,
  formatAuditedRepoLabel,
  PRIVATE_AUDIT_INTENT,
  type ProductionAuditClaim,
} from "@/lib/production-audit";
import ScorecardPublicationCallout from "@/components/auditor/scorecard-publication-callout";
import RepoAccessStatus, {
  VerifiedContributorMark,
  type RepoAccessStatusKind,
} from "@/components/auditor/repo-access-status";
import ProductionScoreVerifiedBadge from "@/components/ProductionScoreVerifiedBadge";
import GuestAuthModal from "@/components/GuestAuthModal";
import { isFilesystemCapRedFlag } from "@/lib/repo-filesystem";
import {
  isInaccessiblePublicAudit,
  isInvalidRepoFormatResponse,
  isPrivateOrNotFoundAuditResponse,
  isUnverifiedOwnershipResponse,
  unverifiedOwnershipUsername,
} from "@/lib/inaccessible-public-audit";
import Toast from "@/components/Toast";
import { createClient } from "@/utils/supabase/client";
import {
  getGitHubUrlValidationMessage,
  hasUsableGitHubAuditTarget,
  isGitHubPlaceholderInput,
} from "@/lib/validate-github-url";

const AUDIT_STAGES = [
  "Artifact Analysis (Check 1)...",
  "Architecture Review (Check 2)...",
  "API & Data Resiliency Check (Check 3)...",
] as const;

function SubMetric({ label, score }: { label: string; score: number }) {
  return (
    <div className="rounded-lg border border-border bg-background px-2.5 py-2 text-center">
      <p className="font-mono text-sm font-bold tabular-nums text-textMain">
        {score}
      </p>
      <p className="mt-0.5 text-[10px] font-medium uppercase tracking-wide text-textMuted">
        {label}
      </p>
    </div>
  );
}

function FindingList({
  title,
  items,
  tone,
}: {
  title: string;
  items: string[];
  tone: "pass" | "warn" | "fix";
}) {
  if (items.length === 0) {
    return null;
  }

  const iconClass =
    tone === "pass"
      ? "text-emerald-400"
      : tone === "warn"
        ? "text-violet-400"
        : "text-neutral-400";

  return (
    <div>
      <p className="mb-3 text-[10px] font-bold uppercase tracking-wider text-textMuted">
        {title}
      </p>
      <ul className="space-y-2">
        {items.map((item) => (
          <li
            key={item}
            className="flex items-start gap-2 text-sm leading-relaxed text-textMuted"
          >
            {tone === "pass" ? (
              <Check className={`mt-0.5 h-4 w-4 shrink-0 ${iconClass}`} aria-hidden />
            ) : (
              <AlertTriangle
                className={`mt-0.5 h-4 w-4 shrink-0 ${iconClass}`}
                aria-hidden
              />
            )}
            <span>{item}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

function FindingsSection({
  strengths,
  gaps,
  fixes,
}: {
  strengths: string[];
  gaps: string[];
  fixes: string[];
}) {
  const groups = [
    { title: "Verified strengths", items: strengths, tone: "pass" as const },
    {
      title: "Gaps and missing proof-of-work",
      items: gaps,
      tone: "warn" as const,
    },
    { title: "Actionable fixes", items: fixes, tone: "fix" as const },
  ];

  return (
    <section className="rounded-2xl border border-neutral-800/80 bg-[#0d0f17] p-5">
      <h3 className="text-sm font-bold tracking-tight text-textMain">
        Findings
      </h3>
      <div className="mt-3 space-y-4">
        {groups.map((group) => (
          <FindingList
            key={group.title}
            title={group.title}
            items={group.items}
            tone={group.tone}
          />
        ))}
      </div>
    </section>
  );
}

export default function PublicProductionAudit({
  initialRepoUrl = "",
  embedded = false,
  showEmptyState = true,
  autoFocus = false,
  isPublicTeaser = false,
  onHasResultsChange,
}: {
  initialRepoUrl?: string;
  /** Keep results on this page instead of navigating to `/audit`. */
  embedded?: boolean;
  showEmptyState?: boolean;
  autoFocus?: boolean;
  /** Homepage teaser: any public repo, no authorship or token gate. */
  isPublicTeaser?: boolean;
  onHasResultsChange?: (hasResults: boolean) => void;
}) {
  const router = useRouter();
  const [repoUrl, setRepoUrl] = useState(initialRepoUrl);
  const [loading, setLoading] = useState(false);
  const [stageIndex, setStageIndex] = useState(0);
  const [result, setResult] = useState<AuditResult | null>(null);
  const [claim, setClaim] = useState<ProductionAuditClaim | null>(null);
  const [repoAccessStatus, setRepoAccessStatus] =
    useState<RepoAccessStatusKind | null>(null);
  const [accessUsername, setAccessUsername] = useState<string | null>(null);
  const inaccessibleRepo = repoAccessStatus === "private";
  const ownershipUnverified = repoAccessStatus === "unverified";
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [limitReached, setLimitReached] = useState(false);
  const [authModalOpen, setAuthModalOpen] = useState(false);
  const [authModalError, setAuthModalError] = useState<string | null>(null);
  const [authModalDescription, setAuthModalDescription] = useState(
    "Sign in or create an account to continue."
  );
  const [authNextPath, setAuthNextPath] = useState("/dashboard");
  const [authIntent, setAuthIntent] = useState(PRIVATE_AUDIT_INTENT);
  const stageIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const autoStartedRef = useRef("");
  const inFlightRef = useRef(false);
  const [viewerSignedIn, setViewerSignedIn] = useState<boolean | null>(null);

  const openAuthModal = (options: {
    description: string;
    nextPath: string;
    intent?: string;
  }) => {
    setAuthModalError(null);
    setAuthModalDescription(options.description);
    setAuthNextPath(options.nextPath);
    setAuthIntent(options.intent ?? PRIVATE_AUDIT_INTENT);
    setAuthModalOpen(true);
  };

  useEffect(() => {
    if (!isPublicTeaser) {
      return;
    }

    let cancelled = false;
    const supabase = createClient();
    void supabase.auth.getUser().then(({ data }) => {
      if (!cancelled) {
        setViewerSignedIn(Boolean(data.user));
      }
    });

    return () => {
      cancelled = true;
    };
  }, [isPublicTeaser]);

  const hasValidGithubInput = hasUsableGitHubAuditTarget(repoUrl);
  const invalidRepoFormat =
    Boolean(repoUrl.trim()) &&
    !isGitHubPlaceholderInput(repoUrl) &&
    !hasValidGithubInput;
  const githubValidationMessage =
    repoUrl.trim() && !hasValidGithubInput && !invalidRepoFormat
      ? getGitHubUrlValidationMessage(repoUrl)
      : null;

  const stopStageProgress = () => {
    if (stageIntervalRef.current) {
      clearInterval(stageIntervalRef.current);
      stageIntervalRef.current = null;
    }
  };

  const startStageProgress = () => {
    setStageIndex(0);
    stopStageProgress();
    stageIntervalRef.current = setInterval(() => {
      setStageIndex((current) =>
        current < AUDIT_STAGES.length - 1 ? current + 1 : current
      );
    }, 1400);
  };

  const runAudit = async (url: string) => {
    const trimmed = url.trim();
    if (inFlightRef.current || limitReached) {
      return;
    }
    if (!hasUsableGitHubAuditTarget(trimmed)) {
      setRepoAccessStatus(
        trimmed && !isGitHubPlaceholderInput(trimmed)
          ? "invalid_format"
          : null
      );
      return;
    }

    inFlightRef.current = true;
    setError(null);
    setResult(null);
    setClaim(null);
    setRepoAccessStatus(null);
    setAccessUsername(null);
    setToastMessage(null);

    try {
      try {
        const usageResponse = await fetch("/api/audit");
        if (usageResponse.ok) {
          const usage = (await readJsonResponse(usageResponse)) as DailyScanUsage;
          if (usage.limit_reached) {
            setLimitReached(true);
            return;
          }
        }
      } catch (err) {
        console.error("Could not load auditor scan usage:", err);
      }

      setLoading(true);
      startStageProgress();

      const response = await fetch("/api/audit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          githubUrl: trimmed,
          compensationLevel: "Mid",
          playground: true,
          isPublicTeaser,
        }),
      });

      let data: AuditResult &
        DailyScanUsage & {
          error?: string;
          isPrivateOrNotFound?: boolean;
          repoUrl?: string;
          inaccessibleRepo?: boolean;
          owner?: string;
          message?: string;
        };
      try {
        data = (await readJsonResponse(response)) as typeof data;
      } catch {
        if (
          response.status === 401 ||
          response.status === 403 ||
          response.status === 404
        ) {
          setRepoAccessStatus("private");
          setResult(null);
          setClaim(null);
          return;
        }
        throw new Error("Audit request failed.");
      }

      if (isInvalidRepoFormatResponse(data)) {
        setLimitReached(Boolean(data.limit_reached));
        setRepoAccessStatus("invalid_format");
        setResult(null);
        setClaim(null);
        return;
      }

      if (!isPublicTeaser && isUnverifiedOwnershipResponse(data)) {
        setLimitReached(Boolean(data.limit_reached));
        setRepoAccessStatus("unverified");
        setAccessUsername(unverifiedOwnershipUsername(data));
        setResult(null);
        setClaim(null);
        return;
      }

      if (
        isPrivateOrNotFoundAuditResponse(data) ||
        isInaccessiblePublicAudit({ status: response.status, result: data })
      ) {
        setLimitReached(Boolean(data.limit_reached));
        setRepoAccessStatus("private");
        setResult(null);
        setClaim(null);
        return;
      }

      if (!response.ok) {
        if (response.status === 429 || data.limit_reached) {
          setLimitReached(true);
        }
        throw new Error(data.error ?? "Audit request failed.");
      }

      // Guard: never treat a score-only payload without real audit fields as success
      // when private/not-found markers are present.
      if (typeof data.score !== "number" || !Array.isArray(data.redFlags)) {
        throw new Error(data.error ?? "Audit request failed.");
      }

      setLimitReached(Boolean(data.limit_reached));
      setRepoAccessStatus(
        (data as { ownership_verified?: boolean }).ownership_verified === true
          ? "verified"
          : null
      );
      const nextResult = {
        ...data,
        checks: normalizeAuditChecks(data.checks),
        filesystem: data.filesystem ?? null,
        commitDates: data.commitDates ?? [],
      };
      setResult(nextResult);

      const nextClaim = buildProductionAuditClaim({
        score: nextResult.score,
        githubUrl: trimmed,
        filesystem: nextResult.filesystem,
        scoreCap: nextResult.scoreCap,
      });
      setClaim(nextClaim);
      clearPendingProductionAudit();
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Could not complete audit.";
      setError(message);
    } finally {
      stopStageProgress();
      inFlightRef.current = false;
      setLoading(false);
    }
  };

  useEffect(() => {
    return () => {
      stopStageProgress();
    };
  }, []);

  useEffect(() => {
    const trimmed = initialRepoUrl.trim();
    if (!hasUsableGitHubAuditTarget(trimmed)) {
      return;
    }
    if (autoStartedRef.current === trimmed) {
      return;
    }
    autoStartedRef.current = trimmed;
    void runAudit(trimmed);
    // Auto-run once per incoming repo query. Usage loads inside runAudit.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialRepoUrl]);

  const onSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmed = repoUrl.trim();
    void runAudit(trimmed);
    if (!embedded && trimmed) {
      router.replace(`/audit?repo=${encodeURIComponent(trimmed)}`, {
        scroll: false,
      });
    }
  };

  const breakdown = claim?.audit_breakdown;
  const score = claim?.production_score ?? 0;
  const repoLabel = breakdown
    ? formatAuditedRepoLabel(breakdown.audited_repo_url)
    : "";
  const visibleRedFlags = (result?.redFlags ?? []).filter(
    (item) => !result?.scoreCap?.applied || !isFilesystemCapRedFlag(item)
  );
  const recommendations = (result?.recommendations ?? []).slice(0, 3);
  const strengths = result?.strengths ?? [];
  const hasResults = Boolean(
    !loading &&
      result &&
      claim &&
      breakdown &&
      !inaccessibleRepo &&
      !ownershipUnverified
  );
  const showSignupCard = isPublicTeaser && viewerSignedIn === false;

  useEffect(() => {
    onHasResultsChange?.(hasResults);
  }, [hasResults, onHasResultsChange]);

  useEffect(() => {
    if (!toastMessage) {
      return;
    }
    const timer = window.setTimeout(() => setToastMessage(null), 6000);
    return () => window.clearTimeout(timer);
  }, [toastMessage]);

  return (
    <div className="mx-auto w-full max-w-4xl space-y-8">
      <form onSubmit={onSubmit} className="w-full space-y-3 print:hidden">
        <div className="relative flex flex-col gap-2 overflow-hidden rounded-xl border border-neutral-800/80 bg-[#0d0f17] p-1.5 transition-colors hover:border-neutral-700/80 sm:flex-row sm:items-stretch">
          <div className="pointer-events-none absolute -right-16 -top-16 h-32 w-32 rounded-full bg-violet-600/5 blur-2xl" />
          <label htmlFor="public-audit-repo" className="sr-only">
            GitHub repository URL
          </label>
          <div className="relative min-w-0 flex-1">
            <input
              id="public-audit-repo"
              name="repo"
              type="text"
              inputMode="url"
              autoComplete="url"
              spellCheck={false}
              autoFocus={autoFocus}
              value={repoUrl}
              onChange={(event) => {
                setRepoUrl(event.target.value);
                setRepoAccessStatus(null);
                setAccessUsername(null);
              }}
              placeholder="Paste GitHub repo URL (owner/repository)"
              aria-invalid={Boolean(githubValidationMessage)}
              className={`relative min-h-12 w-full rounded-lg border border-transparent bg-transparent px-4 py-3 font-mono text-sm text-white placeholder:text-neutral-500 outline-none transition-colors duration-200 focus:border-cyan-500/20 sm:text-[15px] ${
                repoAccessStatus === "verified" ? "pr-40" : ""
              }`}
            />
            <VerifiedContributorMark
              visible={repoAccessStatus === "verified"}
              className="pointer-events-none absolute top-1/2 right-3 -translate-y-1/2"
            />
          </div>
          <button
            type="submit"
            disabled={loading || limitReached}
            className="relative inline-flex min-h-12 shrink-0 cursor-pointer items-center justify-center rounded-lg bg-violet-600 px-5 text-sm font-medium tracking-tight text-white shadow-[0_0_20px_rgba(124,58,237,0.25)] transition-colors hover:bg-violet-500 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? "Running Audit..." : "Run Production Audit"}
          </button>
        </div>
        {githubValidationMessage ? (
          <p role="alert" className="mt-1.5 text-left text-xs text-red-300">
            {githubValidationMessage}
          </p>
        ) : null}
        <RepoAccessStatus
          status={
            invalidRepoFormat ? "invalid_format" : repoAccessStatus
          }
          username={accessUsername}
        />
      </form>

      {limitReached ? (
        <div
          role="status"
          className="rounded-xl border border-violet-500/25 bg-violet-500/10 px-4 py-3 text-sm text-violet-200"
        >
          {DAILY_LIMIT_UI_MESSAGE}
        </div>
      ) : null}

      {loading ? (
        <section className="rounded-2xl border border-neutral-800/80 bg-[#0d0f17] p-6">
          <p className="text-sm font-bold text-textMain">Running production audit</p>
          <p className="mt-1 text-xs text-textMuted">
            Provix is inspecting architecture, tests, CI, and resilience.
          </p>
          <ul className="mt-5 space-y-3">
            {AUDIT_STAGES.map((stage, index) => {
              const isComplete = index < stageIndex;
              const isActive = index === stageIndex;

              return (
                <li
                  key={stage}
