                onRequireAuth={(nextClaim) => {
                  cachePendingProductionAudit(nextClaim);
                  openAuthModal({
                    description:
                      "Sign in with GitHub to verify you authored this repository and publish your dossier.",
                    nextPath: "/dashboard",
                    intent: CLAIM_AUDIT_INTENT,
                  });
                }}
              />
            </div>
          ) : null}

          <div className={showSignupCard ? "lg:col-span-7" : undefined}>
            <FindingsSection
              strengths={strengths}
              gaps={visibleRedFlags}
              fixes={recommendations}
            />
          </div>
        </div>
      ) : null}

      {showEmptyState &&
      !loading &&
      !result &&
      !error &&
      !inaccessibleRepo &&
      !ownershipUnverified ? (
        <section className="rounded-2xl border border-border bg-panel px-6 py-12 text-center">
          <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl border border-border bg-background text-brand">
            <ShieldCheck className="h-7 w-7" aria-hidden />
          </div>
          <h2 className="text-base font-bold text-textMain">
            Audit results appear here
          </h2>
          <p className="mx-auto mt-2 max-w-md text-sm leading-relaxed text-textMuted">
            Paste a public GitHub repository URL above to inspect code health
            and production readiness signals.
          </p>
        </section>
      ) : null}

      <GuestAuthModal
        open={authModalOpen}
        error={authModalError}
        onClose={() => setAuthModalOpen(false)}
        onError={setAuthModalError}
        description={authModalDescription}
        nextPath={authNextPath}
        loginHref={`/login?intent=${encodeURIComponent(authIntent)}&next=${encodeURIComponent(authNextPath)}`}
      />

      <Toast message={toastMessage} variant="error" />
    </div>
  );
}

export type RepoAccessStatusKind =
  | "unverified"
  | "private"
  | "verified"
  | "invalid_format";

export default function RepoAccessStatus({
  status,
  username,
}: {
  status: RepoAccessStatusKind | null;
  username?: string | null;
}) {
  if (!status || status === "verified") {
    return null;
  }

  if (status === "invalid_format") {
    return (
      <p
        role="alert"
        className="mt-1.5 rounded-md border border-amber-500/25 bg-amber-500/10 px-2.5 py-1.5 text-xs leading-relaxed text-amber-200"
      >
        ⚠️ Enter a specific repository name (e.g. owner/project), not just a
        username or profile.
      </p>
    );
  }

  if (status === "unverified") {
    const handle = username?.replace(/^@/, "").trim();
    return (
      <p
        role="alert"
        className="mt-1.5 rounded-md border border-amber-500/25 bg-amber-500/10 px-2.5 py-1.5 text-xs leading-relaxed text-amber-200"
      >
        {`⚠️ Not linked to @${handle || "your GitHub"}. You can only audit repos where you have authored commits.`}
      </p>
    );
  }

  return (
    <p
      role="alert"
      className="mt-1.5 rounded-md border border-red-500/25 bg-red-500/10 px-2.5 py-1.5 text-xs leading-relaxed text-red-300"
    >
      🔒 Repository is private or does not exist. Ensure the URL is public.
    </p>
  );
}

export function VerifiedContributorMark({
  visible,
  className = "",
}: {
  visible: boolean;
  className?: string;
}) {
  if (!visible) {
    return null;
  }

  return (
    <span
      className={`inline-flex items-center gap-1 text-xs font-medium text-emerald-400 ${className}`.trim()}
    >
      <span aria-hidden>✓</span>
      Verified Contributor
    </span>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Check, Copy, FileCode2, Loader2, ShieldCheck } from "lucide-react";
import { fetchWithAuth } from "@/lib/fetch-with-auth";
import { readJsonResponse } from "@/lib/read-json-response";
import {
  buildProvixVerificationToken,
  canonicalGitHubRepoUrl,
  hasPersistedProvixTokenVerification,
  PROVIX_FILENAME,
} from "@/lib/provix-token";
import { createClient } from "@/utils/supabase/client";
import { parseGitHubRepoPath } from "@/lib/validate-github-url";

export const GITHUB_CACHE_RETRY_MESSAGE =
  "GitHub's cache might take 10 seconds to update, please try again";

type VerifyTokenResponse = {
  error?: string;
  success?: boolean;
  verified?: boolean;
  already_verified?: boolean;
  repo_url?: string;
  branch?: string;
};

function isGithubLookupFailure(status: number, message: string): boolean {
  if (status === 404 || status === 502 || status === 504) {
    return true;
  }

  return /not found|could not reach github|timed out/i.test(message);
}

export default function RepoOwnershipVerifier({
  repoUrl,
  userId,
  onVerified,
  variant = "card",
}: {
  repoUrl: string;
  userId?: string | null;
  onVerified?: (result: { repoUrl: string; branch?: string }) => void;
  variant?: "card" | "banner";
}) {
  const parsed = parseGitHubRepoPath(repoUrl);
  const canonicalRepoUrl =
    parsed != null
      ? canonicalGitHubRepoUrl(parsed.owner, parsed.repo)
      : "";

  const [token, setToken] = useState(() =>
    userId ? buildProvixVerificationToken(userId) : ""
  );
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [verified, setVerified] = useState(false);
  const [verifiedBranch, setVerifiedBranch] = useState<string | null>(null);
  const hasAttemptedFetch = useRef(false);
  const copyTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const onVerifiedRef = useRef(onVerified);
  onVerifiedRef.current = onVerified;

  useEffect(() => {
    setToken(userId ? buildProvixVerificationToken(userId) : "");

    return () => {
      if (copyTimeoutRef.current) {
        clearTimeout(copyTimeoutRef.current);
      }
    };
  }, [userId]);

  useEffect(() => {
    if (!userId || !canonicalRepoUrl) {
      return;
    }

    let cancelled = false;
    const supabase = createClient();
    void hasPersistedProvixTokenVerification(
      supabase,
      userId,
      canonicalRepoUrl
    ).then((alreadyVerified) => {
      if (cancelled || !alreadyVerified) {
        return;
      }
      setVerified(true);
      onVerifiedRef.current?.({ repoUrl: canonicalRepoUrl });
    });

    return () => {
      cancelled = true;
    };
  }, [canonicalRepoUrl, userId]);

  useEffect(() => {
    setVerified(false);
    setVerifiedBranch(null);
    setError(null);
    hasAttemptedFetch.current = false;
  }, [canonicalRepoUrl]);

  const copyToken = async () => {
    if (!token) {
      return;
    }

    try {
      await navigator.clipboard.writeText(token);
      setCopied(true);
      if (copyTimeoutRef.current) {
        clearTimeout(copyTimeoutRef.current);
      }
      copyTimeoutRef.current = setTimeout(() => setCopied(false), 1800);
    } catch (copyError) {
      console.error("[verify-repo] clipboard copy failed:", copyError);
      setError("Could not copy the token. Select it and copy manually.");
    }
  };

  const verifyOwnership = async () => {
    if (loading || verified || !canonicalRepoUrl || !token) {
      return;
    }

    setLoading(true);
    setError(null);

    const isInitialFetch = !hasAttemptedFetch.current;

    try {
      const response = await fetchWithAuth("/api/verify-token", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          owner: parsed?.owner,
          repo: parsed?.repo,
          expectedToken: token,
        }),
      });

      const payload = (await readJsonResponse<VerifyTokenResponse>(response).catch(
        () => null
      )) as VerifyTokenResponse | null;

      if (response.status === 401) {
        setError("Sign in to verify repository ownership.");
        return;
      }

      hasAttemptedFetch.current = true;

      if (response.ok && (payload?.verified || payload?.success)) {
        setVerified(true);
        setVerifiedBranch(payload.branch ?? null);
        onVerified?.({
          repoUrl: payload.repo_url ?? canonicalRepoUrl,
          branch: payload.branch,
        });
        return;
      }

      const apiMessage = payload?.error?.trim() || "";

      if (isInitialFetch && isGithubLookupFailure(response.status, apiMessage)) {
        setError(GITHUB_CACHE_RETRY_MESSAGE);
        return;
      }

      setError(apiMessage || "Could not verify repository ownership.");
    } catch (verifyError) {
      console.error("[verify-repo] client request failed:", verifyError);
      hasAttemptedFetch.current = true;
      if (isInitialFetch) {
        setError(GITHUB_CACHE_RETRY_MESSAGE);
        return;
      }
      setError("Could not verify repository ownership. Try again.");
    } finally {
      setLoading(false);
    }
  };

  if (!canonicalRepoUrl) {
    return null;
  }

  if (variant === "banner") {
    return (
      <section
        className="flex w-full flex-col gap-3 rounded-xl border border-purple-500/30 bg-purple-950/20 p-3"
        aria-labelledby="repo-ownership-heading"
      >
        <div>
          <p
            id="repo-ownership-heading"
            className="text-[11px] font-bold uppercase tracking-widest text-purple-300"
          >
            Repository ownership
          </p>
          <p className="mt-1 text-xs leading-relaxed text-zinc-400">
            {verified
              ? `Ownership verified${verifiedBranch ? ` on ${verifiedBranch}` : ""}.`
              : "Add a provix.txt or PROVIX.TXT file at your repository root on main or master, then verify."}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <label htmlFor="provix-verification-token" className="sr-only">
            {PROVIX_FILENAME} contents
          </label>
          <span
            id="provix-verification-token"
            title={token}
            className="max-w-[9.5rem] truncate rounded-md border border-purple-500/25 bg-black/40 px-2 py-1.5 font-mono text-[11px] text-purple-100"
          >
            {token}
          </span>
          <button
            type="button"
            onClick={() => void copyToken()}
            disabled={!token}
            className="inline-flex cursor-pointer items-center gap-1.5 whitespace-nowrap rounded-lg border border-purple-500/30 bg-purple-500/10 px-3 py-1.5 text-xs font-semibold text-purple-100 transition-colors hover:bg-purple-500/20 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {copied ? (
              <>
                <Check className="h-3.5 w-3.5 text-emerald-400" aria-hidden />
                Copied!
              </>
            ) : (
              <>
                <Copy className="h-3.5 w-3.5" aria-hidden />
                Copy
              </>
            )}
          </button>
          <button
            type="button"
            onClick={() => void verifyOwnership()}
            disabled={loading || verified || !token}
            aria-busy={loading}
            className="inline-flex cursor-pointer items-center justify-center gap-1.5 whitespace-nowrap rounded-lg bg-purple-600 px-3 py-1.5 text-xs font-semibold text-white transition-colors hover:bg-purple-500 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden />
                Verifying...
              </>
            ) : verified ? (
              <>
                <Check className="h-3.5 w-3.5" aria-hidden />
                Verified
              </>
            ) : (
              "Verify Ownership"
            )}
          </button>
        </div>

        {verified ? (
          <p
            role="status"
            className="w-full rounded-lg border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-xs leading-relaxed text-emerald-200"
          >
            Ownership verified{verifiedBranch ? ` on ${verifiedBranch}` : ""}.
          </p>
        ) : null}

        {error ? (
          <p
            role="alert"
            className="w-full rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs leading-relaxed text-red-200"
          >
            {error}
          </p>
        ) : null}
      </section>
    );
  }

  return (
    <section
      className="rounded-xl border border-brand/25 bg-brandGlow p-4 sm:p-5"
      aria-labelledby="repo-ownership-heading"
    >
      <p className="inline-flex items-center gap-2 text-[11px] font-bold uppercase tracking-widest text-brand">
        <ShieldCheck className="h-4 w-4" aria-hidden />
        Ownership
      </p>
      <h3
        id="repo-ownership-heading"
        className="mt-2 text-sm font-bold tracking-tight text-textMain"
      >
        Prove you own this repository
      </h3>
      <p className="mt-2 text-xs leading-relaxed text-textMuted">
        Commit a <span className="font-mono text-textMain">provix.txt</span> or{" "}
        <span className="font-mono text-textMain">PROVIX.TXT</span> file at the
        repo root on <span className="font-mono text-textMain">main</span> or{" "}
        <span className="font-mono text-textMain">master</span>, then verify.
        GitHub sometimes serves a cached 404 for a few seconds after you push.
      </p>

      <ol className="mt-4 list-decimal space-y-2 pl-4 text-xs leading-relaxed text-textMuted">
        <li>
          Create <span className="font-mono text-textMain">{PROVIX_FILENAME}</span> in
          the root of{" "}
          <span className="break-all font-mono text-textMain">{canonicalRepoUrl}</span>
          .
        </li>
        <li>Paste the token below as the only file contents — no extra lines or quotes.</li>
        <li>
          Commit and push to <span className="font-mono text-textMain">main</span> or{" "}
          <span className="font-mono text-textMain">master</span>.
        </li>
        <li>Click Verify Ownership. If GitHub has not picked up the file yet, wait and retry.</li>
      </ol>

      <div className="mt-4">
        <div className="mb-2 flex items-center justify-between gap-2">
          <label
            htmlFor="provix-verification-token"
            className="text-[11px] font-bold uppercase tracking-wide text-textMuted"
          >
            {PROVIX_FILENAME} contents
          </label>
          <button
            type="button"
            onClick={() => void copyToken()}
            disabled={!token}
            className="inline-flex items-center gap-1.5 rounded-md border border-border bg-panel px-2.5 py-1 text-[11px] font-semibold text-textMain transition-colors hover:bg-surface disabled:cursor-not-allowed disabled:opacity-50 cursor-pointer"
          >
            {copied ? (
              <>
                <Check className="h-3.5 w-3.5 text-emerald-400" aria-hidden />
                Copied!
              </>
            ) : (
              <>
                <Copy className="h-3.5 w-3.5" aria-hidden />
                Copy token
              </>
            )}
          </button>
        </div>
        <div className="relative">
          <FileCode2
            className="pointer-events-none absolute left-3 top-3 h-4 w-4 text-textMuted"
            aria-hidden
          />
          <textarea
            id="provix-verification-token"
            readOnly
            value={token}
            rows={2}
            spellCheck={false}
            className="w-full resize-none rounded-xl border border-border bg-background py-2.5 pl-9 pr-3 font-mono text-xs text-textMain focus:border-brand focus:outline-none"
          />
        </div>
      </div>

      <button
        type="button"
        onClick={() => void verifyOwnership()}
        disabled={loading || verified || !token}
        aria-busy={loading}
        className="mt-4 inline-flex w-full items-center justify-center gap-2 rounded-md bg-brand px-4 py-3 text-xs font-bold tracking-tight text-white transition-colors duration-200 ease-out hover:bg-brandHover disabled:cursor-not-allowed disabled:opacity-50 cursor-pointer"
      >
        {loading ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" aria-hidden />
            Verifying ownership...
          </>
        ) : verified ? (
          <>
            <Check className="h-4 w-4" aria-hidden />
            Ownership verified
          </>
        ) : (
          "Verify Ownership"
        )}
      </button>

      {verified ? (
        <p
          role="status"
          className="mt-4 w-full rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2.5 text-sm text-emerald-200"
        >
          Ownership verified
          {verifiedBranch ? ` on ${verifiedBranch}` : ""}. This repository is now
          linked to your Provix account.
        </p>
      ) : null}

      {error ? (
        <p
          role="alert"
          className="mt-4 w-full rounded-xl border border-red-500/25 bg-red-500/10 px-3 py-2.5 text-sm leading-relaxed text-red-200"
        >
          {error}
        </p>
      ) : null}
    </section>
  );
}

import { AlertTriangle, Check, Minus } from "lucide-react";
import {
  resolveScoreCapAudit,
  type RepoFilesystemEvidence,
  type ScoreCapAudit,
} from "@/lib/repo-filesystem";

const ARTIFACT_CHIPS: Array<{
  key: keyof ScoreCapAudit["coreArtifacts"];
  label: string;
}> = [
  { key: "tests", label: "Tests" },
  { key: "ci", label: "CI/CD" },
  { key: "error_handling", label: "Error handling" },
];

type ScoreCapBreakdownProps = {
  scoreCap?: ScoreCapAudit | null;
  score?: number;
  filesystem?: RepoFilesystemEvidence | null;
  className?: string;
};

export default function ScoreCapBreakdown({
  scoreCap,
  score,
  filesystem = null,
  className = "",
}: ScoreCapBreakdownProps) {
  const audit = resolveScoreCapAudit(
    score ?? scoreCap?.cappedScore ?? 0,
    scoreCap,
    filesystem
  );

  if (!audit?.applied || audit.deductions.length === 0) {
    return null;
  }

  return (
    <div
      className={`rounded-xl border border-violet-500/25 bg-violet-500/5 p-4 space-y-3 ${className}`.trim()}
    >
      <div className="flex items-start justify-between gap-3">
        <div>
          <div className="text-[10px] uppercase font-bold text-violet-300 tracking-wider mb-1">
            Score cap audit trail
          </div>
          {audit.clipped ? (
            <p className="text-sm text-textMain font-semibold tabular-nums">
              {audit.uncappedScore}
              <span className="text-textMuted font-medium"> → </span>
              {audit.cappedScore}
              <span className="text-violet-200"> (−{audit.pointsDeducted})</span>
            </p>
          ) : (
            <p className="text-sm text-textMain font-semibold tabular-nums">
              Max allowed {audit.ceiling}/100
            </p>
          )}
          <p className="text-[11px] text-violet-100/80 leading-relaxed mt-1">
            {audit.clipped
              ? `Filesystem proof removed ${audit.pointsDeducted} point${audit.pointsDeducted === 1 ? "" : "s"} and capped the score at ${audit.ceiling}. README and write-ups cannot raise it.`
              : `The returned score is already at or below the ${audit.ceiling} filesystem ceiling. Point values below show how that ceiling is allocated across missing artifacts.`}
          </p>
        </div>
        <AlertTriangle
          className="w-4 h-4 text-violet-400 shrink-0 mt-0.5"
          aria-hidden
        />
      </div>

      <div className="flex flex-wrap gap-1.5">
        {ARTIFACT_CHIPS.map((chip) => {
          const present = audit.coreArtifacts[chip.key];
          return (
            <span
              key={chip.key}
              className={`inline-flex items-center gap-1 rounded-md border px-2 py-0.5 text-[10px] font-bold ${
 present
 ? "border-emerald-500/25 bg-emerald-500/10 text-emerald-300"
 : "border-red-500/25 bg-red-500/10 text-red-300"
 }`}
            >
              {present ? (
                <Check className="w-3 h-3" aria-hidden />
              ) : (
                <Minus className="w-3 h-3" aria-hidden />
              )}
              {chip.label}
            </span>
          );
        })}
      </div>

      <ul className="space-y-2">
        {audit.deductions.map((deduction) => (
          <li
            key={deduction.code}
            className="rounded-lg border border-border bg-background px-3 py-2.5"
          >
            <div className="flex items-start justify-between gap-3">
              <p className="text-xs font-semibold text-textMain leading-snug">
                {deduction.label}
              </p>
              <span className="shrink-0 text-xs font-mono font-bold tabular-nums text-violet-300">
                −{deduction.points}
              </span>
            </div>
            <p className="text-[11px] text-textMuted leading-relaxed mt-1">
              {deduction.detail}
            </p>
          </li>
        ))}
      </ul>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  BadgeCheck,
  FileSearch,
