  isAuditorPath,
  isDashboardAuditorPath,
  isDashboardProfilePath,
  isDashboardRootPath,
  isInterviewPrepPath,
  isOpportunitiesPath,
  type DashboardTab,
} from "@/lib/dashboard-account";
