export default function DashboardSidebar() {
  const pathname = usePathname();
  const {
    accountRole,
    authLoading,
    isBusinessAccount,
    isEmployeeAccount,
    isGuest,
    showTalentPoolNav,
    userId,
  } = useDashboardNav();
  const [pendingIntroCount, setPendingIntroCount] = useState(0);

  const navRolePending =
    authLoading || (userId != null && accountRole == null);

  const showCandidateNav =
    isGuest || (!isBusinessAccount && !isEmployeeAccount);

  useEffect(() => {
    if (!userId || !showCandidateNav || isGuest) {
      setPendingIntroCount(0);
      return;
    }

    let cancelled = false;
    const supabase = createClient();

    const loadIntros = async () => {
      const { data, error } = await supabase
        .from("intro_requests")
        .select("id, status, candidate_dismissed_at")
        .eq("candidate_id", userId);

      if (cancelled) {
        return;
      }

      if (error || !data) {
        const fallback = await supabase
          .from("intro_requests")
          .select("id, status")
          .eq("candidate_id", userId);

        if (cancelled || fallback.error || !fallback.data) {
          return;
        }

        const pending = fallback.data.filter((row) =>
          isPendingCandidateIntroStatus(row.status)
        ).length;
        setPendingIntroCount(pending);
        return;
      }

      const pending = data.filter(
        (row) =>
          !isCandidateIntroDismissed(row) &&
          isPendingCandidateIntroStatus(row.status)
      ).length;
      setPendingIntroCount(pending);
    };

    void loadIntros();
    return () => {
      cancelled = true;
    };
  }, [userId, showCandidateNav, isGuest]);

  return (
    <div className="flex min-h-screen flex-col justify-between bg-[#0E0E12] p-4">
      <div>
        <SidebarBrand />

        {navRolePending ? (
          <SidebarNavSkeleton />
        ) : showCandidateNav ? (
          <>
            <NavSection title="Workspace">
              {CANDIDATE_WORKSPACE_NAV.map((item) => (
                <DashboardTabLink
                  key={item.key}
                  tab={item.tab}
                  label={item.label}
                  iconName={item.icon}
                  badge={
                    "showBadge" in item && item.showBadge ? (
                      <IntroBadge count={pendingIntroCount} />
                    ) : undefined
                  }
                />
              ))}
            </NavSection>

            <NavSection title="Tools" className="mt-5">
              {ENGINEERING_TOOLS_NAV.map((item) => {
                const isActive = isEngineeringToolActive(item.key, pathname);
                return (
                  <ProtectedNavLink
                    key={item.key}
                    href={item.href}
                    isActive={isActive}
                    icon={<NavIcon name={item.icon} active={isActive} />}
                    label={item.label}
                  />
                );
              })}
            </NavSection>
          </>
        ) : (
          <>
            {isBusinessAccount && (
              <NavSection title="Organization">
                <DashboardTabLink
                  tab="my_profile"
                  label="Company Profile"
                  iconName="User"
                />
                <ProtectedNavLink
                  href="/dashboard/jobs"
                  label="Job Postings"
                  isActive={isEmployerJobsPath(pathname)}
                  icon={
                    <NavIcon
                      name="Clipboard"
                      active={isEmployerJobsPath(pathname)}
                    />
                  }
                />
                <DashboardTabLink
                  tab="applicants"
                  label="Applicants"
                  iconName="Briefcase"
                />
              </NavSection>
            )}

            {isEmployeeAccount && (
              <NavSection title="Network">
                {EMPLOYEE_HUB_NAV.map((item) => (
                  <DashboardTabLink
                    key={item.key}
                    tab={item.tab}
                    label={item.label}
                    iconName={item.icon}
                  />
                ))}
              </NavSection>
            )}

            {showTalentPoolNav && (
              <NavSection title="Evaluation" className="mt-5">
                {EMPLOYER_CONSOLE_NAV.map((item) => (
                  <DashboardTabLink
                    key={item.key}
                    tab={item.tab}
                    label={item.label}
                    iconName={item.icon}
                  />
                ))}
              </NavSection>
            )}
          </>
        )}
      </div>

      <SidebarUserFooter />
    </div>
  );
}

