  isInterviewPrepPath,
  isOpportunitiesPath,
  type DashboardTab,
} from "@/lib/dashboard-account";
import { useDashboardNav } from "@/components/dashboard/dashboard-nav-context";

type NavLinkDef =
  | {
      key: string;
      label: string;
      kind: "tab";
      tab: DashboardTab;
    }
  | {
      key: string;
      label: string;
      kind: "href";
      href: string;
      isActive: (pathname: string) => boolean;
    };

function isNavTabActive(
  tab: DashboardTab,
  pathname: string,
  activeTab: DashboardTab
) {
  if (tab === "opportunities") {
    return (
      isOpportunitiesPath(pathname) ||
      (isDashboardRootPath(pathname) && activeTab === tab)
    );
  }

  if (tab === "auditor") {
    return (
      isDashboardAuditorPath(pathname) ||
      (isDashboardRootPath(pathname) && activeTab === tab)
    );
  }

  if (tab === "my_profile") {
    return (
      isDashboardProfilePath(pathname) ||
      (isDashboardRootPath(pathname) && activeTab === tab)
    );
  }

  return isDashboardRootPath(pathname) && activeTab === tab;
}

function navLinkClass(isActive: boolean) {
  const base =
    "relative inline-flex h-14 shrink-0 items-center text-xs sm:text-sm font-medium transition-colors whitespace-nowrap";
  if (isActive) {
    return `${base} text-zinc-100 font-semibold after:absolute after:bottom-0 after:inset-x-0 after:h-[2px] after:bg-violet-400 after:shadow-[0_0_10px_rgba(139,92,246,0.5)]`;
  }
  return `${base} text-zinc-400 hover:text-zinc-200`;
}

function TopNavLink({
  isActive,
  children,
  onClick,
  href,
}: {
  isActive: boolean;
  children: ReactNode;
  onClick?: () => void;
  href?: string;
}) {
  const className = navLinkClass(isActive);

  if (href) {
    return (
      <Link href={href} onClick={onClick} className={className}>
        {children}
      </Link>
    );
  }

  return (
    <button type="button" onClick={onClick} className={`${className} cursor-pointer`}>
      {children}
    </button>
  );
}

function buildCandidateLinks(): NavLinkDef[] {
  return [
    { key: "profile", label: "Profile", kind: "tab", tab: "my_profile" },
    {
      key: "intros",
      label: "Intro Requests",
      kind: "tab",
      tab: "intro_requests",
    },
    {
      key: "talent",
      label: "Talent Network",
      kind: "tab",
      tab: "opportunities",
    },
    {
      key: "auditor",
      label: "Roster Verification",
      kind: "href",
      href: "/dashboard/auditor",
      isActive: isAuditorPath,
    },
    {
      key: "simulator",
      label: "Simulator",
      kind: "href",
      href: "/dashboard/interview-prep",
      isActive: isInterviewPrepPath,
    },
  ];
}

function buildEmployeeLinks(): NavLinkDef[] {
  return [
    {
      key: "network",
      label: "Talent Network",
      kind: "tab",
      tab: "opportunity_radar",
    },
    {
      key: "applications",
      label: "Applications",
      kind: "tab",
      tab: "applications",
    },
  ];
}

function buildEmployerLinks(showTalentPool: boolean): NavLinkDef[] {
  const links: NavLinkDef[] = [
    { key: "overview", label: "Overview", kind: "tab", tab: "my_profile" },
    { key: "applicants", label: "Applicants", kind: "tab", tab: "applicants" },
  ];

  if (showTalentPool) {
    links.push(
      { key: "talent", label: "Talent Network", kind: "tab", tab: "talent" },
      {
        key: "evaluator",
        label: "AI Screen",
        kind: "tab",
        tab: "evaluator",
      },
      { key: "auditor", label: "Roster Verification", kind: "tab", tab: "auditor" }
    );
  }

  return links;
}

function StatusBadge() {
  const { isGuest, isVerifiedEmployer, isBusinessAccount } = useDashboardNav();

  if (isGuest) {
    return null;
  }

  if (isBusinessAccount && isVerifiedEmployer === true) {
    return (
      <span className="hidden sm:inline-flex items-center rounded-full border border-emerald-500/25 bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold tracking-wide text-emerald-400">
        Verified
      </span>
    );
  }

  if (!isBusinessAccount) {
    return (
      <span className="hidden sm:inline-flex items-center rounded-full border border-zinc-700/60 bg-zinc-900/80 px-2 py-0.5 text-[10px] font-medium tracking-wide text-zinc-400">
        Member
      </span>
    );
  }

  if (isVerifiedEmployer !== false) {
    return null;
  }

  return (
    <span className="hidden sm:inline-flex items-center rounded-full border border-violet-500/25 bg-violet-500/10 px-2 py-0.5 text-[10px] font-semibold tracking-wide text-violet-400">
      Unverified
    </span>
  );
}

function UserAvatar() {
  const {
    isGuest,
    authLoading,
    userAvatarUrl,
    userInitials,
    requireAuth,
  } = useDashboardNav();

  if (authLoading) {
    return (
      <span className="h-8 w-8 shrink-0 animate-pulse rounded-full bg-zinc-800" />
    );
  }

  if (isGuest) {
    return (
      <button
        type="button"
        onClick={() => requireAuth()}
        className="cursor-pointer rounded-md border border-zinc-700 bg-zinc-900 px-3 py-1.5 text-xs font-semibold text-zinc-100 transition-colors hover:bg-zinc-800"
      >
        Sign In
      </button>
    );
  }

  return (
    <Link
      href="/dashboard"
      aria-label="Open your profile"
      className="flex h-8 w-8 shrink-0 items-center justify-center overflow-hidden rounded-full border border-zinc-700/80 bg-zinc-900 text-[10px] font-bold text-zinc-100 transition-colors hover:border-zinc-500"
    >
      {userAvatarUrl ? (
        // eslint-disable-next-line @next/next/no-img-element -- avatar URL is dynamic/remote; next/image optimization isn't worth the config overhead here
        <img
          src={userAvatarUrl}
          alt=""
          className="h-full w-full object-cover"
        />
      ) : (
        userInitials
      )}
    </Link>
  );
}

export default function DashboardTopNav() {
  const pathname = usePathname();
  const {
    activeTab,
    setActiveTab,
    isGuest,
    isBusinessAccount,
    isEmployeeAccount,
    showTalentPoolNav,
    userId,
    onOpenJobApplicants,
    requireAuth,
  } = useDashboardNav();

  const links = isBusinessAccount
    ? buildEmployerLinks(showTalentPoolNav)
    : isEmployeeAccount
      ? buildEmployeeLinks()
      : buildCandidateLinks();

  const selectTab = (tab: DashboardTab) => {
    if (isGuest) {
      requireAuth();
      return;
    }
    setActiveTab(tab);
  };

  return (
    <header className="sticky top-0 z-50 w-full border-b border-white/[0.08] bg-[#0B0B0D]/85 backdrop-blur-md print:hidden">
      <div className="mx-auto flex h-14 max-w-7xl items-center justify-between gap-4 px-4 sm:gap-6 sm:px-6">
        <div className="flex min-w-0 flex-1 items-center gap-1 sm:gap-2">
          <Link
            href="/"
            className="flex shrink-0 items-center gap-2.5 transition-opacity hover:opacity-90"
          >
            <span className="flex h-6 w-6 items-center justify-center rounded-md border border-zinc-700/80 bg-zinc-900 text-[11px] font-bold text-white">
              P
            </span>
            <span className="hidden text-base font-semibold tracking-tight text-white sm:inline">
              PROVIX
            </span>
          </Link>

          <span
            className="mx-2 hidden h-4 w-px shrink-0 bg-zinc-800 sm:block"
            aria-hidden
          />

          <nav
            aria-label="Dashboard"
            className="flex min-w-0 flex-1 items-center gap-3 overflow-x-auto sm:gap-4 [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
          >
            {links.map((item) => {
              if (item.kind === "href") {
                const active = item.isActive(pathname);
                return (
                  <TopNavLink
                    key={item.key}
                    href={isGuest ? undefined : item.href}
                    isActive={active}
                    onClick={
                      isGuest
                        ? () => requireAuth()
                        : undefined
                    }
                  >
                    {item.label}
                  </TopNavLink>
                );
              }

              const active = isNavTabActive(item.tab, pathname, activeTab);
              const href =
                item.tab === "my_profile" && isBusinessAccount
                  ? "/dashboard?tab=my_profile"
                  : dashboardTabHref(item.tab);

              if (item.tab === "opportunities") {
                return (
                  <TopNavLink
                    key={item.key}
                    href={dashboardTabHref(item.tab)}
                    isActive={active}
                  >
                    {item.label}
                  </TopNavLink>
                );
              }

              if (isGuest) {
                return (
                  <TopNavLink
                    key={item.key}
                    isActive={active}
                    onClick={() => requireAuth()}
                  >
                    {item.label}
                  </TopNavLink>
                );
              }

              if (isDashboardRootPath(pathname)) {
                return (
                  <TopNavLink
                    key={item.key}
                    isActive={active}
                    onClick={() => selectTab(item.tab)}
                  >
                    {item.label}
                  </TopNavLink>
                );
              }

              return (
                <TopNavLink
                  key={item.key}
                  href={href}
                  isActive={active}
                  onClick={() => selectTab(item.tab)}
                >
                  {item.label}
                </TopNavLink>
              );
            })}
          </nav>
        </div>

        <div className="flex shrink-0 items-center gap-2.5 sm:gap-3">
          {!isGuest && isBusinessAccount ? (
            <EmployerNotificationBell
              userId={userId}
              onOpenJobApplicants={(jobId) => onOpenJobApplicants?.(jobId)}
            />
          ) : null}
          <StatusBadge />
          <UserAvatar />
        </div>
      </div>
    </header>
  );
}

"use client";

import { Suspense, useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import DossierVerifiedCard from "@/components/auditor/dossier-verified-card";
import { DOSSIER_PUBLISHED_EVENT } from "@/lib/production-audit";

function DossierClaimBannerInner() {
  const params = useSearchParams();
  const [publishedEvent, setPublishedEvent] = useState(false);
  const published = publishedEvent || params.get("dossier") === "published";
  const claimError = params.get("claim_error")?.trim() || null;

  useEffect(() => {
    const onPublished = () => setPublishedEvent(true);
    window.addEventListener(DOSSIER_PUBLISHED_EVENT, onPublished);
    return () => window.removeEventListener(DOSSIER_PUBLISHED_EVENT, onPublished);
  }, []);

  if (published) {
    return <DossierVerifiedCard className="mb-6" />;
  }

  if (claimError) {
    return (
      <div
        role="alert"
        className="mx-4 mt-4 rounded-xl border border-rose-500/25 bg-rose-500/10 px-4 py-3 text-sm text-rose-200 md:mx-6"
      >
        {claimError}
      </div>
    );
  }

  return null;
}

export default function DossierClaimBanner() {
  return (
    <Suspense fallback={null}>
      <DossierClaimBannerInner />
    </Suspense>
  );
}

"use client";

import { Trash2 } from "lucide-react";
import {
  CREDENTIAL_TYPE_OPTIONS,
  MAX_EDUCATION_ENTRIES,
  SELF_TAUGHT_CHECKBOX_LABEL,
  SELF_TAUGHT_ENGINEER_LABEL,
  createEmptyEducationEntry,
  type EducationEntry,
} from "@/lib/candidate-education";

const inputClass =
  "w-full bg-background border border-border rounded-xl p-3 text-sm text-textMain placeholder:text-textMuted focus:outline-none focus:border-brand";

const labelClass =
  "block text-[11px] font-bold text-textMuted mb-2 uppercase";

type EducationEntriesFormProps = {
  entries: EducationEntry[];
  onChange: (entries: EducationEntry[]) => void;
  isSelfTaught: boolean;
  onSelfTaughtChange: (value: boolean) => void;
  disabled?: boolean;
};

export default function EducationEntriesForm({
  entries,
  onChange,
  isSelfTaught,
  onSelfTaughtChange,
  disabled = false,
}: EducationEntriesFormProps) {
  const atLimit = entries.length >= MAX_EDUCATION_ENTRIES;

  const updateEntry = (id: string, patch: Partial<EducationEntry>) => {
    onChange(
      entries.map((entry) => (entry.id === id ? { ...entry, ...patch } : entry))
    );
  };

  const removeEntry = (id: string) => {
    onChange(entries.filter((entry) => entry.id !== id));
  };

  const addEntry = () => {
    if (disabled || atLimit) return;
    onChange([...entries, createEmptyEducationEntry()]);
  };

  return (
    <div className="space-y-4">
      <div>
        <h3 className="text-sm font-bold text-textMain">Education</h3>
        <label className="mt-3 flex cursor-pointer items-center gap-2.5 select-none">
          <input
            type="checkbox"
            checked={isSelfTaught}
            disabled={disabled}
            onChange={(event) => onSelfTaughtChange(event.target.checked)}
            className="h-4 w-4 shrink-0 rounded border border-zinc-700 bg-zinc-950 accent-zinc-300 focus:outline-none focus-visible:ring-1 focus-visible:ring-zinc-500/40 disabled:cursor-not-allowed disabled:opacity-50"
          />
          <span className="text-sm text-zinc-200">
            {SELF_TAUGHT_CHECKBOX_LABEL}
          </span>
        </label>
        <p className="mt-2 text-[11px] leading-relaxed text-textMuted">
          Optional. Add up to {MAX_EDUCATION_ENTRIES} programs or credentials,
          or mark yourself as self-taught.
        </p>
      </div>

      {isSelfTaught ? (
        <div className="rounded-xl border border-zinc-800 bg-zinc-900/60 px-4 py-3 text-sm text-zinc-300">
          Displayed on your public profile as:{" "}
          <span className="font-semibold text-textMain">
            {SELF_TAUGHT_ENGINEER_LABEL}
          </span>
        </div>
      ) : (
        <>
      {entries.length === 0 ? (
        <div className="rounded-xl border border-dashed border-zinc-800 bg-background px-4 py-6 text-sm text-textMuted">
          No education added yet.
        </div>
      ) : (
        entries.map((entry, index) => (
          <div
            key={entry.id}
            className="space-y-4 rounded-xl border border-zinc-800 bg-background p-4"
          >
            <div className="flex items-center justify-between gap-3">
              <p className="text-[11px] font-bold uppercase tracking-wide text-textMuted">
                Entry {index + 1}
              </p>
              <button
                type="button"
                disabled={disabled}
                onClick={() => removeEntry(entry.id)}
                className="inline-flex items-center gap-1 rounded-lg px-2 py-1 text-[11px] font-semibold text-zinc-400 transition-colors hover:bg-zinc-900 hover:text-rose-300 disabled:cursor-not-allowed disabled:opacity-50"
              >
                <Trash2 className="h-3.5 w-3.5" aria-hidden />
                Remove
              </button>
            </div>

            <div>
              <label className={labelClass} htmlFor={`education-institution-${entry.id}`}>
                Institution / Program name{" "}
                <span className="text-rose-400">*</span>
              </label>
              <input
                id={`education-institution-${entry.id}`}
                type="text"
                value={entry.institution}
                disabled={disabled}
                placeholder="Stanford University, App Academy, ..."
                onChange={(event) =>
                  updateEntry(entry.id, { institution: event.target.value })
                }
                className={inputClass}
              />
            </div>

            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <div>
                <label className={labelClass} htmlFor={`education-credential-${entry.id}`}>
                  Credential type
                </label>
                <select
                  id={`education-credential-${entry.id}`}
                  value={entry.credentialType}
                  disabled={disabled}
                  onChange={(event) =>
                    updateEntry(entry.id, {
                      credentialType: event.target.value as EducationEntry["credentialType"],
                    })
                  }
                  className={`${inputClass} cursor-pointer`}
                >
                  {CREDENTIAL_TYPE_OPTIONS.map((option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className={labelClass} htmlFor={`education-field-${entry.id}`}>
                  Field of study
                </label>
                <input
                  id={`education-field-${entry.id}`}
                  type="text"
                  value={entry.fieldOfStudy}
                  disabled={disabled}
                  placeholder="Computer Science"
                  onChange={(event) =>
                    updateEntry(entry.id, { fieldOfStudy: event.target.value })
                  }
                  className={inputClass}
                />
              </div>
            </div>

            <div>
              <label className={labelClass} htmlFor={`education-year-${entry.id}`}>
                Graduation / completion year
              </label>
              <input
                id={`education-year-${entry.id}`}
                type="text"
                inputMode="numeric"
                value={entry.graduationYear}
                disabled={disabled}
                placeholder="2026"
                onChange={(event) =>
                  updateEntry(entry.id, { graduationYear: event.target.value })
                }
                className={`${inputClass} font-mono sm:max-w-xs`}
              />
            </div>
          </div>
        ))
      )}

      <button
        type="button"
        disabled={disabled || atLimit}
        onClick={addEntry}
        className="inline-flex items-center gap-1.5 rounded-xl border border-zinc-800 bg-background px-3.5 py-2 text-xs font-bold text-textMain transition-colors hover:border-zinc-600 hover:bg-zinc-900 disabled:cursor-not-allowed disabled:opacity-50"
      >
        + Add Education
      </button>
        </>
      )}
    </div>
  );
}

