} from "@/lib/production-audit";
import { repoNamespaceMatchesGitHubUsername } from "@/lib/validate-github-url";

const SIGNED_IN_AUDITOR_PATH = "/dashboard/auditor";
const PUBLIC_AUDITOR_PATH = "/audits";

async function persistOwnScoreVisibility(nextVisible: boolean): Promise<void> {
  const response = await fetchWithAuth("/api/profile/production-audit", {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ is_publicly_visible: nextVisible }),
  });

  let apiError = "Could not update visibility.";
  try {
    const body = await readJsonResponse<{ error?: string }>(response);
    if (response.ok) {
      return;
    }
    if (body.error?.trim()) {
      apiError = body.error.trim();
    }
  } catch {
    if (!response.ok) {
      apiError = "Could not update visibility.";
    }
  }

  throw new Error(apiError);
}

function useEmployerScoreVisibility(
  record: ProductionAuditRecord | null,
  onVisibilityChange?: (visible: boolean) => void,
  linkedGitHubUsername?: string | null
) {
  const isVerified = isVerifiedDossier(record);
  const ownershipBadgeVerified =
    isVerified ||
    repoNamespaceMatchesGitHubUsername(
      record?.breakdown.audited_repo_url,
      linkedGitHubUsername
    );
  const hasScore = Boolean(
    record &&
      (record.breakdown.audited_repo_url || record.productionScore > 0)
  );
  const score = record?.productionScore ?? 0;
  const hygiene = record?.breakdown.delivery_hygiene_score;
  const historyFetched = record?.breakdown.commit_history_fetched;
  const canPublish =
    isVerified &&
    canPublishProductionScore(
      score,
      hygiene,
      historyFetched === false ? false : hygiene == null ? false : true
    );
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [visibilityOverride, setVisibilityOverride] = useState<boolean | null>(
    null
  );
  const recordVisibility = Boolean(record?.isPubliclyVisible);
  const visible = visibilityOverride ?? recordVisibility;
  const visibilitySourceKey = `${record?.productionScore ?? "none"}:${recordVisibility}:${record?.breakdown.audited_at ?? ""}`;
  const [syncedVisibilityKey, setSyncedVisibilityKey] =
    useState(visibilitySourceKey);

  if (syncedVisibilityKey !== visibilitySourceKey) {
    setSyncedVisibilityKey(visibilitySourceKey);
    setVisibilityOverride(null);
  }

  const toggleVisibility = async () => {
    if (!isVerified || !hasScore || !canPublish || saving) {
      return;
    }

    const previousVisible = visible;
    const nextVisible = !visible;
    setVisibilityOverride(nextVisible);
    onVisibilityChange?.(nextVisible);
    setSaving(true);
    setError(null);

    try {
      await persistOwnScoreVisibility(nextVisible);
    } catch (err) {
      setVisibilityOverride(previousVisible);
      onVisibilityChange?.(previousVisible);
      setError(
        err instanceof Error ? err.message : "Could not update visibility."
      );
    } finally {
      setSaving(false);
    }
  };

  return {
    hasScore,
    isVerified,
    ownershipBadgeVerified,
    score,
    canPublish,
    visible,
    saving,
    error,
    toggleVisibility,
  };
}

function EmployerVisibilitySwitch({
  checked,
  disabled,
  saving,
  onToggle,
}: {
  checked: boolean;
  disabled: boolean;
  saving: boolean;
  onToggle: () => void;
}) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label="Show verified score to employers"
      disabled={disabled || saving}
      onClick={onToggle}
      className={`relative h-5 w-9 shrink-0 rounded-full transition-colors ${
        saving
          ? "cursor-wait opacity-60"
          : disabled
            ? "cursor-not-allowed opacity-50"
            : "cursor-pointer"
      } ${checked ? "bg-emerald-500" : "bg-background"}`}
    >
      <span
        className="absolute top-0.5 left-0.5 h-4 w-4 rounded-full bg-white transition-transform"
        style={{
          transform: checked ? "translateX(16px)" : "translateX(0)",
        }}
      />
    </button>
  );
}

const NO_AUDIT_BADGE_CLASS =
  "border-border bg-background text-zinc-400";

function OwnershipUnverifiedBadge() {
  return (
    <span
      title={OWNERSHIP_UNVERIFIED_MESSAGE}
      className="inline-flex items-center rounded-full border border-amber-500/30 bg-amber-500/10 px-1.5 py-0.5 text-xs font-medium uppercase leading-none tracking-wide text-amber-300"
    >
      {OWNERSHIP_UNVERIFIED_LABEL}
    </span>
  );
}

export function AuditStatusBanner({
  record,
  onVisibilityChange,
  linkedGitHubUsername,
}: {
  record: ProductionAuditRecord | null;
  onVisibilityChange?: (visible: boolean) => void;
  linkedGitHubUsername?: string | null;
}) {
  const {
    hasScore,
    isVerified,
    ownershipBadgeVerified,
    score,
    canPublish,
    visible,
    saving,
    error,
    toggleVisibility,
  } = useEmployerScoreVisibility(
    record,
    onVisibilityChange,
    linkedGitHubUsername
  );

  return (
    <div className="rounded-xl border border-border bg-panel px-3 py-2">
      <div className="flex items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-2.5">
          <p className="font-mono text-sm font-bold tabular-nums text-textMain">
            {hasScore ? score : "—"}
            <span className="ml-0.5 text-sm font-semibold text-zinc-400">
              /100
            </span>
          </p>
          {ownershipBadgeVerified ? (
            <ProductionScoreVerifiedBadge score={score} />
          ) : hasScore ? (
            <OwnershipUnverifiedBadge />
          ) : null}
        </div>
        {isVerified ? (
          <div className="flex shrink-0 items-center gap-2">
            <span className="text-sm font-medium text-zinc-400">Employers</span>
            <EmployerVisibilitySwitch
              checked={visible && canPublish}
              disabled={!canPublish}
              saving={saving}
              onToggle={() => void toggleVisibility()}
            />
          </div>
        ) : null}
      </div>
      {hasScore && !ownershipBadgeVerified ? (
        <p className="mt-1 text-sm text-zinc-400">{OWNERSHIP_UNVERIFIED_MESSAGE}</p>
      ) : null}
      {error ? (
        <p className="mt-1 text-sm text-red-300" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

function MetricPill({ label, score }: { label: string; score: number }) {
  return (
    <span className="inline-flex items-center gap-1 rounded-full border border-border bg-background px-2 py-0.5 text-xs leading-none text-zinc-400">
      {label}
      <span className="font-mono font-medium tabular-nums text-textMain">
        {score}
      </span>
    </span>
  );
}

function AuditHistoryList({
  entries,
  loading,
}: {
  entries: ProductionAuditHistoryEntry[];
  loading: boolean;
}) {
  if (loading) {
    return (
      <p className="text-sm text-zinc-400">Loading history…</p>
    );
  }

  if (entries.length === 0) {
    return null;
  }

  return (
    <details className="group">
      <summary className="cursor-pointer list-none text-sm text-zinc-400 hover:text-textMain [&::-webkit-details-marker]:hidden">
        <span className="group-open:hidden">History · {entries.length}</span>
        <span className="hidden group-open:inline">Hide history</span>
      </summary>
      <ul className="mt-1.5 max-h-28 space-y-0.5 overflow-y-auto">
        {entries.map((entry) => {
          const repo = formatAuditedRepoLabel(entry.auditedRepoUrl);
          const when = formatAuditedAt(entry.auditedAt || entry.createdAt);
          return (
            <li
              key={entry.id}
              className="flex items-center justify-between gap-3 py-1 text-sm"
            >
              <p className="min-w-0 truncate text-zinc-400">
                <span className="text-textMain">{repo}</span>
                {when ? ` · ${when}` : ""}
              </p>
              <p className="shrink-0 font-mono tabular-nums text-textMain">
                {entry.productionScore}
              </p>
            </li>
          );
        })}
      </ul>
    </details>
  );
}

export default function VerifiedCodeQualityScorecard({
  record,
  onVisibilityChange,
  linkedGitHubUsername,
  compact = true,
  showVisibilityToggle = true,
}: {
  record: ProductionAuditRecord | null;
  onVisibilityChange?: (visible: boolean) => void;
  linkedGitHubUsername?: string | null;
  compact?: boolean;
  /** Hide when a parent settings surface already owns employer visibility. */
  showVisibilityToggle?: boolean;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const alreadyOnAuditor =
    pathname === SIGNED_IN_AUDITOR_PATH ||
    pathname === PUBLIC_AUDITOR_PATH ||
    pathname.startsWith(`${SIGNED_IN_AUDITOR_PATH}/`);
  const {
    hasScore,
    isVerified,
    ownershipBadgeVerified,
    score,
    canPublish,
    visible,
    saving,
    error,
    toggleVisibility,
  } = useEmployerScoreVisibility(
    record,
    onVisibilityChange,
    linkedGitHubUsername
  );
  const repo = record?.breakdown.audited_repo_url
    ? formatAuditedRepoLabel(record.breakdown.audited_repo_url)
    : "";
  const auditedAt = record?.breakdown.audited_at
    ? formatAuditedAt(record.breakdown.audited_at)
    : "";
  const [history, setHistory] = useState<ProductionAuditHistoryEntry[]>([]);
  const [historyLoading, setHistoryLoading] = useState(true);
  const [signedIn, setSignedIn] = useState<boolean | null>(null);
  const [openingAuditor, setOpeningAuditor] = useState(false);

  useEffect(() => {
    let cancelled = false;

    void (async () => {
      try {
        const supabase = createClient();
        const { data } = await supabase.auth.getUser();
        if (!cancelled) {
          setSignedIn(Boolean(data.user));
        }
      } catch {
        if (!cancelled) {
          setSignedIn(false);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  const openAuditor = async () => {
    if (openingAuditor) {
      return;
    }

    setOpeningAuditor(true);
    try {
      let isSignedIn = signedIn;
      if (isSignedIn == null) {
        const supabase = createClient();
        const { data } = await supabase.auth.getUser();
        isSignedIn = Boolean(data.user);
        setSignedIn(isSignedIn);
      }

      router.push(isSignedIn ? SIGNED_IN_AUDITOR_PATH : PUBLIC_AUDITOR_PATH);
    } catch {
      router.push(PUBLIC_AUDITOR_PATH);
    } finally {
      setOpeningAuditor(false);
    }
  };

  const loadHistory = useCallback(async () => {
    setHistoryLoading(true);
    try {
      const response = await fetchWithAuth("/api/profile/production-audit");
      if (!response.ok) {
        setHistory([]);
        return;
      }
      const payload = await readJsonResponse<{
        history?: Array<Record<string, unknown>>;
      }>(response);
      setHistory(
        (payload.history ?? [])
          .map((row) => parseProductionAuditHistoryRow(row))
          .filter((entry): entry is ProductionAuditHistoryEntry => Boolean(entry))
      );
    } catch {
      setHistory([]);
    } finally {
      setHistoryLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadHistory();
  }, [loadHistory, record?.productionScore, record?.breakdown.audited_at]);

  const visibilityHint =
    !showVisibilityToggle || !isVerified
      ? null
      : !canPublish
        ? `Needs ${PUBLIC_SCORECARD_THRESHOLD}+`
        : visible
          ? "Visible"
          : "Hidden";

  return (
    <section
      className={
        compact
          ? "rounded-lg border border-border bg-panel px-3 py-2.5"
          : "rounded-2xl border border-border bg-panel px-5 py-4"
      }
    >
      <div className="flex items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-3">
          <p
            className={
              compact
                ? "font-mono text-sm font-semibold tabular-nums text-textMain"
                : "font-mono text-3xl font-extrabold tabular-nums tracking-tight text-textMain"
            }
          >
            {hasScore ? score : "—"}
            <span className="ml-0.5 text-sm font-normal text-zinc-400">
              /100
            </span>
          </p>
          {ownershipBadgeVerified ? (
            <ProductionScoreVerifiedBadge score={score} />
          ) : hasScore ? (
            <OwnershipUnverifiedBadge />
          ) : (
            <span
              className={`inline-flex items-center rounded-full border px-1.5 py-0.5 text-xs font-medium leading-none ${NO_AUDIT_BADGE_CLASS}`}
            >
              No audit
            </span>
          )}
        </div>
        {isVerified && showVisibilityToggle ? (
          <label className="flex shrink-0 items-center gap-2 text-sm text-zinc-400">
            <span className="hidden sm:inline">Show to employers</span>
            <span className="sm:hidden">Employers</span>
            <EmployerVisibilitySwitch
              checked={visible && canPublish}
              disabled={!canPublish}
              saving={saving}
              onToggle={() => void toggleVisibility()}
            />
          </label>
        ) : null}
      </div>
      {hasScore && !ownershipBadgeVerified ? (
        <p className="mt-1.5 text-sm text-zinc-400">
          {OWNERSHIP_UNVERIFIED_MESSAGE}
        </p>
      ) : null}

      <div
        className={
          compact
            ? "mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1"
            : "mt-3 flex flex-wrap items-center gap-x-3 gap-y-2"
        }
      >
        {hasScore && record ? (
          <>
            <span className="truncate text-sm text-zinc-400">
              {repo ? (
                isPrivateAuditedRepoLabel(record.breakdown.audited_repo_url) ? (
                  repo
                ) : (
                  <a
                    href={record.breakdown.audited_repo_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="hover:text-textMain"
                  >
                    {repo}
                  </a>
                )
              ) : null}
              {repo && auditedAt ? " · " : null}
              {auditedAt || null}
              {visibilityHint ? ` · ${visibilityHint}` : null}
            </span>
            <span className="hidden h-3 w-px bg-border sm:inline" aria-hidden />
            <MetricPill label="CI" score={record.breakdown.ci_cd_score} />
            <MetricPill label="Tests" score={record.breakdown.test_density} />
            <MetricPill label="Errors" score={record.breakdown.error_handling} />
          </>
        ) : (
          <span className="text-sm text-zinc-400">
            No production audit yet.
          </span>
        )}
      </div>

      {error && showVisibilityToggle ? (
        <p className="mt-1 text-sm text-red-300" role="alert">
          {error}
        </p>
      ) : null}

      {(historyLoading || history.length > 0 || !alreadyOnAuditor) ? (
        <div className="mt-2 flex items-center justify-between gap-3">
          <AuditHistoryList entries={history} loading={historyLoading} />
          {alreadyOnAuditor ? null : (
            <button
              type="button"
              onClick={() => void openAuditor()}
              disabled={openingAuditor}
              className="ml-auto text-sm text-zinc-400 hover:text-textMain disabled:cursor-wait disabled:opacity-60"
            >
              {hasScore ? "Audit another repo" : "Run audit"}
            </button>
          )}
        </div>
      ) : null}
    </section>
  );
}

import { SITE_LOGO_URL, SITE_NAME } from "@/lib/site";

export type JobMatchEmailProps = {
  developerName: string;
  jobTitle: string;
  companyName: string;
  location: string;
  requiredStack: string[];
  repoName: string;
  auditScore: number;
  jobUrl: string;
};

function clampScore(score: number): number {
  if (!Number.isFinite(score)) {
    return 0;
  }
  return Math.min(100, Math.max(0, Math.round(score)));
}

function stackTags(requiredStack: string[]): string {
  if (requiredStack.length === 0) {
    return `<span style="display:inline-block;padding:4px 10px;border-radius:999px;background:#eef2ff;color:#4338ca;font-size:12px;font-weight:600;">Generalist</span>`;
  }

  return requiredStack
    .map(
      (tag) =>
        `<span style="display:inline-block;margin:0 6px 6px 0;padding:4px 10px;border-radius:999px;background:#eef2ff;color:#4338ca;font-size:12px;font-weight:600;">${escapeHtml(tag)}</span>`
    )
    .join("");
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

