          View Role &amp; Apply
        </a>
      </p>

      <div
        style={{
          borderLeft: "3px solid #4f46e5",
          padding: "12px 0 12px 14px",
          background: "#eef2ff",
          borderRadius: "0 12px 12px 0",
        }}
      >
        <p
          style={{
            margin: "0 0 6px",
            fontSize: 12,
            letterSpacing: "0.08em",
            textTransform: "uppercase",
            color: "#4338ca",
            fontWeight: 700,
          }}
        >
          Score / Pro Tip
        </p>
        <p style={{ margin: 0, color: "#374151", fontSize: 14 }}>
          Tip for visibility: Hiring leads review verified profiles first. Your
          current audit score is <strong>{score}/100</strong>. Update your repo
          or resolve open flags anytime to push your application to the top of
          their queue.
        </p>
      </div>

      <p style={{ margin: "28px 0 0", fontSize: 12, color: "#9ca3af" }}>
        You&apos;re receiving this because job-match alerts are enabled on your{" "}
        {SITE_NAME} profile.
      </p>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import LockedContactDossierBadge from "@/components/LockedContactDossierBadge";
import GeminiDeepScreening, {
  buildDeepScreeningCacheKey,
  isValidDeepScreeningJob,
  type DeepScreeningJobContext,
} from "@/components/employer/gemini-deep-screening";
import ProductionCodeAuditSection from "@/components/employer/production-code-audit-section";
import ProductionScoreBadge from "@/components/employer/production-score-badge";
import ScoreMeter from "@/components/ScoreMeter";
import VerifiedOnProvixPill from "@/components/VerifiedOnProvixPill";
import WorkPreferenceTimezoneBadge from "@/components/WorkPreferenceTimezoneBadge";
import CandidateEducationSummary from "@/components/CandidateEducationSummary";
import { buildAlliterativeAliasIdentity } from "@/lib/alias-generator";
import { getAvailabilityBadgeClass } from "@/lib/availability-status";
import {
  getPublicCandidateInitials,
  redactPersonalNamesFromText,
} from "@/lib/candidate-anonymization";
import {
  assessBioQuality,
  buildDeterministicEmployerMatch,
} from "@/lib/employer-match";
import { fetchWithAuth } from "@/lib/fetch-with-auth";
import { jobDisplayTags, parseJobListInput } from "@/lib/jobs";
import { readJsonResponse } from "@/lib/read-json-response";
import { clampScore0to100 } from "@/lib/score-scale";
import {
  getCandidateProjectLinks,
  productionAuditRecordFromCandidate,
  type TalentPoolCandidate,
} from "@/lib/talent-pool-candidate";
import {
  candidateEducationFields,
  educationFromProfileRow,
  fetchCandidateEducationForEmployer,
  hasTalentEducation,
  mergeTalentEducation,
  resolveTalentProfileId,
  type TalentPoolEducation,
} from "@/lib/talent-pool-profiles";
import { createClient } from "@/utils/supabase/client";

const DrawerIcons = {
  XMark: () => (
    <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
    </svg>
  ),
  ExternalLink: () => (
    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.75}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 6L21 3m0 0h-5.25M21 3v5.25" />
    </svg>
  ),
};

type CandidateIntelligenceDrawerProps = {
  candidate: TalentPoolCandidate | null;
  open: boolean;
  isUnlocked: boolean;
  onClose: () => void;
  onRequestIntro: (candidate: TalentPoolCandidate) => void;
  screeningJob?: DeepScreeningJobContext | null;
  companyName?: string;
  requireAuth?: () => boolean;
  onToast?: (message: string) => void;
};

export default function CandidateIntelligenceDrawer({
  candidate,
  open,
  isUnlocked,
  onClose,
  onRequestIntro,
  screeningJob = null,
  companyName,
  requireAuth,
  onToast,
}: CandidateIntelligenceDrawerProps) {
  const [educationOverlay, setEducationOverlay] =
    useState<TalentPoolEducation | null>(null);

  const profileId = candidate ? resolveTalentProfileId(candidate) : "";

  useEffect(() => {
    setEducationOverlay(null);

    if (!open || !candidate) {
      return;
    }

    if (hasTalentEducation(candidateEducationFields(candidate))) {
      setEducationOverlay(null);
      return;
    }

    if (!profileId) {
      return;
    }

    let cancelled = false;

    void (async () => {
      const supabase = createClient();
      const emptyEducation: TalentPoolEducation = {
        university: "",
        major: "",
        gpa: "",
        graduationYear: "",
        isSelfTaught: false,
      };

      const [clientEducation, apiEducation] = await Promise.all([
        fetchCandidateEducationForEmployer(supabase, profileId),
        (async () => {
          try {
            const response = await fetchWithAuth(
              `/api/talent-pool/education?profileId=${encodeURIComponent(profileId)}`
            );
            if (!response.ok) {
              return null;
            }
            const payload = await readJsonResponse<Record<string, unknown>>(
              response
            );
            return educationFromProfileRow(payload);
          } catch (error) {
            console.error("Talent pool education API failed:", error);
            return null;
          }
        })(),
      ]);

      if (cancelled) {
        return;
      }

      const education = mergeTalentEducation(
        clientEducation ?? emptyEducation,
        apiEducation ?? emptyEducation
      );

      if (!hasTalentEducation(education)) {
        return;
      }

      setEducationOverlay(education);
    })();

    return () => {
      cancelled = true;
    };
    // Depend on education fields only — full `candidate` identity changes would refetch constantly.
    // eslint-disable-next-line react-hooks/exhaustive-deps -- education field slice
  }, [
    open,
    profileId,
    candidate?.university,
    candidate?.major,
    candidate?.gpa,
    candidate?.graduationYear,
    candidate?.isSelfTaught,
  ]);

  const liveCandidate = useMemo(
    () =>
      candidate
        ? educationOverlay
          ? {
              ...candidate,
              ...mergeTalentEducation(
                candidateEducationFields(candidate),
                educationOverlay
              ),
            }
          : candidate
        : null,
    [candidate, educationOverlay]
  );

  const publicName = liveCandidate
    ? buildAlliterativeAliasIdentity(liveCandidate.profileId?.trim() || "").alias
    : "";
  const displayInitials = liveCandidate
    ? getPublicCandidateInitials({
        codenameAlias: publicName,
        candidateId: liveCandidate.profileId ?? liveCandidate.id,
      })
    : "";
  const lockedBio = liveCandidate
    ? redactPersonalNamesFromText(
        liveCandidate.bio ?? "",
        liveCandidate,
        publicName
      )
    : "";
  const projectLinks = liveCandidate ? getCandidateProjectLinks(liveCandidate) : [];
  const contactEmail = candidate?.email?.trim() || null;
  const contactPhone = candidate?.phone?.trim() || null;
  const hasScreeningJob = isValidDeepScreeningJob(screeningJob);
  const roleFitInsight = useMemo(() => {
    if (!liveCandidate) {
      return {
        matching: [] as string[],
        missing: [] as string[],
        reasoning: "",
        flag: null as string | null,
      };
    }

    const match = buildDeterministicEmployerMatch(
      {
        title: liveCandidate.role,
        bio: liveCandidate.bio,
        skills: liveCandidate.skills,
        degree: liveCandidate.major,
        experience_level: liveCandidate.experienceLevel,
        auditScore: liveCandidate.productionScore,
        productionScore: liveCandidate.productionScore,
        auditBreakdown: liveCandidate.auditBreakdown,
        githubAudit: liveCandidate.githubAudit,
        github_url: liveCandidate.github || liveCandidate.github_url || "",
      },
      hasScreeningJob && screeningJob
        ? {
            title: screeningJob.title,
            company: screeningJob.company ?? "",
            tags: jobDisplayTags(screeningJob),
            tech_stack: parseJobListInput(screeningJob.tech_stack),
            required_skills: parseJobListInput(screeningJob.required_skills),
            location: screeningJob.location ?? "",
            description: screeningJob.description ?? "",
          }
        : { title: "", tags: [], description: "", searchQuery: "" }
    );

    const bioQuality = assessBioQuality(liveCandidate.bio);
    // Scorer no longer embeds Flag: in reasoning; use it as-is.
    const reasoning = match.reasoning.trim();

    return {
      matching: match.matching_skills.slice(0, 6),
      missing: match.missing_skills.slice(0, 6),
      reasoning,
      flag: bioQuality.flag,
    };
  }, [liveCandidate, hasScreeningJob, screeningJob]);

  return (
    <div className={`fixed inset-0 z-50 ${open ? "" : "pointer-events-none"}`}>
      <div
        onClick={onClose}
        className={`absolute inset-0 bg-black/70 backdrop-blur-sm transition-opacity duration-300 ${
 open ? "opacity-100" : "opacity-0"
 }`}
      />
      <div
        className={`absolute top-0 right-0 h-full w-full max-w-md bg-panel border-l border-border overflow-y-auto transition-transform duration-300 ease-out ${
 open ? "translate-x-0" : "translate-x-full"
 }`}
      >
        {liveCandidate && (
          <div className="p-6 space-y-6">
            <div className="flex items-start justify-between pb-5 border-b border-border">
              <div className="flex items-center gap-3">
                <div className="relative w-11 h-11 rounded-full bg-brand/20 border border-brand/30 text-brand flex items-center justify-center font-bold text-sm shrink-0">
                  {displayInitials}
                </div>
                <div>
                  <h3 className="text-base font-bold text-textMain leading-tight">
                    {publicName}
                  </h3>
                  <p className="text-xs text-brand font-medium mt-0.5">
                    {liveCandidate.role}
                  </p>
                  <WorkPreferenceTimezoneBadge
                    workPreference={liveCandidate.workPreference}
                    timezone={liveCandidate.timezone}
                    className="mt-2"
                  />
                  <div className="mt-2">
                    <ProductionScoreBadge
                      score={liveCandidate.productionScore}
                      verified={Boolean(liveCandidate.isAuditVerified)}
                    />
                  </div>
                  {(liveCandidate.verifiedOnProvix || isUnlocked) && (
                    <div className="mt-2 flex flex-wrap items-center gap-1.5">
                      <VerifiedOnProvixPill
                        verified={Boolean(liveCandidate.verifiedOnProvix)}
                      />
                      {isUnlocked ? (
                        <span className="inline-flex px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/10 text-emerald-300 border border-emerald-500/20">
                          Introduction unlocked
                        </span>
                      ) : null}
                    </div>
                  )}
                  <span className="inline-flex mt-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold bg-brandGlow text-brand border border-brand/20">
                    {liveCandidate.experienceLevel}
                  </span>
                  <button
                    type="button"
                    onClick={() => onRequestIntro(liveCandidate)}
                    className="mt-2.5 inline-flex items-center gap-1.5 bg-brand hover:bg-brandHover text-white text-[11px] font-bold px-3 py-1.5 rounded-lg transition-all cursor-pointer"
                  >
                    Request Introduction
                  </button>
                </div>
              </div>
              <button
                type="button"
                onClick={onClose}
                className="text-textMuted hover:text-textMain bg-background w-7 h-7 rounded-lg border border-border flex items-center justify-center transition-all cursor-pointer shrink-0"
              >
                <DrawerIcons.XMark />
              </button>
            </div>

            <div className="space-y-2 bg-background/60 px-3.5 py-2.5 rounded-xl border border-border">
              <div className="flex items-start justify-between gap-3 text-xs">
                <span
                  className={`px-2.5 py-1 rounded-full text-[10px] font-bold shrink-0 ${getAvailabilityBadgeClass(
                    liveCandidate.availability
                  )}`}
                >
                  {liveCandidate.availability}
                </span>
                <div className="text-right min-w-0">
                  {liveCandidate.matchPending ? (
                    <span className="font-mono font-bold text-brand animate-pulse">
                      Match Pending
                      {hasScreeningJob && screeningJob?.title
                        ? ` • ${screeningJob.title}`
                        : ""}
                    </span>
                  ) : hasScreeningJob ? (
                    <span className="font-mono font-bold text-emerald-400 leading-snug">
                      {clampScore0to100(liveCandidate.matchScore)}% Role Fit
                      {screeningJob?.title?.trim()
                        ? ` • ${screeningJob.title.trim()}`
                        : ""}
                    </span>
                  ) : (
                    <span className="font-mono font-bold text-emerald-400 leading-snug">
                      Profile & Verification Strength:{" "}
                      {clampScore0to100(liveCandidate.matchScore)}%
                    </span>
                  )}
                </div>
              </div>
              {!liveCandidate.matchPending ? (
                <ScoreMeter score={liveCandidate.matchScore} />
              ) : null}
              {!liveCandidate.matchPending && roleFitInsight.flag ? (
                <div
                  role="status"
                  className="rounded-lg border border-amber-500/25 bg-amber-500/10 px-2.5 py-2"
                >
                  <div className="flex items-start gap-2">
                    <span className="mt-0.5 inline-flex shrink-0 rounded-md border border-amber-500/30 bg-amber-500/15 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider text-amber-300">
                      Flag
                    </span>
                    <p className="min-w-0 text-[11px] leading-snug text-amber-100/90">
                      {roleFitInsight.flag}
                    </p>
                  </div>
                </div>
              ) : null}
              {!liveCandidate.matchPending && roleFitInsight.reasoning ? (
                <p className="text-[11px] leading-relaxed text-textMuted">
                  {roleFitInsight.reasoning}
                </p>
              ) : null}
              {hasScreeningJob && !liveCandidate.matchPending ? (
                roleFitInsight.matching.length > 0 ||
                roleFitInsight.missing.length > 0 ? (
                  <div className="space-y-1.5 pt-0.5">
                    <div className="text-[10px] uppercase font-bold text-textMuted tracking-wider">
                      Job Criteria
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                      {roleFitInsight.matching.map((skill) => (
                        <span
                          key={`match-${skill}`}
                          className="inline-flex px-2 py-0.5 rounded-md text-[10px] font-semibold bg-emerald-500/10 text-emerald-300 border border-emerald-500/20"
                        >
                          {skill}
                        </span>
                      ))}
                      {roleFitInsight.missing.map((skill) => (
                        <span
                          key={`miss-${skill}`}
                          className="inline-flex px-2 py-0.5 rounded-md text-[10px] font-semibold bg-amber-500/10 text-amber-200/90 border border-amber-500/20"
                          title="Missing for this role"
                        >
                          {skill}
                        </span>
                      ))}
                    </div>
                  </div>
                ) : (
                  <span className="text-[10px] text-textMuted pt-0.5">
                    No explicit stack tags on this job yet.
                  </span>
                )
              ) : null}
              {!hasScreeningJob ? (
                <p className="text-[11px] text-textMuted leading-relaxed">
                  Select an active job post to evaluate specific role fit.
                </p>
              ) : null}
            </div>

            <p className="text-sm text-textMuted leading-relaxed">{lockedBio}</p>

            <div>
              <div className="text-[10px] uppercase font-bold text-textMuted tracking-wider mb-2">
                Education & Credentials
              </div>
              <div className="bg-background border border-border rounded-xl p-3.5 text-xs text-textMain space-y-2">
                <CandidateEducationSummary
                  isSelfTaught={liveCandidate.isSelfTaught}
                  university={liveCandidate.university}
                  major={liveCandidate.major}
                  gpa={liveCandidate.gpa}
                  graduationYear={liveCandidate.graduationYear}
                />
              </div>
            </div>

            <div>
              <div className="text-[10px] uppercase font-bold text-textMuted tracking-wider mb-2">
                Core Skills
              </div>
              <div className="flex flex-wrap gap-1.5">
                {liveCandidate.skills.map((skill, sIdx) => (
                  <span
                    key={sIdx}
                    className="px-2 py-1 rounded-md text-[10px] font-bold bg-panel/80 text-textMuted border border-border/50"
                  >
                    {skill}
                  </span>
                ))}
              </div>
            </div>

            <div>
              <div className="text-[10px] uppercase font-bold text-textMuted tracking-wider mb-2">
                Contact & Proof Links
              </div>
              {isUnlocked ? (
                <div className="space-y-2">
                  {contactEmail && (
                    <a
                      href={`mailto:${contactEmail}`}
                      className="w-full flex items-center justify-between bg-background border border-border rounded-xl px-3.5 py-2.5 text-xs hover:border-brand/40 transition-all"
                    >
                      <span className="text-brand font-medium">Email</span>
                      <span className="text-textMuted break-all text-right ml-3 font-mono">
                        {contactEmail}
                      </span>
                    </a>
                  )}
                  {contactPhone && (
                    <div className="w-full flex items-center justify-between bg-background border border-border rounded-xl px-3.5 py-2.5 text-xs">
                      <span className="text-brand font-medium">Phone</span>
                      <span className="text-textMuted font-mono">{contactPhone}</span>
                    </div>
                  )}
                  {projectLinks.length === 0 ? (
                    <p className="text-xs text-textMuted italic bg-background border border-border rounded-xl px-3.5 py-2.5">
                      No public project links provided.
                    </p>
                  ) : (
                    projectLinks.map((link) => (
                      <a
                        key={`${link.label}-${link.url}`}
                        href={link.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="w-full flex items-center justify-between bg-background border border-border rounded-xl px-3.5 py-2.5 text-xs hover:border-brand/40 transition-all"
                      >
                        <span className="text-brand font-medium">
                          {link.label}
                        </span>
                        <DrawerIcons.ExternalLink />
                      </a>
                    ))
                  )}
                </div>
              ) : (
                <LockedContactDossierBadge />
              )}
            </div>

            <ProductionCodeAuditSection
              record={productionAuditRecordFromCandidate(liveCandidate)}
            />

            <GeminiDeepScreening
              key={buildDeepScreeningCacheKey(liveCandidate, screeningJob)}
              candidate={liveCandidate}
              publicName={publicName}
              lockedBio={lockedBio}
              screeningJob={screeningJob}
              companyName={companyName}
              requireAuth={requireAuth}
              onToast={onToast}
            />

            <div>
              <div className="text-[10px] uppercase font-bold text-textMuted tracking-wider mb-2">
                Audited Proof-of-Work Breakdown
              </div>
              <ul className="space-y-2">
                {liveCandidate.projects.map((project, pIdx) => (
                  <li
                    key={pIdx}
                    className="text-xs text-textMuted leading-relaxed bg-background border border-border rounded-xl p-3.5"
                  >
                    {project}
                  </li>
                ))}
              </ul>
            </div>

            <button
              type="button"
              onClick={() => onRequestIntro(liveCandidate)}
              className="w-full bg-brand hover:bg-brandHover text-white font-bold py-3.5 rounded-xl text-xs transition-all flex items-center justify-center gap-2 cursor-pointer"
            >
              Request Introduction
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { Loader2 } from "lucide-react";
import CandidateIntelligenceDrawer from "@/components/employer/candidate-intelligence-drawer";
import ProductionScoreBadge from "@/components/employer/production-score-badge";
import ScoreMeter from "@/components/ScoreMeter";
import VerifiedOnProvixPill from "@/components/VerifiedOnProvixPill";
import { fetchWithAuth } from "@/lib/fetch-with-auth";
import { readJsonResponse } from "@/lib/read-json-response";
import {
  APPLICANT_PIPELINE_STATUSES,
  applicantStatusClass,
  applicantStatusLabel,
  getFitVerdictBadgeClass,
  mapApplicantToTalentCandidate,
  type EmployerApplicantView,
  type EmployerApplicantsPayload,
} from "@/lib/job-applicants";
import CandidateEducationSummary from "@/components/CandidateEducationSummary";
import { subscribeIncomingJobInterest } from "@/lib/job-interest";
import { createClient } from "@/utils/supabase/client";

type EmployerApplicantsSectionProps = {
  userId: string | null;
  focusJobId?: string | null;
  onClearFocusJob?: () => void;
  onRequestIntro: (applicant: EmployerApplicantView) => void;
  requireAuth?: () => boolean;
  onToast?: (message: string) => void;
  companyName?: string;
};

export default function EmployerApplicantsSection({
  userId,
  focusJobId = null,
  onClearFocusJob,
  onRequestIntro,
  requireAuth,
  onToast,
  companyName,
}: EmployerApplicantsSectionProps) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [applicants, setApplicants] = useState<EmployerApplicantView[]>([]);
  const [jobs, setJobs] = useState<EmployerApplicantsPayload["jobs"]>([]);
  const [jobFilter, setJobFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [rejectingId, setRejectingId] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [selectedApplicant, setSelectedApplicant] =
    useState<EmployerApplicantView | null>(null);

  const loadApplicants = useCallback(async () => {
    if (!userId) {
      setApplicants([]);
      setJobs([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const response = await fetchWithAuth("/api/employer/applicants");
      const payload = (await readJsonResponse(response).catch(() => null)) as
        | (EmployerApplicantsPayload & { error?: string })
        | null;

      if (!response.ok || !payload || payload.error) {
        throw new Error(payload?.error ?? "Could not load interested candidates.");
      }

      setApplicants(payload.applicants ?? []);
      setJobs(payload.jobs ?? []);
      setActionError(null);
    } catch (loadError) {
      console.error("Failed to load employer applicants:", loadError);
      setError("Could not load interested candidates. Please try again.");
      setApplicants([]);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    void loadApplicants();
  }, [loadApplicants]);

  useEffect(() => {
    if (!userId) {
      return;
    }

    const supabase = createClient();
    return subscribeIncomingJobInterest(supabase, userId, () => {
      void loadApplicants();
    });
  }, [userId, loadApplicants]);

  const rejectApplicant = useCallback(async (applicant: EmployerApplicantView) => {
    if (applicant.status === "rejected" || rejectingId) {
      return;
    }

    setRejectingId(applicant.applicationId);
    setActionError(null);

    try {
      const response = await fetchWithAuth("/api/employer/applicants", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          applicationId: applicant.applicationId,
          status: "rejected",
        }),
      });
      const payload = (await readJsonResponse(response).catch(() => null)) as {
        ok?: boolean;
        error?: string;
      } | null;

      if (!response.ok || !payload?.ok) {
        throw new Error(payload?.error ?? "Could not reject this candidate.");
      }

      setApplicants((current) =>
        current.map((row) =>
          row.applicationId === applicant.applicationId
            ? { ...row, status: "rejected" }
            : row
        )
      );
    } catch (rejectError) {
      console.error("Failed to reject applicant:", rejectError);
      setActionError("Could not reject this candidate. Please try again.");
    } finally {
      setRejectingId(null);
    }
  }, [rejectingId]);

  useEffect(() => {
    if (focusJobId) {
      setJobFilter(focusJobId);
    }
  }, [focusJobId]);

  const visibleApplicants = useMemo(() => {
    return applicants.filter((applicant) => {
      const matchesJob =
        jobFilter === "all" || applicant.jobId === jobFilter;
      const matchesStatus =
        statusFilter === "all" || applicant.status === statusFilter;
      return matchesJob && matchesStatus;
    });
  }, [applicants, jobFilter, statusFilter]);

  const newCount = applicants.filter((row) => row.status === "new").length;

  const selectedTalentCandidate = selectedApplicant
    ? mapApplicantToTalentCandidate(selectedApplicant)
    : null;

  const openApplicantIntelligence = (applicant: EmployerApplicantView) => {
    setSelectedApplicant(applicant);
  };

  useEffect(() => {
    if (!selectedApplicant) {
      return;
    }

    const latest = applicants.find(
      (row) => row.applicationId === selectedApplicant.applicationId
    );
    if (!latest) {
      setSelectedApplicant(null);
      return;
    }
    if (latest !== selectedApplicant) {
      setSelectedApplicant(latest);
    }
  }, [applicants, selectedApplicant]);

  return (
    <div>
      <div className="mb-8">
        <p className="text-xs font-bold uppercase tracking-widest text-brand mb-2">
          Hiring Pipeline
        </p>
        <h1 className="text-3xl font-extrabold tracking-tight text-textMain">
          Interested Candidates
        </h1>
        <p className="mt-2 max-w-2xl text-sm text-zinc-400">
          Developers who expressed interest in your open roles.
        </p>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-3 gap-4 mb-6">
        <div className="card-edge bg-panel p-5 rounded-2xl border border-border">
          <span className="text-[11px] font-bold text-textMuted uppercase tracking-widest block mb-1">
            Total interest
          </span>
          <span className="text-3xl font-mono font-extrabold tabular-nums text-textMain">
            {applicants.length}
          </span>
        </div>
        <div className="card-edge bg-panel p-5 rounded-2xl border border-border">
          <span className="text-[11px] font-bold text-textMuted uppercase tracking-widest block mb-1">
            New to review
          </span>
          <span className="text-3xl font-mono font-extrabold tabular-nums text-violet-300">
            {newCount}
          </span>
        </div>
        <div className="card-edge bg-panel p-5 rounded-2xl border border-border col-span-2 lg:col-span-1">
          <span className="text-[11px] font-bold text-textMuted uppercase tracking-widest block mb-1">
            Roles with interest
          </span>
          <span className="text-3xl font-mono font-extrabold tabular-nums text-brand">
            {new Set(applicants.map((row) => row.jobId)).size}
          </span>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row gap-3 mb-6">
        <label className="sr-only" htmlFor="applicant-job-filter">
          Filter by job
        </label>
        <select
          id="applicant-job-filter"
          value={jobFilter}
          onChange={(event) => {
            setJobFilter(event.target.value);
            if (focusJobId && event.target.value !== focusJobId) {
              onClearFocusJob?.();
            }
          }}
          className="flex-1 bg-panel border border-border rounded-xl px-3 py-2.5 text-sm text-textMain focus:outline-none focus:border-brand"
        >
          <option value="all">All listings</option>
          {jobs.map((job) => (
            <option key={job.id} value={job.id}>
              {job.title}
            </option>
          ))}
        </select>
        <label className="sr-only" htmlFor="applicant-status-filter">
          Filter by status
        </label>
        <select
          id="applicant-status-filter"
          value={statusFilter}
          onChange={(event) => setStatusFilter(event.target.value)}
          className="sm:w-52 bg-panel border border-border rounded-xl px-3 py-2.5 text-sm text-textMain focus:outline-none focus:border-brand"
        >
          <option value="all">All statuses</option>
          {APPLICANT_PIPELINE_STATUSES.map((status) => (
            <option key={status.value} value={status.value}>
              {status.label}
            </option>
          ))}
        </select>
      </div>

      {loading ? (
        <div className="flex items-center justify-center gap-3 py-20 text-sm text-textMuted">
          <Loader2 className="w-5 h-5 animate-spin text-brand" />
          Loading interested candidates...
        </div>
      ) : error ? (
        <div className="rounded-2xl border border-red-500/20 bg-red-500/5 px-4 py-4 text-sm text-red-300">
          {error}
        </div>
      ) : visibleApplicants.length === 0 ? (
        <div className="rounded-2xl border border-border bg-panel px-6 py-14 text-center">
          <p className="text-sm text-textMuted font-medium">
            {applicants.length === 0
              ? "No candidates have expressed interest yet."
              : "No candidates match these filters."}
          </p>
          <p className="text-xs text-textMuted mt-2">
            {applicants.length === 0
              ? "When someone taps Express Interest on one of your listings, they will appear here."
              : "Try another listing or status to keep reviewing your pipeline."}
          </p>
        </div>
      ) : (
        <>
          {actionError ? (
            <div className="mb-4 rounded-xl border border-rose-500/20 bg-rose-500/5 px-4 py-3 text-sm text-rose-300">
              {actionError}
            </div>
          ) : null}
          <ul className="space-y-4">
          {visibleApplicants.map((applicant) => (
            <li key={applicant.applicationId}>
              <div
                role="button"
                tabIndex={0}
                onClick={() => openApplicantIntelligence(applicant)}
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    openApplicantIntelligence(applicant);
                  }
                }}
                className="card-edge rounded-2xl border border-border bg-panel p-5 cursor-pointer hover:border-brand/40 transition-colors"
              >
              <div className="flex flex-col lg:flex-row lg:items-start gap-5">
                <div className="flex items-start gap-3 min-w-0 flex-1">
                  <div className="w-11 h-11 rounded-full bg-brand/20 border border-brand/30 flex items-center justify-center text-xs font-bold text-brand shrink-0">
                    {applicant.initials}
                  </div>
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2 min-w-0">
                      <h2 className="font-bold text-textMain text-sm truncate">
                        {applicant.codenameAlias}
                      </h2>
                      <ProductionScoreBadge
                        score={applicant.productionScore}
                        verified={Boolean(applicant.isAuditVerified)}
                      />
                      <span
                        className={`inline-flex shrink-0 px-2 py-0.5 rounded-full text-[10px] font-bold border ${applicantStatusClass(applicant.status)}`}
                      >
                        {applicantStatusLabel(applicant.status)}
                      </span>
                      <VerifiedOnProvixPill
                        verified={applicant.verifiedOnProvix}
                      />
                    </div>
                    <p className="text-xs text-brand font-medium mt-0.5 truncate">
                      {applicant.headline}
                    </p>
                    <p className="text-[11px] text-textMuted mt-1">
                      {applicant.location}
                      {applicant.experienceLevel
                        ? ` · ${applicant.experienceLevel}`
                        : ""}
                    </p>
                    <p className="text-[11px] text-textMuted mt-2">
                      Interested in{" "}
                      <span className="text-textMain font-medium">
                        {applicant.jobTitle}
                      </span>
                      <span className="text-textMuted">
                        {" "}
                        · {applicant.appliedAtLabel}
                      </span>
                    </p>
                  </div>
                </div>

                <div className="shrink-0 rounded-xl border border-border bg-background px-4 py-3 lg:w-52">
                  <div className="flex items-center justify-between gap-2 mb-1">
                    <span className="text-[10px] font-bold uppercase tracking-widest text-textMuted">
                      AI Match
                    </span>
                    <span
                      className={`px-2 py-0.5 rounded-full text-[10px] font-extrabold border ${getFitVerdictBadgeClass(applicant.fitVerdict)}`}
                    >
                      {applicant.fitVerdict}
                    </span>
                  </div>
                  <p className="font-mono text-lg font-extrabold tabular-nums text-textMain">
                    {applicant.matchScore}%
                  </p>
                  <ScoreMeter score={applicant.matchScore} className="mt-2" />
                </div>
              </div>

              <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <span className="text-[10px] font-bold text-textMuted uppercase tracking-widest block mb-2">
                    Education
                  </span>
                  <div className="rounded-xl border border-border bg-background p-3.5 text-xs text-textMain space-y-2">
                    <CandidateEducationSummary
                      isSelfTaught={applicant.isSelfTaught}
                      university={applicant.university}
                      major={applicant.major}
                      gpa={applicant.gpa}
                      graduationYear={applicant.graduationYear}
                    />
                  </div>
                </div>

                <div>
                  <span className="text-[10px] font-bold text-textMuted uppercase tracking-widest block mb-2">
                    AI Match Analysis
                  </span>
                  <div className="rounded-xl border border-border bg-background p-3.5 text-xs text-textMain space-y-2">
                    {applicant.matchReasoning ? (
                      <p className="text-textMuted leading-relaxed">
                        {applicant.matchReasoning}
                      </p>
                    ) : null}
                    {applicant.matchingSkills.length > 0 ? (
                      <p>
                        <span className="text-emerald-400/90 font-medium">Overlap: </span>
                        {applicant.matchingSkills.join(", ")}
                      </p>
                    ) : null}
                    {applicant.missingSkills.length > 0 ? (
                      <p>
                        <span className="text-violet-300/90 font-medium">Gaps: </span>
                        {applicant.missingSkills.join(", ")}
                      </p>
                    ) : null}
                    {applicant.skills.length > 0 ? (
                      <div className="flex flex-wrap gap-1.5 pt-1">
                        {applicant.skills.slice(0, 6).map((skill) => (
                          <span
                            key={skill}
                            className="px-2 py-1 rounded-md text-[10px] font-bold bg-panel/80 text-textMuted border border-border/50"
                          >
                            {skill}
                          </span>
                        ))}
                      </div>
                    ) : null}
                  </div>
                </div>
              </div>

              {applicant.unlocked ? (
                <div className="mt-4 rounded-xl border border-emerald-500/20 bg-emerald-500/5 p-4 space-y-1.5">
                  <span className="text-[10px] font-bold text-emerald-300 uppercase tracking-widest block">
                    Contact Information
                  </span>
                  {applicant.email ? (
                    <a
                      href={`mailto:${applicant.email}`}
                      onClick={(event) => event.stopPropagation()}
                      className="block text-xs text-textMain hover:text-textMain break-all"
                    >
                      {applicant.email}
                    </a>
                  ) : (
                    <p className="text-xs text-textMuted">No email on file.</p>
                  )}
                  {applicant.phone ? (
                    <p className="text-xs text-textMain">{applicant.phone}</p>
                  ) : null}
                </div>
              ) : null}

              <div className="mt-4 flex items-center justify-end gap-2">
                {applicant.status === "rejected" ? (
                  <span className="text-[11px] font-bold text-rose-300">
                    Rejected
                  </span>
                ) : (
                  <>
                    <button
                      type="button"
                      onClick={(event) => {
                        event.stopPropagation();
                        onRequestIntro(applicant);
                      }}
                      className="text-[11px] font-bold px-3.5 py-2 rounded-lg bg-brand hover:bg-brandHover text-white transition-all cursor-pointer"
                    >
                      Request Intro
                    </button>
                    <button
                      type="button"
                      onClick={(event) => {
                        event.stopPropagation();
                        void rejectApplicant(applicant);
                      }}
                      disabled={rejectingId === applicant.applicationId}
                      className="text-[11px] font-bold px-3.5 py-2 rounded-lg border border-rose-500/30 bg-rose-500/10 hover:bg-rose-500/20 text-rose-200 transition-all cursor-pointer disabled:opacity-60 disabled:cursor-wait"
                    >
                      {rejectingId === applicant.applicationId ? (
                        <span className="inline-flex items-center gap-1.5">
                          <Loader2 className="w-3.5 h-3.5 animate-spin" />
                          Rejecting
                        </span>
                      ) : (
                        "Reject"
                      )}
                    </button>
                  </>
                )}
              </div>
              </div>
            </li>
          ))}
          </ul>
        </>
      )}

      <CandidateIntelligenceDrawer
        candidate={selectedTalentCandidate}
        open={selectedApplicant !== null}
        isUnlocked={Boolean(selectedApplicant?.unlocked)}
        onClose={() => setSelectedApplicant(null)}
        onRequestIntro={() => {
          if (selectedApplicant) {
            onRequestIntro(selectedApplicant);
          }
        }}
        screeningJob={
          selectedApplicant
            ? {
                title: selectedApplicant.jobTitle,
                tags: selectedApplicant.skills.slice(0, 8),
                required_skills: [
                  ...selectedApplicant.matchingSkills,
                  ...selectedApplicant.missingSkills,
                ].slice(0, 8),
                tech_stack: selectedApplicant.matchingSkills,
              }
            : null
        }
        companyName={companyName}
        requireAuth={requireAuth}
        onToast={onToast}
      />
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState, type FormEvent } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Loader2, Trash2, X } from "lucide-react";
import Toast from "@/components/Toast";
import { useDashboardNav } from "@/components/dashboard/dashboard-nav-context";
import { CANDIDATE_DASHBOARD_PATH } from "@/lib/account-role";
import { isMissingCompanyName } from "@/lib/company-name";
import {
  JOB_CONTRACT_BANDWIDTH_OPTIONS,
  normalizeContractHoursPerWeek,
  type ContractHoursPerWeek,
} from "@/lib/contract-availability";
import { dashboardTabHref } from "@/lib/dashboard-account";
import { formatSalaryRange } from "@/lib/format-salary-range";
import {
  employmentTypeFromJobType,
  fetchDashboardJobs,
  jobDisplayTags,
  parseJobListInput,
  type JobEngagementType,
  type JobRow,
} from "@/lib/jobs";
import { readJsonResponse } from "@/lib/read-json-response";
import { isSupabaseSchemaError } from "@/lib/supabase-schema-errors";
import { createClient } from "@/utils/supabase/client";

type ListingRow = {
  id: string;
  title: string;
  company: string | null;
  location: string | null;
  employmentType: string | null;
  applicants: number;
  status: "Active" | "Paused";
};

function toListing(job: JobRow, applicants: number): ListingRow {
  return {
    id: job.id,
    title: job.title?.trim() || "Untitled Role",
    company: job.company,
    location: job.location,
    employmentType: job.employment_type ?? null,
    applicants,
    status: job.status === "paused" ? "Paused" : "Active",
  };
}

export default function EmployerJobPostings() {
  const router = useRouter();
  const {
    accountRole,
    authLoading,
    companyName,
    isBusinessAccount,
    isVerifiedEmployer,
    userId,
  } = useDashboardNav();

  const rolePending = authLoading || (userId != null && accountRole == null);
  const companyForNewJob = isMissingCompanyName(companyName)
    ? ""
    : (companyName ?? "").trim();

  const [jobs, setJobs] = useState<JobRow[]>([]);
  const [interestCounts, setInterestCounts] = useState<Record<string, number>>(
    {}
  );
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [postOpen, setPostOpen] = useState(false);
  const [isCreatingJob, setIsCreatingJob] = useState(false);
  const [engagementType, setEngagementType] =
    useState<JobEngagementType>("full_time");
  const [title, setTitle] = useState("");
  const [company, setCompany] = useState("");
  const [location, setLocation] = useState("");
  const [salaryRange, setSalaryRange] = useState("");
  const [contractHours, setContractHours] = useState<ContractHoursPerWeek | "">(
    ""
  );
  const [hourlyRateRange, setHourlyRateRange] = useState("");
  const [requiredSkills, setRequiredSkills] = useState("");
  const [techStack, setTechStack] = useState("");

  const showToast = (message: string) => {
    setToastMessage(message);
    window.setTimeout(() => {
      setToastMessage((current) => (current === message ? null : current));
    }, 3200);
  };

  const resetForm = useCallback(() => {
    setEngagementType("full_time");
    setTitle("");
    setCompany(companyForNewJob);
    setLocation("");
    setSalaryRange("");
    setContractHours("");
    setHourlyRateRange("");
    setRequiredSkills("");
    setTechStack("");
  }, [companyForNewJob]);

  useEffect(() => {
    if (rolePending) {
      return;
    }
    if (!isBusinessAccount) {
      router.replace(CANDIDATE_DASHBOARD_PATH);
    }
  }, [isBusinessAccount, rolePending, router]);

  const loadListings = useCallback(async () => {
    if (!userId) {
      setJobs([]);
      setInterestCounts({});
      setLoading(false);
      return;
    }

    setLoading(true);
    setLoadError(null);
    const supabase = createClient();

    try {
      const { data, error } = await fetchDashboardJobs(supabase);
      if (error) {
        throw new Error(error.message);
      }

      const owned = data.filter((job) => job.employer_id === userId);
      setJobs(owned);

      if (owned.length === 0) {
        setInterestCounts({});
        return;
      }

      const { data: applications, error: interestError } = await supabase
        .from("job_applications")
        .select("job_id")
        .in(
          "job_id",
          owned.map((job) => job.id)
        );

      if (interestError) {
        console.error("Failed to fetch job interest counts:", interestError);
        return;
      }

      const counts: Record<string, number> = {};
      for (const row of applications ?? []) {
        const jobId = row.job_id;
        if (typeof jobId !== "string") {
          continue;
        }
        counts[jobId] = (counts[jobId] ?? 0) + 1;
      }
      setInterestCounts(counts);
    } catch (error) {
      console.error("Failed to load employer jobs:", error);
      setJobs([]);
      setLoadError("Could not load your job postings. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    if (rolePending || !isBusinessAccount) {
      return;
    }
    void loadListings();
  }, [isBusinessAccount, loadListings, rolePending]);

  const listings = jobs.map((job) =>
    toListing(job, interestCounts[job.id] ?? 0)
  );

  const openPostJob = () => {
    if (!isVerifiedEmployer) {
      showToast(
        "Confirm your work email from Get Verified to unlock job posting."
      );
      router.push("/dashboard?tab=my_profile");
      return;
    }
    setCompany(companyForNewJob);
    setPostOpen(true);
  };

  const toggleStatus = async (listing: ListingRow) => {
    const nextStatus = listing.status === "Active" ? "paused" : "active";
    const previous = jobs;
    setJobs((current) =>
      current.map((job) =>
        job.id === listing.id ? { ...job, status: nextStatus } : job
      )
    );

    try {
      const response = await fetch(`/api/jobs/${listing.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: nextStatus }),
      });
      const payload = (await readJsonResponse(response)) as {
        error?: string;
        job?: JobRow;
      };
      if (!response.ok) {
        throw new Error(payload.error ?? "Could not update listing status.");
      }
      if (payload.job) {
        setJobs((current) =>
          current.map((job) =>
            job.id === listing.id ? { ...job, ...payload.job } : job
          )
        );
      }
      showToast(
        nextStatus === "paused"
          ? "Listing deactivated. It is hidden from other accounts."
          : "Listing reactivated."
      );
    } catch (error) {
      console.error("Job status update failed:", error);
      setJobs(previous);
      showToast("Could not update listing status. Please try again.");
    }
  };

  const deleteListing = async (listing: ListingRow) => {
    if (deletingId) {
      return;
    }
    const confirmed = window.confirm(
      `Delete "${listing.title}"? This cannot be undone.`
    );
    if (!confirmed) {
      return;
    }

    const previous = jobs;
    setDeletingId(listing.id);
    setJobs((current) => current.filter((job) => job.id !== listing.id));

    try {
      const response = await fetch(`/api/jobs/${listing.id}`, {
        method: "DELETE",
      });
      const payload = (await readJsonResponse(response)) as { error?: string };
      if (!response.ok) {
        throw new Error(payload.error ?? "Could not delete listing.");
      }
      showToast("Listing deleted.");
    } catch (error) {
      console.error("Job delete failed:", error);
      setJobs(previous);
      showToast("Could not delete listing. Please try again.");
    } finally {
      setDeletingId(null);
    }
  };

  const handleCreateJob = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!userId || isCreatingJob) {
      return;
    }
    if (!isVerifiedEmployer) {
      showToast(
        "Confirm your work email from Get Verified before posting jobs."
      );
      return;
    }
    if (!title.trim()) {
      showToast("Job title is required.");
      return;
    }
    if (!company.trim()) {
      showToast("Company name is required.");
      return;
    }

    const isContractJob = engagementType === "contract";
    const normalizedContractHours = isContractJob
      ? normalizeContractHoursPerWeek(contractHours)
      : "";
    const hourlyRate = hourlyRateRange.trim();

    if (isContractJob) {
      if (!normalizedContractHours) {
        showToast("Select a weekly bandwidth for contract sprints.");
        return;
      }
      if (!hourlyRate) {
        showToast("Target hourly rate is required for contract sprints.");
        return;
      }
    } else if (!location.trim()) {
      showToast("Location is required.");
      return;
    } else if (!salaryRange.trim()) {
      showToast("Salary range is required.");
      return;
    }

    const skills = parseJobListInput(requiredSkills);
    const stack = parseJobListInput(techStack);
    if (skills.length === 0) {
      showToast("Add at least one required skill.");
      return;
    }

    setIsCreatingJob(true);
    const supabase = createClient();
    const employmentType = employmentTypeFromJobType(engagementType);
    const dbPayload = {
      title: title.trim(),
      company: company.trim(),
      location: isContractJob ? "Remote" : location.trim(),
      salary_range: isContractJob ? hourlyRate : formatSalaryRange(salaryRange.trim()),
      tags: jobDisplayTags({
        tech_stack: stack,
        required_skills: skills,
      }),
      tech_stack: stack.length > 0 ? stack : null,
      required_skills: skills,
      employer_id: userId,
      employment_type: employmentType,
      contract_hours_per_week: isContractJob ? normalizedContractHours : null,
      hourly_rate_range: isContractJob ? hourlyRate : null,
    };

    try {
      let { data, error } = await supabase
        .from("jobs")
        .insert(dbPayload)
        .select("*")
        .single();

      if (error && isSupabaseSchemaError(error)) {
        const {
          contract_hours_per_week: _hours,
          hourly_rate_range: _rate,
          ...withoutContractFields
        } = dbPayload;
        const retry = await supabase
          .from("jobs")
          .insert(withoutContractFields)
          .select("*")
          .single();
        data = retry.data;
        error = retry.error;
      }

      if (error && isSupabaseSchemaError(error)) {
        const fallback = await supabase
          .from("jobs")
          .insert({
            title: dbPayload.title,
            company: dbPayload.company,
            location: dbPayload.location,
            salary_range: dbPayload.salary_range,
            tags: dbPayload.tags,
            employer_id: dbPayload.employer_id,
          })
          .select("*")
          .single();
        data = fallback.data;
        error = fallback.error;
      }

      if (error || !data) {
        console.error("Create job error:", error);
        showToast("Could not post job. Please try again.");
        return;
      }

      setJobs((current) => [data as JobRow, ...current]);
      setPostOpen(false);
      resetForm();
      showToast("Job posted successfully!");
    } catch (error) {
      console.error("Create job error:", error);
      showToast("Could not post job. Please try again.");
    } finally {
      setIsCreatingJob(false);
    }
  };

  if (rolePending || !isBusinessAccount) {
    return (
      <div className="flex min-h-[240px] items-center justify-center text-sm text-textMuted">
