"use client";

import { useMemo, useState } from "react";
import { Check, LoaderCircle, Search, Sparkles } from "lucide-react";
import { formatJobCompensation } from "@/lib/format-salary-range";
import {
  jobDisplayTags,
  jobMatchesWorkType,
  type JobRow,
  type JobWorkType,
} from "@/lib/jobs";
import {
  countActiveOpenings,
  countJobsMatchingCandidateSkills,
  getActiveJobs,
} from "@/lib/opportunities-metrics";
import {
  getFitVerdictBadgeClass,
  splitCandidateMatchReason,
  type OpportunityMatchResult,
} from "@/lib/opportunity-match";
import { clampScore0to100 } from "@/lib/score-scale";
import ScoreMeter from "@/components/ScoreMeter";
import Button from "@/components/ui/Button";
import FormLabel from "@/components/ui/FormLabel";
import PageHeader from "@/components/ui/PageHeader";

export type OpportunitiesJobFeedProps = {
  jobs: JobRow[];
  jobsLoading: boolean;
  jobsError?: string | null;
  isGuest: boolean;
  appliedJobIds: string[];
  onExpressInterest: (job: JobRow) => void;
  matchInsights?: Record<string, OpportunityMatchResult>;
  matchLoadingIds?: Record<string, boolean>;
  candidateSkills?: string[];
  profileVisibleToEmployers?: boolean;
  loadingProfile?: boolean;
  enableAiMatch?: boolean;
  aiMatchRunning?: boolean;
  aiMatchError?: string | null;
  onRunAiMatch?: (options?: { workType?: JobWorkType }) => void;
};

export default function OpportunitiesJobFeed({
  jobs,
  jobsLoading,
  jobsError = null,
  isGuest,
  appliedJobIds,
  onExpressInterest,
  matchInsights = {},
  matchLoadingIds = {},
  candidateSkills = [],
  profileVisibleToEmployers = false,
  loadingProfile = false,
  enableAiMatch = false,
  aiMatchRunning = false,
  aiMatchError = null,
  onRunAiMatch,
}: OpportunitiesJobFeedProps) {
  const [search, setSearch] = useState("");
  const [remoteOnly, setRemoteOnly] = useState(false);
  const [workType, setWorkType] = useState<JobWorkType>("fulltime");
  const [expandedJobId, setExpandedJobId] = useState<string | null>(null);

  const activeJobs = useMemo(() => getActiveJobs(jobs), [jobs]);
  const activeOpeningsCount = useMemo(
    () => countActiveOpenings(jobs),
    [jobs]
  );
  const skillMatchingJobsCount = useMemo(
    () => countJobsMatchingCandidateSkills(jobs, candidateSkills),
    [jobs, candidateSkills]
  );

  const hasAiMatchResults = Object.keys(matchInsights).length > 0;
  const canRunAiMatch =
    enableAiMatch &&
    !jobsLoading &&
    activeJobs.length > 0 &&
    !aiMatchRunning &&
    (isGuest || !loadingProfile);
  const workTypeEmptyMessage =
    workType === "contract"
      ? "No active contract openings right now"
      : "No active full-time openings right now";

  const filteredJobFeed = useMemo(() => {
    const query = search.trim().toLowerCase();

    const filtered = activeJobs.filter((job) => {
      const tags = jobDisplayTags(job);
      const matchesSearch =
        !query ||
        (job.title ?? "").toLowerCase().includes(query) ||
        (job.company ?? "").toLowerCase().includes(query) ||
        tags.some((tag) => tag.toLowerCase().includes(query));
      const matchesRemote =
        !remoteOnly || (job.location ?? "").toLowerCase().includes("remote");
      const matchesWorkType = jobMatchesWorkType(job, workType);

      return matchesSearch && matchesRemote && matchesWorkType;
    });

    if (!hasAiMatchResults) {
      return filtered;
    }

    return [...filtered].sort((left, right) => {
      const leftScore = clampScore0to100(
        matchInsights[left.id]?.match_score ?? 0
      );
      const rightScore = clampScore0to100(
        matchInsights[right.id]?.match_score ?? 0
      );
      return rightScore - leftScore;
    });
  }, [
    activeJobs,
    hasAiMatchResults,
    matchInsights,
    remoteOnly,
    search,
    workType,
  ]);

  return (
    <div className="text-zinc-100">
      <div className="mb-8">
        <PageHeader
          className="mb-0"
          eyebrow="Talent Network"
          title="Provix Talent Network"
          description={
            isGuest
              ? "Browse openings, companies, and requirements. Sign in when you are ready to express interest."
              : "Open roles matched to your verified stack. Connect directly with hiring teams."
          }
        />
        {enableAiMatch ? (
          <div className="mt-5">
            <Button
              type="button"
              onClick={() => onRunAiMatch?.({ workType })}
              disabled={!canRunAiMatch}
            >
              {aiMatchRunning ? (
                <LoaderCircle
                  className="h-3.5 w-3.5 animate-spin"
                  aria-hidden="true"
                />
              ) : (
                <Sparkles className="h-3.5 w-3.5" aria-hidden="true" />
              )}
              {aiMatchRunning
                ? `Matching ${workType === "contract" ? "contract" : "full-time"} roles…`
                : hasAiMatchResults
                  ? "Re-run Provix AI Match"
                  : "Run Provix AI Match"}
            </Button>
            {aiMatchRunning ? (
              <p className="mt-2 text-xs leading-relaxed text-zinc-400">
                Scoring your audited skills against active listings. This can
                take a few seconds.
              </p>
            ) : null}
            {aiMatchError ? (
              <p className="text-xs text-rose-400 mt-2">{aiMatchError}</p>
            ) : null}
          </div>
        ) : null}
      </div>

      <div
        className={`grid grid-cols-1 gap-4 mb-8 ${
 isGuest ? "sm:grid-cols-2" : "sm:grid-cols-3"
 }`}
      >
        <div className="rounded-xl border border-white/[0.08] bg-zinc-900/50 p-5 shadow-xl backdrop-blur-md">
          <span className="mb-2 block font-mono text-[11px] uppercase tracking-wider text-zinc-400">
            Active Openings
          </span>
          <span
            className={`font-mono text-2xl font-bold ${
              !jobsLoading && activeOpeningsCount > 0
                ? "text-violet-400"
                : "text-zinc-100"
            }`}
          >
            {jobsLoading ? "—" : activeOpeningsCount}
          </span>
          {!jobsLoading && activeOpeningsCount === 0 ? (
            <p className="mt-2 text-xs leading-relaxed text-zinc-400">
              New roles are added regularly. Keep your profile updated to match
              with hiring founders.
            </p>
          ) : null}
        </div>
        {isGuest ? (
          <div className="rounded-xl border border-white/[0.08] bg-zinc-900/50 p-5 shadow-xl backdrop-blur-md">
            <span className="mb-2 block font-mono text-[11px] uppercase tracking-wider text-zinc-400">
              Apply
            </span>
            <span className="font-mono text-sm font-bold text-violet-300">
              Sign in to get matched
            </span>
          </div>
        ) : (
          <>
            <div className="rounded-xl border border-white/[0.08] bg-zinc-900/50 p-5 shadow-xl backdrop-blur-md">
              <span className="mb-2 block font-mono text-[11px] uppercase tracking-wider text-zinc-400">
                Matching Your Skills
              </span>
              <span
                className={`font-mono text-2xl font-bold ${
                  !jobsLoading && skillMatchingJobsCount > 0
                    ? "text-violet-400"
                    : "text-zinc-100"
                }`}
              >
                {jobsLoading ? "—" : skillMatchingJobsCount}
              </span>
            </div>
            <div className="rounded-xl border border-white/[0.08] bg-zinc-900/50 p-5 shadow-xl backdrop-blur-md">
              <span className="mb-2 block font-mono text-[11px] uppercase tracking-wider text-zinc-400">
                Profile Visibility
              </span>
              <span
                className={`font-mono text-sm font-bold ${
                  profileVisibleToEmployers ? "text-emerald-400" : "text-zinc-400"
                }`}
              >
                {loadingProfile
                  ? "—"
                  : profileVisibleToEmployers
                    ? "Active"
                    : "Hidden"}
              </span>
            </div>
          </>
        )}
      </div>

      <div className="mb-6 rounded-xl border border-white/[0.08] bg-zinc-900/50 p-4 shadow-xl backdrop-blur-md">
        <div className="mb-4">
          <p className="mb-2 font-mono text-[11px] uppercase tracking-wider text-zinc-500">
            View
          </p>
          <div
            role="tablist"
            aria-label="Work type"
            className="inline-flex rounded-lg border border-white/[0.08] bg-[#070709] p-1"
          >
            {(
              [
                ["fulltime", "Full-Time"],
                ["contract", "Contract"],
              ] as const
            ).map(([mode, label]) => {
              const selected = workType === mode;
              return (
                <button
                  key={mode}
                  type="button"
                  role="tab"
                  aria-selected={selected}
                  onClick={() => setWorkType(mode)}
                  className={`cursor-pointer rounded-md px-3.5 py-1.5 font-mono text-[11px] transition-colors duration-200 ease-out ${
                    selected
                      ? "border border-white/[0.1] bg-[#1A1A1E] font-medium text-zinc-100 shadow-sm"
                      : "text-zinc-400 hover:text-zinc-200"
                  }`}
                >
                  {label}
                </button>
              );
            })}
          </div>
        </div>

        <div className="border-t border-white/[0.06] pt-4">
          <FormLabel htmlFor="opportunities-search" className="mb-2">
            Search & filter
          </FormLabel>
          <div className="flex flex-col gap-2.5 sm:flex-row sm:items-center">
            <div className="relative min-w-0 flex-1">
              <span className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-zinc-500">
                <Search className="h-4 w-4" aria-hidden="true" />
              </span>
              <input
                id="opportunities-search"
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder={`Search ${workType === "contract" ? "contract" : "full-time"} roles, companies, or skills...`}
                className="w-full rounded-lg border border-white/[0.09] bg-[#070709] py-2.5 pl-10 pr-4 font-mono text-sm text-zinc-100 placeholder:text-zinc-600 focus:border-violet-500/60 focus:outline-none focus:ring-1 focus:ring-violet-500/20"
              />
            </div>
            <button
              type="button"
              aria-pressed={remoteOnly}
              onClick={() => setRemoteOnly((prev) => !prev)}
              className={`shrink-0 cursor-pointer rounded-full border px-3.5 py-2 font-mono text-[11px] transition-colors duration-200 ease-out sm:self-auto ${
                remoteOnly
                  ? "border-violet-500/40 bg-violet-500/15 font-medium text-violet-300"
                  : "border-white/[0.12] bg-transparent text-zinc-400 hover:border-white/[0.2] hover:text-zinc-200"
              }`}
            >
              Remote Only
            </button>
          </div>
        </div>
      </div>

      {jobsLoading ? (
        <div className="rounded-xl border border-white/[0.08] bg-[#131316]/90 p-10 text-center shadow-xl backdrop-blur-md">
          <p className="text-sm font-medium text-zinc-400">
            Loading opportunities...
          </p>
        </div>
      ) : jobsError ? (
        <div className="rounded-xl border border-white/[0.08] bg-[#131316]/90 p-10 text-center shadow-xl backdrop-blur-md">
          <p className="text-sm font-medium text-zinc-100">
            Could not load job feed
          </p>
          <p className="mt-1 text-xs text-zinc-400">
            The opportunities list is unavailable right now. You can keep
            using the rest of the dashboard.
          </p>
        </div>
      ) : activeJobs.length === 0 || filteredJobFeed.length === 0 ? (
        <div className="rounded-xl border border-white/[0.08] bg-[#131316]/90 p-10 text-center shadow-xl backdrop-blur-md">
          <p className="text-sm font-medium text-zinc-100">
            {workTypeEmptyMessage}
          </p>
          {activeJobs.length > 0 ? (
            <p className="mt-1 text-xs text-zinc-400">
              Try clearing search or disabling Remote Only.
            </p>
          ) : null}
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {filteredJobFeed.map((job) => {
            const alreadyApplied = appliedJobIds.includes(job.id);
            const tags = jobDisplayTags(job);
            const insight = matchInsights[job.id];
            const isMatching = Boolean(matchLoadingIds[job.id]);
            const matchScore = insight?.match_score ?? 0;
            const formattedSalary = formatJobCompensation(job);
            const isExpanded = expandedJobId === job.id;
            const jobDescription = (job.description ?? "").trim();

            return (
              <div
                key={job.id}
                className="flex flex-col rounded-xl border border-white/[0.08] bg-[#131316]/90 p-5 shadow-2xl transition-all hover:border-violet-500/30"
              >
                <div className="mb-3 flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <h3 className="truncate font-semibold text-zinc-100">
                      {job.title}
                    </h3>
                    <p className="mt-0.5 truncate text-sm font-medium text-violet-300">
                      {job.company}
                    </p>
                  </div>
                  {enableAiMatch ? (
                    <div className="flex shrink-0 flex-col items-end gap-1.5">
                      <span
                        className={
                          isMatching
                            ? "inline-flex items-center rounded-md border border-violet-500/25 bg-violet-500/10 px-2.5 py-1 font-mono text-xs font-medium text-violet-300 animate-pulse"
                            : insight
                              ? getFitVerdictBadgeClass(insight.fit_verdict)
                              : "inline-flex items-center rounded-md border border-white/[0.08] bg-[#1A1A1E] px-2.5 py-1 font-mono text-xs font-medium text-zinc-400"
                        }
                      >
                        {isMatching
                          ? "Scoring…"
                          : insight
                            ? insight.fit_verdict
                            : "Pending"}
                      </span>
                      {insight && !isMatching ? (
                        <>
                          <span className="font-mono text-[10px] font-bold tabular-nums text-zinc-500">
                            {clampScore0to100(matchScore)}% match
                          </span>
                          <ScoreMeter score={matchScore} className="w-16" />
                        </>
                      ) : null}
                    </div>
                  ) : null}
                </div>

                {formattedSalary ? (
                  <p className="mb-1 font-mono text-sm font-semibold text-violet-300">
                    {formattedSalary}
                  </p>
                ) : null}
                <p className="mb-4 font-mono text-xs text-zinc-500">{job.location}</p>

                {tags.length > 0 ? (
                  <div className="mb-4 flex flex-wrap gap-1.5">
                    {tags.map((tag) => (
                      <span
                        key={tag}
                        className="rounded border border-violet-500/20 bg-violet-500/10 px-1.5 py-0.5 font-mono text-[10px] text-violet-300"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                ) : null}

                {jobDescription ? (
                  <div className="mb-4">
                    <p
                      className={`whitespace-pre-wrap text-xs leading-relaxed text-zinc-400 ${
                        isExpanded ? "" : "line-clamp-3"
                      }`}
                    >
                      {jobDescription}
                    </p>
                    {jobDescription.length > 160 && (
                      <button
                        type="button"
                        onClick={() =>
                          setExpandedJobId((prev) =>
                            prev === job.id ? null : job.id
                          )
                        }
                        className="mt-2 cursor-pointer font-mono text-[11px] font-medium text-violet-300 transition-colors duration-200 ease-out hover:text-violet-200"
                      >
                        {isExpanded ? "Show less" : "Read full opening"}
                      </button>
                    )}
                  </div>
                ) : null}

                {enableAiMatch && (isMatching || insight) && (
                  <div className="mb-4 rounded-lg border border-white/[0.06] bg-[#070709] p-3 font-mono text-xs text-zinc-300">
                    <span className="mb-2 block font-mono text-[10px] uppercase tracking-widest text-zinc-500">
                      AI Match Analysis
                    </span>
                    {isMatching ? (
                      <div className="flex items-center gap-2">
                        <span className="relative flex h-2 w-2">
                          <span className="relative inline-flex h-2 w-2 rounded-full bg-violet-400" />
                        </span>
                        <p className="text-xs text-zinc-400">
                          Evaluating your profile against this role with Gemini…
                        </p>
                      </div>
                    ) : (
                      <ul className="space-y-2">
                        {insight?.match_reasons.map((reason, index) => {
                          const { label, body } =
                            splitCandidateMatchReason(reason);
                          return (
                            <li
                              key={`${job.id}-reason-${index}`}
                              className="flex items-start gap-2 text-xs leading-relaxed text-zinc-300"
                            >
                              <span className="mt-1.5 h-1 w-1 shrink-0 rounded-full bg-violet-400" />
                              <span>
                                {label ? (
                                  <>
                                    <span className="font-semibold text-zinc-100">
                                      {label}:
                                    </span>{" "}
                                    {body}
                                  </>
                                ) : (
                                  reason
                                )}
                              </span>
                            </li>
                          );
                        })}
                      </ul>
                    )}
                  </div>
                )}

                <div className="mt-3 flex items-center justify-between border-t border-white/[0.06] pt-3 text-xs text-zinc-400">
                  <Button
                    type="button"
                    onClick={() => onExpressInterest(job)}
                    disabled={alreadyApplied}
                    className="ml-auto"
                  >
                    {alreadyApplied ? (
                      <>
                        Interest Sent
                        <Check className="w-3.5 h-3.5" aria-hidden="true" />
                      </>
                    ) : (
                      "Express Interest"
                    )}
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useDashboardNav } from "@/components/dashboard/dashboard-nav-context";
import OpportunitiesJobFeed from "@/components/opportunities/opportunities-job-feed";
import { submitCandidateJobInterest } from "@/lib/job-interest";
import { extractAuditedSkills, parseExperienceTier } from "@/lib/job-match";
import { fetchPublicJobFeed, type JobRow } from "@/lib/jobs";
import { fetchProfileForCandidateId } from "@/lib/resolve-candidate-profile";
import { useProvixAiMatch } from "@/components/opportunities/use-provix-ai-match";
import { createClient } from "@/utils/supabase/client";
import Toast, { inferToastVariant, type ToastVariant } from "@/components/Toast";

type CandidateMatchProfile = {
  skills: string[] | string;
  experienceTier: string;
  githubUrl: string;
  githubAudit: unknown;
  openToFulltime: boolean;
  openToContract: boolean;
  auditScore: number | null;
  productionScore: number | null;
};

function candidateFromProfileRow(
  row: Record<string, unknown> | null
): CandidateMatchProfile {
  const auditData = row?.audit_data;
  const githubAudit =
    auditData &&
    typeof auditData === "object" &&
    "github_audit" in (auditData as object)
      ? (auditData as { github_audit?: unknown }).github_audit
      : auditData;

  const productionScore =
    typeof row?.production_score === "number" &&
    Number.isFinite(row.production_score)
      ? row.production_score
      : null;
  const auditScore =
    typeof row?.audit_score === "number" && Number.isFinite(row.audit_score)
      ? row.audit_score
      : productionScore;

  const payload = {
    skills: row?.skills as string[] | string | undefined,
    experienceTier:
      typeof row?.experience_level === "string" ? row.experience_level : "",
    githubUrl:
      (typeof row?.portfolio_url === "string" && row.portfolio_url) ||
      (typeof row?.github_url === "string" && row.github_url) ||
      "",
    githubAudit,
  };

  return {
    skills: extractAuditedSkills(payload),
    experienceTier: parseExperienceTier(payload),
    githubUrl: payload.githubUrl,
    githubAudit,
    openToFulltime: row?.open_to_fulltime === true,
    openToContract: row?.open_to_contract === true,
    auditScore,
    productionScore,
  };
}

export default function PublicOpportunitiesFeed() {
  const { requireAuth, userId, authLoading } = useDashboardNav();
  const [jobs, setJobs] = useState<JobRow[]>([]);
  const [jobsLoading, setJobsLoading] = useState(true);
  const [appliedJobIds, setAppliedJobIds] = useState<string[]>([]);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [toastVariant, setToastVariant] = useState<ToastVariant>("success");
  const [candidateProfile, setCandidateProfile] =
    useState<CandidateMatchProfile | null>(null);
  const [loadingProfile, setLoadingProfile] = useState(false);

  const matchCandidate = useMemo(
    () => ({
      skills: candidateProfile?.skills ?? [],
      experienceTier: candidateProfile?.experienceTier ?? "",
      githubUrl: candidateProfile?.githubUrl ?? "",
      githubAudit: candidateProfile?.githubAudit,
      openToFulltime: candidateProfile?.openToFulltime ?? false,
      openToContract: candidateProfile?.openToContract ?? false,
      auditScore: candidateProfile?.auditScore ?? null,
      productionScore: candidateProfile?.productionScore ?? null,
    }),
    [candidateProfile]
  );

  const {
    matchInsights,
    matchLoadingIds,
    aiMatchRunning,
    aiMatchError,
    runAiMatch,
  } = useProvixAiMatch({
    jobs,
    userId,
    authLoading,
    requireAuth,
    candidate: matchCandidate,
  });

  const showToast = useCallback((message: string, variant?: ToastVariant) => {
    setToastMessage(message);
    setToastVariant(variant ?? inferToastVariant(message));
    window.setTimeout(() => setToastMessage(null), 3200);
  }, []);

  useEffect(() => {
    let isMounted = true;

    const loadJobs = async () => {
      try {
        const { data, error } = await fetchPublicJobFeed(createClient());

        if (!isMounted) {
          return;
        }

        if (error) {
          console.error(
            "Failed to fetch public jobs:",
            error.message,
            error.details,
            error.hint
          );
          setJobs([]);
        } else {
          setJobs(data);
        }
      } catch (err) {
        console.error("Failed to fetch public jobs:", err);
        if (isMounted) {
          setJobs([]);
        }
      } finally {
        if (isMounted) {
          setJobsLoading(false);
        }
      }
    };

    void loadJobs();

    return () => {
      isMounted = false;
    };
  }, []);

  useEffect(() => {
    if (!userId) {
      setAppliedJobIds([]);
      setCandidateProfile(null);
      setLoadingProfile(false);
      return;
    }

    let isMounted = true;
    const supabase = createClient();
    setLoadingProfile(true);

    const loadCandidate = async () => {
      const startedAt =
        typeof performance !== "undefined" ? performance.now() : Date.now();
      try {
        const [{ data, error }, profile] = await Promise.all([
          supabase
            .from("job_applications")
            .select("job_id")
            .eq("candidate_id", userId)
            .limit(100),
          fetchProfileForCandidateId(
            supabase,
            userId,
            "skills, experience_level, portfolio_url, github_url, open_to_fulltime, open_to_contract, production_score, audit_score, audit_data"
          ),
        ]);

        if (!isMounted) {
          return;
        }

        const ms = Math.round(
          (typeof performance !== "undefined" ? performance.now() : Date.now()) -
            startedAt
        );
        console.info("[opportunities] candidate context", {
          ms,
          applications: data?.length ?? 0,
          hasProfile: Boolean(profile),
          error: error?.message ?? null,
        });

        if (error) {
          console.error("Failed to fetch job applications:", error);
        } else {
          setAppliedJobIds((data ?? []).map((row) => row.job_id));
        }

        setCandidateProfile(candidateFromProfileRow(profile));
      } catch (err) {
        if (!isMounted) {
          return;
        }
        console.error("Failed to load candidate match profile:", err);
      } finally {
        if (isMounted) {
          setLoadingProfile(false);
        }
      }
    };

    void loadCandidate();

    return () => {
      isMounted = false;
    };
  }, [userId]);

  const handleExpressInterest = async (job: JobRow) => {
    if (authLoading) {
      return;
    }

    if (!requireAuth() || !userId) {
      return;
    }

    if (appliedJobIds.includes(job.id)) {
      return;
    }

    setAppliedJobIds((prev) => [...prev, job.id]);
    showToast("Interest sent. The employer will review your profile.");

    try {
      const result = await submitCandidateJobInterest(job.id);
      if (result.alreadyApplied) {
        return;
      }
    } catch (err) {
      console.error("Failed to submit job interest:", err);
      setAppliedJobIds((prev) => prev.filter((id) => id !== job.id));
      showToast("Could not submit interest. Please try again.");
    }
  };

  return (
    <div className="w-full max-w-5xl mx-auto">
      <OpportunitiesJobFeed
        jobs={jobs}
        jobsLoading={jobsLoading}
        isGuest={!userId}
        appliedJobIds={appliedJobIds}
        onExpressInterest={handleExpressInterest}
        matchInsights={matchInsights}
        matchLoadingIds={matchLoadingIds}
        candidateSkills={
          Array.isArray(candidateProfile?.skills)
            ? candidateProfile.skills
            : []
        }
        loadingProfile={loadingProfile}
        enableAiMatch
        aiMatchRunning={aiMatchRunning}
        aiMatchError={aiMatchError}
        onRunAiMatch={runAiMatch}
      />
      <Toast
        message={toastMessage}
        variant={toastVariant}
        className="bottom-6 left-1/2 -translate-x-1/2 z-[80]"
      />
    </div>
  );
}

"use client";

import { useCallback, useMemo, useRef, useState } from "react";
import {
  buildCandidateJobMatchCacheKey,
  fetchJobMatches,
  toOpportunityMatchInsight,
  type JobMatchCandidatePayload,
} from "@/lib/job-match";
import { getActiveJobs } from "@/lib/opportunities-metrics";
import {
  toJobMatchJobPayload,
  type JobRow,
  type JobWorkType,
} from "@/lib/jobs";
import type { OpportunityMatchResult } from "@/lib/opportunity-match";

export type RunAiMatchOptions = {
  workType?: JobWorkType;
};

export function useProvixAiMatch({
  jobs,
  userId,
  authLoading = false,
  requireAuth,
  candidate,
}: {
  jobs: JobRow[];
  userId: string | null;
  authLoading?: boolean;
  requireAuth: () => boolean;
  candidate: JobMatchCandidatePayload;
}) {
  const [matchInsights, setMatchInsights] = useState<
    Record<string, OpportunityMatchResult>
  >({});
  const [matchLoadingIds, setMatchLoadingIds] = useState<
    Record<string, boolean>
  >({});
  const [aiMatchRunning, setAiMatchRunning] = useState(false);
  const [aiMatchError, setAiMatchError] = useState<string | null>(null);
  const sessionCacheRef = useRef<
    Map<string, Record<string, OpportunityMatchResult>>
  >(new Map());

  const activeJobs = useMemo(() => getActiveJobs(jobs), [jobs]);

  const runAiMatch = useCallback(
    async (options?: RunAiMatchOptions) => {
      if (authLoading || aiMatchRunning) {
        return;
      }

      if (!requireAuth() || !userId) {
        return;
      }

      if (activeJobs.length === 0) {
        setAiMatchError("No active job listings to match right now.");
        return;
      }

      const preferredWorkType =
        options?.workType ?? candidate.preferredWorkType ?? null;
      const jobPayloads = activeJobs.map((job) => toJobMatchJobPayload(job));
      const cacheKey = buildCandidateJobMatchCacheKey(
        candidate,
        jobPayloads.map((job) => job.jobId),
        preferredWorkType
      );
      const cached = sessionCacheRef.current.get(cacheKey);
      if (cached) {
        setAiMatchError(null);
        setMatchInsights(cached);
        return;
      }

      setAiMatchError(null);
      setAiMatchRunning(true);

      try {
        const { matches, error } = await fetchJobMatches(
          candidate,
          jobPayloads,
          { preferredWorkType }
        );

        if (error) {
          setMatchInsights({});
          setAiMatchError(error);
          return;
        }

        if (matches.length === 0) {
          setMatchInsights({});
          setAiMatchError(
            preferredWorkType === "contract"
              ? "No active contract openings match your availability right now."
              : preferredWorkType === "fulltime"
                ? "No active full-time openings match your availability right now."
                : "No active openings match your availability preferences right now."
          );
          return;
        }

        const matchedIds = new Set(matches.map((match) => String(match.jobId)));
        setMatchLoadingIds(
          Object.fromEntries([...matchedIds].map((id) => [id, true]))
        );

        const nextInsights: Record<string, OpportunityMatchResult> = {};
        for (const match of matches) {
          nextInsights[String(match.jobId)] = toOpportunityMatchInsight(match);
        }
        sessionCacheRef.current.set(cacheKey, nextInsights);
        setMatchInsights(nextInsights);
      } catch (err) {
        console.warn("Failed to run Provix AI Match:", err);
        setAiMatchError(
          "Could not complete AI matching. Please try again in a moment."
        );
      } finally {
        setAiMatchRunning(false);
        setMatchLoadingIds({});
      }
    },
    [
      activeJobs,
      aiMatchRunning,
      authLoading,
      candidate,
      requireAuth,
      userId,
    ]
  );

  return {
    matchInsights,
    matchLoadingIds,
    aiMatchRunning,
    aiMatchError,
    runAiMatch,
  };
}

"use client";

import Link from "next/link";
import { useCallback, useEffect, useState } from "react";
import {
  ExternalLink,
  FolderKanban,
  Loader2,
  Plus,
  ShieldCheck,
  Trash2,
} from "lucide-react";
import type { ExternalProjectRecord } from "@/lib/external-projects";
import {
  hasUsableExternalProjects,
  normalizeExternalProjects,
} from "@/lib/external-projects";
import { createClient } from "@/utils/supabase/client";

const inputClass =
  "w-full bg-background border border-border rounded-xl px-4 py-2.5 text-sm text-textMain placeholder:text-textMuted focus:outline-none focus:border-brand";

const labelClass =
  "block text-[11px] font-bold text-textMuted mb-2 uppercase tracking-wide";

function AlternativeArtifactsTrustNotice({ className = "" }: { className?: string }) {
  return (
    <div
      className={`rounded-xl border border-border bg-background px-3.5 py-3 ${className}`}
      role="note"
    >
