    <span
      className={cn(
        "inline-flex items-center rounded-full border border-zinc-700 bg-zinc-900/80 px-2.5 py-1 text-[11px] font-semibold tracking-wide text-zinc-200",
        className
      )}
    >
      {SELF_TAUGHT_ENGINEER_LABEL}
    </span>
  );
}

"use client";

import { useState } from "react";
import { signOutAndClearSession } from "@/lib/sign-out";

interface SignOutButtonProps {
  className?: string;
  redirectTo?: string;
}

const DEFAULT_CLASSES =
  "bg-red-500/10 text-red-400 border border-red-500/30 hover:bg-red-500/20 hover:text-red-300 font-medium text-sm tracking-tight px-4 py-2 rounded-md transition-colors duration-200 ease-out cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed";

export default function SignOutButton({
  className,
  redirectTo = "/",
}: SignOutButtonProps) {
  const [loading, setLoading] = useState(false);

  const handleSignOut = () => {
    setLoading(true);
    window.location.href = redirectTo;
    void signOutAndClearSession();
  };

  return (
    <button
      type="button"
      onClick={handleSignOut}
      disabled={loading}
      className={className ?? DEFAULT_CLASSES}
    >
      {loading ? "Signing out..." : "Sign Out"}
    </button>
  );
}

"use client";

import { Check, X } from "lucide-react";

export type ToastVariant = "success" | "error";

const ERROR_TOAST_PATTERN =
  /required|could not|couldn'?t|failed|must be|try again|invalid|denied|unable|missing/i;

export function inferToastVariant(message: string): ToastVariant {
  return ERROR_TOAST_PATTERN.test(message) ? "error" : "success";
}

type ToastProps = {
  message: string | null;
  variant?: ToastVariant;
  className?: string;
};

export default function Toast({
  message,
  variant,
  className = "bottom-6 right-6",
}: ToastProps) {
  if (!message) return null;

  const resolvedVariant = variant ?? inferToastVariant(message);
  const isError = resolvedVariant === "error";

  return (
    <div
      className={`fixed z-50 bg-panel text-textMain text-xs font-medium px-4 py-3 rounded-xl flex items-center gap-3 border print:hidden ${
        isError ? "border-red-500/40" : "border-border"
      } ${className}`}
      role={isError ? "alert" : "status"}
    >
      <span
        className={`w-5 h-5 rounded-full flex items-center justify-center shrink-0 ${
          isError
            ? "bg-red-500/15 text-red-400"
            : "bg-emerald-500/15 text-emerald-400"
        }`}
      >
        {isError ? (
          <X className="w-3 h-3" strokeWidth={2.5} aria-hidden />
        ) : (
          <Check className="w-3 h-3" strokeWidth={2.5} aria-hidden />
        )}
      </span>
      <span>{message}</span>
    </div>
  );
}

import type { ButtonHTMLAttributes } from "react";
import { cn } from "@/lib/cn";

/** @deprecated Prefer border border-border — hard shadows are retired in the 95/5 system. */
export const HARD_SHADOW = "border border-border";

export const BUTTON_MOTION =
  "transition-colors duration-200 ease-out";

const VARIANT_CLASSES = {
  primary:
    "bg-brand text-white border-transparent hover:bg-brandHover active:bg-brandHover focus-visible:ring-brand/50",
  secondary:
    "bg-panel text-textMain border-border hover:bg-surface focus-visible:ring-border",
  ghost:
    "bg-panel text-textMain border-border hover:bg-surface focus-visible:ring-border",
} as const;

export type ButtonVariant = keyof typeof VARIANT_CLASSES;

type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: ButtonVariant;
};

export default function Button({
  variant = "primary",
  className,
  type = "button",
  children,
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      className={cn(
        "inline-flex cursor-pointer items-center justify-center gap-2 rounded-md border px-4 py-2.5 text-sm font-semibold tracking-tight print:hidden",
        BUTTON_MOTION,
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50",
        VARIANT_CLASSES[variant],
        className
      )}
      {...props}
    >
      {children}
    </button>
  );
