export const INTRO_REQUEST_BASE_COLUMNS =
  "id, candidate_name, candidate_id, company_name, work_email, role_title, compensation_band, status, terms_accepted, terms_agreed_at, created_at";

export const INTRO_REQUEST_EXTENDED_COLUMNS = `${INTRO_REQUEST_BASE_COLUMNS}, agreed_first_year_compensation, candidate_bonus_allocated`;

export type IntroRequestRecord = {
  id: string;
  candidate_name: string | null;
  candidate_id: string;
  company_name: string | null;
  work_email: string | null;
  role_title: string;
  compensation_band: string | null;
  status: string;
  terms_accepted: boolean | null;
  terms_agreed_at: string | null;
  agreed_first_year_compensation: number | null;
  candidate_bonus_allocated: number | null;
  created_at: string;
};

function normalizeIntroRequestRow(
  row: Record<string, unknown>
): IntroRequestRecord {
  return {
    id: String(row.id ?? ""),
    candidate_name:
      typeof row.candidate_name === "string" ? row.candidate_name : null,
    candidate_id: String(row.candidate_id ?? ""),
    company_name:
      typeof row.company_name === "string" ? row.company_name : null,
    work_email: typeof row.work_email === "string" ? row.work_email : null,
    role_title: String(row.role_title ?? "Open role"),
    compensation_band:
      typeof row.compensation_band === "string" ? row.compensation_band : null,
    status: normalizeIntroPipelineStatus(
      typeof row.status === "string" ? row.status : null
    ),
    terms_accepted:
      typeof row.terms_accepted === "boolean" ? row.terms_accepted : null,
    terms_agreed_at:
      typeof row.terms_agreed_at === "string" ? row.terms_agreed_at : null,
    agreed_first_year_compensation:
      typeof row.agreed_first_year_compensation === "number"
        ? row.agreed_first_year_compensation
        : row.agreed_first_year_compensation != null
          ? Number.parseFloat(String(row.agreed_first_year_compensation)) ||
            null
          : null,
    candidate_bonus_allocated:
      typeof row.candidate_bonus_allocated === "number"
        ? row.candidate_bonus_allocated
        : row.candidate_bonus_allocated != null
          ? Number.parseFloat(String(row.candidate_bonus_allocated)) || null
          : null,
    created_at: String(row.created_at ?? new Date().toISOString()),
  };
}

export async function fetchIntroRequests(
  dataClient: SupabaseClient
): Promise<{
  rows: IntroRequestRecord[];
  schemaWarning: string | null;
}> {
  const extendedResult = await dataClient
    .from("intro_requests")
    .select(INTRO_REQUEST_EXTENDED_COLUMNS)
    .order("created_at", { ascending: false });

  if (!extendedResult.error) {
    return {
      rows: (extendedResult.data ?? []).map((row) =>
        normalizeIntroRequestRow(row as Record<string, unknown>)
      ),
      schemaWarning: null,
    };
  }

  if (!isSupabaseSchemaError(extendedResult.error)) {
    throw extendedResult.error;
  }

  console.warn(
    "[admin/requests] Extended intro_requests columns unavailable; falling back to base columns:",
    extendedResult.error
  );

  const baseResult = await dataClient
    .from("intro_requests")
    .select(INTRO_REQUEST_BASE_COLUMNS)
    .order("created_at", { ascending: false });

  if (baseResult.error) {
    throw baseResult.error;
  }

  return {
    rows: (baseResult.data ?? []).map((row) =>
      normalizeIntroRequestRow(row as Record<string, unknown>)
    ),
    schemaWarning:
      "Placement compensation columns are missing. Run migration 0027 in Supabase to enable hire tracking and revenue metrics.",
  };
}

export async function updateIntroRequestRecord(
  dataClient: SupabaseClient,
  requestId: string,
  updatePayload: Record<string, unknown>
): Promise<{
  row: IntroRequestRecord;
  schemaWarning: string | null;
}> {
  const extendedResult = await dataClient
    .from("intro_requests")
    .update(updatePayload)
    .eq("id", requestId)
    .select(INTRO_REQUEST_EXTENDED_COLUMNS)
    .single();

  if (!extendedResult.error && extendedResult.data) {
    return {
      row: normalizeIntroRequestRow(
        extendedResult.data as Record<string, unknown>
      ),
      schemaWarning: null,
    };
  }

  if (!isSupabaseSchemaError(extendedResult.error)) {
    throw extendedResult.error;
  }

  const { agreed_first_year_compensation, candidate_bonus_allocated, ...rest } =
    updatePayload;

  if (
    agreed_first_year_compensation !== undefined ||
    candidate_bonus_allocated !== undefined
  ) {
    console.warn(
      "[admin/requests] Compensation columns unavailable during update:",
      extendedResult.error
    );
  }

  const baseResult = await dataClient
    .from("intro_requests")
    .update(rest)
    .eq("id", requestId)
    .select(INTRO_REQUEST_BASE_COLUMNS)
    .single();

  if (baseResult.error || !baseResult.data) {
    throw baseResult.error ?? extendedResult.error;
  }

  return {
    row: normalizeIntroRequestRow(baseResult.data as Record<string, unknown>),
    schemaWarning:
      "Status saved, but compensation columns are missing in Supabase. Run migration 0027 to persist hire revenue data.",
  };
}

export async function getIntroRequestById(
  dataClient: SupabaseClient,
  requestId: string
): Promise<IntroRequestRecord | null> {
  const extendedResult = await dataClient
    .from("intro_requests")
    .select(INTRO_REQUEST_EXTENDED_COLUMNS)
    .eq("id", requestId)
    .maybeSingle();

  if (!extendedResult.error && extendedResult.data) {
    return normalizeIntroRequestRow(
      extendedResult.data as Record<string, unknown>
    );
  }

  if (extendedResult.error && !isSupabaseSchemaError(extendedResult.error)) {
    throw extendedResult.error;
  }

  const baseResult = await dataClient
    .from("intro_requests")
    .select(INTRO_REQUEST_BASE_COLUMNS)
    .eq("id", requestId)
    .maybeSingle();

  if (baseResult.error) {
    throw baseResult.error;
  }

  return baseResult.data
    ? normalizeIntroRequestRow(baseResult.data as Record<string, unknown>)
    : null;
}

export type CandidateDiscipline =
  | "engineering"
  | "design"
  | "product"
  | "data"
  | "general";

export type CodenameAliasInput = {
  profileId: string;
  role?: string | null;
  jobTitle?: string | null;
  headline?: string | null;
  major?: string | null;
  skills?: string[] | null;
};

const ADJECTIVES = [
  "Cobalt",
  "Swift",
  "Prime",
  "Lunar",
  "Solar",
  "Nova",
  "Apex",
  "Velvet",
  "Iron",
  "Crystal",
  "Ember",
  "Frost",
] as const;

const CODENAMES = [
  "Atlas",
  "Nova",
  "Orion",
  "Crest",
  "Summit",
  "Vertex",
  "Harbor",
  "Pulse",
  "Forge",
  "Echo",
  "Drift",
  "Signal",
  "Lynx",
  "Ion",
  "Aether",
] as const;

export const DEFAULT_PUBLIC_COUNTRY = "United States";
export const DEFAULT_PUBLIC_TIMEZONE = "MT (UTC-6)";

export const CONTACT_DOSSIER_LOCK_MESSAGE =
  "Full contact dossier unlocks upon approved introduction";

export const GITHUB_REPOS_LOCK_MESSAGE =
  "🔒 GitHub & Repos Unlocked on Intro Request";

function hashStringToIndex(input: string, modulo: number): number {
  let hash = 2166136261;

  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return Math.abs(hash) % modulo;
}

export function detectCandidateDiscipline(
  roleText: string,
  skills: string[] = []
): CandidateDiscipline {
  const haystack = `${roleText} ${skills.join(" ")}`.toLowerCase();

  if (
    /(\bdesign\b|\bux\b|\bui\b|\bfigma\b|\bvisual\b|\bcreative\b)/.test(
      haystack
    )
  ) {
    return "design";
  }

  if (/(\bproduct\b|\bpm\b|\bprogram manager\b)/.test(haystack)) {
    return "product";
  }

  if (
    /(\bdata\b|\banalyst\b|\banalytics\b|\bml\b|\bmachine learning\b|\bscience\b|\bbi\b)/.test(
      haystack
    )
  ) {
    return "data";
  }

  if (
    /(\bengineer\b|\bdeveloper\b|\bsoftware\b|\bfull[- ]stack\b|\bfrontend\b|\bbackend\b|\bdevops\b|\bplatform\b|\binfrastructure\b|\bmobile\b|\bsystems\b)/.test(
      haystack
    )
  ) {
    return "engineering";
  }

  return "general";
}

/** Stable two-word alias from a profile UUID, e.g. "Solar Summit" or "Apex Atlas". */
export function generateMaskedAliasFromUuid(uuid: string): string {
  const seed = uuid.trim().toLowerCase() || "candidate";
  const adjective =
    ADJECTIVES[hashStringToIndex(`${seed}:adj`, ADJECTIVES.length)];
  const letter = adjective.charAt(0).toUpperCase();
  const matchingNouns = CODENAMES.filter(
    (noun) => noun.charAt(0).toUpperCase() === letter
  );
  const nounPool = matchingNouns.length > 0 ? matchingNouns : CODENAMES;
  const noun = nounPool[hashStringToIndex(`${seed}:noun`, nounPool.length)];
  return `${adjective} ${noun}`;
}

export function generateCodenameAlias(input: CodenameAliasInput): string {
  return generateMaskedAliasFromUuid(input.profileId);
}

export type AlliterativeAliasIdentity = {
  alias: string;
  firstName: string;
  lastName: string;
  initials: string;
};

/** Force any profile id onto a two-word alliterative alias. Ignores DB names. */
export function buildAlliterativeAliasIdentity(
  profileId: string
): AlliterativeAliasIdentity {
  const alias = generateMaskedAliasFromUuid(profileId);
  const parts = alias.trim().split(/\s+/).filter(Boolean);
  return {
    alias,
    firstName: parts[0] ?? "Candidate",
    lastName: parts.slice(1).join(" "),
    initials: getCodenameInitials(alias),
  };
}

export function getCodenameInitials(alias: string): string {
  const parts = alias.trim().split(/\s+/).filter(Boolean);

  if (parts.length >= 3) {
    const adjective = parts[parts.length - 2] ?? "";
    const codename = parts[parts.length - 1] ?? "";
    return `${adjective.charAt(0)}${codename.charAt(0)}`.toUpperCase() || "??";
  }

  if (parts.length === 2) {
    return `${parts[0].charAt(0)}${parts[1].charAt(0)}`.toUpperCase() || "??";
  }

  return parts[0]?.slice(0, 2).toUpperCase() || "??";
}

export function formatPublicLocation(
  country?: string | null,
  timezone?: string | null
): string {
  const resolvedCountry = country?.trim() || DEFAULT_PUBLIC_COUNTRY;
  const resolvedTimezone = timezone?.trim() || DEFAULT_PUBLIC_TIMEZONE;
  return `${resolvedCountry} • ${resolvedTimezone}`;
}

export function buildCodenameAliasInputFromProfile(input: {
  id: string;
  job_title?: string | null;
  headline?: string | null;
  major?: string | null;
  role?: string | null;
  skills?: string[] | null;
}): CodenameAliasInput {
  return {
    profileId: input.id,
    jobTitle: input.job_title,
    headline: input.headline,
    major: input.major,
    role: input.role,
    skills: input.skills,
  };
}

/** Always derive from the profile UUID so stored or real names never leak. */
export function resolveCodenameAlias(profile: {
  id: string;
  codename_alias?: string | null;
  job_title?: string | null;
  headline?: string | null;
  major?: string | null;
  role?: string | null;
  skills?: string[] | null;
}): string {
  return generateMaskedAliasFromUuid(profile.id?.trim() || "");
}

import { NextResponse } from "next/server";
import { createClient as createJwtClient } from "@supabase/supabase-js";
import type { SupabaseClient, User } from "@supabase/supabase-js";
import { consumeRateLimit, tooManyRequestsResponse } from "@/lib/ip-rate-limit";
import { createClient } from "@/utils/supabase/server";
import { resolveAccountRole } from "@/lib/account-role";
import {
  isEmployerRole,
  isVerifiedEmployerFlag,
} from "@/lib/dashboard-account";
import { fetchProfileForCandidateId } from "@/lib/resolve-candidate-profile";

const AUTHENTICATED_AI_LIMIT = 30;
const AUTHENTICATED_AI_WINDOW_MS = 60_000;

export type ApiUserAccess = {
  user: User;
  supabase: SupabaseClient;
};

function readBearerToken(request?: Request): string | null {
  const header = request?.headers.get("authorization")?.trim();
  if (!header) {
    return null;
  }

  const match = /^Bearer\s+(\S+)/i.exec(header);
  return match?.[1] ?? null;
}

function createAccessTokenClient(accessToken: string): SupabaseClient {
  return createJwtClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      global: {
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      },
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    }
  );
}

export async function requireApiUser(
  request?: Request
): Promise<ApiUserAccess | NextResponse> {
  try {
    const cookieClient = await createClient();
    const {
      data: { user },
    } = await cookieClient.auth.getUser();

    if (user) {
      return { user, supabase: cookieClient };
    }

    const accessToken = readBearerToken(request);
    if (accessToken) {
      try {
        const tokenClient = createAccessTokenClient(accessToken);
        const {
          data: { user: tokenUser },
          error: tokenError,
        } = await tokenClient.auth.getUser(accessToken);

        if (tokenUser && !tokenError) {
          return { user: tokenUser, supabase: tokenClient };
        }
      } catch (error) {
        console.error("[api-auth] bearer token validation failed:", error);
      }
    }

    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  } catch (error) {
    console.error("[api-auth] requireApiUser failed:", error);
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
}

export async function requireAiApiUser(): Promise<ApiUserAccess | NextResponse> {
  const access = await requireApiUser();
  if (access instanceof NextResponse) {
    return access;
  }

  const limited = consumeRateLimit(
    `ai:${access.user.id}`,
    AUTHENTICATED_AI_LIMIT,
    AUTHENTICATED_AI_WINDOW_MS
  );

  if (!limited.ok) {
    return tooManyRequestsResponse(limited.retryAfterSec);
  }

  return access;
}

export async function rejectUnlessVerifiedEmployer(
  access: ApiUserAccess
): Promise<NextResponse | null> {
  try {
    const viewerRow = await fetchProfileForCandidateId(
      access.supabase,
      access.user.id,
      "role, is_verified"
    );
    const viewerRole = resolveAccountRole(
      typeof viewerRow?.role === "string" ? viewerRow.role : null,
      access.user
    );

    if (!isEmployerRole(viewerRole)) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    if (!isVerifiedEmployerFlag(viewerRow?.is_verified === true)) {
      return NextResponse.json(
        {
          error:
            "A verified corporate work email is required to use employer dashboard features.",
        },
        { status: 403 }
      );
    }

    return null;
  } catch (error) {
    console.error("[api-auth] employer verification lookup failed:", error);
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }
}

export async function requireVerifiedEmployer(
  request?: Request
): Promise<ApiUserAccess | NextResponse> {
  const access = await requireApiUser(request);
  if (access instanceof NextResponse) {
    return access;
  }

  const rejected = await rejectUnlessVerifiedEmployer(access);
  if (rejected) {
    return rejected;
  }

  return access;
}

export async function requireAiApiAccess(): Promise<NextResponse | null> {
  const access = await requireAiApiUser();
  if (access instanceof NextResponse) {
    return access;
  }

  return null;
}

/** Run an async operation; on throw, log and return a fallback. */
export async function withLoggedFallback<T>(
  label: string,
  run: () => Promise<T>,
  fallback: T
): Promise<T> {
  try {
    return await run();
  } catch (error) {
    console.error(`[${label}]`, error);
    return fallback;
  }
}

/** Run an async operation; on throw, log and return null. */
export async function withLoggedNull<T>(
  label: string,
  run: () => Promise<T>
): Promise<T | null> {
  return withLoggedFallback(label, run, null);
}

export type AuditCheckId =
  | "artifact_analysis"
  | "architecture_review"
  | "api_resiliency";

export type AuditCheck = {
  id: AuditCheckId;
  title: string;
  summary: string;
};

export const CANONICAL_AUDIT_CHECKS: readonly {
  id: AuditCheckId;
  title: string;
}[] = [
  { id: "artifact_analysis", title: "Artifact Analysis (Check 1)" },
  { id: "architecture_review", title: "Architecture Review (Check 2)" },
  {
    id: "api_resiliency",
    title: "API & Data Resiliency Check (Check 3)",
  },
] as const;

export function defaultAuditCheckSummary(id: AuditCheckId): string {
  switch (id) {
    case "artifact_analysis":
      return "Artifact evidence was too thin to verify README quality, commit history, or language signals against the claimed role.";
    case "architecture_review":
      return "Architecture signals were limited. No clear module structure, design notes, or system-level ownership could be confirmed from the provided artifacts.";
    case "api_resiliency":
      return "API and data-resiliency evidence was not found. Error handling, persistence, and production hardening could not be verified.";
  }
}

function parseCheckRecord(value: unknown): {
  id: string;
  title: string;
  summary: string;
} | null {
  if (!value || typeof value !== "object") {
    return null;
  }

  const record = value as Record<string, unknown>;
  const summarySource =
    record.summary ?? record.analysis ?? record.body ?? record.text;
  const summary =
    typeof summarySource === "string" ? summarySource.trim() : "";

  if (!summary) {
    return null;
  }

  return {
    id: typeof record.id === "string" ? record.id.trim() : "",
    title: typeof record.title === "string" ? record.title.trim() : "",
    summary,
  };
}

function asCheckList(raw: unknown): unknown[] {
  if (Array.isArray(raw)) {
    return raw.length === 1 && Array.isArray(raw[0]) ? raw[0] : raw;
  }

  if (raw && typeof raw === "object") {
    const values = Object.values(raw as Record<string, unknown>);
    if (values.length === 1 && Array.isArray(values[0])) {
      return values[0];
    }
    if (values.length > 0) {
      return values;
    }
  }

  return [];
}

export function normalizeAuditChecks(raw: unknown): AuditCheck[] {
  const parsed = asCheckList(raw)
    .map(parseCheckRecord)
    .filter((item): item is NonNullable<typeof item> => Boolean(item));

  return CANONICAL_AUDIT_CHECKS.map((canonical, index) => {
    const byId = parsed.find((item) => item.id === canonical.id);
    const titleNeedle =
      canonical.title.split("(")[0]?.trim().toLowerCase() ?? "";
    const byTitle = parsed.find((item) =>
      item.title.toLowerCase().includes(titleNeedle)
    );
    const byIndex = parsed[index];
    const match = byId ?? byTitle ?? byIndex;

    return {
      id: canonical.id,
      title: canonical.title,
      summary: match?.summary || defaultAuditCheckSummary(canonical.id),
    };
  });
}

import { describe, expect, it } from "vitest";
import {
  analyzeCiGates,
  analyzeCredentialExposure,
  analyzeRouteContracts,
  analyzeSupabaseHygiene,
  analyzeTestFileContent,
  analyzeTsconfigStrict,
  analyzeTypeScriptHygiene,
  analyzeWorkflowDepth,
  countUnhandledAsyncCalls,
  preferSupabaseSqlSamplePaths,
  preferWorkflowSamplePaths,
  selectPrimaryCiWorkflowPath,
  summarizeSampledTests,
} from "./audit-content-signals";

describe("countUnhandledAsyncCalls", () => {
  it("counts fetch and await outside try/catch", () => {
    const source = `
      export async function load() {
        const res = await fetch("/api");
        return res.json();
      }
    `;
    expect(countUnhandledAsyncCalls(source)).toBe(1);
  });

  it("does not count calls that sit inside try/catch", () => {
    const source = `
      export async function load() {
        try {
          const res = await fetch("/api");
          return res.json();
        } catch (error) {
          return null;
        }
      }
    `;
    expect(countUnhandledAsyncCalls(source)).toBe(0);
  });
});

describe("analyzeWorkflowDepth", () => {
  it("grades lint/build-only workflows", () => {
    expect(
      analyzeWorkflowDepth([
        "jobs:\n  build:\n    steps:\n      - run: npm run lint\n      - run: npm run build\n",
      ])
    ).toBe("lint_build");
  });

  it("grades workflows that execute tests", () => {
    expect(
      analyzeWorkflowDepth([
        "on: pull_request\njobs:\n  test:\n    steps:\n      - run: npm test\n",
      ])
    ).toBe("tests");
  });

  it("grades multi-stage deploy/preview workflows", () => {
    expect(
      analyzeWorkflowDepth([
        "jobs:\n  test:\n    steps:\n      - run: npm test\n  deploy:\n    environment: preview\n    steps:\n      - run: vercel deploy\n",
      ])
    ).toBe("deploy");
  });
});

describe("analyzeCiGates", () => {
  it("aggregates lint/test/build across multiple workflow files", () => {
    expect(
      analyzeCiGates([
        "jobs:\n  quality:\n    steps:\n      - run: turbo lint\n      - run: turbo build\n",
        "jobs:\n  e2e:\n    steps:\n      - run: turbo test\n",
