describe("dual-mode audit evaluation", () => {
  it("normalizes auditMode aliases to contract | fulltime", () => {
    expect(normalizeAuditMode("contract")).toBe("contract");
    expect(normalizeAuditMode("fulltime")).toBe("fulltime");
    expect(normalizeAuditMode("full-time")).toBe("fulltime");
    expect(normalizeAuditMode("unknown")).toBe("contract");
  });

  it("uses distinct weight tables per mode", () => {
    expect(AUDIT_MODE_WEIGHTS.fulltime).toEqual({
      architecture: 0.3,
      resilience: 0.25,
      devops: 0.15,
      testing: 0.3,
    });
    expect(AUDIT_MODE_WEIGHTS.contract).toEqual({
      architecture: 0.45,
      resilience: 0.25,
      devops: 0.15,
      testing: 0.15,
    });
  });

  it("assigns mode-specific tiers", () => {
    expect(assignAuditTier("fulltime", 82)).toBe(
      "Production-Grade / Core Lead"
    );
    expect(assignAuditTier("fulltime", 74)).toBe(
      "Mid/Senior Production-Ready"
    );
    expect(assignAuditTier("fulltime", 60)).toBe("Needs Refinement");
    expect(assignAuditTier("contract", 82)).toBe("Elite Sprint Contractor");
    expect(assignAuditTier("contract", 76)).toBe("Verified Sprint Builder");
    expect(assignAuditTier("contract", 68)).toBe("Supervised Feature Builder");
    expect(assignAuditTier("contract", 50)).toBe("Needs Hardening");
  });

  it("keeps solid contract codebases at or above 70 with thin tests", () => {
    const score = weightedScoreForMode("contract", {
      architecture: 82,
      testing: 0,
      devops: 55,
      resilience: 80,
    });
    expect(score).toBeGreaterThanOrEqual(70);
    expect(assignAuditTier("contract", score)).not.toBe("Needs Hardening");
  });

  it("lands Arch 82 / DevOps 90 / Test 68 as Verified Sprint Builder with soft resilience", () => {
    const score = weightedScoreForMode("contract", {
      architecture: 82,
      testing: 68,
      devops: 90,
      resilience: 15,
    });
    expect(score).toBeGreaterThanOrEqual(72);
    expect(score).toBeLessThanOrEqual(82);
    expect(assignAuditTier("contract", score)).toBe("Verified Sprint Builder");
  });

  it("penalizes missing tests more under fulltime weights", () => {
    const parts = {
      architecture: 82,
      testing: 0,
      devops: 0,
      resilience: 80,
    };
    const contract = weightedScoreForMode("contract", parts);
    const fulltime = weightedScoreForMode("fulltime", parts);
    expect(fulltime).toBeLessThan(contract);
  });

  it("keeps Full-Time below Mid/Senior for sparse tests and soft resilience", () => {
    // Mirrors carfax-like pillars after Full-Time density + −30 boundary scoring.
    const fulltime = weightedScoreForMode("fulltime", {
      architecture: 82,
      testing: 31,
      devops: 90,
      resilience: 54,
    });
    const contract = weightedScoreForMode("contract", {
      architecture: 82,
      testing: 68,
      devops: 90,
      resilience: 69,
    });
    expect(fulltime).toBeGreaterThanOrEqual(58);
    expect(fulltime).toBeLessThanOrEqual(64);
    expect(contract).toBeGreaterThanOrEqual(74);
    expect(contract).toBeLessThanOrEqual(82);
    expect(assignAuditTier("fulltime", fulltime)).toBe("Needs Refinement");
    expect(assignAuditTier("contract", contract)).toBe("Verified Sprint Builder");
  });

  it("derives dual trend scores from pillars or mirrors a single headline", () => {
    const dual = deriveDualModeScores({
      productionScore: 76,
      architecture: 82,
      testing: 68,
      devops: 90,
      resilience: 69,
    });
    expect(dual.contractScore).toBeGreaterThan(dual.fullTimeScore);
    expect(dual.contractScore).toBeGreaterThanOrEqual(72);

    const mirrored = deriveDualModeScores({ productionScore: 81 });
    expect(mirrored).toEqual({ contractScore: 81, fullTimeScore: 81 });
  });

  it("returns structured evaluation payload fields", () => {
    const evaluation = buildModeAwareEvaluation("contract", {
      architecture: 88,
      testing: 70,
      devops: 72,
      resilience: 84,
    });
    expect(evaluation.auditMode).toBe("contract");
    expect(evaluation.breakdown).toEqual({
      architecture: 88,
      security: 84,
      tooling: 72,
      testing: 70,
    });
    expect(evaluation.overallScore).toBeGreaterThan(0);
    expect(evaluation.tier).toBeTruthy();
  });
});

import { clampScore0to100 } from "@/lib/score-scale";

/** Dual evaluation modes for roster / sprint contracting audits. */
export type AuditMode = "contract" | "fulltime";

export const DEFAULT_AUDIT_MODE: AuditMode = "contract";

export const AUDIT_MODE_OPTIONS = [
  {
    value: "contract" as const,
    label: "Contract Work (Speed & Architecture)",
  },
  {
    value: "fulltime" as const,
    label: "Full-Time Work (Enterprise & Tests)",
  },
] as const;

/** Persistence keys used by the file-tree scorer. */
export type AuditPillarKey =
  | "architecture"
  | "resilience"
  | "devops"
  | "testing";

export type AuditModeWeights = Record<AuditPillarKey, number>;

/** Founder-facing category scores in the structured evaluation response. */
export type EvaluationBreakdown = {
  architecture: number;
  security: number;
  tooling: number;
  testing: number;
};

export type ModeAwareEvaluation = {
  overallScore: number;
  auditMode: AuditMode;
  tier: string;
  breakdown: EvaluationBreakdown;
};

/** Full-time: enterprise maintainability, tests, and CI dominate. */
export const FULLTIME_WEIGHTS: AuditModeWeights = {
  architecture: 0.3,
  resilience: 0.25,
  devops: 0.15,
  testing: 0.3,
};

/**
 * Contract: velocity + clean TypeScript first.
 * Missing error.tsx / thin tests are polish inside the smaller 15% testing bucket
 * and a moderated security pillar — not fatal vetoes.
 */
export const CONTRACT_WEIGHTS: AuditModeWeights = {
  architecture: 0.45,
  resilience: 0.25,
  devops: 0.15,
  testing: 0.15,
};

export const AUDIT_MODE_WEIGHTS: Record<AuditMode, AuditModeWeights> = {
  fulltime: FULLTIME_WEIGHTS,
  contract: CONTRACT_WEIGHTS,
};

export function isAuditMode(value: unknown): value is AuditMode {
  return value === "contract" || value === "fulltime";
}

export function normalizeAuditMode(value: unknown): AuditMode {
  if (typeof value !== "string") {
    return DEFAULT_AUDIT_MODE;
  }
  const normalized = value.trim().toLowerCase();
  if (normalized === "full-time" || normalized === "full_time") {
    return "fulltime";
  }
  if (isAuditMode(normalized)) {
    return normalized;
  }
  return DEFAULT_AUDIT_MODE;
}

export function weightsForAuditMode(mode: AuditMode): AuditModeWeights {
  return AUDIT_MODE_WEIGHTS[mode];
}

/** Contract-mode readiness titles (Founder Verdict badge uses the same bands). */
export const CONTRACT_TIER_ELITE = "Elite Sprint Contractor";
export const CONTRACT_TIER_VERIFIED = "Verified Sprint Builder";
export const CONTRACT_TIER_SUPERVISED = "Supervised Feature Builder";
export const CONTRACT_TIER_HARDENING = "Needs Hardening";

export function assignAuditTier(mode: AuditMode, score: number): string {
  const s = clampScore0to100(score);
  if (mode === "fulltime") {
    if (s >= 80) {
      return "Production-Grade / Core Lead";
    }
    if (s >= 70) {
      return "Mid/Senior Production-Ready";
    }
    return "Needs Refinement";
  }
  if (s >= 80) {
    return CONTRACT_TIER_ELITE;
  }
  if (s >= 72) {
    return CONTRACT_TIER_VERIFIED;
  }
  if (s >= 60) {
    return CONTRACT_TIER_SUPERVISED;
  }
  return CONTRACT_TIER_HARDENING;
}

/**
 * Mode-specific pillar shaping before weighting.
 * Contract: missing tests / soft resilience get polish floors so they cannot
 * veto a clean architecture + tooling repo.
 * Full-time: keep harsh zeros for missing Vitest/Playwright and CI workflows.
 */
export function shapePillarsForMode(
  mode: AuditMode,
  parts: {
    architecture: number;
    testing: number;
    devops: number;
    resilience: number;
  }
): {
  architecture: number;
  testing: number;
  devops: number;
  resilience: number;
} {
  const architecture = clampScore0to100(parts.architecture);
  let resilience = clampScore0to100(parts.resilience);
  let testing = clampScore0to100(parts.testing);
  let devops = clampScore0to100(parts.devops);

  if (mode === "contract") {
    if (testing < 55) {
      testing = 55;
    }
    if (devops < 35) {
      devops = Math.max(devops, 35);
    }
    // Missing error.tsx / thin async wrappers are polish when architecture is solid.
    if (architecture >= 75 && resilience < 60) {
      resilience = 60;
    }
  }

  return { architecture, testing, devops, resilience };
}

/**
 * Contract mode: solid architecture + tooling must stay ≥ 70 even when
 * testing / resilience are only polish-level.
 */
export function applyContractScoreFloor(
  mode: AuditMode,
  score: number,
  parts: {
    architecture: number;
    testing: number;
    devops: number;
    resilience: number;
  }
): number {
  if (mode !== "contract") {
    return clampScore0to100(score);
  }
  const solidCore =
    parts.architecture >= 75 &&
    parts.devops >= 50 &&
    parts.testing < 75;
  if (!solidCore) {
    return clampScore0to100(score);
  }
  return clampScore0to100(Math.max(score, 70));
}

export function weightedScoreForMode(
  mode: AuditMode,
  parts: {
    architecture: number;
    testing: number;
    devops: number;
    resilience: number;
  }
): number {
  const shaped = shapePillarsForMode(mode, parts);
  const weights = weightsForAuditMode(mode);
  const raw = clampScore0to100(
    Math.round(
      shaped.architecture * weights.architecture +
        shaped.testing * weights.testing +
        shaped.devops * weights.devops +
        shaped.resilience * weights.resilience
    )
  );
  return applyContractScoreFloor(mode, raw, shaped);
}

/**
 * Map a historical (or live) audit into both mode scores for trend charts.
 * Prefer explicit dual scores; otherwise recompute from pillars; if only a
 * single headline exists, mirror it onto both series so coordinates stay valid.
 */
export function deriveDualModeScores(input: {
  productionScore?: number;
  contractScore?: number | null;
  fullTimeScore?: number | null;
  architecture?: number | null;
  testing?: number | null;
  devops?: number | null;
  resilience?: number | null;
}): { contractScore: number; fullTimeScore: number } {
  const headline = clampScore0to100(input.productionScore ?? 0);
  const hasExplicit =
    typeof input.contractScore === "number" &&
    Number.isFinite(input.contractScore) &&
    typeof input.fullTimeScore === "number" &&
    Number.isFinite(input.fullTimeScore);
  if (hasExplicit) {
    return {
      contractScore: clampScore0to100(input.contractScore),
      fullTimeScore: clampScore0to100(input.fullTimeScore),
    };
  }

  const testing = clampScore0to100(input.testing ?? 0);
  const devops = clampScore0to100(input.devops ?? 0);
  const resilience = clampScore0to100(input.resilience ?? 0);
  const hasPillars = testing > 0 || devops > 0 || resilience > 0;

  if (!hasPillars) {
    return { contractScore: headline, fullTimeScore: headline };
  }

  let architecture =
    typeof input.architecture === "number" && Number.isFinite(input.architecture)
      ? clampScore0to100(input.architecture)
      : null;

  if (architecture == null) {
    // Back-solve architecture assuming the stored headline used Contract weights.
    const residual =
      headline - resilience * 0.25 - devops * 0.15 - testing * 0.15;
    architecture = clampScore0to100(residual / 0.45);
  }

  const parts = { architecture, testing, devops, resilience };
  return {
    contractScore: weightedScoreForMode("contract", parts),
    fullTimeScore: weightedScoreForMode("fulltime", parts),
  };
}

export function buildEvaluationBreakdown(parts: {
  architecture: number;
  testing: number;
  devops: number;
  resilience: number;
}): EvaluationBreakdown {
  return {
    architecture: clampScore0to100(parts.architecture),
    security: clampScore0to100(parts.resilience),
    tooling: clampScore0to100(parts.devops),
    testing: clampScore0to100(parts.testing),
  };
}

export function buildModeAwareEvaluation(
  mode: AuditMode,
  parts: {
    architecture: number;
    testing: number;
    devops: number;
    resilience: number;
  }
): ModeAwareEvaluation {
  const overallScore = weightedScoreForMode(mode, parts);
  return {
    overallScore,
    auditMode: mode,
    tier: assignAuditTier(mode, overallScore),
    breakdown: buildEvaluationBreakdown(parts),
  };
}

export function auditModeLabel(mode: AuditMode): string {
  return mode === "fulltime"
    ? "Full-Time Work (Enterprise & Tests)"
    : "Contract Work (Speed & Architecture)";
}

/** Injected into the Gemini system prompt for the selected mode. */
export function buildAuditModeRubricPrompt(mode: AuditMode): string {
  if (mode === "fulltime") {
    return `EVALUATION MODE: fulltime (permanent / core engineering hire)
Prioritize enterprise maintainability, automated test coverage, error boundaries, and strict CI/CD. No polish floors — sparse tests and missing error.tsx must lower the headline score.
Weighted score = Math.round(architecture * 0.30 + testing * 0.30 + security * 0.25 + tooling * 0.15).
- Code Architecture & Clean Patterns (30%, key: architecture)
- Automated Testing & CI/CD (30%, key: testing) — STRICT volume curve: 1–5 suites score 20–35, 6–24 score 35–48, and ≥25 verified suites floor around 50 then scale toward 90+ with route/API/E2E coverage (large apps are not crushed by a low test/source ratio). Missing Vitest/Jest/Playwright suites or missing .github/workflows must heavily lower this pillar.
- Security & Resilience (25%, key: resilience) — STRICT: web apps missing error.tsx / error boundaries deduct −30 from this pillar. No structure floor.
- Production Tooling & Linters (15%, key: devops)
Tiers: "Production-Grade / Core Lead" (>= 80), "Mid/Senior Production-Ready" (70-79), "Needs Refinement" (< 70).
Copy overallScore, auditMode, tier, and breakdown from deterministicMetrics. Do not recompute.`;
  }

  return `EVALUATION MODE: contract (sprint velocity / MVP / rapid feature builds)
Prioritize fast feature delivery, clean TypeScript, and safe data access. Missing error.tsx or thin test harnesses are polish recommendations — not fatal score killers.
Weighted score = Math.round(architecture * 0.45 + security * 0.25 + tooling * 0.15 + testing * 0.15).
- Architecture & Code Hygiene (45%, key: architecture): Strict TypeScript, modular structure, clean component separation.
- Security & Safe Data Access (25%, key: resilience): Auth hygiene, safe queries/RLS signals, input validation. Missing error boundaries are a moderate ding with a ~50 floor when structure is clean.
- DevOps & Tooling (15%, key: devops): Build scripts, ESLint/Prettier, package hygiene; thin CI still earns a modest baseline.
- Testing & Resilience polish (15%, key: testing): BONUS / polish. Missing tests or error.tsx must NOT drag an otherwise clean Arch+DevOps codebase out of Verified Sprint (72–79) territory.
Tiers: "Elite Sprint Contractor" (>= 80), "Verified Sprint Builder" (72-79), "Supervised Feature Builder" (60-71), "Needs Hardening" (< 60).
Copy overallScore, auditMode, tier, and breakdown from deterministicMetrics. Do not recompute.`;
}

import { formatCommitHistoryReason } from "@/lib/commit-history-score";
import { clampScore0to100 } from "@/lib/score-scale";
import {
  scoreTesting,
  type CommitHistoryStat,
} from "@/lib/production-audit-metrics";
import {
  resolveUnitTestFileCount,
  type RepoFilesystemEvidence,
  type ScoreCapAudit,
} from "@/lib/repo-filesystem";

export type { CommitHistoryStat };

export type ReadinessBadge = {
  label: string;
  className: string;
  meterClassName: string;
};

/**
 * Verification labels for contract / full-time audits.
 * No third "Sparse History" tier — fail closed to Needs Refinement.
 */
export type VerificationTier = "Provix Verified" | "Needs Refinement";

export const VERIFICATION_TIER_PROVIX = "Provix Verified" as const;
/** @deprecated Third tier removed; kept for older string compares. */
export const VERIFICATION_TIER_SPARSE_HISTORY =
  "Code Verified · Sparse History" as const;
export const VERIFICATION_TIER_NEEDS_REFINEMENT = "Needs Refinement" as const;

export const CODE_HEALTH_VERIFIED_THRESHOLD = 75;
/** Delivery Hygiene / History floor for Provix Verified (contract + full-time). */
export const DELIVERY_HYGIENE_VERIFIED_THRESHOLD = 80;

export const HISTORY_BLOCKS_QUALIFY_NOTE =
  "History needs 80+ to qualify." as const;

export type ChecklistTone = "pass" | "warn" | "fail";

export type RepoActivityStatus = "active" | "stable";

export type ExecutiveChecklistItem = {
  id: "ci" | "error_handling" | "tests" | "history";
  label: string;
  status: string;
  tone: ChecklistTone;
};

/**
 * Shared Verified / publish / onboarding-track gate input.
 * `historyAvailable: false` means the commit list fetch failed — History
 * cannot pass even if a numeric hygiene placeholder is 100.
 */
export type ProvixVerifiedGateInput = {
  codeHealthScore: number;
  deliveryHygieneScore?: number | null;
  historyAvailable?: boolean | null;
};

/** History ≥ 80 and a successful commit fetch. */
export function isHistoryGateMet(
  input: Pick<
    ProvixVerifiedGateInput,
    "deliveryHygieneScore" | "historyAvailable"
  >
): boolean {
  if (input.historyAvailable === false) {
    return false;
  }
  if (
    typeof input.deliveryHygieneScore !== "number" ||
    !Number.isFinite(input.deliveryHygieneScore)
  ) {
    return false;
  }
  return (
    clampScore0to100(input.deliveryHygieneScore) >=
    DELIVERY_HYGIENE_VERIFIED_THRESHOLD
  );
}

/**
 * Single source of truth for Provix Verified, onboarding track qualification,
 * and production-score publishing: Code Health ≥ 75 and History ≥ 80 with
 * fetched commit history.
 */
export function meetsProvixVerifiedGates(
  input: ProvixVerifiedGateInput
): boolean {
  return (
    clampScore0to100(input.codeHealthScore) >= CODE_HEALTH_VERIFIED_THRESHOLD &&
    isHistoryGateMet(input)
  );
}

/** Full-Time / Contract track qualification (same floors as Verified). */
export function qualifiesHiringTrack(
  trackScore: number,
  deliveryHygieneScore?: number | null,
  historyAvailable?: boolean | null
): boolean {
  return meetsProvixVerifiedGates({
    codeHealthScore: trackScore,
    deliveryHygieneScore,
    historyAvailable,
  });
}

/**
 * Dual-threshold verification (contract + full-time share these floors):
 * - Provix Verified: codeHealth >= 75 AND history gate met
 * - Needs Refinement: otherwise (no Sparse History tier)
 */
export function assignVerificationTier(
  codeHealthScore: number,
  deliveryHygieneScore?: number | null,
  historyAvailable?: boolean | null
): VerificationTier {
  return meetsProvixVerifiedGates({
    codeHealthScore,
    deliveryHygieneScore,
    historyAvailable,
  })
    ? VERIFICATION_TIER_PROVIX
    : VERIFICATION_TIER_NEEDS_REFINEMENT;
}

export function getVerificationTierBadge(
  codeHealthScore: number,
  deliveryHygieneScore?: number | null,
  historyAvailable?: boolean | null
): ReadinessBadge {
  const tier = assignVerificationTier(
    codeHealthScore,
    deliveryHygieneScore,
    historyAvailable
  );

  if (tier === VERIFICATION_TIER_PROVIX) {
    return {
      label: tier,
      className: "text-emerald-300 bg-emerald-500/10 border-emerald-500/30",
      meterClassName: "text-emerald-400",
    };
  }

  return {
    label: tier,
    className: "text-rose-300 bg-rose-500/10 border-rose-500/30",
    meterClassName: "text-rose-400",
  };
}

/**
 * Readiness / verification badge using the shared Provix Verified gates.
 */
export function getReadinessBadge(
  score: number,
  deliveryHygieneScore?: number | null,
  historyAvailable?: boolean | null
): ReadinessBadge {
  return getVerificationTierBadge(
    score,
    deliveryHygieneScore,
    historyAvailable
  );
}

const STALE_AFTER_MS = 180 * 24 * 60 * 60 * 1000;

export const READINESS_QUALITATIVE_WEIGHT = 0.45;
export const READINESS_PRODUCTION_WEIGHT = 0.55;

export function normalizeCommitDates(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is string => typeof item === "string")
    .map((item) => item.trim())
    .filter((item) => item.length > 0 && item.toLowerCase() !== "unknown");
}

function parseCommitTimestamps(
  commitDates: string[] | null | undefined
): number[] {
  return (commitDates ?? [])
    .map((value) => Date.parse(value))
    .filter((value) => Number.isFinite(value))
    .sort((left, right) => left - right);
}

function isStaleCommitHistory(
  parsed: number[],
  now = Date.now()
): boolean {
  if (parsed.length === 0) {
    return true;
  }

  return now - parsed[parsed.length - 1] >= STALE_AFTER_MS;
}

export function classifyRepoActivityStatus(
  commitDates: string[] | null | undefined,
  now = Date.now()
): RepoActivityStatus {
  return isStaleCommitHistory(parseCommitTimestamps(commitDates), now)
    ? "stable"
    : "active";
}

/** UI label kept for older dossiers. Inactivity no longer deducts points. */
export function formatHistoryDeductionLabel(_penalty?: number): string {
  return "History 0";
}

export function hasCoreProductionArtifacts(
  scoreCap?: ScoreCapAudit | null,
  filesystem?: RepoFilesystemEvidence | null
): boolean {
  const flags = coreArtifactFlags(scoreCap, filesystem);
  return flags.tests && flags.ci && flags.error_handling;
}

/**
 * Inactivity never lowers the score. Floor qualitative output to the
 * production pillar score when the model still emits a history ding.
 */
export function applyCommitHistoryScoreFloor(
  score: number,
  productionScore: number,
  _commitDates?: string[] | null,
  _now?: number
): number {
  return clampScore0to100(
    Math.max(clampScore0to100(score), clampScore0to100(productionScore))
  );
}

/**
 * Blend qualitative LLM score with the file-tree production scorecard.
 * Commit age is informational only and is not subtracted here.
 */
export function blendReadinessScore(input: {
  qualitativeScore: number;
  productionScore: number;
  /** @deprecated History floor no longer depends on core artifacts. */
  coreArtifactsPresent?: boolean;
  commitDates?: string[] | null;
  now?: number;
}): number {
  const production = clampScore0to100(input.productionScore);
  const qualitativeAdjusted = applyCommitHistoryScoreFloor(
    input.qualitativeScore,
    production,
    input.commitDates,
    input.now
  );

  return clampScore0to100(
    Math.round(
      qualitativeAdjusted * READINESS_QUALITATIVE_WEIGHT +
        production * READINESS_PRODUCTION_WEIGHT
    )
  );
}

/**
 * Lift an already-persisted readiness score when a prior scan applied a
 * heavy stale-history ding (e.g. History −25 with a Verified Human checklist).
 */
export function resolveDisplayedReadinessScore(input: {
  score: number;
  productionScore?: number;
  filesystem?: RepoFilesystemEvidence | null;
  scoreCap?: ScoreCapAudit | null;
  commitDates?: string[] | null;
  now?: number;
}): number {
  const score = clampScore0to100(input.score);
  const production = clampScore0to100(input.productionScore);

  if (!input.filesystem?.inspected || production <= 0) {
    return score;
  }

  return applyCommitHistoryScoreFloor(
    score,
    production,
    input.commitDates,
    input.now
  );
}

function coreArtifactFlags(
  scoreCap?: ScoreCapAudit | null,
  filesystem?: RepoFilesystemEvidence | null
): { tests: boolean; ci: boolean; error_handling: boolean } {
  if (filesystem) {
    return {
      tests: filesystem.test_paths.length > 0,
      ci: filesystem.ci_workflow_paths.length > 0,
      error_handling: filesystem.error_handling_paths.length > 0,
    };
  }

  return {
    tests: Boolean(scoreCap?.coreArtifacts.tests),
    ci: Boolean(scoreCap?.coreArtifacts.ci),
    error_handling: Boolean(scoreCap?.coreArtifacts.error_handling),
  };
}

function testCoverageRatio(
  filesystem?: RepoFilesystemEvidence | null
): number | null {
  if (!filesystem?.inspected) {
    return null;
  }

  const testFiles = resolveUnitTestFileCount(filesystem);
  if (testFiles === 0) {
    return 0;
  }

  const sourceFiles = Math.max(
    filesystem.executable_source_count > 0
      ? filesystem.executable_source_count
      : filesystem.source_file_count,
    filesystem.file_count - testFiles,
    testFiles
  );
  return testFiles / sourceFiles;
}

export function classifyTestSuites(
  testsPresent: boolean,
  filesystem?: RepoFilesystemEvidence | null,
  testingScore?: number | null
): { status: string; tone: ChecklistTone } {
  const paths = filesystem?.test_paths ?? [];
  if (!testsPresent && paths.length === 0) {
    return { status: "No tests", tone: "fail" };
  }

  const ratio = testCoverageRatio(filesystem);
  const score =
    typeof testingScore === "number" && Number.isFinite(testingScore)
      ? clampScore0to100(testingScore)
      : filesystem?.inspected
        ? scoreTesting(filesystem)
        : testsPresent
          ? 50
          : 0;

  if (score < 30 || (ratio != null && ratio < 0.15)) {
    return { status: "Coverage Gaps", tone: "warn" };
  }

  if (score < 75 && !(ratio != null && ratio >= 0.35)) {
    return { status: "Partial Suite", tone: "warn" };
  }

  if (score >= 75 || (ratio != null && ratio >= 0.35)) {
    return { status: "Full coverage", tone: "pass" };
  }

  return { status: "Partial Suite", tone: "warn" };
}

/**
 * Informational repo activity from sampled commit dates only.
 * Kept for callers; Executive Checklist uses History instead.
 */
export function classifyCommitCadence(
  commitDates: string[] | null | undefined,
  now = Date.now(),
  _commitStats?: CommitHistoryStat[] | null
): {
  status: string;
  tone: ChecklistTone;
  /** Always 0 — activity is informational. */
  penalty: number;
  /** Always 0 — kept for callers that still read the field. */
  commitHistoryPenalty: number;
  activity: RepoActivityStatus;
} {
  const activity = classifyRepoActivityStatus(commitDates, now);
  return {
    status: activity,
    activity,
    tone: activity === "active" ? "pass" : "warn",
    penalty: 0,
    commitHistoryPenalty: 0,
  };
}

/** Executive Checklist History row from Delivery Hygiene + commit signals. */
export function classifyHistoryChecklist(
  deliveryHygieneScore: number,
  commitDates?: string[] | null,
  commitStats?: CommitHistoryStat[] | null,
  historyAvailable: boolean | null = true
): { status: string; tone: ChecklistTone } {
  if (historyAvailable === false) {
    return { status: "History unavailable", tone: "fail" };
  }
  const hygiene = clampScore0to100(deliveryHygieneScore);
  const status = formatCommitHistoryReason(commitDates, commitStats);
  // Verified History floor is 80 — do not treat 60 as a pass band.
  if (isHistoryGateMet({ deliveryHygieneScore: hygiene, historyAvailable })) {
    return { status, tone: "pass" };
  }
  if (hygiene > 0) {
    return { status, tone: "warn" };
  }
  return { status, tone: "fail" };
}

export const PRODUCTION_READY_VERIFIED =
  "Production-ready engineering standards verified across pipelines, test coverage, and schema boundaries.";

export function isProductionReadyAudit(metrics: {
  productionScore: number;
  architecture: number;
  testing: number;
  devops: number;
  resilience: number;
}): boolean {
  return (
    metrics.productionScore >= 90 &&
    metrics.architecture >= 85 &&
    metrics.testing >= 85 &&
    metrics.devops >= 85 &&
    metrics.resilience >= 85
  );
}

export function targetedAuditSuggestions(input: {
  language: string | null;
  testingScore: number;
  testFileCount: number;
  devopsScore: number;
  needsSchemaValidation: boolean;
  needsBuildGate: boolean;
}): string[] {
  const language = input.language?.trim().toLowerCase() ?? "";
  const javascript = /^(typescript|javascript|tsx|jsx)$/i.test(language);
  const suggestions: string[] = [];

  if (input.needsBuildGate && input.devopsScore < 75) {
    if (javascript) {
      suggestions.push(
        "Add a production build step (`next build` or `tsc`) to the CI workflow."
      );
    } else if (language === "go") {
      suggestions.push(
        "Add a CI step that runs `go build ./...` (and ideally `go test ./...`) on pull requests."
      );
    } else if (language === "python" || language === "jupyter notebook") {
      suggestions.push(
        "Add a CI step that runs `pytest` (and ideally `ruff check` or `mypy`) on pull requests."
      );
    } else if (language === "rust") {
      suggestions.push(
        "Add a CI step that runs `cargo check` and `cargo test` on pull requests."
      );
    } else {
      suggestions.push(
        "Add a CI workflow that runs this repository's native lint, test, and build commands on pull requests."
      );
    }
  }
  if (javascript && input.needsSchemaValidation) {
    suggestions.push(
      "Add Zod schema parsing on API route handlers that currently cast JSON with `as Type`."
    );
  }
  if (input.testingScore < 70 && input.testFileCount < 10) {
    suggestions.push(
      javascript
        ? "Expand integration or end-to-end coverage with a TypeScript test such as src/foo.test.ts."
        : language === "go"
          ? "Expand package coverage with a Go test such as foo_test.go using `go test ./...`."
          : language === "python" || language === "jupyter notebook"
            ? "Expand coverage with a pytest module such as tests/test_app.py."
            : language === "rust"
              ? "Expand coverage with a Rust unit/integration test and `cargo test`."
              : "Expand integration or end-to-end coverage with a test file that matches this repository's primary language."
    );
  }

  return suggestions;
}

export function buildExecutiveChecklist(input: {
  scoreCap?: ScoreCapAudit | null;
  filesystem?: RepoFilesystemEvidence | null;
  commitDates?: string[] | null;
  commitStats?: CommitHistoryStat[] | null;
  commitHistoryPenalty?: number | null;
  deliveryHygieneScore?: number | null;
  historyAvailable?: boolean | null;
  testingScore?: number | null;
}): ExecutiveChecklistItem[] {
  const artifacts = coreArtifactFlags(input.scoreCap, input.filesystem);
  const tests = classifyTestSuites(
    artifacts.tests,
    input.filesystem,
    input.testingScore
  );
  const hygiene =
    typeof input.deliveryHygieneScore === "number" &&
    Number.isFinite(input.deliveryHygieneScore)
      ? input.deliveryHygieneScore
      : typeof input.commitHistoryPenalty === "number" &&
          Number.isFinite(input.commitHistoryPenalty)
        ? Math.max(0, 100 - Math.max(0, input.commitHistoryPenalty))
        : 100;
  const history = classifyHistoryChecklist(
    hygiene,
    input.commitDates,
    input.commitStats,
    input.historyAvailable
  );

  return [
    {
      id: "ci",
      label: "CI/CD Pipelines",
      status: artifacts.ci ? "Configured" : "None detected",
      tone: artifacts.ci ? "pass" : "fail",
    },
    {
      id: "error_handling",
      label: "Error Handling",
      status: artifacts.error_handling ? "Standardized" : "Missing boundaries",
      tone: artifacts.error_handling ? "pass" : "fail",
    },
    {
      id: "tests",
      label: "Test Suites",
      status: tests.status,
      tone: tests.tone,
    },
    {
      id: "history",
      label: "History",
      status: history.status,
      tone: history.tone,
    },
  ];
}

