const RETURNABLE_PATH_PREFIXES = [
  "/opportunities",
  "/audit",
  "/audits",
  "/onboarding",
  "/dashboard",
] as const;

/** Stash post-OAuth destination; query-string redirectTo is often not allow-listed. */
export const OAUTH_NEXT_COOKIE = "provix_oauth_next";

export function isSafeOAuthNextPath(
  path: string | null | undefined
): path is string {
  if (!path) {
    return false;
  }
  const trimmed = path.trim();
  return (
    trimmed.startsWith("/") &&
    !trimmed.startsWith("//") &&
    !trimmed.includes("\\")
  );
}

export function rememberOAuthNext(path: string) {
  if (typeof document === "undefined" || !isSafeOAuthNextPath(path)) {
    return;
  }
  document.cookie = `${OAUTH_NEXT_COOKIE}=${encodeURIComponent(path)}; Path=/; Max-Age=600; SameSite=Lax`;
}

export function clearOAuthNextCookie() {
  if (typeof document === "undefined") {
    return;
  }
  document.cookie = `${OAUTH_NEXT_COOKIE}=; Path=/; Max-Age=0; SameSite=Lax`;
}

/** Exact callback URL — matches Supabase allow-listed Redirect URLs (no query). */
export function buildExactOAuthCallbackUrl(origin = window.location.origin): string {
  return `${origin}/auth/callback`;
}

function decodePathCandidate(raw: string): string {
  try {
    return decodeURIComponent(raw.trim());
  } catch {
    return raw.trim();
  }
}

/**
 * Prefer explicit next (query or cookie). Password recovery wins.
 * Falls back to /dashboard.
 */
export function resolveOAuthSuccessPath(
  nextParam: string | null | undefined,
  cookieNext?: string | null
): string {
  const candidates = [nextParam, cookieNext];

  for (const raw of candidates) {
    if (!raw) {
      continue;
    }
    const path = decodePathCandidate(raw);
    if (
      path === "/update-password" ||
      path.startsWith("/update-password?")
    ) {
      return "/update-password";
    }
    if (isSafeOAuthNextPath(path)) {
      return path;
    }
  }

  return "/dashboard";
}

export function buildOAuthCallbackUrl(): string {
  const { origin, pathname, search } = window.location;

  if (pathname === "/login" || pathname.startsWith("/login/")) {
    const params = new URLSearchParams(search);
    const next = params.get("next")?.trim() ?? "";
    const destination = isSafeOAuthNextPath(next) ? next : "/dashboard";
    rememberOAuthNext(destination);
    return buildExactOAuthCallbackUrl(origin);
  }

  const canReturn = RETURNABLE_PATH_PREFIXES.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`)
  );

  if (canReturn) {
    rememberOAuthNext(pathname);
  } else {
    rememberOAuthNext("/dashboard");
  }

  return buildExactOAuthCallbackUrl(origin);
}

export const AVAILABILITY_STATUS_OPTIONS = [
  "Available Now",
  "Interviewing",
  "Not Available",
] as const;

export type AvailabilityStatus = (typeof AVAILABILITY_STATUS_OPTIONS)[number];

export const DEFAULT_AVAILABILITY_STATUS: AvailabilityStatus = "Available Now";

export function parseAvailabilityStatus(
  value: string | null | undefined
): AvailabilityStatus | null {
  const status = value?.trim();
  if (
    status &&
    AVAILABILITY_STATUS_OPTIONS.includes(status as AvailabilityStatus)
  ) {
    return status as AvailabilityStatus;
  }

  return null;
}

export function normalizeAvailabilityStatus(
  value: string | null | undefined
): AvailabilityStatus {
  return parseAvailabilityStatus(value) ?? DEFAULT_AVAILABILITY_STATUS;
}

export type AvailabilitySidebarTone = "emerald" | "violet" | "zinc";

export function getAvailabilitySidebarPresentation(
  value: string | null | undefined
): { label: string; tone: AvailabilitySidebarTone; dotClass: string } {
  const status = parseAvailabilityStatus(value);

  if (status === "Available Now") {
    return {
      label: "Available Now",
      tone: "emerald",
      dotClass: "bg-emerald-500",
    };
  }

  if (status === "Interviewing") {
    return {
      label: "Interviewing",
      tone: "violet",
      dotClass: "bg-violet-500",
    };
  }

  if (status === "Not Available") {
    return {
      label: "Not Available",
      tone: "zinc",
      dotClass: "bg-zinc-500",
    };
  }

  return {
    label: "Open to roles",
    tone: "emerald",
    dotClass: "bg-emerald-500",
  };
}

export function getAvailabilityBadgeClass(availability: string): string {
  if (availability === "Available Now") {
    return "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20";
  }

  if (availability === "Interviewing") {
    return "bg-violet-500/10 text-violet-400 border border-violet-500/20";
  }

  return "bg-slate-800 text-slate-500 border border-slate-700/50";
}

