  "React Native",
  "Terraform",
  "GraphQL",
] as const;

export type CoreSkill = (typeof CORE_SKILL_OPTIONS)[number];

const CORE_SKILL_LOOKUP = new Map(
  CORE_SKILL_OPTIONS.map((skill) => [skill.toLowerCase(), skill])
);

export const CANDIDATE_SKILLS_PLACEHOLDER = "Search or type a skill (max 3)...";
export const CANDIDATE_SKILLS_LIMIT_TEXT =
  "Maximum of 3 specializations selected";
export const CANDIDATE_SKILLS_HELPER_TEXT = CANDIDATE_SKILLS_LIMIT_TEXT;

export const candidateSkillsSchema = z
  .array(z.string().trim().min(1))
  .min(MIN_CORE_SKILLS, "Select at least 1 core specialization.")
  .max(MAX_CORE_SKILLS, CANDIDATE_SKILLS_LIMIT_TEXT);

export function parseCandidateSkills(
  skills: string[] | string | null | undefined
): string[] {
  const raw = Array.isArray(skills)
    ? skills
    : typeof skills === "string"
      ? skills.split(",")
      : [];

  const seen = new Set<string>();
  const parsed: string[] = [];

  for (const value of raw) {
    const trimmed = value.trim();
    if (!trimmed) continue;

    const key = trimmed.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    parsed.push(CORE_SKILL_LOOKUP.get(key) ?? trimmed);
  }

  return parsed;
}

export function limitCandidateSkills(
  skills: string[] | string | null | undefined
): string[] {
  return parseCandidateSkills(skills).slice(0, MAX_CORE_SKILLS);
}

export function canonicalizeSkillLabel(value: string): string | null {
  const parsed = parseCandidateSkills([value]);
  return parsed[0] ?? null;
}

export function filterSkillSuggestions(
  query: string,
  selected: string[]
): string[] {
  const selectedKeys = new Set(
    selected.map((skill) => skill.trim().toLowerCase()).filter(Boolean)
  );
  const needle = query.trim().toLowerCase();

  return CORE_SKILL_OPTIONS.filter((option) => {
    if (selectedKeys.has(option.toLowerCase())) {
      return false;
    }

    if (!needle) {
      return true;
    }

    return option.toLowerCase().includes(needle);
  });
}

export function getCandidateSkillsValidationError(
  skills: string[] | string | null | undefined
): string | null {
  const result = candidateSkillsSchema.safeParse(parseCandidateSkills(skills));
  if (result.success) {
    return null;
  }

  return result.error.issues[0]?.message ?? CANDIDATE_SKILLS_HELPER_TEXT;
}

export function candidateSkillsEqual(
  left: string[] | string | null | undefined,
  right: string[] | string | null | undefined
): boolean {
  const a = parseCandidateSkills(left);
  const b = parseCandidateSkills(right);
  if (a.length !== b.length) {
    return false;
  }

  return a.every((skill, index) => skill === b[index]);
}

export function cn(
  ...classes: Array<string | false | null | undefined>
): string {
  return classes.filter(Boolean).join(" ");
}

import { describe, expect, it } from "vitest";
import {
  formatCodebaseBenchmark,
  getCalibratedBenchmark,
  VERIFIED_ENGINEERING_BENCHMARK,
} from "./codebase-benchmark";

describe("calibrated codebase benchmark", () => {
  it("maps score bands to industry reference labels", () => {
    expect(getCalibratedBenchmark(95).label).toBe("Top 1% Codebase Benchmark");
    expect(getCalibratedBenchmark(85).label).toBe("Top 10% Codebase Benchmark");
    expect(getCalibratedBenchmark(78).label).toBe("Top 25% Codebase Benchmark");
    expect(getCalibratedBenchmark(68).label).toBe("60th Percentile Benchmark");
    expect(getCalibratedBenchmark(58).label).toBe("35th Percentile Benchmark");
    expect(getCalibratedBenchmark(45).label).toBe("18th Percentile Benchmark");
    expect(getCalibratedBenchmark(44).label).toBe(
      "Tier III Benchmark (Baseline Architecture)"
    );
  });

  it("never includes live sample-size suffixes", () => {
    for (const score of [95, 85, 78, 68, 58, 45, 20]) {
      const label = getCalibratedBenchmark(score).label;
      expect(label).not.toMatch(/\(n\s*=/);
      expect(label).not.toMatch(/audited repos/i);
    }
  });

  it("formats null as the verified fallback", () => {
    expect(formatCodebaseBenchmark(null)).toBe(VERIFIED_ENGINEERING_BENCHMARK);
    expect(formatCodebaseBenchmark(undefined)).toBe(
      VERIFIED_ENGINEERING_BENCHMARK
    );
  });

  it("formats calibrated labels directly", () => {
    expect(formatCodebaseBenchmark(getCalibratedBenchmark(90))).toBe(
      "Top 10% Codebase Benchmark"
    );
  });
});

import { clampScore0to100 } from "@/lib/score-scale";

export const VERIFIED_ENGINEERING_BENCHMARK = "Verified Engineering Benchmark";

export type BenchmarkTier =
  | "Tier I - Staff-Grade Architecture"
  | "Tier I - Production Autonomous"
  | "Tier II - Advanced Full-Stack"
  | "Tier II - Competent Mid-Level"
  | "Tier II - Supervised Implementation"
  | "Tier III - Baseline MVP"
  | "Tier III - Baseline Architecture";

export type CodebaseBenchmark = {
  /** Calibrated outperformance percentile on the industry reference curve. */
  topPercentile: number;
  /** Hiring-facing primary label (no sample-size suffix). */
  label: string;
  tier: BenchmarkTier;
  /** Always null — retained so older payloads deserialize safely. */
  totalAudits: null;
};

/** Deterministic industry reference curve for production full-stack repos. */
export function getCalibratedBenchmark(score: number): CodebaseBenchmark {
  const s = clampScore0to100(score);

  if (s >= 92) {
    return {
      topPercentile: 99,
      label: "Top 1% Codebase Benchmark",
      tier: "Tier I - Staff-Grade Architecture",
      totalAudits: null,
    };
  }
  if (s >= 85) {
    return {
      topPercentile: 90,
      label: "Top 10% Codebase Benchmark",
      tier: "Tier I - Production Autonomous",
      totalAudits: null,
    };
  }
  if (s >= 78) {
    return {
      topPercentile: 75,
      label: "Top 25% Codebase Benchmark",
      tier: "Tier II - Advanced Full-Stack",
      totalAudits: null,
    };
  }
  if (s >= 68) {
    return {
      topPercentile: 60,
      label: "60th Percentile Benchmark",
      tier: "Tier II - Competent Mid-Level",
      totalAudits: null,
    };
  }
  if (s >= 58) {
    return {
      topPercentile: 35,
      label: "35th Percentile Benchmark",
      tier: "Tier II - Supervised Implementation",
      totalAudits: null,
    };
  }
  if (s >= 45) {
    return {
      topPercentile: 18,
      label: "18th Percentile Benchmark",
      tier: "Tier III - Baseline MVP",
      totalAudits: null,
    };
  }
  return {
    topPercentile: 5,
    label: "Tier III Benchmark (Baseline Architecture)",
    tier: "Tier III - Baseline Architecture",
    totalAudits: null,
  };
}

export function formatCodebaseBenchmark(
  benchmark: CodebaseBenchmark | null | undefined
): string {
  if (!benchmark?.label?.trim()) {
    return VERIFIED_ENGINEERING_BENCHMARK;
  }
  return benchmark.label;
}

/** Sync alias for call sites that previously awaited a DB lookup. */
export function loadCodebaseBenchmark(currentScore: number): CodebaseBenchmark {
  return getCalibratedBenchmark(currentScore);
}

