 * Preference label for sidebar / settings.
 * Pass already mode-gated engagement flags (`canToggle* && openTo*`) so the
 * header pill never shows Full-Time/Contract when that mode is locked.
 */
export function getPreferenceAvailabilityPresentation(
  openToFulltime: boolean,
  openToContract: boolean,
  _isPublishEligible = false
): PreferenceAvailabilityPresentation {
  if (openToFulltime && openToContract) {
    return {
      label: "● Full-Time + Contract",
      tone: "emerald",
      dotClass: "bg-emerald-500",
      isLive: true,
      statusBadge: "Live",
    };
  }
  if (openToFulltime) {
    return {
      label: "● Full-Time Only",
      tone: "emerald",
      dotClass: "bg-emerald-500",
      isLive: true,
      statusBadge: "Live",
    };
  }
  if (openToContract) {
    return {
      label: "● Contract Sprints Only",
      tone: "emerald",
      dotClass: "bg-emerald-500",
      isLive: true,
      statusBadge: "Live",
    };
  }
  return {
    label: "○ Verification Required (Private)",
    tone: "zinc",
    dotClass: "bg-zinc-500",
    isLive: false,
    statusBadge: "Not live",
  };
}

import {
  getStandardEmailValidationMessage,
  isStandardEmail,
  normalizeEmail,
} from "@/lib/validate-email";

/** Consumer inboxes that cannot verify an employer as a company. */
export const FREE_WEBMAIL_DOMAINS = [
  "gmail.com",
  "yahoo.com",
  "hotmail.com",
  "outlook.com",
  "icloud.com",
] as const;

const FREE_WEBMAIL_DOMAIN_SET = new Set<string>(FREE_WEBMAIL_DOMAINS);

export const CORPORATE_WORK_EMAIL_MESSAGE =
  "Use a corporate work email. Personal inboxes (Gmail, Yahoo, Hotmail, Outlook, and iCloud) are not accepted.";

export function extractEmailDomain(email: string): string | null {
  const normalized = normalizeEmail(email).toLowerCase();
  const at = normalized.lastIndexOf("@");
  if (at <= 0 || at === normalized.length - 1) {
    return null;
  }

  const domain = normalized.slice(at + 1).replace(/\.+$/, "");
  if (!domain || !domain.includes(".")) {
    return null;
  }

  return domain;
}

export function isFreeWebmailDomain(domain: string | null | undefined): boolean {
  if (!domain) {
    return false;
  }

  return FREE_WEBMAIL_DOMAIN_SET.has(domain.trim().toLowerCase());
}

export function isCorporateWorkEmail(email: string | null | undefined): boolean {
  if (!email || !isStandardEmail(email)) {
    return false;
  }

  const domain = extractEmailDomain(email);
  if (!domain) {
    return false;
  }

  return !isFreeWebmailDomain(domain);
}

export function getCorporateWorkEmailValidationMessage(
  email: string
): string | null {
  const basic = getStandardEmailValidationMessage(email);
  if (basic) {
    return basic;
  }

  if (!isCorporateWorkEmail(email)) {
    return CORPORATE_WORK_EMAIL_MESSAGE;
  }

  return null;
}

import type { SupabaseClient } from "@supabase/supabase-js";

export const DAILY_SCAN_LIMIT = 10;

export const DAILY_LIMIT_API_MESSAGE =
  "Daily limit reached (10/10). Resets at midnight.";

export const DAILY_LIMIT_UI_MESSAGE =
  "Daily limit reached (10/10). Resets tomorrow.";

export type DailyScanUsage = {
  daily_scans: number;
  last_scan_date: string | null;
  limit_reached: boolean;
  remaining: number;
};

function todayUtcDate(): string {
  return new Date().toISOString().slice(0, 10);
}

function normalizeScanDate(value: string | null | undefined): string | null {
  if (typeof value !== "string") {
    return null;
  }

  const trimmed = value.trim();
  return trimmed.length >= 10 ? trimmed.slice(0, 10) : null;
}

export function resolveDailyScanUsage(
  dailyScans: number | null | undefined,
  lastScanDate: string | null | undefined,
  today = todayUtcDate()
): DailyScanUsage {
  const storedDate = normalizeScanDate(lastScanDate);
  const isSameDay = storedDate === today;
  const parsedCount =
    typeof dailyScans === "number" && Number.isFinite(dailyScans)
      ? Math.round(dailyScans)
      : 0;
  const count = isSameDay ? Math.max(0, parsedCount) : 0;
  const remaining = Math.max(0, DAILY_SCAN_LIMIT - count);

  return {
    daily_scans: count,
    last_scan_date: storedDate,
    limit_reached: count >= DAILY_SCAN_LIMIT,
    remaining,
  };
}

export async function loadDailyScanUsage(
  supabase: SupabaseClient,
  userId: string
): Promise<{ usage: DailyScanUsage; error: string | null }> {
  try {
    const { data, error } = await supabase
      .from("profiles")
      .select("daily_scans, last_scan_date")
      .eq("id", userId)
      .maybeSingle();

    if (error) {
      return {
        usage: resolveDailyScanUsage(0, null),
        error: error.message,
      };
    }

    return {
      usage: resolveDailyScanUsage(data?.daily_scans, data?.last_scan_date),
      error: null,
    };
  } catch (error) {
    console.error("[daily-scan-limit] load failed:", error);
    return {
      usage: resolveDailyScanUsage(0, null),
      error:
        error instanceof Error ? error.message : "Could not load scan usage.",
    };
  }
}

export async function incrementDailyScanUsage(
  supabase: SupabaseClient,
  userId: string,
  current: DailyScanUsage
): Promise<DailyScanUsage> {
  const today = todayUtcDate();
  const nextCount = current.daily_scans + 1;

  try {
    const { error } = await supabase
      .from("profiles")
      .update({
        daily_scans: nextCount,
        last_scan_date: today,
      })
      .eq("id", userId);

    if (error) {
      console.error("[daily-scan-limit] increment failed:", error);
      return current;
    }

    return resolveDailyScanUsage(nextCount, today, today);
  } catch (error) {
    console.error("[daily-scan-limit] increment threw:", error);
    return current;
  }
}

