export const EMPLOYER_VERIFICATION_TTL_MS = 24 * 60 * 60 * 1000;

export function generateEmployerVerificationToken(): {
  token: string;
  tokenHash: string;
} {
  const token = randomBytes(32).toString("base64url");
  return {
    token,
    tokenHash: hashEmployerVerificationToken(token),
  };
}

export function hashEmployerVerificationToken(token: string): string {
  return createHash("sha256").update(token, "utf8").digest("hex");
}

export function buildEmployerVerificationConfirmUrl(
  origin: string,
  token: string
): string {
  // Frontend page — not the API — so corporate spam filters don't flag a raw API URL.
  const url = new URL("/verify-email", normalizeSiteUrl(origin));
  url.searchParams.set("token", token);
  return url.toString();
}

import {
  computeAuditScoreBonus,
  extractAuditedSkills,
  parseAuditBreakdownSignals,
  summarizeGithubAudit,
} from "@/lib/job-match";
import {
  clampMatchPercentage,
  normalizeStringArray,
  scoreTalentMatch,
  type MatchCandidatePayload,
  type MatchJobPayload,
  type MatchResult,
} from "@/lib/match-heuristic";

export type EmployerMatchCandidatePayload = MatchCandidatePayload & {
  experience_level?: string;
  experienceLevel?: string;
  auditScore?: number | null;
  productionScore?: number | null;
  auditBreakdown?: unknown;
  githubAudit?: unknown;
  github_url?: string;
  githubUrl?: string;
};

const BIO_JUNK_PATTERNS = [
  /^(n\/?a|none|nil|null|test|asdf|lorem|ipsum|placeholder|todo|tbd)\b/i,
  /^(hi|hello|hey)[\s,.!]*$/i,
  /^(looking for|open to|seeking)\s+(work|opportunities?|roles?)[\s.]*$/i,
];

export type BioQuality = {
  substantive: boolean;
  /** severe = empty/placeholder (drawer shows amber + single executive line). */
  severity: "none" | "mild" | "severe";
  penalty: number;
  flag: string | null;
};

/** Empty, tiny, or placeholder bios drag down role fit and get flagged. */
export function assessBioQuality(bio: string | undefined | null): BioQuality {
  const text = (bio ?? "").replace(/\s+/g, " ").trim();
  if (!text) {
    return {
      substantive: false,
      severity: "severe",
      penalty: 18,
      flag: "Empty bio",
    };
  }
  if (text.length < 40 || BIO_JUNK_PATTERNS.some((re) => re.test(text))) {
    return {
      substantive: false,
      severity: "severe",
      penalty: 12,
      flag: "Placeholder or thin bio",
    };
  }
  // Very short "real" bios still under-inform JD fit.
  if (text.length < 80) {
    return {
      substantive: false,
      severity: "mild",
      penalty: 6,
      flag: "Short bio",
    };
  }
  return { substantive: true, severity: "none", penalty: 0, flag: null };
}

function tokenizeForFit(text: string): string[] {
  return text
    .toLowerCase()
    .split(/[^a-z0-9+#]+/g)
    .map((t) => t.replace(/^\.+|\.+$/g, ""))
    .filter((t) => t.length >= 3);
}

function resolveExperienceLevel(
  candidate: EmployerMatchCandidatePayload
): string {
  return (
    candidate.experience_level?.trim() ||
    candidate.experienceLevel?.trim() ||
    ""
  );
}

function resolveAuditScore(
  candidate: EmployerMatchCandidatePayload
): number | null {
  for (const value of [candidate.auditScore, candidate.productionScore]) {
    if (typeof value === "number" && Number.isFinite(value)) {
      return Math.round(value);
    }
  }
  return null;
}

/**
 * Profile narrative + experience vs full job description (not tags alone).
 * Returns 0–100.
 */
export function scoreProfileAgainstJobDescription(
  candidate: EmployerMatchCandidatePayload,
  job: MatchJobPayload
): number {
  const profileText = [
    candidate.title ?? "",
    candidate.bio ?? "",
    candidate.degree ?? "",
    resolveExperienceLevel(candidate),
    normalizeStringArray(candidate.skills).join(" "),
  ]
    .join(" ")
    .trim();

  const jobText = [
    job.title ?? "",
    job.company ?? "",
    job.location ?? "",
    job.description ?? "",
    job.searchQuery ?? "",
    ...normalizeStringArray(job.techStack ?? job.tech_stack),
    ...normalizeStringArray(job.requiredSkills ?? job.required_skills),
    ...normalizeStringArray(job.tags),
  ]
    .join(" ")
    .trim();

  if (!jobText || !profileText) {
    return 0;
  }

  const profileTokens = [...new Set(tokenizeForFit(profileText))];
  const jobTokens = [...new Set(tokenizeForFit(jobText))];
  if (jobTokens.length === 0 || profileTokens.length === 0) {
    return 0;
  }

  // Prefer JD description substance: weight longer description tokens.
  const descriptionTokens = [
    ...new Set(tokenizeForFit(job.description ?? "")),
  ];
  const primaryPool =
    descriptionTokens.length >= 8 ? descriptionTokens : jobTokens;

  let hits = 0;
  for (const req of primaryPool) {
    if (
      profileTokens.some(
        (tok) =>
          tok === req ||
          (tok.length >= 4 &&
            req.length >= 4 &&
            (tok.includes(req) || req.includes(tok)))
      )
    ) {
      hits += 1;
    }
  }

  const overlap = hits / primaryPool.length;
  // Bio length signal: substantive bios unlock the upper band of this pillar.
  const bioLen = (candidate.bio ?? "").trim().length;
  const narrativeBoost = bioLen >= 120 ? 8 : bioLen >= 80 ? 4 : 0;
  return clampMatchPercentage(Math.round(overlap * 92) + narrativeBoost);
}

/** Verified profile skills plus technologies inferred from audit payloads. */
export function resolveEmployerMatchSkills(
  candidate: EmployerMatchCandidatePayload
): string[] {
  const fromAudit = extractAuditedSkills({
    skills: candidate.skills,
    githubAudit: candidate.githubAudit,
  });
  if (fromAudit.length > 0) {
    return fromAudit;
  }
  return normalizeStringArray(candidate.skills);
}

export type EmployerVerifiedMatchContext = {
  verifiedTechnologies: string[];
  experienceLevel: string;
  auditScore: number | null;
  github: ReturnType<typeof summarizeGithubAudit>;
  productionSignals: ReturnType<typeof parseAuditBreakdownSignals> & {
    hasCiSignal: boolean;
    hasTestSignal: boolean;
  };
};

export function buildEmployerVerifiedMatchContext(
  candidate: EmployerMatchCandidatePayload
): EmployerVerifiedMatchContext {
  const breakdown = parseAuditBreakdownSignals(candidate.auditBreakdown);
  const github = summarizeGithubAudit(candidate.githubAudit);
  const auditScore = resolveAuditScore(candidate);

  return {
    verifiedTechnologies: resolveEmployerMatchSkills(candidate),
    experienceLevel: resolveExperienceLevel(candidate),
    auditScore,
    github,
    productionSignals: {
      ...breakdown,
      hasCiSignal:
        (breakdown.ciCdScore !== null && breakdown.ciCdScore > 0) ||
        Boolean(github),
      hasTestSignal:
        breakdown.testDensity !== null && breakdown.testDensity > 0,
    },
  };
}

/**
 * Employer talent-pool match % — TypeScript only.
 * Skill overlap + profile/bio vs full JD + experience bump + bounded audit bonus
 * − bio substance penalty.
 */
export function buildDeterministicEmployerMatch(
  candidate: EmployerMatchCandidatePayload,
  job: MatchJobPayload
): MatchResult {
  const verifiedSkills = resolveEmployerMatchSkills(candidate);
  const experienceLevel = resolveExperienceLevel(candidate);
  const auditScore = resolveAuditScore(candidate);
  const bioQuality = assessBioQuality(candidate.bio);

  const base = scoreTalentMatch(
    {
      title: candidate.title,
      bio: candidate.bio,
      skills: verifiedSkills,
      degree: candidate.degree,
    },
    job
  );

  const requirementCount =
    base.matching_skills.length + base.missing_skills.length;

  let skillScore = 0;
  if (requirementCount === 0) {
    // No explicit job stack — mirror candidate job-match conservative floor.
    skillScore = experienceLevel
      ? 35
      : verifiedSkills.length > 0
        ? 28
        : 20;
  } else {
    skillScore = Math.round(
      (base.matching_skills.length / requirementCount) * 80
    );
  }

  const profileJdScore = scoreProfileAgainstJobDescription(candidate, job);
  // Blend: stack proof still matters, but bio/background vs JD is first-class.
  let match_percentage = Math.round(skillScore * 0.5 + profileJdScore * 0.5);

  if (experienceLevel) {
    match_percentage += 8;
  }

  match_percentage += computeAuditScoreBonus(auditScore);
  match_percentage -= bioQuality.penalty;
  match_percentage = clampMatchPercentage(match_percentage);

  const roleLabel =
    job.title?.trim() ||
    (job.searchQuery?.trim() ? `"${job.searchQuery.trim()}"` : "this search");

  // One executive line. Severe bio flags use a single verdict — no skill/JD echo.
  // Do not append Flag text here; the drawer owns the amber callout.
  let reasoning: string;
  if (bioQuality.severity === "severe") {
    reasoning = `Candidate profile lacks verifiable background narrative against ${roleLabel} criteria.`;
  } else if (base.matching_skills.length > 0) {
    reasoning = `Verified overlap on ${base.matching_skills
      .slice(0, 3)
      .join(", ")} for ${roleLabel}.`;
    if (profileJdScore < 55) {
      reasoning +=
        " Profile narrative only partially aligns with the role criteria.";
    }
  } else if (requirementCount > 0) {
    reasoning = `Limited verified skill overlap with ${roleLabel}.`;
    if (profileJdScore < 30) {
      reasoning += " Profile narrative does not align with the role criteria.";
    }
  } else {
    reasoning =
      "No active job stack yet — score reflects profile depth and audit confidence.";
  }

  return {
    match_percentage,
    reasoning,
    matching_skills: base.matching_skills,
    missing_skills: base.missing_skills,
  };
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { isSupabaseSchemaError } from "@/lib/supabase-schema-errors";

export type EmployerNotificationRow = {
  id: string;
  message: string;
  job_id: string | null;
  is_read: boolean;
  created_at: string;
};

export async function fetchEmployerNotifications(
  supabase: SupabaseClient,
  userId: string
): Promise<EmployerNotificationRow[]> {
  try {
    const { data, error } = await supabase
      .from("notifications")
      .select("id, message, job_id, is_read, created_at")
      .eq("user_id", userId)
      .order("created_at", { ascending: false })
      .limit(20);

    if (error) {
      if (!isSupabaseSchemaError(error)) {
        console.warn("Failed to fetch notifications:", error.message);
      }
      return [];
    }

    return (data ?? []) as EmployerNotificationRow[];
  } catch (error) {
    console.error(
      "[employer-notifications] fetchEmployerNotifications failed:",
      error
    );
    return [];
  }
}

export async function markEmployerNotificationRead(
  supabase: SupabaseClient,
  notificationId: string,
  userId: string
): Promise<boolean> {
  try {
    const { error } = await supabase
      .from("notifications")
      .update({ is_read: true })
      .eq("id", notificationId)
      .eq("user_id", userId);

    if (error && !isSupabaseSchemaError(error)) {
      console.warn("Failed to mark notification as read:", error.message);
      return false;
    }

    return !error;
  } catch (error) {
    console.error(
      "[employer-notifications] markEmployerNotificationRead failed:",
      error
    );
    return false;
  }
}

export async function createEmployerNotification(
  supabase: SupabaseClient,
  notification: {
    userId: string;
    jobId: string;
    title?: string;
    message: string;
  }
): Promise<boolean> {
  try {
    const { error } = await supabase.from("notifications").insert({
      user_id: notification.userId,
      job_id: notification.jobId,
      title: notification.title ?? "New Candidate Interest",
      message: notification.message,
      is_read: false,
    });

    if (error) {
      if (!isSupabaseSchemaError(error)) {
        console.warn("Failed to create employer notification:", error.message);
      }
      return false;
    }

    return true;
  } catch (error) {
    console.error(
      "[employer-notifications] createEmployerNotification failed:",
      error
    );
    return false;
  }
}

import { describe, expect, it } from "vitest";
import {
  assignRecommendedRoleBand,
  finalizeExecutiveBrief,
  parseExecutiveBrief,
} from "./executive-brief";

describe("assignRecommendedRoleBand", () => {
  it("maps Contract scores onto Verified / Elite / Supervised bands", () => {
    expect(
      assignRecommendedRoleBand({
        productionScore: 88,
        auditMode: "contract",
      })
    ).toBe("Elite Sprint Contractor");
    expect(
      assignRecommendedRoleBand({
        productionScore: 76,
        auditMode: "contract",
      })
    ).toBe("Verified Sprint Builder");
    expect(
      assignRecommendedRoleBand({
        productionScore: 68,
        auditMode: "contract",
      })
    ).toBe("Supervised Feature Builder");
  });

  it("never labels 80+ Contract scores as Mid-Level or Early-Stage Generalist", () => {
    const band = assignRecommendedRoleBand({
      productionScore: 82,
      testing: 70,
      resilience: 65,
      auditMode: "contract",
    });
    expect(band).toBe("Elite Sprint Contractor");
    expect(band).not.toBe("Mid-Level");
    expect(band).not.toBe("Early-Stage Generalist");
  });

  it("uses Needs Hardening below 60 in Contract mode", () => {
    expect(
      assignRecommendedRoleBand({
        productionScore: 40,
        testing: 10,
        resilience: 50,
        auditMode: "contract",
      })
    ).toBe("Needs Hardening");
  });

  it("mirrors Full-Time tiers when auditMode is fulltime", () => {
    expect(
      assignRecommendedRoleBand({
        productionScore: 82,
        auditMode: "fulltime",
      })
    ).toBe("Production-Grade / Core Lead");
    expect(
      assignRecommendedRoleBand({
        productionScore: 74,
        auditMode: "fulltime",
      })
    ).toBe("Mid/Senior Production-Ready");
  });
});

describe("finalizeExecutiveBrief", () => {
  it("overwrites invalid model bands with the metric tier by default", () => {
    const brief = finalizeExecutiveBrief({
      draft: {
        employerSummary: "Founders should treat this as a scoped product bet.",
        developerSummary: "Split the data client out of the page component.",
        recommendedRoleBand: "Mid-Level",
      },
      productionScore: 60,
      architectureScore: 70,
      testScore: 20,
      devopsScore: 40,
      resilienceScore: 50,
      isUpstreamDerivative: false,
      auditMode: "contract",
    });

    expect(brief.employerSummary).toMatch(/Founders should treat/);
    expect(brief.developerSummary).toMatch(/data client/);
    expect(brief.recommendedRoleBand).toBe("Supervised Feature Builder");
  });

  it("keeps a valid Gemini hiring verdict when preferModelRoleBand is true", () => {
    const brief = finalizeExecutiveBrief({
      draft: {
        employerSummary:
          "Strong JD narrative fit for Frontend; codebase proof is mid-tier.",
        developerSummary: "Tighten test density on the checkout route.",
        recommendedRoleBand: "Verified Sprint Builder",
      },
      productionScore: 88,
      architectureScore: 90,
      testScore: 85,
      devopsScore: 80,
      resilienceScore: 88,
      isUpstreamDerivative: false,
      auditMode: "contract",
      preferModelRoleBand: true,
    });

    // Metric tier would be Elite (88), but overall fit verdict stays model-chosen.
    expect(brief.recommendedRoleBand).toBe("Verified Sprint Builder");
    expect(brief.employerSummary).toMatch(/JD narrative fit/);
  });

  it("falls back to metric tier when preferModelRoleBand is true but band is invalid", () => {
    const brief = finalizeExecutiveBrief({
      draft: {
        employerSummary: "Fit is unclear.",
        developerSummary: "Add CI gates.",
        recommendedRoleBand: "Mid-Level",
      },
      productionScore: 88,
      architectureScore: 90,
      testScore: 85,
      devopsScore: 80,
      resilienceScore: 88,
      isUpstreamDerivative: false,
      auditMode: "contract",
      preferModelRoleBand: true,
    });

    expect(brief.recommendedRoleBand).toBe("Elite Sprint Contractor");
  });

  it("fills empty summaries and syncs 80+ to Elite Sprint Contractor", () => {
    expect(parseExecutiveBrief(null)).toBeNull();
    const brief = finalizeExecutiveBrief({
      draft: null,
      productionScore: 88,
      architectureScore: 80,
      testScore: 70,
      devopsScore: 85,
      resilienceScore: 90,
      isUpstreamDerivative: true,
      auditMode: "contract",
    });
    expect(brief.recommendedRoleBand).toBe("Elite Sprint Contractor");
    expect(brief.employerSummary).toMatch(/88\/100/);
    expect(brief.employerSummary).toMatch(/30-point/);
    expect(brief.developerSummary.length).toBeGreaterThan(40);
  });
});

import {
  assignAuditTier,
  CONTRACT_TIER_ELITE,
  CONTRACT_TIER_HARDENING,
  CONTRACT_TIER_SUPERVISED,
  CONTRACT_TIER_VERIFIED,
  DEFAULT_AUDIT_MODE,
  normalizeAuditMode,
  type AuditMode,
} from "@/lib/audit-mode";
/** Founder Verdict / Contract tier titles (synced with assignAuditTier). */
export const ROLE_BANDS = [
  CONTRACT_TIER_ELITE,
  CONTRACT_TIER_VERIFIED,
  CONTRACT_TIER_SUPERVISED,
  CONTRACT_TIER_HARDENING,
  "Production-Grade / Core Lead",
  "Mid/Senior Production-Ready",
  "Needs Refinement",
] as const;

export type RecommendedRoleBand = (typeof ROLE_BANDS)[number];

export type ExecutiveBrief = {
  employerSummary: string;
  developerSummary: string;
  recommendedRoleBand: RecommendedRoleBand;
};

/** Talent-network bar — Verified Sprint Builder and above. */
export const ROLE_BAND_SCORE_THRESHOLD = 72;

export function isRecommendedRoleBand(
  value: unknown
): value is RecommendedRoleBand {
  return (
    typeof value === "string" &&
    (ROLE_BANDS as readonly string[]).includes(value)
  );
}

/**
 * Founder Hiring Verdict badge — mirrors mode-aware audit tiers so an 80+
 * Contract score never shows legacy "Mid-Level" / "Early-Stage Generalist".
 */
export function assignRecommendedRoleBand(input: {
  productionScore: number;
  testing?: number;
  resilience?: number;
  auditMode?: AuditMode | string;
}): RecommendedRoleBand {
  const mode = normalizeAuditMode(input.auditMode ?? DEFAULT_AUDIT_MODE);
  const tier = assignAuditTier(mode, input.productionScore);
  if (isRecommendedRoleBand(tier)) {
    return tier;
  }
  return CONTRACT_TIER_HARDENING;
}

function asSummary(value: unknown): string {
  if (typeof value !== "string") {
    return "";
  }
  return value.replace(/\s+/g, " ").trim();
}

export function parseExecutiveBrief(value: unknown): ExecutiveBrief | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }
  const record = value as Record<string, unknown>;
  const employerSummary = asSummary(record.employerSummary);
  const developerSummary = asSummary(record.developerSummary);
  if (!employerSummary && !developerSummary) {
    return null;
  }
  return {
    employerSummary,
    developerSummary,
    recommendedRoleBand: isRecommendedRoleBand(record.recommendedRoleBand)
      ? record.recommendedRoleBand
      : CONTRACT_TIER_HARDENING,
  };
}

function fallbackSummaries(input: {
  productionScore: number;
  architectureScore: number;
  testScore: number;
  devopsScore: number;
  resilienceScore: number;
  isUpstreamDerivative: boolean;
  recommendedRoleBand: RecommendedRoleBand;
}): Pick<ExecutiveBrief, "employerSummary" | "developerSummary"> {
  const upstream = input.isUpstreamDerivative
    ? " The repository is an upstream fork or generated template, and the headline already includes the 30-point deduction."
    : "";
  return {
    employerSummary: `Headline production score is ${input.productionScore}/100, with architecture ${input.architectureScore}, tests ${input.testScore}, DevOps ${input.devopsScore}, and resilience ${input.resilienceScore}.${upstream} The Founder Verdict is ${input.recommendedRoleBand}.`,
    developerSummary: `Peer review of the file tree: tests are ${input.testScore}/100 and resilience is ${input.resilienceScore}/100.${upstream} The highest-leverage fix is the weaker of those two pillars, because that is what keeps the verdict at ${input.recommendedRoleBand}.`,
  };
}

/**
 * Keep the model's sentences.
 * When preferModelRoleBand is true (job-aware screening), keep Gemini's valid
 * hiring verdict band. Repo metrics remain the fallback / technical-proof band only.
 */
export function finalizeExecutiveBrief(input: {
  draft: unknown;
  productionScore: number;
  architectureScore: number;
  testScore: number;
  devopsScore: number;
  resilienceScore: number;
  isUpstreamDerivative: boolean;
  auditMode?: AuditMode | string;
  /** Default false preserves audit-route metric tiers. Screen job_aware passes true. */
  preferModelRoleBand?: boolean;
}): ExecutiveBrief {
  const metricBand = assignRecommendedRoleBand({
    productionScore: input.productionScore,
    testing: input.testScore,
    resilience: input.resilienceScore,
    auditMode: input.auditMode,
  });
  const parsed = parseExecutiveBrief(input.draft);
  // Prefer an explicitly valid model band when asked; parseExecutiveBrief maps
  // invalid bands to HARDENING, so re-check the raw draft for a real ROLE_BAND.
  const rawBand =
    input.draft &&
    typeof input.draft === "object" &&
    !Array.isArray(input.draft)
      ? (input.draft as Record<string, unknown>).recommendedRoleBand
      : undefined;
  const recommendedRoleBand =
    input.preferModelRoleBand && isRecommendedRoleBand(rawBand)
      ? rawBand
      : metricBand;

  const fallback = fallbackSummaries({
    ...input,
    recommendedRoleBand,
  });
  return {
    employerSummary: parsed?.employerSummary || fallback.employerSummary,
    developerSummary: parsed?.developerSummary || fallback.developerSummary,
    recommendedRoleBand,
  };
}

export function deterministicMetricsPayload(input: {
  productionScore: number;
  isUpstreamDerivative: boolean;
  architectureScore: number;
  testScore: number;
  devopsScore: number;
  resilienceScore: number;
  auditMode?: string;
  overallScore?: number;
  tier?: string;
  breakdown?: unknown;
  /**
   * When true, roleBandRule tells the model the band is overall hiring fit,
   * not a copy of the technical tier.
   */
  hiringVerdictFromFit?: boolean;
}) {
  const mode = normalizeAuditMode(input.auditMode ?? DEFAULT_AUDIT_MODE);
  const tier =
    input.tier ?? assignAuditTier(mode, input.overallScore ?? input.productionScore);
  const fitRule =
    'recommendedRoleBand is the OVERALL hiring verdict for this candidate vs the target role (bio, experience, skills, JD requirements, with repo audit as technical proof only). Choose from the allowed band strings. Do NOT copy "tier" blindly — a strong repo with a weak JD/profile fit must not get Elite/Core Lead.';
  const metricRule =
    mode === "fulltime"
      ? 'Copy tier as recommendedRoleBand. Full-time: "Production-Grade / Core Lead" (>= 80), "Mid/Senior Production-Ready" (70-79), "Needs Refinement" (< 70). Do not invent Mid-Level or Early-Stage Generalist.'
      : 'Copy tier as recommendedRoleBand. Contract: "Elite Sprint Contractor" (>= 80), "Verified Sprint Builder" (72-79), "Supervised Feature Builder" (60-71), "Needs Hardening" (< 60). Do not invent Mid-Level or Early-Stage Generalist.';
  return {
    productionScore: input.productionScore,
    overallScore: input.overallScore ?? input.productionScore,
    auditMode: input.auditMode ?? null,
    tier,
    breakdown: input.breakdown ?? null,
    is_upstream_derivative: input.isUpstreamDerivative,
    architectureScore: input.architectureScore,
    testScore: input.testScore,
    devopsScore: input.devopsScore,
    resilienceScore: input.resilienceScore,
    securityScore: input.resilienceScore,
    toolingScore: input.devopsScore,
    roleBandRule: input.hiringVerdictFromFit ? fitRule : metricRule,
    technicalProofNote:
      "productionScore and pillar scores are the codebase/technical-proof pillar only; they are not the hiring verdict by themselves.",
  };
}

export const EXPERIENCE_LEVEL_OPTIONS = [
  "Student / Intern",
  "Junior / Entry-Level",
  "Mid-Level",
  "Senior+",
] as const;

export type ExperienceLevel = (typeof EXPERIENCE_LEVEL_OPTIONS)[number];

