        user({ app_metadata: { provider: "email", providers: ["email"] } })
      )
    ).toBe(false);
  });
});

import type { SupabaseClient, User } from "@supabase/supabase-js";
import { isSupabaseSchemaError } from "@/lib/supabase-schema-errors";

export type GitHubProfileLink = {
  github_username: string | null;
  github_verified: boolean;
};

function firstUsername(values: unknown[]): string | null {
  for (const value of values) {
    if (typeof value !== "string") {
      continue;
    }
    const trimmed = value.trim().replace(/^@/, "");
    if (trimmed) {
      return trimmed;
    }
  }
  return null;
}

/** GitHub login from a Supabase user (identity first, then user_metadata). */
export function githubUsernameFromUser(
  user: User | null | undefined
): string | null {
  if (!user) {
    return null;
  }

  const identity = user.identities?.find((item) => item.provider === "github");
  const identityData = (identity?.identity_data ?? {}) as Record<string, unknown>;
  const meta = (user.user_metadata ?? {}) as Record<string, unknown>;

  return firstUsername([
    identityData.user_name,
    identityData.preferred_username,
    identityData.login,
    meta.user_name,
    meta.preferred_username,
    meta.login,
    meta.github_username,
    meta.github,
  ]);
}

export function userHasGitHubIdentity(
  user: User | null | undefined
): boolean {
  if (!user) {
    return false;
  }

  if (user.identities?.some((item) => item.provider === "github")) {
    return true;
  }

  const app = (user.app_metadata ?? {}) as Record<string, unknown>;
  if (app.provider === "github") {
    return true;
  }

  return (
    Array.isArray(app.providers) &&
    app.providers.some((provider) => provider === "github")
  );
}

/** Profile GitHub link derived from the current auth user. */
export function githubLinkFromUser(
  user: User | null | undefined
): GitHubProfileLink {
  if (!userHasGitHubIdentity(user)) {
    return { github_username: null, github_verified: false };
  }

  return {
    github_username: githubUsernameFromUser(user),
    github_verified: true,
  };
}

export async function syncGitHubIdentityToProfile(
  supabase: Pick<SupabaseClient, "from">,
  user: User | null | undefined
): Promise<GitHubProfileLink | null> {
  try {
    if (!user?.id) {
      return null;
    }

    const link = githubLinkFromUser(user);
    // Never wipe an existing linked identity when the current session has no
    // GitHub provider (e.g. email/Google session after a prior GitHub link).
    if (!link.github_verified || !link.github_username?.trim()) {
      return link;
    }

    const { error } = await supabase
      .from("profiles")
      .update({
        github_username: link.github_username,
        github_verified: true,
      })
      .or(`id.eq.${user.id},user_id.eq.${user.id}`);

    if (error && !isSupabaseSchemaError(error)) {
      console.error("[github-identity] profile sync failed:", error);
    }

    return link;
  } catch (error) {
    console.error("[github-identity] syncGitHubIdentityToProfile failed:", error);
    return null;
  }
}

import { afterEach, describe, expect, it, vi } from "vitest";
import type { User } from "@supabase/supabase-js";
import {
  contributionIsLow,
  githubCommitMatchesLinkedUsername,
  verifyGitHubRepoOwnership,
} from "./github-ownership";

const acmeUser = {
  identities: [
    {
      provider: "github",
      identity_data: { user_name: "Acme" },
    },
  ],
} as unknown as User;

function commit(login: string, sha: string) {
  return {
    sha,
    author: { login },
    commit: { author: { email: `${login.toLowerCase()}@users.noreply.github.com` } },
  };
}

function jsonResponse(body: unknown) {
  return new Response(JSON.stringify(body), {
    status: 200,
    headers: { "content-type": "application/json" },
  });
}

function mockCommitFetches(authored: unknown[], recent: unknown[]) {
  vi.stubGlobal(
    "fetch",
    vi.fn(async (input: RequestInfo | URL) => {
      const href = String(input);
      return jsonResponse(href.includes("author=") ? authored : recent);
    })
  );
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("verifyGitHubRepoOwnership", () => {
  it("verifies a direct owner match case-insensitively", async () => {
    const authored = [
      commit("Acme", "aaa"),
      commit("Acme", "bbb"),
      commit("Acme", "ccc"),
    ];
    mockCommitFetches(authored, authored);

    const result = await verifyGitHubRepoOwnership({
      user: acmeUser,
      repoUrl: "https://github.com/acme/widgets",
    });

    expect(result.verified).toBe(true);
    expect(result.method).toBe("owner");
    expect(result.username).toBe("Acme");
    expect(result.lowContributionWarning).toBe(false);
  });

  it("verifies an owner/repo namespace against the linked username", async () => {
    const authored = [
      commit("Acme", "aaa"),
      commit("Acme", "bbb"),
      commit("Acme", "ccc"),
    ];
    mockCommitFetches(authored, authored);

    const result = await verifyGitHubRepoOwnership({
      user: acmeUser,
      repoUrl: "acme/widgets",
    });

    expect(result.verified).toBe(true);
    expect(result.method).toBe("owner");
    expect(result.owner).toBe("acme");
    expect(result.lowContributionWarning).toBe(false);
  });

  it("clears the contribution warning when the applicant has 3 distinct commits", async () => {
    const authored = [
      commit("Acme", "aaa"),
      commit("Acme", "bbb"),
      commit("Acme", "ccc"),
    ];
    mockCommitFetches(authored, [commit("other", "ddd")]);

    const result = await verifyGitHubRepoOwnership({
      user: acmeUser,
      repoUrl: "https://github.com/acme/widgets",
