  },
  {
    value: "interviewing",
    label: "Interviewing",
  },
  {
    value: "hired",
    label: "Hired",
  },
  {
    value: "passed",
    label: "Passed",
  },
] as const;

export type IntroPipelineStatus =
  (typeof INTRO_PIPELINE_STATUSES)[number]["value"];

export const INTRO_UNLOCK_STATUSES = new Set<string>([
  "accepted",
  "approved_intro_sent",
  "interviewing",
  "hired",
  "approved",
  "completed",
]);

const LEGACY_STATUS_MAP: Record<string, IntroPipelineStatus> = {
  pending: "pending_admin_approval",
  pending_admin_approval: "pending_admin_approval",
  accepted: "approved_intro_sent",
  approved: "approved_intro_sent",
  approved_intro_sent: "approved_intro_sent",
  interviewing: "interviewing",
  hired: "hired",
  passed: "passed",
  rejected: "passed",
  declined: "passed",
  dismissed: "passed",
  trashed: "passed",
  completed: "approved_intro_sent",
};

export function normalizeIntroPipelineStatus(
  status: string | null | undefined
): IntroPipelineStatus {
  const normalized = (status ?? "").trim().toLowerCase();
  return LEGACY_STATUS_MAP[normalized] ?? "pending_admin_approval";
}

export function isIntroUnlockStatus(status: string | null | undefined): boolean {
  const raw = (status ?? "").trim().toLowerCase();
  if (!raw) {
    return false;
  }

  if (INTRO_UNLOCK_STATUSES.has(raw)) {
    return true;
  }

  return INTRO_UNLOCK_STATUSES.has(normalizeIntroPipelineStatus(status));
}

export function introUnlockKeysForCandidateId(candidateId: string): string[] {
  const key = candidateId.trim().toLowerCase();
  if (!key) {
    return [];
  }

  const keys = new Set<string>([key]);
  const compact = key.replace(/-/g, "");
  if (/^[0-9a-f]{32}$/.test(compact)) {
    keys.add(`c-${compact.slice(0, 3)}`);
  }

  return [...keys];
}

export function collectUnlockedCandidateIds(
  rows: Array<{ candidate_id?: string | null; status?: string | null }>
): Set<string> {
  const unlocked = new Set<string>();

  for (const row of rows) {
    const candidateId = row.candidate_id?.trim();
    if (!candidateId || !isIntroUnlockStatus(row.status)) {
      continue;
    }

    for (const key of introUnlockKeysForCandidateId(candidateId)) {
      unlocked.add(key);
    }
  }

  return unlocked;
}

export function getIntroStatusLabel(status: IntroPipelineStatus): string {
  return (
    INTRO_PIPELINE_STATUSES.find((entry) => entry.value === status)?.label ??
    status
  );
}

export function getIntroStatusBadgeClass(status: IntroPipelineStatus): string {
  switch (status) {
    case "approved_intro_sent":
      return "text-emerald-400 bg-emerald-500/10 border-emerald-500/30";
    case "interviewing":
      return "text-indigo-300 bg-indigo-500/10 border-indigo-500/30";
    case "hired":
      return "text-emerald-300 bg-emerald-500/15 border-emerald-500/40";
    case "passed":
      return "text-slate-400 bg-slate-500/10 border-slate-600/40";
    default:
      return "text-violet-400 bg-violet-500/10 border-violet-500/30";
  }
}

import { NextResponse } from "next/server";

type RateBucket = {
  count: number;
  resetAt: number;
};

const buckets = new Map<string, RateBucket>();

export function getRequestIp(request: Request): string {
  const forwarded = request.headers.get("x-forwarded-for");
  if (forwarded) {
    const first = forwarded.split(",")[0]?.trim();
    if (first) {
      return first;
    }
  }

  return request.headers.get("x-real-ip")?.trim() || "unknown";
}

export function consumeRateLimit(
  key: string,
  limit: number,
  windowMs: number
): { ok: boolean; retryAfterSec: number } {
  const now = Date.now();
  const existing = buckets.get(key);

  if (!existing || now >= existing.resetAt) {
    buckets.set(key, { count: 1, resetAt: now + windowMs });
    return { ok: true, retryAfterSec: Math.ceil(windowMs / 1000) };
  }

  if (existing.count >= limit) {
    return {
      ok: false,
      retryAfterSec: Math.max(1, Math.ceil((existing.resetAt - now) / 1000)),
    };
  }

  existing.count += 1;
  return {
    ok: true,
    retryAfterSec: Math.max(1, Math.ceil((existing.resetAt - now) / 1000)),
  };
}

export function tooManyRequestsResponse(retryAfterSec: number): NextResponse {
  return NextResponse.json(
    { error: "Too many requests. Try again shortly." },
    {
      status: 429,
      headers: { "Retry-After": String(retryAfterSec) },
    }
  );
}

import { Resend } from "resend";
import {
  buildJobMatchEmailHtml,
  type JobMatchEmailProps,
} from "@/components/emails/JobMatchEmail";
import { clampScore0to100 } from "@/lib/score-scale";

export type SendJobMatchNotificationInput = JobMatchEmailProps & {
  to: string;
};

export type SendJobMatchNotificationResult = {
  error: string | null;
  id?: string;
};

function normalizeStack(requiredStack: string[]): string[] {
  const seen = new Set<string>();
  const tags: string[] = [];

  for (const item of requiredStack) {
    const trimmed = item.trim();
    if (!trimmed) {
      continue;
    }
    const key = trimmed.toLowerCase();
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    tags.push(trimmed);
  }

  return tags;
}

/** Send a Resend job-match alert. Never throws — failures return `{ error }`. */
export async function sendJobMatchNotification(
  input: SendJobMatchNotificationInput
): Promise<SendJobMatchNotificationResult> {
  try {
    const to = input.to.trim();
    if (!to) {
      return { error: "A recipient email address is required." };
    }

    const resendApiKey = process.env.RESEND_API_KEY?.trim();
    if (!resendApiKey) {
      console.warn(
        "[job-alerts] RESEND_API_KEY is not set; skipping job match email."
      );
      return {
        error:
          "Email delivery is not configured. Set RESEND_API_KEY and try again.",
      };
    }

    const props: JobMatchEmailProps = {
      developerName: input.developerName.trim() || "there",
      jobTitle: input.jobTitle.trim() || "Open role",
      companyName: input.companyName.trim() || "Hiring team",
      location: input.location.trim(),
      requiredStack: normalizeStack(input.requiredStack),
      repoName: input.repoName.trim() || "your repository",
      auditScore: clampScore0to100(input.auditScore),
      jobUrl: input.jobUrl.trim(),
    };

    if (!props.jobUrl) {
      return { error: "jobUrl is required." };
    }

    const resend = new Resend(resendApiKey);
    const { data, error } = await resend.emails.send({
      from: "Provix <notifications@getprovix.com>",
      to,
      subject: `New role match: ${props.jobTitle} at ${props.companyName}`,
      html: buildJobMatchEmailHtml(props),
    });

    if (error) {
      console.error("[job-alerts] Resend failed:", error);
      return {
        error: "Could not send the job match email. Try again shortly.",
      };
    }

    return {
      error: null,
      id: typeof data?.id === "string" ? data.id : undefined,
    };
  } catch (error) {
    console.error("[job-alerts] sendJobMatchNotification threw:", error);
    return {
      error:
        error instanceof Error
          ? error.message
          : "Could not send the job match email.",
    };
  }
}

