  const roleTitle = applicant.jobTitle?.trim() || applicant.headline;
  const parsedScore =
    typeof applicant.matchScore === "number" && Number.isFinite(applicant.matchScore)
      ? applicant.matchScore
      : Number.parseInt(applicant.aiScoreLabel?.replace(/\D/g, "") ?? "", 10);
  const matchScore = Number.isFinite(parsedScore)
    ? parsedScore
    : scoreTalentMatch(
        { title: applicant.headline, skills: applicant.skills },
        { title: roleTitle }
      ).match_percentage;
  const codename = applicant.codenameAlias;
  const github = resolveCandidateGithubUrl({
    github_url: applicant.githubUrl,
    github: applicant.github,
  });

  return {
    id: `C-${applicant.profileId.replace(/-/g, "").slice(0, 3).toUpperCase()}`,
    profileId: applicant.profileId,
    name: codename,
    fullName: codename,
    profileName: codename,
    firstName: codename.split(/\s+/)[0] ?? codename,
    lastName: codename.split(/\s+/).slice(1).join(" "),
    headline: applicant.headline,
    codenameAlias: codename,
    country: applicant.country || applicant.location,
    timezone: applicant.timezone || applicant.location,
    workPreference: applicant.workPreference || DEFAULT_WORK_PREFERENCE,
    email: applicant.email ?? "",
    phone: applicant.phone ?? "",
    linkedin_url: applicant.linkedinUrl ?? "",
    github_url: github.githubUrl,
    role: applicant.headline,
    university: applicant.university,
    major: applicant.major,
    gpa: formatGpa(applicant.gpa),
    graduationYear: applicant.graduationYear,
    isSelfTaught: Boolean(applicant.isSelfTaught),
    skills: applicant.skills,
    rating: applicant.aiScoreLabel || `${matchScore}% Match`,
    execution_score: matchScore,
    matchScore,
    status: applicant.availability || "Available Now",
    experienceLevel: applicant.experienceLevel || DEFAULT_EXPERIENCE_LEVEL,
    roleType: "General",
    availability: applicant.availability || "Available Now",
    openToFulltime: normalizeOpenToFulltime(applicant.openToFulltime),
    openToContract: normalizeOpenToContract(applicant.openToContract),
    contractHoursPerWeek:
      normalizeContractHoursPerWeek(applicant.contractHoursPerWeek) || null,
    contractHourlyRate: normalizeContractHourlyRate(
      applicant.contractHourlyRate
    ),
    bio: applicant.bio || "Candidate expressed interest in this role via Provix.",
    github: github.github,
    demoVideo: applicant.demoVideo || "",
    projects: applicant.projects ?? [],
    verifiedOnProvix: applicant.verifiedOnProvix,
    productionScore: applicant.productionScore ?? null,
    auditBreakdown:
      parseProductionAuditFromProfileRow({
        production_score: applicant.productionScore,
        audit_breakdown: applicant.auditBreakdown,
        is_audit_verified: applicant.isAuditVerified,
      })?.breakdown ?? null,
    isAuditVerified: Boolean(applicant.isAuditVerified),
  };
}

import { fetchWithAuth } from "@/lib/fetch-with-auth";
import { readJsonResponse } from "@/lib/read-json-response";
import type { SupabaseClient } from "@supabase/supabase-js";
import { isSupabaseSchemaError } from "@/lib/supabase-schema-errors";

export type IncomingJobInterest = {
  id: string;
  jobId: string;
  message: string;
  createdAt: string;
  isRead: boolean;
};

export async function submitCandidateJobInterest(jobId: string): Promise<{
  ok: boolean;
  alreadyApplied: boolean;
}> {
  const response = await fetchWithAuth(
    `/api/jobs/${encodeURIComponent(jobId)}/interest`,
    { method: "POST" }
  );
  const payload = (await readJsonResponse(response).catch(() => null)) as {
    ok?: boolean;
    alreadyApplied?: boolean;
    error?: string;
  } | null;

  if (response.status === 409 || payload?.alreadyApplied) {
    return { ok: true, alreadyApplied: true };
  }

  if (!response.ok || !payload?.ok) {
    throw new Error(payload?.error ?? "Could not submit interest.");
  }

  return {
    ok: true,
    alreadyApplied: Boolean(payload.alreadyApplied),
  };
}

export async function fetchIncomingJobInterest(
  supabase: SupabaseClient,
  employerId: string
): Promise<IncomingJobInterest[]> {
  try {
    const { data: listings, error: listingsError } = await supabase
      .from("jobs")
      .select("id, title")
      .eq("employer_id", employerId);

    if (listingsError) {
      if (!isSupabaseSchemaError(listingsError)) {
        console.warn("Failed to load employer jobs for interest:", listingsError.message);
      }
      return [];
    }

    const jobs = listings ?? [];
    if (jobs.length === 0) {
      return [];
    }

    const titleById = new Map(
      jobs.map((job) => [job.id, job.title?.trim() || "Open Role"])
    );
    const jobIds = jobs.map((job) => job.id);

    const [{ data: applications, error: applicationsError }, notifications] =
      await Promise.all([
        supabase
          .from("job_applications")
          .select("id, job_id, created_at")
          .in("job_id", jobIds)
          .order("created_at", { ascending: false })
          .limit(20),
        supabase
          .from("notifications")
          .select("job_id, is_read, created_at")
          .eq("user_id", employerId)
          .order("created_at", { ascending: false })
          .limit(50)
          .then((result) => {
            if (result.error && !isSupabaseSchemaError(result.error)) {
              console.warn(
                "Failed to load interest notification state:",
                result.error.message
              );
            }
            return result.data ?? [];
          }),
      ]);

    if (applicationsError) {
      if (!isSupabaseSchemaError(applicationsError)) {
        console.warn(
          "Failed to load incoming job interest:",
          applicationsError.message
        );
      }
      return [];
    }

    return (applications ?? []).map((row) => {
      const title = titleById.get(row.job_id) ?? "Open Role";
      const appliedAt = new Date(row.created_at).getTime();
      const nearbyNotes = notifications.filter((note) => {
        if (note.job_id !== row.job_id) {
          return false;
        }
        return (
          Math.abs(new Date(note.created_at).getTime() - appliedAt) < 15_000
        );
      });
      const isRead =
        nearbyNotes.length > 0 && nearbyNotes.every((note) => note.is_read);

      return {
        id: row.id,
        jobId: row.job_id,
        message: `A candidate expressed interest in your role: ${title}`,
        createdAt: row.created_at,
        isRead,
      };
    });
  } catch (error) {
    console.error("[job-interest] fetchIncomingJobInterest failed:", error);
    return [];
  }
}

export async function markJobInterestRead(
  supabase: SupabaseClient,
  employerId: string,
  jobId: string
): Promise<void> {
  try {
    const { error } = await supabase
      .from("notifications")
      .update({ is_read: true })
      .eq("user_id", employerId)
      .eq("job_id", jobId)
      .eq("is_read", false);

    if (error && !isSupabaseSchemaError(error)) {
      console.warn("Failed to mark job interest as read:", error.message);
    }
  } catch (error) {
    console.error("[job-interest] markJobInterestRead failed:", error);
  }
}

function notificationChangeBelongsToEmployer(
  payload: { new: Record<string, unknown>; old: Record<string, unknown> },
  employerId: string
): boolean {
  const nextUserId = payload.new.user_id;
  const prevUserId = payload.old.user_id;
  // If Realtime omits user_id (replica identity / WAL), still refresh rather
  // than drop the event. RLS already limits which rows this client can see.
  if (typeof nextUserId !== "string" && typeof prevUserId !== "string") {
    return true;
  }
  return nextUserId === employerId || prevUserId === employerId;
}

export function subscribeIncomingJobInterest(
  supabase: SupabaseClient,
  employerId: string,
  onChange: () => void
): () => void {
  const channel = supabase
    .channel(`job-interest-${employerId}-${Math.random()}`)
    .on(
      "postgres_changes",
      { event: "INSERT", schema: "public", table: "job_applications" },
      () => onChange()
    )
    .on(
      "postgres_changes",
      {
        event: "*",
        schema: "public",
        table: "notifications",
      },
      (payload) => {
        if (notificationChangeBelongsToEmployer(payload, employerId)) {
          onChange();
        }
      }
    )
    .subscribe();

  return () => {
    void supabase.removeChannel(channel);
  };
}

