};

export type MatchJobPayload = {
  title?: string;
  company?: string;
  tags?: string[] | string;
  tech_stack?: string[] | string;
  techStack?: string[] | string;
  required_skills?: string[] | string;
  requiredSkills?: string[] | string;
  location?: string;
  description?: string;
  searchQuery?: string;
};

export type MatchResult = {
  match_percentage: number;
  reasoning: string;
  matching_skills: string[];
  missing_skills: string[];
};

const STOPWORDS = new Set([
  "a",
  "an",
  "and",
  "as",
  "at",
  "be",
  "by",
  "for",
  "from",
  "in",
  "is",
  "job",
  "of",
  "on",
  "or",
  "our",
  "role",
  "the",
  "this",
  "to",
  "we",
  "with",
  "you",
  "your",
]);

const TECH_ALIASES: Record<string, string[]> = {
  js: ["javascript"],
  javascript: ["js"],
  ts: ["typescript"],
  typescript: ["ts"],
  react: ["reactjs", "react.js"],
  reactjs: ["react"],
  node: ["nodejs", "node.js"],
  nodejs: ["node"],
  next: ["nextjs", "next.js"],
  nextjs: ["next"],
  py: ["python"],
  python: ["py"],
  postgres: ["postgresql", "sql"],
  postgresql: ["postgres", "sql"],
  ml: ["machinelearning", "ai"],
  ai: ["ml"],
};

export function clampMatchPercentage(value: unknown): number {
  return clampScore0to100(value, 0);
}

export function isCannedMatchScore(score: number): boolean {
  return score === 50 || score === 65 || score === 94;
}

export function normalizeStringArray(value: unknown): string[] {
  if (typeof value === "string") {
    return value
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is string => typeof item === "string")
    .map((item) => item.trim())
    .filter(Boolean);
}

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .split(/[^a-z0-9+#]+/g)
    .map((token) => token.replace(/^\.+|\.+$/g, ""))
    .filter((token) => token.length >= 2 && !STOPWORDS.has(token));
}

function expandToken(token: string): Set<string> {
  const expanded = new Set<string>([token]);
  for (const alias of TECH_ALIASES[token] ?? []) {
    expanded.add(alias);
  }
  return expanded;
}

function tokenMatches(candidateToken: string, requirementToken: string): boolean {
  if (candidateToken === requirementToken) {
    return true;
  }

  const candidateExpanded = expandToken(candidateToken);
  const requirementExpanded = expandToken(requirementToken);

  for (const left of candidateExpanded) {
    for (const right of requirementExpanded) {
      if (left === right) {
        return true;
      }
      if (left.length >= 3 && right.length >= 3 && (left.includes(right) || right.includes(left))) {
        return true;
      }
    }
  }

  return false;
}

function uniqueNormalized(values: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const value of values) {
    const key = value.trim().toLowerCase();
    if (!key || seen.has(key)) {
      continue;
    }
    seen.add(key);
    result.push(value.trim());
  }

  return result;
}

function jobRequirementLists(job: MatchJobPayload): string[] {
  return uniqueNormalized([
    ...normalizeStringArray(job.techStack ?? job.tech_stack),
    ...normalizeStringArray(job.requiredSkills ?? job.required_skills),
    ...normalizeStringArray(job.tags),
  ]);
}

function buildRequirementTokens(job: MatchJobPayload): string[] {
  const requirements = jobRequirementLists(job);
  const primary = uniqueNormalized(
    tokenize(
      [job.title ?? "", job.searchQuery ?? "", requirements.join(" ")].join(" ")
    )
  );
  const descriptionTokens = uniqueNormalized(
    tokenize(job.description ?? "").filter((token) => token.length >= 4)
  ).slice(0, 12);

  return uniqueNormalized([...primary, ...descriptionTokens]);
}

function findMatchingSkills(
  candidateSkills: string[],
  requirementTokens: string[],
  jobText: string
): string[] {
  return candidateSkills.filter((skill) => {
    const skillTokens = tokenize(skill);
    if (skillTokens.length === 0) {
      return jobText.includes(skill.toLowerCase());
    }

    return skillTokens.some((skillToken) =>
      requirementTokens.some((requirement) => tokenMatches(skillToken, requirement))
    );
  });
}

/**
 * Lightweight talent-pool scorer: candidate skills/bio/title vs job description,
 * tags, and the employer's live search query. Returns 0-100, never a canned 50.
 */
export function scoreTalentMatch(
  candidate: MatchCandidatePayload,
  job: MatchJobPayload
): MatchResult {
  const candidateSkills = uniqueNormalized(normalizeStringArray(candidate.skills));
  const title = candidate.title?.trim() ?? "";
  const bio = candidate.bio?.trim() ?? "";
  const degree = candidate.degree?.trim() ?? "";
  const searchQuery = job.searchQuery?.trim() ?? "";
  const jobTitle = job.title?.trim() ?? "";
  const jobDescription = job.description?.trim() ?? "";
  const jobTags = jobRequirementLists(job);

  const candidateTokens = uniqueNormalized(
    tokenize([title, bio, degree, candidateSkills.join(" ")].join(" "))
  );
  const requirementTokens = buildRequirementTokens(job);
  const jobText = [
    jobTitle,
    job.company ?? "",
    job.location ?? "",
    jobDescription,
    searchQuery,
    jobTags.join(" "),
  ]
    .join(" ")
    .toLowerCase();

  const matching_skills = findMatchingSkills(
    candidateSkills,
    requirementTokens,
    jobText
  );

  const missing_skills = jobTags.filter(
    (tag) =>
      !matching_skills.some(
        (skill) =>
          skill.toLowerCase() === tag.toLowerCase() ||
          tokenMatches(skill.toLowerCase(), tag.toLowerCase())
      )
  );

  const hasJobSignal = requirementTokens.length > 0;
  let match_percentage = 0;

  if (hasJobSignal) {
    const overlap =
      requirementTokens.length === 0
        ? 0
        : requirementTokens.filter((requirement) =>
            candidateTokens.some((token) => tokenMatches(token, requirement))
          ).length / requirementTokens.length;

    const skillOverlap =
      jobTags.length > 0
        ? matching_skills.length / jobTags.length
        : candidateSkills.length > 0
          ? Math.min(1, matching_skills.length / Math.max(candidateSkills.length, 1))
          : overlap;

    const titleOverlap =
      title && jobTitle
        ? tokenize(title).some((token) =>
            tokenize(jobTitle).some((jobToken) => tokenMatches(token, jobToken))
          )
          ? 1
          : 0.15
        : 0;

    const query = searchQuery.toLowerCase();
    const queryHit =
      query.length >= 2 &&
      [title, bio, degree, candidateSkills.join(" ")]
        .join(" ")
        .toLowerCase()
        .includes(query)
        ? 1
        : query
            .split(/\s+/)
            .filter((part) => part.length >= 2)
            .some((part) =>
              candidateTokens.some((token) => tokenMatches(token, part))
            )
          ? 0.7
          : 0;

    match_percentage =
      Math.round(skillOverlap * 50) +
      Math.round(overlap * 25) +
      Math.round(titleOverlap * 15) +
      Math.round(queryHit * 10);
  } else {
    const skillDepth = Math.min(candidateSkills.length, 8) * 6;
    const bioSignal = Math.min(18, Math.round(bio.length / 40));
    const titleSignal = title ? 10 : 0;
    const degreeSignal = degree ? 6 : 0;
    match_percentage = skillDepth + bioSignal + titleSignal + degreeSignal;
  }

  match_percentage = clampMatchPercentage(match_percentage);

  const roleLabel = jobTitle || (searchQuery ? `"${searchQuery}"` : "this search");
  const reasoning =
    matching_skills.length > 0
      ? `Strong overlap on ${matching_skills.slice(0, 3).join(", ")} for ${roleLabel}.`
      : hasJobSignal
        ? `Limited skill overlap with ${roleLabel} based on the current profile.`
        : "No active job or search query yet — score reflects profile depth only.";

  return {
    match_percentage,
    reasoning,
    matching_skills,
    missing_skills,
  };
}

export function normalizeMatchResult(raw: unknown): MatchResult {
  const record =
    raw && typeof raw === "object" ? (raw as Record<string, unknown>) : {};

  const scoreSource = record.score ?? record.match_percentage;
  const breakdownSource = record.breakdown ?? record.reasoning;

  const reasoning =
    typeof breakdownSource === "string" && breakdownSource.trim()
      ? breakdownSource.trim()
      : "Profile partially aligns with this role's requirements.";

  return {
    match_percentage: clampMatchPercentage(scoreSource),
    reasoning,
    matching_skills: normalizeStringArray(record.matching_skills),
    missing_skills: normalizeStringArray(record.missing_skills),
  };
}

export function buildFallbackMatch(
  candidate: MatchCandidatePayload,
  job: MatchJobPayload
): MatchResult {
  // Keep export stable for callers; deterministic employer scoring lives in
  // employer-match and is preferred by /api/match + talent-match-scores.
  return scoreTalentMatch(candidate, job);
}

import { normalizeStringArray } from "@/lib/match-heuristic";
import { jobDisplayTags } from "@/lib/jobs";

export function normalizeJobStatus(status: string | null | undefined): string {
  return (status ?? "active").trim().toLowerCase();
}

export function isActiveJob(job: { status?: string | null }): boolean {
  return normalizeJobStatus(job.status) === "active";
}

export function getActiveJobs<T extends { status?: string | null }>(
  jobs: T[]
): T[] {
  return jobs.filter(isActiveJob);
}

export function countActiveOpenings(
  jobs: Array<{ status?: string | null }>
): number {
  return getActiveJobs(jobs).length;
}

export function skillsOverlap(
  candidateSkills: string[],
  jobTags: string[]
): boolean {
  const normalizedCandidate = normalizeStringArray(candidateSkills).map((skill) =>
    skill.toLowerCase()
  );
  const normalizedTags = normalizeStringArray(jobTags).map((tag) =>
    tag.toLowerCase()
  );

  if (normalizedCandidate.length === 0 || normalizedTags.length === 0) {
    return false;
  }

  return normalizedTags.some((tag) =>
    normalizedCandidate.some(
      (skill) => skill.includes(tag) || tag.includes(skill)
    )
  );
}

export function countJobsMatchingCandidateSkills(
  jobs: Array<{
    status?: string | null;
    tags?: string[] | null;
    tech_stack?: string[] | null;
    required_skills?: string[] | null;
  }>,
  candidateSkills: string[] | string
): number {
  const skills = normalizeStringArray(candidateSkills);

  return getActiveJobs(jobs).filter((job) =>
    skillsOverlap(skills, jobDisplayTags(job))
  ).length;
}

export function coerceVisibilityFlag(value: unknown): boolean {
  if (value === true || value === 1) {
    return true;
  }

  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    return (
      normalized === "true" ||
      normalized === "t" ||
      normalized === "1" ||
      normalized === "yes"
    );
  }

  return false;
}

export function isVisibleToEmployers(
  visibleToEmployers: unknown
): boolean {
  return coerceVisibilityFlag(visibleToEmployers);
}

export function profileRowIsPublicToEmployers(row: {
  is_visible_in_pool?: unknown;
  visible_to_employers?: unknown;
}): boolean {
  if (row.is_visible_in_pool != null) {
    return coerceVisibilityFlag(row.is_visible_in_pool);
  }

  if (row.visible_to_employers != null) {
    return coerceVisibilityFlag(row.visible_to_employers);
  }

  return false;
}

import type { GitHubAuditContext } from "@/lib/github-audit";
import { readJsonResponse } from "@/lib/read-json-response";
import { normalizeStringArray } from "@/lib/match-heuristic";
import { clampScore0to100 } from "@/lib/score-scale";
import { filterTechnicalRequirements } from "@/lib/technical-skill-requirements";

export type FitVerdict = "Strong Fit" | "Moderate Fit" | "Growth Fit";

export type OpportunityMatchCandidatePayload = {
  title?: string;
  bio?: string;
  skills?: string[] | string;
  role_type?: string;
  github_url?: string;
  experience_level?: string;
};

export type OpportunityMatchJobPayload = {
  title?: string;
  company?: string;
  tags?: string[] | string;
  tech_stack?: string[] | string;
  techStack?: string[] | string;
  required_skills?: string[] | string;
  requiredSkills?: string[] | string;
  location?: string;
  description?: string;
  salary_range?: string;
};

export type OpportunityMatchResult = {
  match_score: number;
  fit_verdict: FitVerdict;
  match_reasons: string[];
};

const FIT_VERDICTS: FitVerdict[] = [
  "Strong Fit",
  "Moderate Fit",
  "Growth Fit",
];

export function clampMatchScore(value: unknown): number {
  return clampScore0to100(value, 0);
}

export function scoreToFitVerdict(score: number): FitVerdict {
  if (score >= 75) {
    return "Strong Fit";
  }
  if (score >= 50) {
    return "Moderate Fit";
  }
  return "Growth Fit";
}

export function normalizeFitVerdict(value: unknown, score: number): FitVerdict {
  if (typeof value === "string") {
    const normalized = value.trim();
    if (FIT_VERDICTS.includes(normalized as FitVerdict)) {
      return normalized as FitVerdict;
    }
  }

  return scoreToFitVerdict(score);
}

export function normalizeMatchReasons(value: unknown): string[] {
  return normalizeStringArray(value)
    .map((reason) => reason.replace(/\s+/g, " ").trim())
    .filter(Boolean)
    .slice(0, 3);
}

const CANDIDATE_MATCH_SECTION =
  /^(Your Stack Edge|Verified Proof|Application Angle)\s*:\s*(.*)$/i;

/** Split "Your Stack Edge: …" into a labeled section for candidate UI. */
export function splitCandidateMatchReason(reason: string): {
  label: string | null;
  body: string;
} {
  const match = reason.trim().match(CANDIDATE_MATCH_SECTION);
  if (!match) {
    return { label: null, body: reason.trim() };
  }
  return {
    label: match[1],
    body: (match[2] ?? "").trim(),
  };
}

export function normalizeOpportunityMatchResult(
  raw: unknown
): OpportunityMatchResult {
  const record =
    raw && typeof raw === "object" ? (raw as Record<string, unknown>) : {};

  const scoreSource =
    record.match_score ?? record.score ?? record.match_percentage;
  const match_score = clampMatchScore(scoreSource);
  const fit_verdict = normalizeFitVerdict(record.fit_verdict, match_score);

  return {
    match_score,
    fit_verdict,
    match_reasons: normalizeMatchReasons(
      record.match_reasons ?? record.reasons ?? record.matching_skills
    ),
  };
}

export function getFitVerdictBadgeClass(verdict: FitVerdict): string {
  const base =
    "inline-flex items-center px-2.5 py-1 rounded-md text-xs font-mono font-medium";

  switch (verdict) {
    case "Strong Fit":
      return `${base} bg-emerald-500/10 text-emerald-400 border border-emerald-500/25`;
    case "Moderate Fit":
      return `${base} bg-[#1A1A1E] text-zinc-300 border border-white/[0.08]`;
    case "Growth Fit":
      return `${base} bg-violet-500/10 text-violet-300 border border-violet-500/25`;
  }
}

function uniqueJobRequirements(job: OpportunityMatchJobPayload): string[] {
  return filterTechnicalRequirements([
    ...normalizeStringArray(job.techStack ?? job.tech_stack),
    ...normalizeStringArray(job.requiredSkills ?? job.required_skills),
    ...normalizeStringArray(job.tags),
  ]);
}

export function buildFallbackOpportunityMatch(
  candidate: OpportunityMatchCandidatePayload,
  job: OpportunityMatchJobPayload,
  githubAudit?: GitHubAuditContext | null
): OpportunityMatchResult {
  const candidateSkills = normalizeStringArray(candidate.skills);
  const jobTags = uniqueJobRequirements(job);
  const roleLabel = job.title?.trim() || "this role";

  const normalizedCandidateSkills = candidateSkills.map((skill) =>
    skill.toLowerCase()
  );

  const matchingTags = jobTags.filter((tag) =>
    normalizedCandidateSkills.some(
      (skill) =>
        skill.includes(tag.toLowerCase()) || tag.toLowerCase().includes(skill)
    )
  );

  const missingTags = jobTags.filter(
    (tag) =>
      !matchingTags.some(
        (match) =>
          match.toLowerCase() === tag.toLowerCase() ||
          match.toLowerCase().includes(tag.toLowerCase()) ||
          tag.toLowerCase().includes(match.toLowerCase())
      )
  );

  let match_score = 0;
  if (matchingTags.length > 0) {
    match_score += Math.min(45, matchingTags.length * 12);
  } else if (candidateSkills.length > 0) {
    match_score += 18;
  }

  if (candidate.bio?.trim()) {
    match_score += 10;
  }

  const repoLabel =
    githubAudit?.owner && githubAudit?.repo
      ? `${githubAudit.owner}/${githubAudit.repo}`
      : "your audited repo";

  if (githubAudit) {
    if (
      githubAudit.language &&
      matchingTags.some((tag) =>
        tag.toLowerCase().includes(githubAudit.language!.toLowerCase())
      )
    ) {
      match_score += 15;
    } else if (githubAudit.commit_count_sampled >= 3) {
      match_score += 10;
    }
  }

  const stackSkills =
    matchingTags.length > 0
      ? matchingTags.slice(0, 3)
      : candidateSkills.slice(0, 3);

  const stackEdge =
    matchingTags.length > 0
      ? `Your Stack Edge: Your verified ${stackSkills.join(", ")} overlap ${roleLabel}'s listed stack — lead with those exact technologies.`
      : stackSkills.length > 0
        ? `Your Stack Edge: Highlight your audited ${stackSkills.join(", ")} and map each to the closest requirement on ${roleLabel}.`
        : `Your Stack Edge: Add core languages/frameworks to your profile so this role can cite exact stack overlap.`;

  const verifiedProof = githubAudit
    ? githubAudit.commit_count_sampled >= 3
      ? `Verified Proof: ${githubAudit.commit_count_sampled} recent commits on ${repoLabel}${
          githubAudit.language ? ` (${githubAudit.language})` : ""
        } demonstrate shipping cadence most applicants cannot show.`
      : githubAudit.language
        ? `Verified Proof: Your GitHub work on ${repoLabel} is primarily ${githubAudit.language} — cite that as production evidence.`
        : `Verified Proof: Keep your Provix audit and GitHub activity current to prove production readiness.`
    : `Verified Proof: Connect a public repo and keep a 75+ audit so this application shows verified production proof.`;

  const applicationAngle =
    missingTags.length > 0
      ? `Application Angle: Address ${missingTags.slice(0, 2).join(" and ")} by pairing adjacent audited skills with a short repo walkthrough — and frame velocity on ${repoLabel} to offset generic tenure asks.`
      : `Application Angle: Lead with stack overlap and audit proof, then show a short walkthrough of your highest-signal project for ${roleLabel}.`;

  const clampedScore = clampMatchScore(match_score);

  return {
    match_score: clampedScore,
    fit_verdict: scoreToFitVerdict(clampedScore),
    match_reasons: normalizeMatchReasons([
      stackEdge,
      verifiedProof,
      applicationAngle,
    ]),
  };
}

export async function fetchOpportunityMatch(
  candidate: OpportunityMatchCandidatePayload,
  job: OpportunityMatchJobPayload
): Promise<OpportunityMatchResult> {
  try {
    const response = await fetch("/api/opportunities/match", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ candidate, job }),
    });

    if (!response.ok) {
      return buildFallbackOpportunityMatch(candidate, job);
    }

    const raw = (await readJsonResponse(response)) as unknown;
    if (raw && typeof raw === "object" && "error" in (raw as object)) {
      return buildFallbackOpportunityMatch(candidate, job);
    }

    return normalizeOpportunityMatchResult(raw);
  } catch (error) {
    console.warn("Opportunity match API unavailable, using fallback.", error);
    return buildFallbackOpportunityMatch(candidate, job);
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";

export type ParsedJsonBody<T> =
  | { ok: true; data: T }
  | { ok: false; response: NextResponse };

/** Parse and validate a JSON request body with Zod. Invalid JSON or schema → 400. */
export async function parseJsonWithSchema<T extends z.ZodTypeAny>(
  request: Request,
  schema: T
): Promise<ParsedJsonBody<z.infer<T>>> {
  let raw: unknown;
  try {
    raw = await request.json();
  } catch {
    return {
      ok: false,
      response: NextResponse.json(
        {
          error: "Invalid JSON body.",
          details: ["Request body must be valid JSON."],
        },
        { status: 400 }
      ),
    };
  }

  const parsed = schema.safeParse(raw);
  if (!parsed.success) {
    return {
      ok: false,
      response: NextResponse.json(
        {
          error: "Invalid request payload.",
          details: parsed.error.issues.map((issue) => {
            const path = issue.path.length > 0 ? issue.path.join(".") : "body";
            return `${path}: ${issue.message}`;
          }),
        },
        { status: 400 }
      ),
    };
  }

  return { ok: true, data: parsed.data };
}

export function formatZodErrorDetails(error: z.ZodError): string[] {
  return error.issues.map((issue) => {
    const path = issue.path.length > 0 ? issue.path.join(".") : "body";
    return `${path}: ${issue.message}`;
  });
}

