export type CandidateProfileSaveInput = {
  fullName: string;
  jobTitle: string;
  bio: string;
  university: string;
  major: string;
  degree: string;
  skills: string[] | string | null | undefined;
  education?: EducationEntry[] | unknown;
  isSelfTaught?: boolean;
  portfolioUrl: string;
  youtubeUrl: string;
  experienceLevel: string;
  availabilityStatus: string;
  workPreference: string;
  candidateTimezone: string;
  openToFulltime: boolean;
  openToContract: boolean;
  contractHoursPerWeek: string;
  contractHourlyRate: number | string | null;
  isVisibleInPool: boolean;
  gradYear: string;
  gpa: string;
  keyAccomplishments: string;
};

type PersistOptions = {
  existingProfileSlug?: string | null;
};

type ProfilePayload = Record<
  string,
  | string
  | number
  | boolean
  | string[]
  | Array<Record<string, string>>
  | null
>;

function nullIfEmpty(value: string | null | undefined): string | null {
  const trimmed = value?.trim();
  return trimmed ? trimmed : null;
}

export function normalizeSkillsForDb(
  skills: string[] | string | null | undefined
): string[] {
  return parseCandidateSkills(skills);
}

export function buildCandidateProfileUpdatePayload(
  input: CandidateProfileSaveInput,
  userId: string,
  options?: PersistOptions
): ProfilePayload {
  const educationEntries = serializeEducationEntries(
    parseEducationEntries(input.education)
  );
  const primaryEducation = primaryEducationFields(educationEntries);
  const parsedGradYear = Number.parseInt(primaryEducation.graduationYear, 10);
  const existingSlug = options?.existingProfileSlug?.trim();
  const institution = primaryEducation.institution;
  const fieldOfStudy = primaryEducation.fieldOfStudy;

  const openToContract = normalizeOpenToContract(input.openToContract);
  const contractHours = openToContract
    ? normalizeContractHoursPerWeek(input.contractHoursPerWeek)
    : "";
  const contractRate = openToContract
    ? normalizeContractHourlyRate(input.contractHourlyRate)
    : null;
  // Positive rate only — 0 is treated as unset when contract is open.
  const persistedContractRate =
    contractRate != null && contractRate > 0 ? contractRate : null;

  const metadataDefaults = talentPoolMetadataDefaults({
    work_preference: input.workPreference,
    timezone: input.candidateTimezone,
    availability_status: input.availabilityStatus,
  });

  const payload: ProfilePayload = {
    full_name: nullIfEmpty(input.fullName),
    job_title: nullIfEmpty(input.jobTitle),
    bio: nullIfEmpty(input.bio),
    university: nullIfEmpty(institution),
    school: nullIfEmpty(institution),
    major: nullIfEmpty(fieldOfStudy),
    degree: nullIfEmpty(primaryEducation.credentialType),
    education: educationEntries,
    is_self_taught: Boolean(input.isSelfTaught),
    skills: normalizeSkillsForDb(input.skills),
    user_id: userId,
    portfolio_url: nullIfEmpty(normalizeGitHubUrl(input.portfolioUrl)),
    youtube_url: nullIfEmpty(input.youtubeUrl),
    experience_level: nullIfEmpty(input.experienceLevel),
    availability_status: normalizeAvailabilityStatus(
      input.availabilityStatus || metadataDefaults.availability_status
    ),
    work_preference: normalizeWorkPreference(
      input.workPreference || metadataDefaults.work_preference
    ),
    timezone: normalizeCandidateTimezone(
      input.candidateTimezone || metadataDefaults.timezone
    ),
    open_to_fulltime: normalizeOpenToFulltime(input.openToFulltime),
    open_to_contract: openToContract,
    contract_hours_per_week: contractHours || null,
    contract_hourly_rate: persistedContractRate,
    is_visible_in_pool: Boolean(input.isVisibleInPool),
    graduation_year: Number.isFinite(parsedGradYear) ? parsedGradYear : null,
    gpa: nullIfEmpty(formatGpa(input.gpa)),
    key_accomplishments: nullIfEmpty(input.keyAccomplishments),
  };

  if (existingSlug) {
    payload.profile_slug = existingSlug;
  } else {
    payload.profile_slug = buildUniqueProfileSlug(input.fullName, userId);
  }

  return payload;
}

function isMissingColumnError(error: { message?: string; code?: string } | null) {
  if (!error) {
    return false;
  }

  return (
    error.code === "42703" ||
    error.code === "PGRST204" ||
    (error.message?.includes("does not exist") ?? false)
  );
}

function isUniqueViolation(error: { code?: string } | null) {
  return error?.code === "23505";
}

function isRowLevelSecurityError(error: { code?: string; message?: string } | null) {
  return (
    error?.code === "42501" ||
    (error?.message?.toLowerCase().includes("row-level security") ?? false)
  );
}

/** Structured log fields for Supabase / unknown errors (avoids console `{}`). */
export function serializePersistError(error: unknown): Record<string, unknown> {
  if (error == null) {
    return { error: null };
  }

  if (typeof error === "string") {
    return { message: error };
  }

  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      stack: error.stack,
    };
  }

  if (typeof error === "object") {
    const record = error as Record<string, unknown>;
    let json: string | null = null;
    try {
      json = JSON.stringify(error);
    } catch {
      json = "[unserializable]";
    }
    // Prefer own + inherited enumerable fields; fall back to explicit keys
    // because some PostgrestError shapes serialize to "{}".
    const message =
      typeof record.message === "string"
        ? record.message
        : typeof (record as { msg?: unknown }).msg === "string"
          ? String((record as { msg: string }).msg)
          : undefined;
    return {
      message,
      details: record.details,
      hint: record.hint,
      code: record.code,
      status: record.status ?? record.statusCode,
      userMessage:
        typeof record.userMessage === "string" ? record.userMessage : undefined,
      json: json && json !== "{}" ? json : undefined,
      keys: Object.keys(record),
      stringTag: Object.prototype.toString.call(error),
    };
  }

  return { error: String(error) };
}

function asProfileRow(data: unknown): Record<string, unknown> | null {
  if (!data || typeof data !== "object" || Array.isArray(data)) {
    return null;
  }
  return data as Record<string, unknown>;
}

/** Load a profile by auth user id, trying `id` then `user_id`. */
async function loadProfileForUserId(
  supabase: SupabaseClient,
  userId: string,
  select: string
): Promise<Record<string, unknown> | null> {
  const byId = await supabase
    .from("profiles")
    .select(select)
    .eq("id", userId)
    .maybeSingle();
  if (!byId.error) {
    const row = asProfileRow(byId.data);
    if (row) {
      return row;
    }
  }

  const byUserId = await supabase
    .from("profiles")
    .select(select)
    .eq("user_id", userId)
    .maybeSingle();
  if (!byUserId.error) {
    return asProfileRow(byUserId.data);
  }

  return null;
}

function formatPersistError(
  error: { message?: string; details?: string; code?: string } | null
): string {
  if (!error) {
    return "Could not save profile. Please try again.";
  }

  if (isRowLevelSecurityError(error)) {
    return "Could not save profile: permission denied. Ask an admin to apply profiles RLS migration 0037.";
  }

  if (isUniqueViolation(error)) {
    return "Could not save profile: profile URL slug conflict. Try again.";
  }

  const message = (error.message ?? "").toLowerCase();
  const details = (error.details ?? "").toLowerCase();
  const combined = `${message} ${details}`;

  if (
    combined.includes("profiles_candidate_bio_length_check") ||
    (error.code === "23514" && combined.includes("bio"))
  ) {
    return CANDIDATE_BIO_LIMIT_TEXT;
  }

  if (
    combined.includes("profiles_contract_hourly_rate_check") ||
    (error.code === "23514" && combined.includes("contract_hourly_rate"))
  ) {
    return "Target payout rate must be a whole-dollar amount of $0 or more.";
  }

  if (
    combined.includes("profiles_contract_hours_per_week_check") ||
    (error.code === "23514" && combined.includes("contract_hours_per_week"))
  ) {
    return "Select a valid weekly bandwidth before saving contract availability.";
  }

  if (
    combined.includes("contract_hourly_rate") &&
    (combined.includes("invalid input") ||
      combined.includes("type") ||
      error.code === "22P02")
  ) {
    return "Target payout rate must be a whole number (no currency symbols).";
  }

  return error.message?.trim() || "Could not save profile. Please try again.";
}

/** Ensure contract_hourly_rate is an integer or null before writing to Postgres. */
function coerceContractHourlyRateInPayload(payload: ProfilePayload): ProfilePayload {
  if (!("contract_hourly_rate" in payload)) {
    return payload;
  }

  const normalized = normalizeContractHourlyRate(
    payload.contract_hourly_rate as number | string | null
  );
  const persisted =
    normalized != null && normalized > 0 ? normalized : null;

  return {
    ...payload,
    contract_hourly_rate: persisted,
  };
}

async function runProfileWrite(
  supabase: SupabaseClient,
  userId: string,
  payload: ProfilePayload,
  mode: "update" | "upsert"
) {
  if (mode === "update") {
    const byId = await supabase
      .from("profiles")
      .update(payload)
      .eq("id", userId)
      .select("*")
      .maybeSingle();

    if (byId.data || byId.error) {
      return byId;
    }

    const byUserId = await supabase
      .from("profiles")
      .update(payload)
      .eq("user_id", userId)
      .select("*")
      .maybeSingle();

    if (
      byUserId.error &&
      (isMissingColumnError(byUserId.error) ||
        isSupabaseSchemaError(byUserId.error))
    ) {
      return byId;
    }

    return byUserId;
  }

  return supabase
    .from("profiles")
    .upsert({ id: userId, ...payload }, { onConflict: "id" })
    .select("*")
    .maybeSingle();
}

export async function persistCandidatePoolVisibility(
  supabase: SupabaseClient,
  userId: string,
  isVisibleInPool: boolean
): Promise<{
  error: { message?: string; code?: string } | null;
  userMessage: string | null;
}> {
  try {
    const {
      data: { session },
      error: sessionError,
    } = await supabase.auth.getSession();

    if (sessionError) {
      return {
        error: sessionError,
        userMessage: sessionError.message,
      };
    }

    if (!session?.user?.id) {
      return {
        error: { message: "No active session. Please sign in again." },
        userMessage: "You must be logged in to update visibility.",
      };
    }

    if (session.user.id !== userId) {
      return {
        error: { message: "Session user does not match profile owner." },
        userMessage: "Could not update visibility for this account.",
      };
    }

    if (isVisibleInPool) {
      // Keep profiles.github_* in sync with the auth identity before gating.
      // Local UI can already show "Linked" after a client-side merge even when
      // the DB row was stale — without this, the toggle fails with Connect GitHub.
      const syncedLink = await syncGitHubIdentityToProfile(
        supabase,
        session.user
      );

      const visibilitySelectFull =
        "id, user_id, github_verified, github_username, verification_status, is_audit_verified, production_score, audit_score, audit_breakdown, portfolio_url";
      const visibilitySelectFallback =
        "id, user_id, github_verified, github_username, verification_status, production_score, audit_score, portfolio_url";

      const profile =
        (await loadProfileForUserId(supabase, userId, visibilitySelectFull)) ??
        (await loadProfileForUserId(
          supabase,
          userId,
          visibilitySelectFallback
        ));

      const history = await supabase
        .from("production_audit_history")
        .select("production_score, audited_repo_url")
        .eq("user_id", userId)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      const historyScore =
        typeof history.data?.production_score === "number"
          ? history.data.production_score
          : null;
      const historyRepoUrl =
        typeof history.data?.audited_repo_url === "string"
          ? history.data.audited_repo_url
          : null;

      const githubUsername =
        (typeof profile?.github_username === "string" &&
        profile.github_username.trim()
          ? String(profile.github_username)
          : null) ??
        syncedLink?.github_username ??
        null;
      const githubVerified = isTalentPoolGitHubLinked({
        githubVerified:
          profile?.github_verified === true ||
          syncedLink?.github_verified === true,
        githubUsername,
      });
      const parsedAudit = parseProductionAuditFromProfileRow(
        profile
          ? {
              production_score:
                typeof profile.production_score === "number" ||
                typeof profile.production_score === "string"
                  ? profile.production_score
                  : null,
              audit_breakdown: profile.audit_breakdown,
              is_audit_verified:
                typeof profile.is_audit_verified === "boolean"
                  ? profile.is_audit_verified
                  : null,
              verification_status:
                typeof profile.verification_status === "string"
                  ? profile.verification_status
                  : null,
            }
          : null
      );
      const auditedRepoUrl = resolveTalentPoolAuditedRepoUrl({
        auditedRepoUrl: parsedAudit?.breakdown.audited_repo_url,
        auditBreakdown: profile?.audit_breakdown,
        portfolioUrl:
          typeof profile?.portfolio_url === "string"
            ? profile.portfolio_url
            : null,
        historyRepoUrl,
      });
      const ownershipVerified = isTalentPoolOwnershipVerified({
        verificationStatus:
          typeof profile?.verification_status === "string"
            ? profile.verification_status
            : parsedAudit?.verificationStatus ?? null,
        isAuditVerified:
          profile?.is_audit_verified === true ||
          parsedAudit?.isAuditVerified === true,
        auditedRepoUrl,
        auditBreakdown: profile?.audit_breakdown,
        portfolioUrl:
          typeof profile?.portfolio_url === "string"
            ? profile.portfolio_url
            : null,
        historyRepoUrl,
        githubUsername,
      });
      const scores: Array<number | null | undefined> = [
        typeof profile?.production_score === "number"
          ? profile.production_score
          : null,
        typeof profile?.audit_score === "number" ? profile.audit_score : null,
        parsedAudit?.productionScore ?? null,
        historyScore,
      ];

      if (
        !canEnableTalentPoolVisibility({
          githubVerified,
          ownershipVerified,
          scores,
        })
      ) {
        const message = talentPoolVisibilityFailureMessage({
          githubVerified,
          ownershipVerified,
          scores,
        });
        return {
          error: { message },
          userMessage: message,
        };
      }
    }

    const payload: ProfilePayload = {
      is_visible_in_pool: isVisibleInPool,
    };

    const { error } = await supabase
      .from("profiles")
      .update(payload)
      .or(`id.eq.${userId},user_id.eq.${userId}`);

    if (error) {
      return { error, userMessage: formatPersistError(error) };
    }

    return { error: null, userMessage: null };
  } catch (error) {
    console.error(
      "[persist-candidate-profile] persistCandidatePoolVisibility failed:",
      error
    );
    const message =
      error instanceof Error
        ? error.message
        : "Could not update visibility. Please try again.";
    return {
      error: { message },
      userMessage: message,
    };
  }
}

export async function persistCandidateProfile(
  supabase: SupabaseClient,
  userId: string,
  payload: ProfilePayload
): Promise<{
  data: Record<string, unknown> | null;
  error: { message?: string; code?: string } | null;
  userMessage: string | null;
}> {
  try {
    const {
      data: { session },
      error: sessionError,
    } = await supabase.auth.getSession();

    if (sessionError) {
      return {
        data: null,
        error: sessionError,
        userMessage: sessionError.message,
      };
    }

    if (!session?.user?.id) {
      return {
        data: null,
        error: { message: "No active session. Please sign in again." },
        userMessage: "You must be logged in to save your profile.",
      };
    }

    if (session.user.id !== userId) {
      return {
        data: null,
        error: { message: "Session user does not match profile owner." },
        userMessage: "Could not save profile for this account.",
      };
    }

    if ("bio" in payload) {
      const bioValue = typeof payload.bio === "string" ? payload.bio : "";
      const bioError = getCandidateBioValidationError(bioValue);
      if (bioError) {
        return {
          data: null,
          error: { message: bioError },
          userMessage: bioError,
        };
      }
    }

    if (payload.open_to_contract === true) {
      const contractDetailsError = getContractDetailsValidationError(
        true,
        typeof payload.contract_hours_per_week === "string"
          ? payload.contract_hours_per_week
          : null,
        typeof payload.contract_hourly_rate === "number"
          ? payload.contract_hourly_rate
          : null
      );
      if (contractDetailsError) {
        return {
          data: null,
          error: { message: contractDetailsError },
          userMessage: contractDetailsError,
        };
      }
    }

    if ("skills" in payload) {
      const parsedSkills = parseCandidateSkills(
        payload.skills as string[] | string | null | undefined
      );
      const skillsError = getCandidateSkillsValidationError(parsedSkills);
      if (skillsError) {
        return {
          data: null,
          error: { message: skillsError },
          userMessage: skillsError,
        };
      }
      payload = { ...payload, skills: parsedSkills };
    }

    if ("education" in payload) {
      const parsedEducation = parseEducationEntries(payload.education);
      const educationError = getEducationValidationError(parsedEducation, {
        isSelfTaught: Boolean(payload.is_self_taught),
      });
      if (educationError) {
        return {
          data: null,
          error: { message: educationError },
          userMessage: educationError,
        };
      }
      payload = {
        ...payload,
        education: serializeEducationEntries(parsedEducation),
      };
    }

    const publishGateSelect =
      "id, role, full_name, name, first_name, last_name, job_title, headline, bio, skills, github_verified, github_username, verification_status, is_audit_verified, production_score, audit_score, audit_breakdown, portfolio_url, is_visible_in_pool";
    let publishGateProfile = await loadProfileForUserId(
      supabase,
      userId,
      publishGateSelect
    );

    const mergedForPublish: PublishedCandidateProfileRow = {
      ...(publishGateProfile ?? {}),
      id: userId,
      full_name:
        typeof payload.full_name === "string"
          ? payload.full_name
          : typeof publishGateProfile?.full_name === "string"
            ? publishGateProfile.full_name
            : null,
      job_title:
        typeof payload.job_title === "string"
          ? payload.job_title
          : typeof publishGateProfile?.job_title === "string"
            ? publishGateProfile.job_title
            : null,
      bio:
        typeof payload.bio === "string"
          ? payload.bio
          : typeof publishGateProfile?.bio === "string"
            ? publishGateProfile.bio
            : null,
      skills: Array.isArray(payload.skills)
        ? (payload.skills as string[])
        : Array.isArray(publishGateProfile?.skills)
          ? (publishGateProfile.skills as string[]).filter(
              (skill): skill is string => typeof skill === "string"
            )
          : null,
      github_verified: publishGateProfile?.github_verified === true,
      production_score:
        typeof publishGateProfile?.production_score === "number"
          ? publishGateProfile.production_score
          : null,
      audit_score:
        typeof publishGateProfile?.audit_score === "number"
          ? publishGateProfile.audit_score
          : null,
      role:
        typeof publishGateProfile?.role === "string"
          ? publishGateProfile.role
          : null,
    };

    if (meetsTalentPoolAutoPublishCriteria(mergedForPublish)) {
      const metadata = talentPoolMetadataDefaults({
        work_preference:
          typeof payload.work_preference === "string"
            ? payload.work_preference
            : null,
        timezone: typeof payload.timezone === "string" ? payload.timezone : null,
        availability_status:
          typeof payload.availability_status === "string"
            ? payload.availability_status
            : null,
      });
      payload = {
        ...payload,
        is_visible_in_pool: true,
        work_preference: metadata.work_preference,
        timezone: metadata.timezone,
        availability_status: metadata.availability_status,
      };
    }

    const wantsMarketplaceAvailability =
      payload.open_to_fulltime === true || payload.open_to_contract === true;

    if (wantsMarketplaceAvailability) {
      // Match the green "✓ Linked / Ownership verified" UI: sync OAuth GitHub
      // onto the profile before gating, and resolve ownership via audit history
      // when the profile row is still catching up.
      const syncedLink = await syncGitHubIdentityToProfile(
        supabase,
        session.user
      );
      publishGateProfile =
        (await loadProfileForUserId(supabase, userId, publishGateSelect)) ??
        publishGateProfile;

      const history = await supabase
        .from("production_audit_history")
        .select("production_score, audited_repo_url")
        .eq("user_id", userId)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      const historyScore =
        typeof history.data?.production_score === "number"
          ? history.data.production_score
          : null;
      const historyRepoUrl =
        typeof history.data?.audited_repo_url === "string"
          ? history.data.audited_repo_url
          : null;

      const profileScores = [
        typeof publishGateProfile?.production_score === "number"
          ? publishGateProfile.production_score
          : null,
        typeof publishGateProfile?.audit_score === "number"
          ? publishGateProfile.audit_score
          : null,
      ];

      const githubUsername =
        (typeof publishGateProfile?.github_username === "string" &&
        publishGateProfile.github_username.trim()
          ? String(publishGateProfile.github_username)
          : null) ??
        syncedLink?.github_username ??
        null;
      const githubVerified = isTalentPoolGitHubLinked({
        githubVerified:
          publishGateProfile?.github_verified === true ||
          syncedLink?.github_verified === true,
        githubUsername,
      });
      const publishAudit = parseProductionAuditFromProfileRow(
        publishGateProfile
          ? {
              production_score:
                typeof publishGateProfile.production_score === "number" ||
                typeof publishGateProfile.production_score === "string"
                  ? publishGateProfile.production_score
                  : null,
              audit_breakdown: publishGateProfile.audit_breakdown,
              is_audit_verified:
                typeof publishGateProfile.is_audit_verified === "boolean"
                  ? publishGateProfile.is_audit_verified
                  : null,
              verification_status:
                typeof publishGateProfile.verification_status === "string"
                  ? publishGateProfile.verification_status
                  : null,
            }
          : null
      );
      const portfolioUrl =
        typeof publishGateProfile?.portfolio_url === "string"
          ? publishGateProfile.portfolio_url
          : typeof payload.portfolio_url === "string"
            ? payload.portfolio_url
            : null;
      const ownershipVerified = isTalentPoolOwnershipVerified({
        verificationStatus:
          typeof publishGateProfile?.verification_status === "string"
            ? publishGateProfile.verification_status
            : publishAudit?.verificationStatus ?? null,
        isAuditVerified:
          publishGateProfile?.is_audit_verified === true ||
          publishAudit?.isAuditVerified === true,
        auditedRepoUrl: resolveTalentPoolAuditedRepoUrl({
          auditedRepoUrl: publishAudit?.breakdown.audited_repo_url,
          auditBreakdown: publishGateProfile?.audit_breakdown,
          portfolioUrl,
          historyRepoUrl,
        }),
        auditBreakdown: publishGateProfile?.audit_breakdown,
        portfolioUrl,
        historyRepoUrl,
        githubUsername,
      });
      const isVisibleInPool =
        payload.is_visible_in_pool === true ||
        publishGateProfile?.is_visible_in_pool === true;

      const publishFailures = listMarketplacePublishGateFailures({
        isVisibleInPool,
        githubVerified,
        ownershipVerified,
        scores: [
          ...profileScores,
          publishAudit?.productionScore ?? null,
          historyScore,
        ],
      });

      if (publishFailures.length > 0) {
        const message =
          formatMarketplacePublishSaveBlockedMessage(publishFailures);
        console.error(
          "[persist-candidate-profile] marketplace availability blocked",
          {
            failures: publishFailures,
            githubVerified,
            ownershipVerified,
            githubUsername,
            isVisibleInPool,
            historyRepoUrl,
            syncedLink,
            profileGithubVerified: publishGateProfile?.github_verified,
            verificationStatus: publishGateProfile?.verification_status,
            isAuditVerified: publishGateProfile?.is_audit_verified,
          }
        );
        return {
          data: null,
          error: { message },
          userMessage: message,
        };
      }
    }

    const { visible_to_employers: _visibleToEmployersAlias, ...writablePayload } =
      payload;
    let attemptPayload: ProfilePayload = coerceContractHourlyRateInPayload({
      ...writablePayload,
    });
    const maxAttempts = Object.keys(attemptPayload).length + 3;

    for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
      let result = await runProfileWrite(supabase, userId, attemptPayload, "update");

      if (!result.error && !result.data) {
        result = await runProfileWrite(supabase, userId, attemptPayload, "upsert");
      }

      if (result.error) {
        console.error("[persist-candidate-profile] profile write failed:", {
          message: result.error?.message,
          details: result.error?.details,
          hint: result.error?.hint,
          code: result.error?.code,
          error: result.error,
          attempt,
          modeHint: "update/upsert",
          contract_hourly_rate: attemptPayload.contract_hourly_rate,
          contract_hours_per_week: attemptPayload.contract_hours_per_week,
          open_to_contract: attemptPayload.open_to_contract,
        });
      }

      if (!result.error && result.data) {
        const educationPatch: ProfilePayload = {};
        for (const key of [
          "university",
          "school",
          "major",
          "degree",
          "gpa",
          "graduation_year",
          "education",
          "is_self_taught",
        ] as const) {
          if (key in attemptPayload) {
            educationPatch[key] = attemptPayload[key];
          }
        }

        if (Object.keys(educationPatch).length > 0) {
          await supabase
            .from("profiles")
            .update(educationPatch)
            .eq("user_id", userId);
        }

        return { data: result.data, error: null, userMessage: null };
      }

      if (
        result.error &&
        !isMissingColumnError(result.error) &&
        !isUniqueViolation(result.error) &&
        !isSupabaseSchemaError(result.error)
      ) {
        return {
          data: null,
          error: result.error,
          userMessage: formatPersistError(result.error),
        };
      }

      if (result.error && isUniqueViolation(result.error) && attemptPayload.profile_slug) {
        const { profile_slug: _removed, ...rest } = attemptPayload;
        attemptPayload = rest;
        continue;
      }

      if (
        result.error &&
        (isMissingColumnError(result.error) || isSupabaseSchemaError(result.error))
      ) {
        const keyToDrop = findMentionedColumn(
          result.error,
          Object.keys(attemptPayload)
        );
        if (keyToDrop && keyToDrop in attemptPayload) {
          const { [keyToDrop]: _removed, ...rest } = attemptPayload;
          attemptPayload = rest;
          continue;
        }
      }

      return {
        data: null,
        error: result.error,
        userMessage: formatPersistError(result.error),
      };
    }

    return {
      data: null,
      error: { message: "Profile save failed after retries." },
      userMessage: "Could not save profile. Please try again.",
    };
  } catch (error) {
    console.error(
      "[persist-candidate-profile] persistCandidateProfile failed:",
      error
    );
    const message =
      error instanceof Error
        ? error.message
        : "Could not save profile. Please try again.";
    return {
      data: null,
      error: { message },
      userMessage: message,
    };
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import {
  isSupabaseSchemaError,
  schemaErrorMentionsColumn,
} from "@/lib/supabase-schema-errors";

export type EmployerProfileFormData = {
  businessName: string;
  industry: string;
  companyBio: string;
  workEmail: string;
  phone: string;
  billingPlan: string;
};

function nullIfEmpty(value: string | null | undefined): string | null {
  const trimmed = value?.trim();
  return trimmed ? trimmed : null;
}

export function resolveEmployerBillingPlan(profile: {
  is_pro?: boolean | null;
  tier?: string | null;
}): string {
  if (profile.is_pro) {
    const tier = profile.tier?.trim();
    if (tier && tier.toLowerCase() !== "free") {
      return tier;
    }
    return "Pro";
  }

  return "Free Plan";
}

export function hydrateEmployerProfileFromRow(
  profile: {
    company_name?: string | null;
    industry?: string | null;
    bio?: string | null;
    contact_email?: string | null;
    email?: string | null;
    phone?: string | null;
    is_pro?: boolean | null;
    tier?: string | null;
  } | null,
  fallbackEmail?: string | null
): EmployerProfileFormData {
  return {
    businessName: profile?.company_name?.trim() ?? "",
    industry: profile?.industry?.trim() ?? "",
    companyBio: profile?.bio?.trim() ?? "",
    workEmail:
      profile?.contact_email?.trim() ??
      profile?.email?.trim() ??
      fallbackEmail?.trim() ??
      "",
    phone: profile?.phone?.trim() ?? "",
    billingPlan: resolveEmployerBillingPlan(profile ?? {}),
  };
}

export function buildEmployerProfileUpdatePayload(
  input: Pick<
    EmployerProfileFormData,
    "businessName" | "industry" | "companyBio" | "workEmail" | "phone"
  >
): Record<string, string | boolean | null> {
  const workEmail = nullIfEmpty(input.workEmail);

  return {
    company_name: nullIfEmpty(input.businessName),
    industry: nullIfEmpty(input.industry),
    bio: nullIfEmpty(input.companyBio),
    contact_email: workEmail,
    email: workEmail,
    phone: nullIfEmpty(input.phone),
  };
}

async function updateEmployerProfile(
  supabase: SupabaseClient,
  userId: string,
  payload: Record<string, string | boolean | null>
): Promise<{ error: { message?: string } | null }> {
  const { error } = await supabase
    .from("profiles")
    .update(payload)
    .eq("id", userId);

  if (
    error &&
    isSupabaseSchemaError(error) &&
    schemaErrorMentionsColumn(error, "is_verified")
  ) {
    const retryPayload = { ...payload };
    delete retryPayload.is_verified;
    const retry = await supabase
      .from("profiles")
      .update(retryPayload)
      .eq("id", userId);
    return { error: retry.error };
  }

  return { error };
}

export async function persistEmployerProfile(
  supabase: SupabaseClient,
  userId: string,
  input: Pick<
    EmployerProfileFormData,
    "businessName" | "industry" | "companyBio" | "workEmail" | "phone"
  >
): Promise<{ error: { message?: string } | null; isVerified: boolean }> {
  try {
    const payload = buildEmployerProfileUpdatePayload(input);
    const nextEmail = (payload.contact_email ?? "").toString().trim().toLowerCase();

    const { data: current } = await supabase
      .from("profiles")
      .select("contact_email, email, is_verified")
      .eq("id", userId)
      .maybeSingle();

    const previousEmail = (
      current?.contact_email?.trim() ||
      current?.email?.trim() ||
      ""
    ).toLowerCase();
    const emailChanged = Boolean(nextEmail) && nextEmail !== previousEmail;
    const stillVerified = current?.is_verified === true && !emailChanged;

    if (emailChanged && current?.is_verified === true) {
      payload.is_verified = false;
    }

    const { error } = await updateEmployerProfile(supabase, userId, payload);

    return {
      error,
      isVerified: stillVerified,
    };
  } catch (error) {
    console.error("[persist-employer-profile] persistEmployerProfile failed:", error);
    return {
      error: {
        message:
          error instanceof Error
            ? error.message
            : "Could not save employer profile.",
      },
      isVerified: false,
    };
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";

type VerifiedProfileRow = {
  id?: string | null;
  user_id?: string | null;
  is_verified?: boolean | null;
};

function rowIsVerified(row: VerifiedProfileRow | null | undefined): boolean {
  return row?.is_verified === true;
}

async function selectVerifiedRows(
  admin: SupabaseClient,
  userId: string
): Promise<VerifiedProfileRow[]> {
  const [byId, byUserId] = await Promise.all([
    admin
      .from("profiles")
      .select("id, user_id, is_verified")
      .eq("id", userId),
    admin
      .from("profiles")
      .select("id, user_id, is_verified")
      .eq("user_id", userId),
  ]);

  const rows = new Map<string, VerifiedProfileRow>();
  for (const row of [...(byId.data ?? []), ...(byUserId.data ?? [])]) {
    const key = typeof row.id === "string" ? row.id : JSON.stringify(row);
    rows.set(key, row as VerifiedProfileRow);
  }
  return [...rows.values()];
}

async function updateIsVerifiedByUserId(
  admin: SupabaseClient,
  userId: string,
  patch: Record<string, string | boolean | null>
): Promise<VerifiedProfileRow[]> {
  const byId = await admin
    .from("profiles")
    .update(patch)
    .eq("id", userId)
    .select("id, user_id, is_verified");

  const byUserId = await admin
    .from("profiles")
    .update(patch)
    .eq("user_id", userId)
    .select("id, user_id, is_verified");

  if (byId.error) {
    console.error("[employer-verify] is_verified update by id failed:", byId.error);
  }
  if (byUserId.error) {
    console.error(
      "[employer-verify] is_verified update by user_id failed:",
      byUserId.error
    );
  }

  return [...(byId.data ?? []), ...(byUserId.data ?? [])] as VerifiedProfileRow[];
}

export async function persistEmployerVerifiedFlag(
  admin: SupabaseClient,
  userId: string,
  email: string
): Promise<{ ok: boolean; profileId: string | null }> {
  try {
    const normalizedEmail = email.trim().toLowerCase();
    const nowIso = new Date().toISOString();

    const rpc = await admin.rpc("mark_employer_email_verified", {
      p_user_id: userId,
      p_email: normalizedEmail,
    });

    if (!rpc.error) {
      const rpcRows = (Array.isArray(rpc.data) ? rpc.data : rpc.data ? [rpc.data] : []) as VerifiedProfileRow[];
      if (rpcRows.some(rowIsVerified)) {
        const verified = rpcRows.find(rowIsVerified);
        return { ok: true, profileId: verified?.id ?? userId };
      }
    } else {
      console.warn("[employer-verify] mark_employer_email_verified rpc:", rpc.error.message);
    }

    const fullPatch = {
      is_verified: true,
      email_verified_at: nowIso,
      contact_email: normalizedEmail || null,
      email: normalizedEmail || null,
    };

    let updated = await updateIsVerifiedByUserId(admin, userId, fullPatch);
    if (!updated.some(rowIsVerified)) {
      updated = await updateIsVerifiedByUserId(admin, userId, { is_verified: true });
    }

    const confirmed = (await selectVerifiedRows(admin, userId)).find(rowIsVerified);
    if (confirmed) {
      return { ok: true, profileId: confirmed.id ?? userId };
    }

    console.error(
      "[employer-verify] is_verified did not persist for user",
      userId,
      updated
    );
    return { ok: false, profileId: null };
  } catch (error) {
    console.error("[employer-verify] persistEmployerVerifiedFlag failed:", error);
    return { ok: false, profileId: null };
  }
}

export async function employerIsVerifiedInDatabase(
  admin: SupabaseClient,
  userId: string
): Promise<boolean> {
  try {
    const rows = await selectVerifiedRows(admin, userId);
    return rows.some(rowIsVerified);
  } catch (error) {
    console.error("[employer-verify] employerIsVerifiedInDatabase failed:", error);
    return false;
  }
}

export const FLAT_FEE_THRESHOLD = 25_000;
export const FLAT_FEE_AMOUNT = 2_500;
export const CONTINGENCY_RATE = 0.1;
export const REPLACEMENT_GUARANTEE_DAYS = 90;
export const DEFAULT_CANDIDATE_BONUS = 750;
export const CANDIDATE_BONUS_RANGE_LABEL = "$750";

export type PlacementRevenueInput = {
  agreed_first_year_compensation?: number | null;
  candidate_bonus_allocated?: number | null;
};

export function parseCompensationValue(
  value: number | string | null | undefined
): number | null {
  if (value == null) {
    return null;
  }

  if (typeof value === "number") {
    return Number.isFinite(value) && value > 0 ? value : null;
  }

  const parsed = Number.parseFloat(String(value).replace(/[^0-9.]/g, ""));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

export function calculatePlacementFee(salary: number): number {
  if (salary <= FLAT_FEE_THRESHOLD) {
    return FLAT_FEE_AMOUNT;
  }

  return salary * CONTINGENCY_RATE;
}

export function calculateCandidateBonus(
  salary: number,
  allocated?: number | null
): number {
  if (salary > FLAT_FEE_THRESHOLD) {
    return 0;
  }

  const parsedAllocated = parseCompensationValue(allocated ?? null);
  return parsedAllocated ?? DEFAULT_CANDIDATE_BONUS;
}

export function summarizePlacementRevenue(
  hires: PlacementRevenueInput[]
): {
  platformRevenue: number;
  candidateBonusesAllocated: number;
  hiredCount: number;
} {
  let platformRevenue = 0;
  let candidateBonusesAllocated = 0;
  let hiredCount = 0;

  for (const hire of hires) {
    const salary = parseCompensationValue(hire.agreed_first_year_compensation);
    if (!salary) {
      continue;
    }

    hiredCount += 1;
    platformRevenue += calculatePlacementFee(salary);
    candidateBonusesAllocated += calculateCandidateBonus(
      salary,
      hire.candidate_bonus_allocated
    );
  }

  return {
    platformRevenue,
    candidateBonusesAllocated,
    hiredCount,
  };
}

export function formatCurrency(amount: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(amount);
}

