import { NextResponse } from "next/server";
import { createServiceRoleClient } from "@/lib/admin-access";
import { isSupabaseSchemaError } from "@/lib/supabase-schema-errors";
import {
  PROVIX_BRANCHES,
  PROVIX_FILENAME,
  PROVIX_FILENAMES,
  normalizeProofToken,
} from "@/lib/provix-token";

export type GithubFileResult =
  | { kind: "found"; branch: string; content: string }
  | { kind: "missing"; branch: string }
  | { kind: "error"; branch: string; status: number; message: string };

function githubRawProvixUrl(
  owner: string,
  repo: string,
  branch: string,
  filename: string
): string {
  return `https://raw.githubusercontent.com/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/${encodeURIComponent(branch)}/${filename}`;
}

function githubFetchHeaders(): HeadersInit {
  const headers: Record<string, string> = {
    Accept: "text/plain",
    "User-Agent": "Provix-RepoVerification/1.0",
  };

  const token = process.env.GITHUB_TOKEN?.trim();
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  return headers;
}

export async function fetchProvixOnBranch(
  owner: string,
  repo: string,
  branch: string,
  filename: string = PROVIX_FILENAME
): Promise<GithubFileResult> {
  const url = githubRawProvixUrl(owner, repo, branch, filename);

  try {
    const response = await fetch(url, {
      method: "GET",
      cache: "no-store",
      redirect: "follow",
      headers: githubFetchHeaders(),
      signal: AbortSignal.timeout(15_000),
    });

    if (response.status === 404) {
      return { kind: "missing", branch };
    }

    if (response.status === 429) {
      return {
        kind: "error",
        branch,
        status: 429,
        message: "GitHub rate-limited the verification request. Try again shortly.",
      };
    }

    if (response.status === 401 || response.status === 403) {
      return {
        kind: "error",
        branch,
        status: response.status,
        message:
          "GitHub denied access to this repository. Make sure the repo is public and provix.txt or PROVIX.TXT is at the root.",
      };
    }

    if (!response.ok) {
      return {
        kind: "error",
        branch,
        status: response.status,
        message: `GitHub returned ${response.status} while reading ${filename} on ${branch}.`,
      };
    }

    const content = await response.text();
    return { kind: "found", branch, content };
  } catch (error) {
    const name = error instanceof Error ? error.name : "";
    if (name === "AbortError" || name === "TimeoutError") {
      return {
        kind: "error",
        branch,
        status: 504,
        message: `Timed out reading ${filename} from the ${branch} branch.`,
      };
    }

    console.error(`[provix-token] fetch failed for ${url}:`, error);
    return {
      kind: "error",
      branch,
      status: 502,
      message: `Could not reach GitHub to read ${filename} on ${branch}.`,
    };
  }
}

export async function findMatchingProvixFile(
  owner: string,
  repo: string,
  expectedToken: string
): Promise<
  | { ok: true; branch: string }
  | { ok: false; response: NextResponse }
> {
  const expected = normalizeProofToken(expectedToken).trim();
  let sawFile = false;
  let lastError: Extract<GithubFileResult, { kind: "error" }> | null = null;
  const missingBranches: string[] = [];

  for (const branch of PROVIX_BRANCHES) {
    let branchMissing = true;

    for (const filename of PROVIX_FILENAMES) {
      const result = await fetchProvixOnBranch(owner, repo, branch, filename);

      if (result.kind === "missing") {
        continue;
      }

      branchMissing = false;

      if (result.kind === "error") {
        lastError = result;
        continue;
      }

      sawFile = true;
      const fetched = normalizeProofToken(result.content).trim();
      if (fetched === expected) {
        return { ok: true, branch: result.branch };
      }
    }

    if (branchMissing) {
      missingBranches.push(branch);
    }
  }

  if (sawFile) {
    return {
      ok: false,
      response: NextResponse.json(
        {
          error: "provix.txt or PROVIX.TXT was found, but the token did not match.",
          verified: false,
          success: false,
        },
        { status: 400 }
      ),
    };
  }

  if (lastError) {
    const status =
      lastError.status === 429 ? 429 : lastError.status >= 500 ? 502 : 400;
    return {
      ok: false,
      response: NextResponse.json(
        {
          error: lastError.message,
          verified: false,
          success: false,
          missing_branches: missingBranches,
        },
        { status }
      ),
    };
  }

  return {
    ok: false,
    response: NextResponse.json(
      {
        error:
          "provix.txt or PROVIX.TXT was not detected on main or master. Add the file at the repository root with your verification token and try again.",
        verified: false,
        success: false,
        missing_branches:
          missingBranches.length > 0 ? missingBranches : [...PROVIX_BRANCHES],
      },
      { status: 404 }
    ),
  };
}

function missingTableResponse() {
  return NextResponse.json(
    {
      error:
        "Repo verification is not enabled yet. Apply Supabase migration 0072_create_repo_verifications.sql.",
      verified: false,
      success: false,
    },
    { status: 500 }
  );
}

export async function persistVerifiedRepo(input: {
  userId: string;
  repoUrl: string;
  token: string;
}): Promise<
  | { ok: true; alreadyVerified: boolean }
  | { ok: false; response: NextResponse }
> {
  try {
    const admin = createServiceRoleClient();
    if (!admin) {
      return {
        ok: false,
        response: NextResponse.json(
          { error: "Verification is temporarily unavailable.", verified: false, success: false },
          { status: 503 }
        ),
      };
    }

    const normalizedRepoUrl = input.repoUrl.trim().toLowerCase();
    const { data: existingRows, error: lookupError } = await admin
      .from("repo_verifications")
      .select("id, is_verified, repo_url")
      .eq("user_id", input.userId);

    if (lookupError) {
      if (isSupabaseSchemaError(lookupError)) {
        return { ok: false, response: missingTableResponse() };
      }
      console.error("[provix-token] lookup failed:", lookupError.message);
      return {
        ok: false,
        response: NextResponse.json(
          { error: "Could not update repository verification.", verified: false, success: false },
          { status: 500 }
        ),
      };
    }

    const existing = (existingRows ?? []).find(
      (row) =>
        typeof row.repo_url === "string" &&
        row.repo_url.trim().toLowerCase() === normalizedRepoUrl
    );

    if (existing?.id) {
      const { error: updateError } = await admin
        .from("repo_verifications")
        .update({
          token: input.token,
          repo_url: normalizedRepoUrl,
          is_verified: true,
        })
        .eq("id", existing.id)
        .eq("user_id", input.userId);

      if (updateError) {
        if (isSupabaseSchemaError(updateError)) {
          return { ok: false, response: missingTableResponse() };
        }
        console.error("[provix-token] update failed:", updateError.message);
        return {
          ok: false,
          response: NextResponse.json(
            { error: "Could not update repository verification.", verified: false, success: false },
            { status: 500 }
          ),
        };
      }

      return { ok: true, alreadyVerified: existing.is_verified === true };
    }

    const { error: insertError } = await admin.from("repo_verifications").insert({
      user_id: input.userId,
      repo_url: normalizedRepoUrl,
      token: input.token,
      is_verified: true,
    });

    if (!insertError) {
      return { ok: true, alreadyVerified: false };
    }

    if (isSupabaseSchemaError(insertError)) {
      return { ok: false, response: missingTableResponse() };
    }

    if (insertError.code === "23505") {
      const { error: conflictUpdateError } = await admin
        .from("repo_verifications")
        .update({
          token: input.token,
          repo_url: normalizedRepoUrl,
          is_verified: true,
        })
        .eq("user_id", input.userId)
        .ilike("repo_url", normalizedRepoUrl);

      if (conflictUpdateError) {
        console.error("[provix-token] conflict update failed:", conflictUpdateError.message);
        return {
          ok: false,
          response: NextResponse.json(
            { error: "Could not update repository verification.", verified: false, success: false },
            { status: 500 }
          ),
        };
      }

      return { ok: true, alreadyVerified: false };
    }

    console.error("[provix-token] insert failed:", insertError.message);
    return {
      ok: false,
      response: NextResponse.json(
        { error: "Could not save repository verification.", verified: false, success: false },
        { status: 500 }
      ),
    };
  } catch (error) {
    console.error("[provix-token] persistVerifiedRepo failed:", error);
    return {
      ok: false,
      response: NextResponse.json(
        { error: "Could not save repository verification.", verified: false, success: false },
        { status: 500 }
      ),
    };
  }
}

import { describe, expect, it } from "vitest";
import type { User } from "@supabase/supabase-js";
import {
  buildProvixVerificationToken,
  canBypassProvixTokenChallenge,
  normalizeProofToken,
} from "./provix-token";

function user(overrides: Record<string, unknown> = {}): User {
  return {
    id: "user-1",
    identities: [],
    user_metadata: {},
    app_metadata: {},
    ...overrides,
  } as unknown as User;
}

describe("provix token helpers", () => {
  it("builds a deterministic short-user token", () => {
    expect(
      buildProvixVerificationToken("a1b2c3d4-e5f6-7890-abcd-ef1234567890")
    ).toBe("provix-verify-a1b2c3d4");
  });

  it("canonicalizes GitHub repo URLs in lowercase", async () => {
    const { canonicalGitHubRepoUrl } = await import("./provix-token");
    expect(canonicalGitHubRepoUrl("OctoCat", "Hello-World")).toBe(
      "https://github.com/octocat/hello-world"
    );
  });

  it("bypasses the token challenge for GitHub OAuth or a verified profile", () => {
    expect(
      canBypassProvixTokenChallenge(
        user({
          identities: [{ provider: "github", identity_data: { user_name: "octo" } }],
        })
      )
    ).toBe(true);
    expect(
      canBypassProvixTokenChallenge(
        user({ app_metadata: { provider: "google", providers: ["google"] } }),
        true
      )
    ).toBe(true);
    expect(
      canBypassProvixTokenChallenge(
        user({ app_metadata: { provider: "email", providers: ["email"] } }),
        false
      )
    ).toBe(false);
  });

  it("trims BOM and whitespace from proof tokens", () => {
    expect(normalizeProofToken("\uFEFFprovix-verify-abcd  \n")).toBe(
      "provix-verify-abcd"
    );
  });
});

import type { SupabaseClient, User } from "@supabase/supabase-js";
import { userHasGitHubIdentity } from "@/lib/github-identity";
import { isSupabaseSchemaError } from "@/lib/supabase-schema-errors";

export const PROVIX_FILENAME = "provix.txt";
export const PROVIX_FILENAMES = ["provix.txt", "PROVIX.TXT"] as const;
export const PROVIX_TOKEN_PREFIX = "provix-verify-";
export const PROVIX_BRANCHES = ["main", "master"] as const;

export function buildProvixVerificationToken(userId: string): string {
  const compact = userId.replace(/-/g, "").toLowerCase();
  const shortId = compact.slice(0, 8) || "user";
  return `${PROVIX_TOKEN_PREFIX}${shortId}`;
}

export function canBypassProvixTokenChallenge(
  user: User | null | undefined,
  profileGithubVerified?: boolean | null
): boolean {
  return userHasGitHubIdentity(user) || profileGithubVerified === true;
}

export function normalizeProofToken(value: string): string {
  return value.replace(/^\uFEFF/, "").trim();
}

export function canonicalGitHubRepoUrl(owner: string, repo: string): string {
  return `https://github.com/${owner.trim().toLowerCase()}/${repo.trim().toLowerCase()}`;
}

export async function hasPersistedProvixTokenVerification(
  supabase: Pick<SupabaseClient, "from">,
  userId: string,
  repoUrl: string
): Promise<boolean> {
  const normalized = repoUrl.trim().toLowerCase();
  const { data, error } = await supabase
    .from("repo_verifications")
    .select("is_verified, repo_url")
    .eq("user_id", userId)
    .eq("is_verified", true);

  if (error) {
    if (!isSupabaseSchemaError(error)) {
      console.error("[provix-token] existing verification lookup failed:", error.message);
    }
    return false;
  }

  return (data ?? []).some(
    (row) =>
      typeof row.repo_url === "string" &&
      row.repo_url.trim().toLowerCase() === normalized
  );
}

