  });

  it("excludes employer and employee roles from the talent pool", () => {
    expect(
      isPublishedVerifiedCandidateProfile(
        completeVerifiedRow({ role: "employer" })
      )
    ).toBe(false);
    expect(
      isPublishedVerifiedCandidateProfile(
        completeVerifiedRow({ role: "employee" })
      )
    ).toBe(false);
  });
});

