export function normalizeSiteUrl(raw: string): string {
  const trimmed = raw.replace(/\/$/, "");
  try {
    const url = new URL(trimmed);
    if (url.hostname === "www.getprovix.com") {
      url.hostname = "getprovix.com";
      return url.origin;
    }
  } catch {
