export function resolveCandidateGithubUrl(input: {
  github_url?: string | null;
  portfolio_url?: string | null;
  github?: string | null;
}): { githubUrl: string; github: string } {
  const portfolioUrl = input.portfolio_url?.trim() || "";
  const explicitGithub = input.github_url?.trim() || input.github?.trim() || "";
  const isLinkedIn = portfolioUrl.toLowerCase().includes("linkedin");
  const githubUrl =
    explicitGithub || (!isLinkedIn && portfolioUrl ? portfolioUrl : "");

  return {
    githubUrl,
    github: githubUrl || portfolioUrl,
  };
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { formatGpa } from "@/lib/gpa";
import {
  parseEducationFromProfileRow,
  parseIsSelfTaught,
} from "@/lib/candidate-education";
import { isEmployerRole } from "@/lib/dashboard-account";
import {
  explainPublishedVerifiedCandidateRejection,
  isPublishedVerifiedCandidateProfile,
} from "@/lib/published-candidate-profile";
import {
  findMentionedColumn,
  isSupabaseSchemaError,
  schemaErrorMentionsColumn,
} from "@/lib/supabase-schema-errors";

export type TalentPoolEducation = {
  university: string;
  major: string;
  gpa: string;
  graduationYear: string;
  isSelfTaught?: boolean;
};

const UNIVERSITY_KEYS = [
  "university",
  "school",
  "college",
  "institution",
  "school_name",
] as const;

const MAJOR_KEYS = ["major", "degree", "specialization", "intended_major"] as const;

const GPA_KEYS = ["gpa", "grade_point_average", "gpa_value"] as const;

const GRADUATION_YEAR_KEYS = [
  "graduation_year",
  "graduationYear",
  "grad_year",
  "gradYear",
] as const;

export const PROFILE_EDUCATION_COLUMNS = [
  "id",
  "user_id",
  "university",
  "school",
  "major",
  "degree",
  "gpa",
  "graduation_year",
  "education",
  "is_self_taught",
] as const;

const PROFILE_ID_COLUMNS = ["id", "user_id"] as const;
const missingTalentPoolFilterColumns = new Set<string>();

function coerceProfileText(value: unknown): string {
  if (value == null) {
    return "";
  }

  if (typeof value === "number" && Number.isFinite(value)) {
    return String(value);
  }

  if (typeof value === "bigint") {
    return value.toString();
  }

  if (typeof value === "string") {
    return value.trim();
  }

  return "";
}

function valueFromRow(
  row: Record<string, unknown>,
  keys: readonly string[]
): string {
  const lowerEntries = new Map(
    Object.entries(row).map(([key, value]) => [key.toLowerCase(), value])
  );

  for (const key of keys) {
    const direct = coerceProfileText(row[key]);
    if (direct) {
      return direct;
    }

    const lowered = coerceProfileText(lowerEntries.get(key.toLowerCase()));
    if (lowered) {
      return lowered;
    }
  }

  return "";
}

export function educationFromProfileRow(
  row: Record<string, unknown> | null | undefined
): TalentPoolEducation {
  if (!row) {
    return {
      university: "",
      major: "",
      gpa: "",
      graduationYear: "",
      isSelfTaught: false,
    };
  }

  const fromEntries = parseEducationFromProfileRow(row);
  const primary = fromEntries[0];

  return {
    university: primary?.institution || valueFromRow(row, UNIVERSITY_KEYS),
    major: primary?.fieldOfStudy || valueFromRow(row, MAJOR_KEYS),
    gpa: formatGpa(valueFromRow(row, GPA_KEYS)),
    graduationYear:
      primary?.graduationYear || valueFromRow(row, GRADUATION_YEAR_KEYS),
    isSelfTaught: parseIsSelfTaught(row.is_self_taught ?? row.isSelfTaught),
  };
}

export function resolveTalentProfileId(candidate: {
  id?: string | null;
  profileId?: string | null;
}): string {
  const uuidPattern =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  for (const value of [candidate.profileId, candidate.id]) {
    const trimmed = typeof value === "string" ? value.trim() : "";
    if (uuidPattern.test(trimmed)) {
      return trimmed;
    }
  }

  return (
    (typeof candidate.profileId === "string" ? candidate.profileId.trim() : "") ||
    (typeof candidate.id === "string" ? candidate.id.trim() : "")
  );
}

export function candidateEducationFields(
  candidate: TalentPoolEducation
): TalentPoolEducation {
  return {
    university: candidate.university,
    major: candidate.major,
    gpa: formatGpa(candidate.gpa),
    graduationYear: candidate.graduationYear,
    isSelfTaught: Boolean(candidate.isSelfTaught),
  };
}

export function hasTalentEducation(education: TalentPoolEducation): boolean {
  if (education.isSelfTaught) {
    return true;
  }

  return [
    education.university,
    education.major,
    formatGpa(education.gpa),
    education.graduationYear,
  ].some(Boolean);
}

export function mergeTalentEducation(
  current: TalentPoolEducation,
  incoming: TalentPoolEducation
): TalentPoolEducation {
  return {
    university: incoming.university || current.university,
    major: incoming.major || current.major,
    gpa: formatGpa(incoming.gpa) || formatGpa(current.gpa),
    graduationYear: incoming.graduationYear || current.graduationYear,
    isSelfTaught: Boolean(incoming.isSelfTaught || current.isSelfTaught),
  };
}

function profileRowLookupIds(row: Record<string, unknown>): string[] {
  return PROFILE_ID_COLUMNS.map((column) => coerceProfileText(row[column])).filter(
    Boolean
  );
}

function isEmptyProfileValue(value: unknown): boolean {
  if (value == null) {
    return true;
  }
  if (typeof value === "string") {
    return value.trim() === "";
  }
  if (Array.isArray(value)) {
    return value.length === 0;
  }
  return false;
}

function mergeProfileRowFields(
  current: Record<string, unknown>,
  incoming: Record<string, unknown>
): Record<string, unknown> {
  const merged = { ...current };
  for (const [key, value] of Object.entries(incoming)) {
    if (isEmptyProfileValue(merged[key]) && !isEmptyProfileValue(value)) {
      merged[key] = value;
    }
  }
  return merged;
}

async function selectProfilesByIds(
  supabase: SupabaseClient,
  ids: string[],
  columns: string[]
): Promise<Record<string, unknown>[]> {
  const uniqueIds = [...new Set(ids.map((id) => id.trim()).filter(Boolean))];
  if (uniqueIds.length === 0) {
    return [];
  }

  const collected: Record<string, unknown>[] = [];

  for (const column of PROFILE_ID_COLUMNS) {
    if (missingTalentPoolFilterColumns.has(column)) {
      continue;
    }

    const selectColumns =
      columns[0] === "*"
        ? ["*"]
        : columns.includes(column)
          ? columns
          : [...columns, column];

    const { data, error } = await supabase
      .from("profiles")
      .select(selectColumns.join(", "))
      .in(column, uniqueIds);

    if (!error) {
      collected.push(
        ...(((data ?? []) as unknown) as Record<string, unknown>[])
      );
      continue;
    }

    if (
      isSupabaseSchemaError(error) &&
      (findMentionedColumn(error, [column]) ||
        error.message?.toLowerCase().includes(column))
    ) {
      missingTalentPoolFilterColumns.add(column);
      continue;
    }

    if (!isSupabaseSchemaError(error)) {
      console.error(
        `Talent pool education select by ${column} failed:`,
        error
      );
    }
  }

  return collected;
}

async function selectProfileEducationRows(
  supabase: SupabaseClient,
  ids: string[]
): Promise<Record<string, unknown>[]> {
  const uniqueIds = [...new Set(ids.map((id) => id.trim()).filter(Boolean))];
  if (uniqueIds.length === 0) {
    return [];
  }

  let columns: string[] = [...PROFILE_EDUCATION_COLUMNS];

  for (let attempt = 0; attempt < PROFILE_EDUCATION_COLUMNS.length; attempt += 1) {
    const rows = await selectProfilesByIds(supabase, uniqueIds, columns);
    if (rows.length > 0) {
      return rows;
    }

    const { error } = await supabase
      .from("profiles")
      .select(columns.join(", "))
      .in("id", uniqueIds)
      .limit(1);

    if (!error) {
      return [];
    }

    if (!isSupabaseSchemaError(error)) {
      console.error("Talent pool education select failed:", error);
      break;
    }

    const droppable = columns.filter((column) => column !== "id");
    const mentioned = findMentionedColumn(error, droppable);
    if (mentioned) {
      columns = columns.filter((column) => column !== mentioned);
      continue;
    }

    break;
  }

  const fallback = await selectProfilesByIds(supabase, uniqueIds, ["*"]);
  if (fallback.length > 0) {
    return fallback;
  }

  const { data, error } = await supabase
    .from("profiles")
    .select("*")
    .in("id", uniqueIds);

  if (error) {
    if (!isSupabaseSchemaError(error)) {
      console.error("Talent pool education fallback fetch failed:", error);
    }
    return [];
  }

  return (data ?? []) as Record<string, unknown>[];
}

function mergeEducationIntoProfileRows<T extends Record<string, unknown>>(
  rows: T[],
  educationRows: Record<string, unknown>[]
): T[] {
  if (educationRows.length === 0) {
    return rows;
  }

  const educationById = new Map<string, Record<string, unknown>>();
  for (const row of educationRows) {
    const mergedKeys = profileRowLookupIds(row);
    for (const id of mergedKeys) {
      const existing = educationById.get(id);
      educationById.set(
        id,
        existing ? mergeProfileRowFields(existing, row) : row
      );
    }
  }

  return rows.map((row) => {
    let extra: Record<string, unknown> | undefined;
    for (const id of profileRowLookupIds(row)) {
      const match = educationById.get(id);
      extra = extra && match ? mergeProfileRowFields(extra, match) : extra ?? match;
    }
    return extra ? ({ ...row, ...extra } as T) : row;
  });
}

export async function hydrateRowsWithEducation<T extends Record<string, unknown>>(
  supabase: SupabaseClient,
  rows: T[]
): Promise<T[]> {
  const ids = rows.flatMap((row) => profileRowLookupIds(row));
  const educationRows = await selectProfileEducationRows(supabase, ids);
  return mergeEducationIntoProfileRows(rows, educationRows);
}

export async function fetchCandidateEducationForEmployer(
  supabase: SupabaseClient,
  profileId: string
): Promise<TalentPoolEducation | null> {
  const id = profileId.trim();
  if (!id) {
    return null;
  }

  const rows = await selectProfileEducationRows(supabase, [id]);
  if (rows.length === 0) {
    return null;
  }

  const merged = rows.reduce(
    (current, row) => mergeProfileRowFields(current, row),
    {} as Record<string, unknown>
  );

  return educationFromProfileRow(merged);
}

export type TalentPoolProfileRow = {
  id?: string | null;
  role?: string | null;
  is_visible_in_pool?: boolean | string | number | null;
  visible_to_employers?: boolean | string | number | null;
  role_type?: string | null;
  [key: string]: unknown;
};

const VISIBILITY_COLUMNS = [
  "is_visible_in_pool",
  "visible_to_employers",
] as const;

function isEmployerProfileRow(row: TalentPoolProfileRow): boolean {
  return isEmployerRole(typeof row.role === "string" ? row.role : null);
}

function explainTalentPoolRowRejection(
  row: TalentPoolProfileRow
): string | null {
  if (isEmployerProfileRow(row)) {
    return `isEmployerProfileRow (role=${String(row.role)})`;
  }

  return explainPublishedVerifiedCandidateRejection(row);
}

function filterTalentPoolRows(
  rows: TalentPoolProfileRow[]
): TalentPoolProfileRow[] {
  console.info("[talent-pool] filterTalentPoolRows: raw rows from Supabase", {
    count: rows.length,
    rows: rows.map((row) => ({
      id: row.id,
      role: row.role,
      is_visible_in_pool: row.is_visible_in_pool,
      visible_to_employers: row.visible_to_employers,
      github_verified: row.github_verified,
      production_score: row.production_score,
      audit_score: row.audit_score,
      open_to_fulltime: row.open_to_fulltime,
      open_to_contract: row.open_to_contract,
      full_name: row.full_name ?? row.name,
      job_title: row.job_title ?? row.headline,
      has_bio: typeof row.bio === "string" && row.bio.trim().length > 0,
      has_skills: Array.isArray(row.skills)
        ? row.skills.length
        : typeof row.skills === "string"
          ? row.skills.length
          : 0,
    })),
  });

  const kept: TalentPoolProfileRow[] = [];
  for (const row of rows) {
    const rejection = explainTalentPoolRowRejection(row);
    if (rejection) {
      console.warn("[talent-pool] filterTalentPoolRows: rejected row", {
        id: row.id,
        reason: rejection,
        isEmployerProfileRow: isEmployerProfileRow(row),
        isPublishedVerifiedCandidateProfile:
          isPublishedVerifiedCandidateProfile(row),
      });
      continue;
    }
    kept.push(row);
  }

  console.info("[talent-pool] filterTalentPoolRows: kept rows", {
    rawCount: rows.length,
    keptCount: kept.length,
    keptIds: kept.map((row) => row.id),
  });

  return kept;
}

function cacheBustTalentPoolQuery<
  T extends { neq: (column: string, value: string) => T },
>(query: T): T {
  const nonce =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `talent-pool-${Date.now()}`;
  return query.neq("id", nonce);
}

export async function fetchEmployerTalentPoolProfiles(
  supabase: SupabaseClient
): Promise<
  { data: TalentPoolProfileRow[]; error: null } | { data: []; error: unknown }
> {
  for (const visibilityColumn of VISIBILITY_COLUMNS) {
    let query = supabase
      .from("profiles")
      .select("*")
      .eq(visibilityColumn, true);

    query = cacheBustTalentPoolQuery(query);

    const { data, error } = await query;

    if (!error) {
      console.info("[talent-pool] fetchEmployerTalentPoolProfiles query ok", {
        visibilityColumn,
        rawCount: (data ?? []).length,
      });
      const filtered = filterTalentPoolRows(
        (data ?? []) as TalentPoolProfileRow[]
      );
      const ids = filtered.flatMap((row) => profileRowLookupIds(row));
      const educationRows = await selectProfileEducationRows(supabase, ids);

      return {
        data: mergeEducationIntoProfileRows(filtered, educationRows),
        error: null,
      };
    }

    if (!isSupabaseSchemaError(error)) {
      console.error("Failed to fetch talent pool profiles:", error);
      return { data: [], error };
    }

    if (schemaErrorMentionsColumn(error, visibilityColumn)) {
      continue;
    }

    console.warn(
      "Talent pool fetch skipped due to schema mismatch:",
      error.message
    );
    return { data: [], error: null };
  }

  return { data: [], error: null };
}

import type { SupabaseClient } from "@supabase/supabase-js";

export const TALENT_POOL_VISIBILITY_CHANNEL = "talent-pool-visibility";
export const TALENT_POOL_VISIBILITY_EVENT = "visibility";
const LOCAL_CHANNEL = "provix-talent-pool-visibility";

export type TalentPoolVisibilityChange = {
  profileId: string;
  visible: boolean;
};

export function parseTalentPoolVisibilityChange(
  value: unknown
): TalentPoolVisibilityChange | null {
  if (!value || typeof value !== "object") {
    return null;
  }

  const record = value as Record<string, unknown>;
  const profileId =
    typeof record.profileId === "string" ? record.profileId.trim() : "";
  if (!profileId) {
    return null;
  }

  return {
    profileId,
    visible: Boolean(record.visible),
  };
}

export function publishLocalTalentPoolVisibility(
  change: TalentPoolVisibilityChange
) {
  if (typeof window === "undefined") {
    return;
  }

  try {
    const channel = new BroadcastChannel(LOCAL_CHANNEL);
    channel.postMessage(change);
    channel.close();
  } catch {
    // BroadcastChannel is unavailable in some embedded browsers.
  }

  try {
    localStorage.setItem(LOCAL_CHANNEL, JSON.stringify(change));
    localStorage.removeItem(LOCAL_CHANNEL);
  } catch {
    // Private mode may block storage events.
  }
}

export function subscribeLocalTalentPoolVisibility(
  handler: (change: TalentPoolVisibilityChange) => void
): () => void {
  if (typeof window === "undefined") {
    return () => {};
  }

  let channel: BroadcastChannel | null = null;
  try {
    channel = new BroadcastChannel(LOCAL_CHANNEL);
    channel.onmessage = (event) => {
      const parsed = parseTalentPoolVisibilityChange(event.data);
      if (parsed) {
        handler(parsed);
      }
    };
  } catch {
    channel = null;
  }

  const onStorage = (event: StorageEvent) => {
    if (event.key !== LOCAL_CHANNEL || !event.newValue) {
      return;
    }

    try {
      const parsed = parseTalentPoolVisibilityChange(JSON.parse(event.newValue));
      if (parsed) {
        handler(parsed);
      }
    } catch {
      // Ignore malformed storage payloads.
    }
  };
  window.addEventListener("storage", onStorage);

  return () => {
    channel?.close();
    window.removeEventListener("storage", onStorage);
  };
}

function findTalentPoolVisibilityChannel(supabase: SupabaseClient) {
  return supabase
    .getChannels()
    .find((channel) => channel.topic.includes(TALENT_POOL_VISIBILITY_CHANNEL));
}

export function ensureTalentPoolVisibilityChannel(
  supabase: SupabaseClient
): () => void {
  const existing = findTalentPoolVisibilityChannel(supabase);
  if (existing) {
    return () => {};
  }

  const channel = supabase.channel(TALENT_POOL_VISIBILITY_CHANNEL).subscribe();
  return () => {
    void supabase.removeChannel(channel);
  };
}

async function sendTalentPoolVisibility(
  supabase: SupabaseClient,
  change: TalentPoolVisibilityChange
) {
  const existing = findTalentPoolVisibilityChannel(supabase);
  if (existing) {
    await existing.send({
      type: "broadcast",
      event: TALENT_POOL_VISIBILITY_EVENT,
      payload: change,
    });
    return;
  }

  const channel = supabase.channel(TALENT_POOL_VISIBILITY_CHANNEL, {
    config: { broadcast: { ack: true } },
  });

  try {
    const subscribed = await new Promise<boolean>((resolve) => {
      const timeoutId = window.setTimeout(() => resolve(false), 2000);
      channel.subscribe((status) => {
        if (status === "SUBSCRIBED") {
          window.clearTimeout(timeoutId);
          resolve(true);
          return;
        }

        if (
          status === "CHANNEL_ERROR" ||
          status === "TIMED_OUT" ||
          status === "CLOSED"
        ) {
          window.clearTimeout(timeoutId);
          resolve(false);
        }
      });
    });

    if (subscribed) {
      await channel.send({
        type: "broadcast",
        event: TALENT_POOL_VISIBILITY_EVENT,
        payload: change,
      });
    }
  } finally {
    await supabase.removeChannel(channel);
  }
}

export async function publishTalentPoolVisibility(
  supabase: SupabaseClient,
  change: TalentPoolVisibilityChange
): Promise<void> {
  publishLocalTalentPoolVisibility(change);

  try {
    await sendTalentPoolVisibility(supabase, change);
  } catch (error) {
    console.warn("Talent pool visibility broadcast failed:", error);
  }
}

export function subscribeTalentPoolVisibility(
  supabase: SupabaseClient,
  handler: (change: TalentPoolVisibilityChange) => void
): () => void {
  const unsubscribeLocal = subscribeLocalTalentPoolVisibility(handler);

  const channel = supabase
    .channel(TALENT_POOL_VISIBILITY_CHANNEL)
    .on(
      "broadcast",
      { event: TALENT_POOL_VISIBILITY_EVENT },
      ({ payload }) => {
        const parsed = parseTalentPoolVisibilityChange(payload);
        if (parsed) {
          handler(parsed);
        }
      }
    )
    .on(
      "postgres_changes",
      { event: "DELETE", schema: "public", table: "profiles" },
      (payload) => {
        const id = (payload.old as { id?: string } | null)?.id?.trim();
        if (id) {
          handler({ profileId: id, visible: false });
        }
      }
    )
    .subscribe();

  return () => {
    unsubscribeLocal();
    void supabase.removeChannel(channel);
  };
}

