export { readBrowserSession };

import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import { isAdminUser } from "@/lib/admin-access";
import {
  isAuditorPath,
  isProtectedAppPath,
  isPublicRoute,
  shouldSkipMiddlewareAuth,
} from "@/lib/dashboard-account";
import {
  CANDIDATE_DASHBOARD_PATH,
  CANDIDATE_SETUP_PATH,
  EMPLOYER_DASHBOARD_PATH,
  isEmployerAllowedDashboardRequest,
  isEmployerDashboardRequest,
  isRoleOnboardingPath,
  normalizeAccountKind,
  resolvePostAuthDestination,
  ROLE_ONBOARDING_PATH,
} from "@/lib/account-role";
import {
  hasCompletedCandidateSetup,
  isCandidateSetupPath,
} from "@/lib/candidate-onboarding";

const PROFILE_SETUP_SELECT =
  "role, full_name, name, first_name, last_name, job_title, headline, bio, skills, experience_level, portfolio_url";

const cookieOptions = {
  path: "/",
  sameSite: "lax" as const,
};

function copyResponseCookies(from: NextResponse, to: NextResponse) {
  from.cookies.getAll().forEach((cookie) => {
    to.cookies.set({
      name: cookie.name,
      value: cookie.value,
      path: cookie.path ?? cookieOptions.path,
      domain: cookie.domain,
      expires: cookie.expires,
      maxAge: cookie.maxAge,
      httpOnly: cookie.httpOnly,
      secure: cookie.secure,
      sameSite: cookie.sameSite ?? cookieOptions.sameSite,
    });
  });

  // Supabase may attach cache headers when refreshing tokens — keep them in sync.
  for (const header of ["cache-control", "expires", "pragma"] as const) {
    const value = from.headers.get(header);
    if (value) {
      to.headers.set(header, value);
    }
  }
}

function redirectWithSessionCookies(
  request: NextRequest,
  supabaseResponse: NextResponse,
  pathname: string,
  search = ""
) {
  const url = request.nextUrl.clone();
  url.pathname = pathname;
  url.search = search;
  const redirectResponse = NextResponse.redirect(url, 303);
  copyResponseCookies(supabaseResponse, redirectResponse);
  return redirectResponse;
}

export async function updateSession(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Public homepage, marketing/legal pages, and static assets must not
  // create a Supabase client or call getUser() / refresh the session.
  // Auth runs only on protected app paths such as /dashboard and /settings.
  if (shouldSkipMiddlewareAuth(pathname)) {
    return NextResponse.next({ request });
  }

  let supabaseResponse = NextResponse.next({
    request,
  });

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookieOptions,
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet, headers) {
          cookiesToSet.forEach(({ name, value, options: _options }) =>
            request.cookies.set(name, value)
          );
          supabaseResponse = NextResponse.next({
            request,
          });
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, {
              ...cookieOptions,
              ...options,
            })
          );
          if (headers) {
            Object.entries(headers).forEach(([key, value]) => {
              supabaseResponse.headers.set(key, value);
            });
          }
        },
      },
    }
  );

  const {
    data: { user },
  } = await supabase.auth.getUser();

  // API routes must always return JSON. A redirect to the marketing page
  // follows to HTML, and response.json() then throws on "<!DOCTYPE".
  // Route handlers authenticate (cookie or bearer) and return { error }.
  if (pathname.startsWith("/api/")) {
    return supabaseResponse;
  }

  const isLogin =
    pathname === "/login" || pathname.startsWith("/login/");
  const isHome = pathname === "/";
  const isUpdatePassword =
    pathname === "/update-password" ||
    pathname.startsWith("/update-password/");
  const isEmployer =
    pathname === "/employer" || pathname.startsWith("/employer/");
  const onRoleOnboarding = isRoleOnboardingPath(pathname);
  const onCandidateSetup = isCandidateSetupPath(pathname);
  const isProtectedRoute = isProtectedAppPath(pathname);

  // Unauthenticated users must be allowed to stay on /login (no redirect).
  if (isLogin && !user) {
    return supabaseResponse;
  }

  if (isUpdatePassword) {
    return supabaseResponse;
  }

  if (!user && onCandidateSetup) {
    return redirectWithSessionCookies(
      request,
      supabaseResponse,
      "/login",
      `?next=${encodeURIComponent(CANDIDATE_SETUP_PATH)}`
    );
  }

  // Unsigned visitors never enter the app shell. Send them to the marketing page.
  if (!user && isProtectedRoute && !isPublicRoute(pathname)) {
    return redirectWithSessionCookies(request, supabaseResponse, "/");
  }

  const isAdminConsole =
    pathname.startsWith("/admin") &&
    pathname !== "/admin/login" &&
    !pathname.startsWith("/admin/login/");

  if (isAdminConsole) {
    if (!user) {
      return redirectWithSessionCookies(
        request,
        supabaseResponse,
        "/login",
        `?next=${encodeURIComponent(pathname)}`
      );
    }
    if (!isAdminUser(user)) {
      return redirectWithSessionCookies(request, supabaseResponse, "/");
    }
  }

  if (user) {
    const employerRequest = isEmployerDashboardRequest(
      pathname,
      request.nextUrl.search
    );
    const needsRole =
      isHome ||
      isLogin ||
      isEmployer ||
      employerRequest ||
      isAuditorPath(pathname) ||
      onRoleOnboarding ||
      onCandidateSetup ||
      (isProtectedRoute && !isLogin);

    let role: ReturnType<typeof normalizeAccountKind> = null;
    let setupComplete = true;
    let profileRow: Record<string, unknown> | null = null;

    if (needsRole) {
      try {
        const { data: profile } = await supabase
          .from("profiles")
          .select(PROFILE_SETUP_SELECT)
          .eq("id", user.id)
          .maybeSingle();
        profileRow =
          profile && typeof profile === "object"
            ? (profile as Record<string, unknown>)
            : null;
        role = normalizeAccountKind(
          typeof profile?.role === "string" ? profile.role : null
        );

        if (!role) {
          const { data: linkedProfile } = await supabase
            .from("profiles")
            .select(PROFILE_SETUP_SELECT)
            .eq("user_id", user.id)
            .maybeSingle();
          profileRow =
            linkedProfile && typeof linkedProfile === "object"
              ? (linkedProfile as Record<string, unknown>)
              : profileRow;
          role = normalizeAccountKind(
            typeof linkedProfile?.role === "string" ? linkedProfile.role : null
          );
        }

        if (role === "candidate") {
          setupComplete = hasCompletedCandidateSetup(profileRow);
        }
      } catch (err) {
        console.error("Account role check failed:", err);
      }

      if (
        !role &&
        !isAdminUser(user) &&
        !onRoleOnboarding &&
        !isLogin &&
        (isProtectedRoute || isHome || onCandidateSetup)
      ) {
        return redirectWithSessionCookies(
          request,
          supabaseResponse,
          ROLE_ONBOARDING_PATH
        );
      }

      if (role && onRoleOnboarding) {
        const destination = new URL(
          role === "employer"
            ? EMPLOYER_DASHBOARD_PATH
            : setupComplete
              ? CANDIDATE_DASHBOARD_PATH
              : CANDIDATE_SETUP_PATH,
          request.url
        );
        return redirectWithSessionCookies(
          request,
          supabaseResponse,
          destination.pathname,
          destination.search
        );
      }

      if (
        role === "candidate" &&
        !setupComplete &&
        !onCandidateSetup &&
        !isLogin &&
        (isProtectedRoute || isHome)
      ) {
        return redirectWithSessionCookies(
          request,
          supabaseResponse,
          CANDIDATE_SETUP_PATH
        );
      }

      if (role === "candidate" && setupComplete && onCandidateSetup) {
        return redirectWithSessionCookies(
          request,
          supabaseResponse,
          CANDIDATE_DASHBOARD_PATH
        );
      }

      if (role === "employer" && onCandidateSetup) {
        return redirectWithSessionCookies(
          request,
          supabaseResponse,
          EMPLOYER_DASHBOARD_PATH
        );
      }

      if (isLogin) {
        const destination = new URL(
          resolvePostAuthDestination({
            role,
            requestedNext: request.nextUrl.searchParams.get("next"),
            isAdmin: isAdminUser(user),
            setupComplete,
          }),
          request.url
        );
        if (
          destination.pathname !== "/login" &&
          !destination.pathname.startsWith("/login/")
        ) {
          return redirectWithSessionCookies(
            request,
            supabaseResponse,
            destination.pathname,
            destination.search
          );
        }
      }

      const isEmployerAccount = role === "employer";

      if (
        isEmployerAccount &&
        pathname === "/dashboard" &&
        !isEmployerAllowedDashboardRequest(pathname, request.nextUrl.search)
      ) {
        const destination = new URL(EMPLOYER_DASHBOARD_PATH, request.url);
        return redirectWithSessionCookies(
          request,
          supabaseResponse,
          destination.pathname,
          destination.search
        );
      }

      if (isEmployerAccount && (isHome || isEmployer || isAuditorPath(pathname))) {
        const destination = new URL(EMPLOYER_DASHBOARD_PATH, request.url);
        return redirectWithSessionCookies(
          request,
          supabaseResponse,
          destination.pathname,
          destination.search
        );
      }

      if (!isEmployerAccount && (isEmployer || employerRequest)) {
        const tab =
          request.nextUrl.searchParams.get("tab")?.trim().toLowerCase() ?? "";
        // Candidates/admins may browse the Talent Network directory.
        // Hiring-only tabs (applicants, evaluator) stay employer-gated.
        const allowTalentBrowse =
          isEmployer ||
          pathname.startsWith("/employer") ||
          tab === "talent";
        if (!allowTalentBrowse) {
          return redirectWithSessionCookies(
            request,
            supabaseResponse,
            CANDIDATE_DASHBOARD_PATH
          );
        }
      }

      if (
        role === "candidate" &&
        pathname === "/dashboard"
      ) {
        const tab = request.nextUrl.searchParams.get("tab")?.trim() ?? "";
        if (!tab || tab === "overview" || tab === "my_profile") {
          return redirectWithSessionCookies(
            request,
            supabaseResponse,
            CANDIDATE_DASHBOARD_PATH
          );
        }
      }
    }
  }

  // Signed-in candidates: /auditor and /audits belong in the dashboard auditor.
  if (user && isAuditorPath(pathname) && !pathname.startsWith("/dashboard/")) {
    return redirectWithSessionCookies(
      request,
      supabaseResponse,
      "/dashboard/auditor",
      request.nextUrl.search
    );
  }

  // Home only: active session → candidate dashboard. Employers already left above.
  if (isHome && user) {
    if (request.nextUrl.searchParams.get("passwordUpdated") === "1") {
      return supabaseResponse;
    }

    return redirectWithSessionCookies(
      request,
      supabaseResponse,
      CANDIDATE_DASHBOARD_PATH
    );
  }

  return supabaseResponse;
}

import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'

export async function createClient() {
  const cookieStore = await cookies()

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // The `setAll` method was called from a Server Component.
            // This can be ignored if you have middleware refreshing user sessions.
          }
        },
      },
    }
  )
}

